@dataclass
class MasterReleaseMutationAndMerklePCCReport:
    release_version: str
    release_ready: bool
    cas_lineage_verified: bool
    parent_bundle_sha256: str
    total_modules_audited: int
    total_functions_certified: int
    total_mutants_generated: int
    higher_order_mutants_count: int
    equivalent_mutants_pruned_count: int
    killed_mutants_count: int
    survived_mutants_count: int
