class INPTopLayerStartingStyleLCPFinding:
    defect_type: str
    severity: str
    web_vital_or_spec: str
    location_hint: str
    explanation: str
    remediation: str


@dataclass
class AwwwardsINPTopLayerStartingStyleLCPReport:
    component_name: str
    proven_inp_toplayer_and_lcp_soty_safe: bool
    inp_cooperative_yield_or_transition_verified: bool
    top_layer_starting_style_discrete_verified: bool
    offscreen_canvas_worker_isolation_verified: bool
