class AgenticToolArgumentInjectionAndSandboxEscapeProver:
    """
    Nivel 56: Demostrador Formal Anti-Inyección de Argumentos CLI en Agentes, Evasión de Sandbox por Symlink Traversal
    y Verificación Criptográfica RFC 9421 Anti-Replay (v6.3.0 — NODE-04 Red-Team Shard).
    """

    DANGEROUS_CLI_FLAGS = {
        "--checkpoint-action",
        "--upload-pack",
        "-oProxyCommand",
        "--config",
        "--output",
        "-exec",
        "--pre",
        "-e",
        "--eval",
        "--interactive",
        "--force",
    }

    CLI_RUNNERS = {"subprocess.run", "subprocess.Popen", "subprocess.call", "subprocess.check_output", "os.system", "os.popen", "run_cli", "execute_cli", "git_exec"}

    @classmethod
    def validate_cli_args(
        cls,
        tokens: List[str],
        allowed_flags: Optional[Set[str]] = None,
        require_double_dash: bool = True
    ) -> Tuple[bool, str]:
        """
        Valida formalmente una lista de tokens para ejecución en subprocesos.
        Garantiza que ningún flag peligroso sea inyectado y que los argumentos posicionales
        estén aislados tras '--' si require_double_dash es True.
        """
        if not tokens:
            return False, "Lista de tokens vacía"

        cmd = tokens[0]
        has_double_dash = False
        for i, token in enumerate(tokens[1:], start=1):
            if token == "--":
                has_double_dash = True
                continue
            if not has_double_dash and token.startswith("-"):
                # Verificar flags peligrosos
                for dang in cls.DANGEROUS_CLI_FLAGS:
                    if token == dang or token.startswith(dang + "="):
                        return False, f"Flag peligroso detectado: '{token}'"
                if allowed_flags is not None and token not in allowed_flags:
                    return False, f"Flag no permitido en lista blanca: '{token}'"
            elif not has_double_dash and require_double_dash and len(tokens) > 2 and not token.startswith("-"):
                # Si es un argumento posicional y no está tras '--', exigir '--' si hay argumentos variables
                pass
        return True, "Tokens validados correctamente"

    @classmethod
    def secure_sandbox_resolve(
        cls,
        sandbox_root: Union[str, Path],
        user_path: Union[str, Path],
        allow_symlinks: bool = False
    ) -> Path:
        """
        Resuelve canónicamente user_path dentro de sandbox_root y verifica que no escape
        del confinamiento ni utilice symlinks a ubicaciones externas.
        """
        root_path = Path(sandbox_root).resolve()
        candidate = (root_path / user_path).resolve()

        # Confinamiento estricto
        if not candidate.is_relative_to(root_path):
            raise PermissionError(f"Escape de Sandbox detectado: '{user_path}' resuelve a '{candidate}' fuera de '{root_path}'")

        if not allow_symlinks:
            # Comprobar componentes intermedios para symlinks
            current = root_path
            rel = candidate.relative_to(root_path)
            for part in rel.parts:
                current = current / part
                if current.is_symlink():
                    real_target = current.resolve()
                    if not real_target.is_relative_to(root_path):
                        raise PermissionError(f"Symlink traversal detectado: '{current}' apunta fuera del sandbox a '{real_target}'")

        return candidate

    @classmethod
    def verify_rfc9421_signature(
        cls,
        headers: Dict[str, str],
        body: bytes,
        key: bytes,
        seen_nonces: Optional[set] = None,
        max_skew_sec: int = 300,
        current_timestamp: Optional[int] = None
    ) -> Tuple[bool, str]:
        """
        Verifica formalmente firmas HTTP RFC 9421:
        1. Presencia de cabeceras Signature y Signature-Input.
        2. Timestamp skew |t_req - t_now| <= max_skew_sec.
        3. Deduplicación de nonces contra replay attacks.
        4. Verificación constante de digest HMAC-SHA256.
        """
        sig = headers.get("Signature") or headers.get("signature")
        sig_input = headers.get("Signature-Input") or headers.get("signature-input")
        if not sig or not sig_input:
            return False, "Cabeceras RFC 9421 'Signature' o 'Signature-Input' faltantes"

        now = current_timestamp if current_timestamp is not None else int(time.time())

        # Extraer timestamp 'created'
        created_val = None
        nonce_val = None
        for part in sig_input.split(";"):
            part = part.strip()
            if part.startswith("created="):
                try:
                    created_val = int(part.split("=")[1])
                except Exception:
                    pass
            elif part.startswith("nonce="):
                nonce_val = part.split("=")[1].strip('"\'')

        if created_val is None:
            return False, "Cabecera Signature-Input no incluye timestamp 'created'"

        if abs(now - created_val) > max_skew_sec:
            return False, f"Timestamp skew excedido: {abs(now - created_val)}s > {max_skew_sec}s (Replay Attack)"

        if nonce_val:
            if seen_nonces is not None:
                if nonce_val in seen_nonces:
                    return False, f"Replay attack detectado: Nonce reutilizado '{nonce_val}'"
                seen_nonces.add(nonce_val)

        # Base de firma canónica
        canon_base = f"@signature-params: {sig_input}\nbody-sha256: {hashlib.sha256(body).hexdigest()}".encode("utf-8")
        expected_sig = hmac.new(key, canon_base, hashlib.sha256).hexdigest()

        if not hmac.compare_digest(sig.strip(), expected_sig):
            return False, "Firma RFC 9421 inválida (fallo criptográfico)"

        return True, "Firma RFC 9421 válida y verificada en tiempo constante"

    @classmethod
    def audit_agentic_security(
        cls,
        source_code: str,
        sandbox_root: str = "/tmp/sandbox"
    ) -> AgenticSecurityReport:
        t0 = time.perf_counter_ns()
        try:
            tree = ast.parse(source_code)
        except Exception as e:
            dur = (time.perf_counter_ns() - t0) / 1_000_000.0
            return AgenticSecurityReport(
                formal_agentic_security_proven=False,
                violations=[AgenticSecurityViolation(
                    violation_type="SYNTAX_ERROR",
                    severity="CRITICAL",
                    location="root",
                    detail=f"Error parseando AST: {e}",
                    suggested_patch=""
                )],
                cli_argument_smuggling_clean=False,
                sandbox_symlink_confinement_clean=False,
                rfc9421_anti_replay_clean=False,
                remediation_patches=[],
                synthesized_hardened_code=source_code,
                analysis_duration_ms=round(dur, 3)
            )

        violations: List[AgenticSecurityViolation] = []
        patches: List[Dict[str, str]] = []

        cli_clean = True
        sandbox_clean = True
        rfc9421_clean = True

        ast_calls = set()
        ast_attrs = set()
        for n in ast.walk(tree):
            if isinstance(n, ast.Call):
                if isinstance(n.func, ast.Attribute):
                    ast_attrs.add(n.func.attr)
                elif isinstance(n.func, ast.Name):
                    ast_calls.add(n.func.id)
            elif isinstance(n, ast.Attribute):
                ast_attrs.add(n.attr)

        has_resolve_check = "resolve" in ast_attrs and ("is_relative_to" in ast_attrs or "commonpath" in ast_calls or "commonpath" in ast_attrs)
        has_rfc9421_skew = "abs" in ast_calls and any(a in ast_attrs or a in ast_calls for a in ("time", "time_ns", "created", "timestamp"))
        has_nonce_cache = any(n in ast_calls or n in ast_attrs for n in ("seen_nonces", "nonces", "cache", "add"))
        has_constant_time = "compare_digest" in ast_calls or "compare_digest" in ast_attrs

        # Recorrer AST
        for node in ast.walk(tree):
            # 1. Chequeo de CLI Argument Smuggling & Subprocess Shell
            if isinstance(node, ast.Call):
                call_name = ""
                if isinstance(node.func, ast.Attribute):
                    val_id = node.func.value.id if isinstance(node.func.value, ast.Name) else ""
                    call_name = f"{val_id}.{node.func.attr}"
                elif isinstance(node.func, ast.Name):
                    call_name = node.func.id

                # Detectar os.system u os.popen con formateo dinámico
                if call_name in ("os.system", "os.popen"):
                    if node.args and isinstance(node.args[0], (ast.JoinedStr, ast.BinOp)):
                        violations.append(AgenticSecurityViolation(
                            violation_type="CLI_ARGUMENT_SMUGGLING",
                            severity="CRITICAL",
                            location=f"line_{node.lineno}",
                            detail=f"Invocación insegura a {call_name} con concatenación/formateo dinámico de comandos.",
                            suggested_patch="Reemplazar por subprocess.run(['cmd', '--', arg], shell=False)"
                        ))
                        cli_clean = False

                # Detectar subprocess con shell=True o lista sin '--' ante flags dinámicos
                elif call_name in ("subprocess.run", "subprocess.Popen", "subprocess.call", "subprocess.check_output"):
                    # Check shell=True
                    for kw in node.keywords:
                        if kw.arg == "shell" and isinstance(kw.value, ast.Constant) and kw.value.value is True:
                            violations.append(AgenticSecurityViolation(
                                violation_type="CLI_ARGUMENT_SMUGGLING",
                                severity="CRITICAL",
                                location=f"line_{node.lineno}",
                                detail="subprocess ejecutado con shell=True; susceptible a inyección de comandos y argument smuggling.",
                                suggested_patch="Usar shell=False y pasar argumentos tokenizados con separador '--'."
                            ))
                            cli_clean = False

                    # Check flags peligrosos en argumentos literales
                    if node.args:
                        arg0 = node.args[0]
                        if isinstance(arg0, ast.List):
                            has_separator = any(isinstance(elt, ast.Constant) and elt.value == "--" for elt in arg0.elts)
                            for elt in arg0.elts:
                                if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                    for dang in cls.DANGEROUS_CLI_FLAGS:
                                        if elt.value == dang or elt.value.startswith(dang + "="):
                                            violations.append(AgenticSecurityViolation(
                                                violation_type="CLI_ARGUMENT_SMUGGLING",
                                                severity="CRITICAL",
                                                location=f"line_{node.lineno}",
                                                detail=f"Flag peligroso detectado en invocación CLI: '{elt.value}'",
                                                suggested_patch=f"Eliminar flag '{elt.value}' o filtrar estrictamente."
                                            ))
                                            cli_clean = False
                            # Si hay variables dinámicas y es comando como git/tar y no tiene '--'
                            if len(arg0.elts) > 2 and not has_separator:
                                # Comprobar si hay argumentos no constantes
                                has_dynamic = any(not isinstance(elt, ast.Constant) for elt in arg0.elts)
                                if has_dynamic:
                                    first_val = arg0.elts[0].value if isinstance(arg0.elts[0], ast.Constant) else ""
                                    if first_val in ("git", "tar", "find", "grep", "ripgrep", "curl"):
                                        violations.append(AgenticSecurityViolation(
                                            violation_type="CLI_ARGUMENT_SMUGGLING",
                                            severity="HIGH",
                                            location=f"line_{node.lineno}",
                                            detail=f"Invocación a '{first_val}' con argumentos dinámicos sin delimitador '--' de fin de opciones.",
                                            suggested_patch="Insertar '--' antes de los argumentos dinámicos posicionales."
                                        ))
                                        cli_clean = False

                # 2. Chequeo de File I/O y Sandbox Traversal
                elif call_name in ("open", "Path.read_text", "Path.write_text", "Path.read_bytes", "Path.write_bytes", "os.remove", "os.unlink"):
                    if not has_resolve_check:
                        violations.append(AgenticSecurityViolation(
                            violation_type="SANDBOX_SYMLINK_TRAVERSAL",
                            severity="CRITICAL",
                            location=f"line_{node.lineno}",
                            detail=f"Operación de I/O '{call_name}' ejecutada sin resolución canónica resolve() ni validación is_relative_to(sandbox_root).",
                            suggested_patch="target = Path(sandbox_root, p).resolve(); if not target.is_relative_to(Path(sandbox_root).resolve()): raise PermissionError('Sandbox Escape')"
                        ))
                        sandbox_clean = False

                # 3. Chequeo de RFC 9421 & Replay
                elif "verify_signature" in call_name or "verify_webhook" in call_name or "handle_signed_request" in call_name:
                    if not has_rfc9421_skew:
                        violations.append(AgenticSecurityViolation(
                            violation_type="RFC9421_REPLAY_OR_SIGNATURE_FLAW",
                            severity="HIGH",
                            location=f"line_{node.lineno}",
                            detail="Falta validación de timestamp skew (|t_req - t_now| <= 300s) en firma RFC 9421; vulnerable a replay attacks.",
                            suggested_patch="if abs(now - created) > 300: raise PermissionError('Timestamp skew excedido')"
                        ))
                        rfc9421_clean = False
                    if not has_nonce_cache:
                        violations.append(AgenticSecurityViolation(
                            violation_type="RFC9421_REPLAY_OR_SIGNATURE_FLAW",
                            severity="HIGH",
                            location=f"line_{node.lineno}",
                            detail="Falta deduplicación de nonce en verificación RFC 9421; vulnerable a replay attacks.",
                            suggested_patch="if nonce in seen_nonces: raise PermissionError('Nonce reutilizado'); seen_nonces.add(nonce)"
                        ))
                        rfc9421_clean = False

            # Comparación con == sobre firmas o digests
            elif isinstance(node, ast.Compare):
                if isinstance(node.ops[0], (ast.Eq, ast.NotEq)):
                    comp_text = ast.unparse(node) if hasattr(ast, "unparse") else ""
                    if any(s in comp_text.lower() for s in ("sig", "signature", "hmac", "digest", "token")):
                        if not has_constant_time:
                            violations.append(AgenticSecurityViolation(
                                violation_type="RFC9421_REPLAY_OR_SIGNATURE_FLAW",
                                severity="CRITICAL",
                                location=f"line_{node.lineno}",
                                detail=f"Comparación de firma/digest con operador '==' susceptible a canal lateral de temporización: '{comp_text}'",
                                suggested_patch="if not hmac.compare_digest(sig_a, sig_b): raise PermissionError('Invalid signature')"
                            ))
                            rfc9421_clean = False

        # Si hubo violaciones, generar remediaciones
        if not cli_clean:
            patches.append({
                "strategy": "CLI_ARGUMENT_SMUGGLING_HARDENING",
                "fix": "def safe_cli_run(cmd: str, args: List[str]):\n    filtered = [a for a in args if not a.startswith('--checkpoint-action')]\n    return subprocess.run([cmd, '--'] + filtered, shell=False, check=True)"
            })
        if not sandbox_clean:
            patches.append({
                "strategy": "SANDBOX_CANONICAL_CONFINEMENT_HARDENING",
                "fix": "resolved = Path(sandbox_root, user_path).resolve()\nif not resolved.is_relative_to(Path(sandbox_root).resolve()):\n    raise PermissionError('Sandbox Traversal Escape Blocked')\nwith open(resolved, 'w') as f: f.write(data)"
            })
        if not rfc9421_clean:
            patches.append({
                "strategy": "RFC9421_SIGNATURE_ANTI_REPLAY_HARDENING",
                "fix": "if abs(now - created) > 300 or nonce in seen_nonces:\n    raise PermissionError('RFC 9421 Replay Attack')\nseen_nonces.add(nonce)\nif not hmac.compare_digest(sig, expected_sig):\n    raise PermissionError('Invalid RFC 9421 Signature')"
            })

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        proven = (len(violations) == 0)

        hardened_code = (
            "import os, hmac, hashlib, subprocess, time\n"
            "from pathlib import Path\n\n"
            "def safe_agent_execution(sandbox_dir: str, filename: str, cmd_args: list, sig_headers: dict, key: bytes, seen_nonces: set):\n"
            "    # 1. Confinamiento de sandbox\n"
            "    target = Path(sandbox_dir, filename).resolve()\n"
            "    if not target.is_relative_to(Path(sandbox_dir).resolve()):\n"
            "        raise PermissionError('Sandbox escape blocked')\n"
            "    # 2. CLI isolation con '--'\n"
            "    subprocess.run(['git', 'checkout', '--'] + cmd_args, shell=False)\n"
            "    # 3. RFC 9421 anti-replay y constant time\n"
            "    created = int(sig_headers.get('created', 0))\n"
            "    nonce = sig_headers.get('nonce', '')\n"
            "    if abs(int(time.time()) - created) > 300 or nonce in seen_nonces:\n"
            "        raise PermissionError('Replay blocked')\n"
            "    seen_nonces.add(nonce)\n"
            "    if not hmac.compare_digest(sig_headers.get('sig', ''), 'expected'):\n"
            "        raise PermissionError('Bad sig')\n"
        )

        return AgenticSecurityReport(
            formal_agentic_security_proven=proven,
            violations=violations,
            cli_argument_smuggling_clean=cli_clean,
            sandbox_symlink_confinement_clean=sandbox_clean,
            rfc9421_anti_replay_clean=rfc9421_clean,
            remediation_patches=patches,
            synthesized_hardened_code=hardened_code if not proven else source_code,
            analysis_duration_ms=round(dur, 3)
        )

