# PKCS#1 v1.5 EXIGIENDO RSA-OAEP SHA-256 (CWE-780) E INTEGRIDAD SRI / AISLAMIENTO
# CROSS-ORIGIN COOP/COEP (CWE-353 / CWE-829) (v8.3.0)
# ==============================================================================

@dataclass
class JWKAlgorithmConfusionRSAOAEPSRIViolation:
    violation_type: str
    severity: str
    location: str
    detail: str
    suggested_patch: str


@dataclass
class JWKAlgorithmConfusionRSAOAEPSRIReport:
    formal_jwk_rsaoaep_sri_safe: bool
    jwt_rfc8725_header_and_alg_clean: bool
    rsa_oaep_sha256_anti_marvin_clean: bool
    sri_and_cross_origin_isolation_clean: bool
    violations: List[JWKAlgorithmConfusionRSAOAEPSRIViolation]
    remediation_patches: List[Dict[str, str]]
    analysis_duration_ms: float


class JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver:
    """
    Nivel 80 (NODE-04 Shard: Red-Team Security, IFDS Taint, Criptografia y Anti-SSRF):
    Demostrador formal triple que certifica:
    1. Seguridad en cabeceras JOSE/JWT bajo RFC 8725 (CWE-347 / CVE-2026-0265): bloqueo de
       cabeceras de inyección de claves ('jku', 'x5u', 'jwk'), sanitización alfanumérica
       estricta de 'kid' contra Path Traversal / SQLi, y prohibición de confusión de
       algoritmo RS256 -> HS256 usando claves públicas PEM como secretos HMAC.
    2. Inmunidad contra el ataque Marvin / Bleichenbacher en RSA PKCS#1 v1.5 (CWE-203 /
       CWE-780): prohibición de padding PKCS1v15 y SHA-1 en cifrado asimétrico, exigiendo
       RSA-OAEP con MGF1(SHA-256) y módulo >= 2048 bits.
    3. Integridad de Subrecursos (SRI SHA-384/SHA-512, CWE-353 / CWE-829) en scripts/estilos
       externos y aislamiento de origen cruzado (COOP: same-origin, COEP: require-corp,
       CORP: same-origin).
    """

    ASYMMETRIC_PEM_MARKERS = (
        "-----BEGIN PUBLIC KEY-----",
        "-----BEGIN RSA PUBLIC KEY-----",
        "-----BEGIN EC PUBLIC KEY-----",
        "ssh-rsa ",
        "ssh-ed25519 ",
    )

    @classmethod
    def verify_jwt_rfc8725_header_and_key_binding(
        cls,
        jwt_header: Dict[str, Any],
        allowed_algorithms: Set[str],
        verification_key_material: str,
        trusted_kids: Optional[Set[str]] = None,
    ) -> Tuple[bool, str]:
        if not isinstance(jwt_header, dict):
            return False, "Cabecera JWT inválida."

        for forbidden_hdr in ("jku", "x5u", "jwk", "x5c"):
            if forbidden_hdr in jwt_header:
                return False, f"RFC 8725 / CWE-347 JWT Header Injection bloqueada: parámetro '{forbidden_hdr}' embebido prohibido."

        if "crit" in jwt_header:
            return False, "RFC 8725 JWT Critical Header ('crit') no soportado o ambiguo bloqueado."

        alg = str(jwt_header.get("alg", "")).strip()
        if not alg or alg.lower() == "none" or alg not in allowed_algorithms:
            return False, f"RFC 8725 / CWE-347 JWT Algorithm '{alg}' fuera de allowlist explícita {sorted(allowed_algorithms)}."

        has_sym = any(a.startswith("HS") for a in allowed_algorithms)
        has_asym = any(a.startswith(("RS", "ES", "PS", "Ed")) for a in allowed_algorithms)
        if has_sym and has_asym:
            return False, "RFC 8725 / CVE-2026-0265 Algorithm Confusion Risk: prohibido mezclar algoritmos simétricos (HS*) y asimétricos (RS*/ES*/EdDSA) en allowed_algorithms."

        key_str = str(verification_key_material)
        if alg.startswith("HS") and any(marker in key_str for marker in cls.ASYMMETRIC_PEM_MARKERS):
            return False, "CWE-347 / CVE-2026-0265 Key Confusion Attack detectado: intento de verificar algoritmo HMAC ('HS*') usando una clave pública PEM/SSH."

        if "kid" in jwt_header:
            kid = str(jwt_header["kid"])
            if not re.fullmatch(r"[A-Za-z0-9_\-\.]{1,64}", kid) or ".." in kid or "/" in kid or "\\" in kid:
                return False, f"CWE-22 / CWE-347 JWT 'kid' Path Traversal / SQLi bloqueado: '{kid}'."
            if trusted_kids is not None and kid not in trusted_kids:
                return False, f"CWE-347 JWT 'kid' desconocido: '{kid}' no figura en el registro de claves confiables."

        return True, "Cabecera JWT verificada bajo RFC 8725 (libre de jku/x5u/jwk, kid traversal y confusión RS256->HS256)."

    @classmethod
    def verify_rsa_oaep_and_key_size(
        cls,
        padding_scheme: str,
        hash_algorithm: str,
        mgf1_hash_algorithm: str,
        modulus_bits: int,
    ) -> Tuple[bool, str]:
        pad = str(padding_scheme).upper().strip()
        if "PKCS1V15" in pad or "PKCS#1V1.5" in pad or pad == "V1_5":
            return False, "CWE-203 / CWE-780 Marvin & Bleichenbacher Padding Oracle: PKCS#1 v1.5 prohibido para cifrado; se exige RSA-OAEP."

        if "OAEP" not in pad:
            return False, f"CWE-780 Esquema de relleno RSA no seguro '{padding_scheme}'; se exige 'RSA-OAEP'."

        h_alg = str(hash_algorithm).upper().replace("-", "")
        m_alg = str(mgf1_hash_algorithm).upper().replace("-", "")
        if h_alg not in ("SHA256", "SHA384", "SHA512") or m_alg != h_alg:
            return False, f"RFC 8017 RSA-OAEP Hash débil o discordante: hash='{hash_algorithm}', mgf1='{mgf1_hash_algorithm}' (se exige SHA-256/384/512 simétrico)."

        if int(modulus_bits) < 2048:
            return False, f"NIST SP 800-57 RSA Modulus insuficiente ({modulus_bits} bits < 2048 bits)."

        return True, f"Esquema RSA-OAEP ({hash_algorithm}, {modulus_bits} bits) verificado contra oráculos Marvin/Bleichenbacher."

    @classmethod
    def verify_sri_and_cross_origin_headers(
        cls,
        external_script_tags: List[Dict[str, str]],
        response_headers: Dict[str, str],
    ) -> Tuple[bool, str]:
        for tag in external_script_tags:
            src = str(tag.get("src", "")).strip()
            if src.startswith(("http://", "https://", "//")):
                if src.startswith("http://"):
                    return False, f"CWE-319 Script externo sobre canal sin cifrar HTTP: '{src}'."
                integrity = str(tag.get("integrity", "")).strip()
                crossorigin = str(tag.get("crossorigin", "")).strip()
                if not integrity.startswith(("sha384-", "sha512-")) or len(integrity) < 50:
                    return False, f"CWE-353 / CWE-829 Missing Subresource Integrity (SRI): '{src}' carece de hash sha384-/sha512- válido."
                if crossorigin not in ("anonymous", "use-credentials"):
                    return False, f"CWE-353 SRI requiere atributo crossorigin='anonymous' en '{src}'."

        norm_h = {str(k).lower(): str(v).strip().lower() for k, v in (response_headers or {}).items()}
        if norm_h.get("cross-origin-opener-policy") != "same-origin":
            return False, "Falta cabecera Cross-Origin-Opener-Policy: same-origin (requerida contra ataques XS-Leaks / Spectre)."
        if norm_h.get("cross-origin-embedder-policy") not in ("require-corp", "credentialless"):
            return False, "Falta cabecera Cross-Origin-Embedder-Policy: require-corp."
        if norm_h.get("cross-origin-resource-policy") not in ("same-origin", "same-site"):
            return False, "Falta cabecera Cross-Origin-Resource-Policy: same-origin."

        return True, "Integridad SRI (SHA-384/512) y aislamiento Cross-Origin (COOP/COEP/CORP) verificados."

    @classmethod
    def audit_jwk_rsaoaep_and_sri_security(cls, source_code: str) -> JWKAlgorithmConfusionRSAOAEPSRIReport:
        t0 = time.perf_counter_ns()
        violations: List[JWKAlgorithmConfusionRSAOAEPSRIViolation] = []
        patches: List[Dict[str, str]] = []

        jwt_clean = True
        rsa_clean = True
        sri_clean = True

        try:
            tree = ast.parse(source_code)
        except SyntaxError as exc:
            dur = (time.perf_counter_ns() - t0) / 1_000_000.0
            return JWKAlgorithmConfusionRSAOAEPSRIReport(
                formal_jwk_rsaoaep_sri_safe=False,
                jwt_rfc8725_header_and_alg_clean=False,
                rsa_oaep_sha256_anti_marvin_clean=False,
                sri_and_cross_origin_isolation_clean=False,
                violations=[JWKAlgorithmConfusionRSAOAEPSRIViolation(
                    violation_type="SYNTAX_ERROR",
                    severity="CRITICAL",
                    location=f"line_{exc.lineno or 1}",
                    detail=str(exc),
                    suggested_patch="Corregir sintaxis Python antes de auditar."
                )],
                remediation_patches=[],
                analysis_duration_ms=round(dur, 3)
            )

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                call_src = ast.get_source_segment(source_code, node) or ""
                if "jwt.decode(" in call_src:
                    if ("HS256" in call_src and ("RS256" in call_src or "PUBLIC KEY" in source_code)) or "jku" in source_code:
                        violations.append(JWKAlgorithmConfusionRSAOAEPSRIViolation(
                            violation_type="JWT_ALGORITHM_CONFUSION_OR_JKU_INJECTION_CWE347",
                            severity="CRITICAL",
                            location=f"line_{node.lineno}",
                            detail="Decodificación JWT vulnerable a confusión de algoritmo RS256->HS256 o inyección de cabecera jku/kid (RFC 8725 / CVE-2026-0265).",
                            suggested_patch="Separar estrictamente algoritmos asimétricos y validar cabecera con verify_jwt_rfc8725_header_and_key_binding."
                        ))
                        jwt_clean = False

                if "PKCS1v15(" in call_src:
                    violations.append(JWKAlgorithmConfusionRSAOAEPSRIViolation(
                        violation_type="RSA_PKCS1V15_MARVIN_ORACLE_CWE780",
                        severity="CRITICAL",
                        location=f"line_{node.lineno}",
                        detail="Uso de padding.PKCS1v15() detectado; expone a ataques de canal lateral Marvin / Bleichenbacher (CWE-203 / CWE-780).",
                        suggested_patch="Reemplazar por padding.OAEP(mgf=padding.MGF1(algorithm=hashes.SHA256()), algorithm=hashes.SHA256(), label=None)."
                    ))
                    rsa_clean = False

        if "<script" in source_code and ("http://" in source_code or "https://" in source_code):
            if "integrity=" not in source_code or "sha384-" not in source_code:
                violations.append(JWKAlgorithmConfusionRSAOAEPSRIViolation(
                    violation_type="MISSING_SUBRESOURCE_INTEGRITY_CWE353",
                    severity="HIGH",
                    location="script_tag",
                    detail="Script externo cargado desde CDN sin hash Subresource Integrity (integrity='sha384-...' crossorigin='anonymous') (CWE-353).",
                    suggested_patch="Añadir integrity='sha384-...' y crossorigin='anonymous', más cabeceras COOP/COEP/CORP."
                ))
                sri_clean = False

        if not jwt_clean:
            patches.append({
                "strategy": "RFC8725_STRICT_JWT_KEY_AND_HEADER_GUARD",
                "fix": "ok, msg = JWKHeaderInjectionAlgorithmConfusionRSAOAEPAndSRICrossOriginProver.verify_jwt_rfc8725_header_and_key_binding(hdr, {'RS256'}, pub_key, trusted_kids)\nif not ok: raise PermissionError(msg)"
            })
        if not rsa_clean:
            patches.append({
                "strategy": "RSA_OAEP_SHA256_MGF1_ENFORCEMENT",
                "fix": "pad = padding.OAEP(mgf=padding.MGF1(algorithm=hashes.SHA256()), algorithm=hashes.SHA256(), label=None)"
            })
        if not sri_clean:
            patches.append({
                "strategy": "W3C_SRI_SHA384_AND_CROSS_ORIGIN_ISOLATION",
                "fix": "<script src='https://cdn.example.com/app.js' integrity='sha384-...' crossorigin='anonymous'></script>"
            })

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = (len(violations) == 0)

        return JWKAlgorithmConfusionRSAOAEPSRIReport(
            formal_jwk_rsaoaep_sri_safe=safe,
            jwt_rfc8725_header_and_alg_clean=jwt_clean,
            rsa_oaep_sha256_anti_marvin_clean=rsa_clean,
            sri_and_cross_origin_isolation_clean=sri_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3)
        )



