class TLS13ZeroRTTXSLeaksCOOPCORPAndURLParserSSRFProver:
    """
    NIVEL 89 (v9.2.0): Demostrador Formal Unificado de Protección Anti-Replay
    TLS 1.3 0-RTT Early Data (RFC 8446 §8 / RFC 8470 HTTP 425 Too Early y ALPN
    estricto contra ALPACA), Aislamiento Cross-Origin Anti-XS-Leaks (COOP, CORP,
    COEP y Fetch Metadata Sec-Fetch-Site) y Prevención de SSRF por Diferenciales
    de Parsers URL (@, backslash) y Ofuscación IPv4 Octal/Hex/Dword (CWE-918).
    """

    APPROVED_TLS_VERSIONS = {"TLSV1.2", "TLSV1.3"}
    SAFE_EARLY_DATA_METHODS = {"GET", "HEAD", "OPTIONS"}

    @classmethod
    def verify_tls13_zero_rtt_and_alpn_policy(
        cls,
        tls_version: str = "TLSv1.3",
        early_data_enabled: bool = False,
        http_method: str = "GET",
        early_data_header: str = "0",
        returns_425_on_unsafe_early_data: bool = True,
        has_anti_replay_strike_register: bool = True,
        strict_alpn_negotiation: bool = True,
    ) -> Tuple[bool, str]:
        ver_norm = (tls_version or "").strip().upper().replace(" ", "")
        if ver_norm not in cls.APPROVED_TLS_VERSIONS:
            return (
                False,
                f"Versión de protocolo '{tls_version}' obsoleta o insegura (RFC 8996): se exige TLSv1.2 o TLSv1.3.",
            )
        if not strict_alpn_negotiation:
            return (
                False,
                "Falta negociación estricta ALPN (RFC 7301): expone el servidor a ataques cross-protocolo ALPACA (CVE-2021-3618).",
            )
        method_norm = (http_method or "GET").strip().upper()
        is_early = early_data_enabled or str(early_data_header).strip() == "1"
        if is_early:
            if not has_anti_replay_strike_register:
                return (
                    False,
                    "Violación RFC 8446 §8: TLS 1.3 0-RTT habilitado sin Strike Register / caché Anti-Replay de tickets de sesión.",
                )
            if method_norm not in cls.SAFE_EARLY_DATA_METHODS and not returns_425_on_unsafe_early_data:
                return (
                    False,
                    f"Vulnerabilidad de Replay 0-RTT (RFC 8470): petición '{method_norm}' con Early-Data aceptada sin responder HTTP 425 Too Early.",
                )
        return (
            True,
            "Política TLS 1.3 0-RTT Anti-Replay (RFC 8446 / RFC 8470) y negociación ALPN verificadas.",
        )

    @classmethod
    def verify_xsleaks_coop_corp_and_fetch_metadata_policy(
        cls,
        coop_header: str = "same-origin",
        corp_header: str = "same-origin",
        coep_header: str = "require-corp",
        sec_fetch_site: str = "same-origin",
        sec_fetch_mode: str = "cors",
        is_state_changing_or_sensitive: bool = True,
    ) -> Tuple[bool, str]:
        coop_norm = (coop_header or "").strip().lower()
        if coop_norm not in {"same-origin", "same-origin-allow-popups"}:
            return (
                False,
                f"Cabecera Cross-Origin-Opener-Policy '{coop_header}' insegura: permite retener referencias window.opener y ataques XS-Leaks de conteo de frames.",
            )
        corp_norm = (corp_header or "").strip().lower()
        if corp_norm not in {"same-origin", "same-site"}:
            return (
                False,
                f"Cabecera Cross-Origin-Resource-Policy '{corp_header}' débil: permite inclusión cross-origin y sondeo XS-Leaks de eventos de error/carga.",
            )
        coep_norm = (coep_header or "").strip().lower()
        if coep_norm not in {"require-corp", "credentialless"}:
            return (
                False,
                f"Cabecera Cross-Origin-Embedder-Policy '{coep_header}' insuficiente para aislamiento de proceso cross-origin.",
            )
        sfs_norm = (sec_fetch_site or "").strip().lower()
        sfm_norm = (sec_fetch_mode or "").strip().lower()
        if is_state_changing_or_sensitive and sfs_norm == "cross-site":
            if sfm_norm != "navigate":
                return (
                    False,
                    f"Violación de política Fetch Metadata Anti-XS-Leaks: petición sensible con Sec-Fetch-Site='cross-site' y Sec-Fetch-Mode='{sfm_norm}' no fue rechazada.",
                )
        return (
            True,
            "Aislamiento Cross-Origin (COOP, CORP, COEP) y política Fetch Metadata Anti-XS-Leaks verificados.",
        )

    @classmethod
    def verify_url_parser_and_ip_obfuscation_ssrf(
        cls,
        raw_url: str,
    ) -> Tuple[bool, str]:
        u = (raw_url or "").strip()
        if not u:
            return (False, "URL vacía en verificador Anti-SSRF.")
        u_low = u.lower()
        if chr(92) in u or "%5c" in u_low:
            return (
                False,
                f"Diferencial de parser URL detectado en '{raw_url}': contiene barra invertida ('\\' / '%5c') que provoca discrepancia de autoridad entre WHATWG y RFC 3986 (CWE-918).",
            )
        if not (u_low.startswith("https://") or u_low.startswith("http://")):
            return (False, f"Esquema de URL no permitido en '{raw_url}'.")

        after_scheme = u.split("://", 1)[1]
        if after_scheme.startswith("/"):
            return (
                False,
                f"Anomalía triple-slash en autoridad de URL '{raw_url}' (bypass de parser URL).",
            )
        authority = after_scheme.split("/", 1)[0].split("?", 1)[0].split("#", 1)[0]
        if "@" in authority or "%40" in authority.lower():
            return (
                False,
                f"Confusión de autoridad URL mediante credencial '@' detectada en '{raw_url}' (HackerOne #3887969 / CWE-918).",
            )
        host = authority.split(":", 1)[0].strip().lower()
        if not host:
            return (False, "Host vacío en URL.")

        if host.isdigit():
            return (
                False,
                f"Ofuscación IPv4 en formato entero decimal Dword ('{host}') detectada en '{raw_url}' (CWE-918).",
            )
        if host.startswith("0x") or ".0x" in host:
            return (
                False,
                f"Ofuscación IPv4 en formato hexadecimal ('{host}') detectada en '{raw_url}' (CWE-918).",
            )

        labels = host.split(".")
        if all(lbl.isdigit() for lbl in labels):
            if len(labels) != 4:
                return (
                    False,
                    f"Notación IPv4 abreviada de {len(labels)} partes ('{host}') prohibida contra bypass SSRF.",
                )
            for lbl in labels:
                if len(lbl) > 1 and lbl.startswith("0"):
                    return (
                        False,
                        f"Ofuscación IPv4 en base octal ('{lbl}' en '{host}') detectada (CWE-918).",
                    )
            ok_ip, reason_ip = PQCKyberSlashCookiePrefixCRLFAndDNSRebindingTOCTOUProver._is_public_ip(host)
            if not ok_ip:
                return (False, f"IP literal bloqueada por Anti-SSRF: {reason_ip}")

        return (
            True,
            f"URL '{raw_url}' libre de diferenciales de parser (@/backslash) y de ofuscación IPv4 octal/hex/dword.",
        )

    @classmethod
    def audit_tls13_xsleaks_and_urlparser_ssrf(
        cls,
        source_code: str = "",
        tls13_config: Optional[Dict[str, Any]] = None,
        xsleaks_context: Optional[Dict[str, Any]] = None,
        url_ssrf_context: Optional[Dict[str, Any]] = None,
    ) -> TLS13XSLeaksURLParserReport:
        t0 = time.perf_counter_ns()
        violations: List[TLS13XSLeaksURLParserViolation] = []
        patches: List[Dict[str, str]] = []

        tls_clean = True
        xsleaks_clean = True
        url_clean = True

        if tls13_config is not None:
            ok_t, msg_t = cls.verify_tls13_zero_rtt_and_alpn_policy(
                tls_version=str(tls13_config.get("tls_version", "TLSv1.3")),
                early_data_enabled=bool(tls13_config.get("early_data_enabled", False)),
                http_method=str(tls13_config.get("http_method", "GET")),
                early_data_header=str(tls13_config.get("early_data_header", "0")),
                returns_425_on_unsafe_early_data=bool(
                    tls13_config.get("returns_425_on_unsafe_early_data", True)
                ),
                has_anti_replay_strike_register=bool(
                    tls13_config.get("has_anti_replay_strike_register", True)
                ),
                strict_alpn_negotiation=bool(tls13_config.get("strict_alpn_negotiation", True)),
            )
            if not ok_t:
                tls_clean = False
                violations.append(
                    TLS13XSLeaksURLParserViolation(
                        violation_type="TLS13_ZERO_RTT_REPLAY_OR_ALPN_VIOLATION",
                        severity="CRITICAL",
                        location="tls13_config",
                        detail=msg_t,
                        suggested_patch="Rechazar Early-Data en métodos no idempotentes con HTTP 425 Too Early (RFC 8470), activar Strike Register y fijar ALPN.",
                    )
                )

        if xsleaks_context is not None:
            ok_x, msg_x = cls.verify_xsleaks_coop_corp_and_fetch_metadata_policy(
                coop_header=str(xsleaks_context.get("coop_header", "same-origin")),
                corp_header=str(xsleaks_context.get("corp_header", "same-origin")),
                coep_header=str(xsleaks_context.get("coep_header", "require-corp")),
                sec_fetch_site=str(xsleaks_context.get("sec_fetch_site", "same-origin")),
                sec_fetch_mode=str(xsleaks_context.get("sec_fetch_mode", "cors")),
                is_state_changing_or_sensitive=bool(
                    xsleaks_context.get("is_state_changing_or_sensitive", True)
                ),
            )
            if not ok_x:
                xsleaks_clean = False
                violations.append(
                    TLS13XSLeaksURLParserViolation(
                        violation_type="XSLEAKS_COOP_CORP_OR_FETCH_METADATA_VIOLATION",
                        severity="HIGH",
                        location="xsleaks_context",
                        detail=msg_x,
                        suggested_patch="Enviar COOP: same-origin, CORP: same-origin, COEP: require-corp y bloquear Sec-Fetch-Site: cross-site en endpoints sensibles.",
                    )
                )

        if url_ssrf_context is not None:
            candidate_urls = url_ssrf_context.get("candidate_urls", [])
            if isinstance(candidate_urls, str):
                candidate_urls = [candidate_urls]
            for cu in candidate_urls:
                ok_u, msg_u = cls.verify_url_parser_and_ip_obfuscation_ssrf(str(cu))
                if not ok_u:
                    url_clean = False
                    violations.append(
                        TLS13XSLeaksURLParserViolation(
                            violation_type="URL_PARSER_DIFFERENTIAL_OR_IP_OBFUSCATION_SSRF",
                            severity="CRITICAL",
                            location="url_ssrf_context",
                            detail=msg_u,
                            suggested_patch="Normalizar y rechazar URLs con '@', '\\', o IPs en formato octal/hex/dword/abreviado antes de resolver DNS.",
                        )
                    )

        if source_code and source_code.strip():
            low_src = source_code.lower()
            if "early-data" in low_src and "post" in low_src and "425" not in source_code:
                tls_clean = False
                violations.append(
                    TLS13XSLeaksURLParserViolation(
                        violation_type="AST_TLS13_EARLY_DATA_POST_WITHOUT_425",
                        severity="HIGH",
                        location="ast_early_data_handler",
                        detail="Endpoint procesa peticiones POST con Early-Data sin emitir HTTP 425 Too Early (RFC 8470).",
                        suggested_patch="Verificar cabecera Early-Data == '1' y retornar 425 Too Early en métodos mutadores.",
                    )
                )

            if "unsafe-none" in low_src and "cross-origin-opener-policy" in low_src:
                xsleaks_clean = False
                violations.append(
                    TLS13XSLeaksURLParserViolation(
                        violation_type="AST_COOP_UNSAFE_NONE_XSLEAKS",
                        severity="HIGH",
                        location="ast_response_headers",
                        detail="Cross-Origin-Opener-Policy configurado en 'unsafe-none' expone referencias window.opener a ataques XS-Leaks.",
                        suggested_patch="Configurar Cross-Origin-Opener-Policy: same-origin y Cross-Origin-Resource-Policy: same-origin.",
                    )
                )

            if ("0177.0.0.1" in source_code or "2130706433" in source_code or "0x7f000001" in low_src) and (
                "verify_url_parser_and_ip_obfuscation_ssrf" not in source_code
            ):
                url_clean = False
                violations.append(
                    TLS13XSLeaksURLParserViolation(
                        violation_type="AST_OBFUSCATED_IPV4_SSRF_LITERAL",
                        severity="CRITICAL",
                        location="ast_url_target",
                        detail="Presencia de literal IPv4 ofuscado (octal/dword/hex) sin validación canónica Anti-SSRF.",
                        suggested_patch="Invocar verify_url_parser_and_ip_obfuscation_ssrf antes de abrir conexiones.",
                    )
                )

        if not tls_clean:
            patches.append(
                {
                    "strategy": "RFC8470_EARLY_DATA_425_AND_STRICT_ALPN",
                    "fix": "ok, msg = TLS13ZeroRTTXSLeaksCOOPCORPAndURLParserSSRFProver.verify_tls13_zero_rtt_and_alpn_policy('TLSv1.3', False, 'POST', '0', True, True, True)",
                }
            )
        if not xsleaks_clean:
            patches.append(
                {
                    "strategy": "COOP_CORP_COEP_AND_SEC_FETCH_ISOLATION",
                    "fix": "ok, msg = TLS13ZeroRTTXSLeaksCOOPCORPAndURLParserSSRFProver.verify_xsleaks_coop_corp_and_fetch_metadata_policy('same-origin', 'same-origin', 'require-corp', 'same-origin', 'cors', True)",
                }
            )
        if not url_clean:
            patches.append(
                {
                    "strategy": "CANONICAL_URL_AUTHORITY_AND_IPV4_NORMALIZATION",
                    "fix": "ok, msg = TLS13ZeroRTTXSLeaksCOOPCORPAndURLParserSSRFProver.verify_url_parser_and_ip_obfuscation_ssrf(url)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return TLS13XSLeaksURLParserReport(
            formal_tls13_xsleaks_urlparser_safe=safe,
            tls13_zero_rtt_and_alpn_clean=tls_clean,
            xsleaks_coop_corp_and_sec_fetch_clean=xsleaks_clean,
            url_parser_differential_and_ip_obfuscation_clean=url_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )


