class JWERFC8725bisECDHESCSPBaseURIAndEnvoyMeshSSRFProver:
    """
    NIVEL 90 (v9.3.0): Demostrador Formal Unificado de Seguridad JWE RFC 8725bis /
    RFC 7516 (Validación de Punto en Curva ECDH-ES epk, Cota de Iteraciones PBES2
    p2c <= 310000, Límite de Descompresión zip:DEF <= 250 KB y Prohibición RSA1_5),
    Directivas de Documento CSP (base-uri 'none'/'self', object-src 'none',
    form-action y Anti-Dangling-Markup) y Aislamiento Anti-SSRF en Sidecars
    Envoy/Istio (puertos 15000/9901 /quitquitquit /certs) y DNS Interno Kubernetes
    (*.svc.cluster.local / Kubelet 10250) (CWE-918).
    """

    APPROVED_JWE_ENCS = {
        "A128GCM",
        "A192GCM",
        "A256GCM",
        "A128CBC-HS256",
        "A192CBC-HS384",
        "A256CBC-HS512",
    }

    FORBIDDEN_MESH_AND_K8S_PORTS = {
        15000,
        15001,
        15020,
        9901,
        10250,
        10255,
        2379,
    }

    @classmethod
    def verify_jwe_rfc8725bis_policy(
        cls,
        alg: str = "ECDH-ES+A256KW",
        enc: str = "A256GCM",
        p2c_iterations: int = 0,
        validates_epk_on_curve: bool = True,
        zip_enabled: bool = False,
        max_decompressed_bytes: int = 250000,
    ) -> Tuple[bool, str]:
        alg_norm = (alg or "").strip().upper()
        enc_norm = (enc or "").strip().upper()
        if not alg_norm or alg_norm in {"RSA1_5", "RSA-PKCS1V15", "NONE"}:
            return (
                False,
                f"Algoritmo JWE '{alg}' prohibido por RFC 8725bis §3.2 (vulnerable a oráculo de Bleichenbacher).",
            )
        if enc_norm not in cls.APPROVED_JWE_ENCS:
            return (
                False,
                f"Algoritmo de cifrado de contenido JWE '{enc}' no aprobado por RFC 7518.",
            )
        if "ECDH-ES" in alg_norm and not validates_epk_on_curve:
            return (
                False,
                "Violación RFC 8725bis §2.5 / §3.4: falta verificar que la clave pública efímera 'epk' en ECDH-ES pertenezca a la curva elíptica (ataque de curva inválida).",
            )
        if "PBES2" in alg_norm:
            if p2c_iterations < 1000 or p2c_iterations > 310000:
                return (
                    False,
                    f"Parámetro JWE PBES2 'p2c' fuera de rango seguro ({p2c_iterations}): RFC 8725bis §2.10 / §3.13 exige acotar las iteraciones para impedir denegación de servicio por CPU.",
                )
        if zip_enabled and (max_decompressed_bytes <= 0 or max_decompressed_bytes > 256000):
            return (
                False,
                f"Vulnerabilidad JWE Decompression Bomb (RFC 8725bis §2.12 / §3.15): 'zip=DEF' habilitado con límite={max_decompressed_bytes} bytes (> 250 KB recomendados).",
            )
        return (
            True,
            "Política JWE RFC 8725bis verificada (sin RSA1_5, epk validada en curva, p2c acotado y descompresión limitada <= 250 KB).",
        )

    @classmethod
    def verify_csp_base_uri_and_dangling_markup_policy(
        cls,
        base_uri: str = "'none'",
        object_src: str = "'none'",
        form_action: str = "'self'",
        blocks_dangling_markup_and_meta_refresh: bool = True,
    ) -> Tuple[bool, str]:
        bu = (base_uri or "").strip().lower()
        if bu not in {"'none'", "'self'"}:
            return (
                False,
                f"Directiva CSP base-uri '{base_uri}' insegura (OWASP CSP Cheat Sheet): permite inyección de <base href='https://attacker.com/'> y secuestro de scripts relativos.",
            )
        ob = (object_src or "").strip().lower()
        if ob != "'none'":
            return (
                False,
                f"Directiva CSP object-src '{object_src}' insegura: se exige object-src 'none' en políticas estrictas.",
            )
        fa = (form_action or "").strip().lower()
        if not fa or fa == "*" or "unsafe" in fa:
            return (
                False,
                f"Directiva CSP form-action '{form_action}' débil: permite exfiltración de formularios a orígenes arbitrarios.",
            )
        if not blocks_dangling_markup_and_meta_refresh:
            return (
                False,
                "Falta bloqueo de Dangling Markup (<img src='https://attacker.com?') y redirecciones <meta http-equiv='refresh'>.",
            )
        return (
            True,
            "Directivas de documento CSP (base-uri, object-src, form-action) y defensa Anti-Dangling-Markup verificadas.",
        )

    @classmethod
    def verify_envoy_mesh_and_k8s_ssrf_policy(
        cls,
        target_host: str = "api.partner.example.com",
        target_port: int = 443,
        envoy_admin_allow_paths_restricted: bool = True,
        automount_service_account_token: bool = False,
    ) -> Tuple[bool, str]:
        h_low = (target_host or "").strip().lower().rstrip(".")
        if (
            h_low.endswith(".svc.cluster.local")
            or h_low.endswith(".svc")
            or h_low == "kubernetes.default"
            or h_low.startswith("kubernetes.default.")
        ):
            return (
                False,
                f"Destino SSRF apunta a DNS interno del clúster Kubernetes ('{target_host}', CWE-918).",
            )
        if target_port in cls.FORBIDDEN_MESH_AND_K8S_PORTS:
            return (
                False,
                f"Puerto de destino {target_port} corresponde a interfaz administrativa interna de Envoy/Istio (15000/9901), Kubelet (10250/10255) o etcd (2379) (CWE-918).",
            )
        if not envoy_admin_allow_paths_restricted:
            return (
                False,
                "Interfaz administrativa de Envoy (127.0.0.1:9901 / :15000) expone rutas críticas (/quitquitquit, /config_dump, /certs) sin restricción allow_paths.",
            )
        if automount_service_account_token:
            return (
                False,
                "Pod monta automáticamente el token de ServiceAccount (automountServiceAccountToken=True), exponiendo credenciales del API Server ante SSRF/LFI.",
            )
        return (
            True,
            "Aislamiento Anti-SSRF de sidecar Envoy/Istio, puertos de control-plane y ServiceAccount de Kubernetes verificado.",
        )

    @classmethod
    def audit_jwe_csp_baseuri_and_envoy_ssrf(
        cls,
        source_code: str = "",
        jwe_config: Optional[Dict[str, Any]] = None,
        csp_document_context: Optional[Dict[str, Any]] = None,
        envoy_k8s_context: Optional[Dict[str, Any]] = None,
    ) -> JWECSPBaseURIEnvoyReport:
        t0 = time.perf_counter_ns()
        violations: List[JWECSPBaseURIEnvoyViolation] = []
        patches: List[Dict[str, str]] = []

        jwe_clean = True
        csp_clean = True
        mesh_clean = True

        if jwe_config is not None:
            ok_j, msg_j = cls.verify_jwe_rfc8725bis_policy(
                alg=str(jwe_config.get("alg", "ECDH-ES+A256KW")),
                enc=str(jwe_config.get("enc", "A256GCM")),
                p2c_iterations=int(jwe_config.get("p2c_iterations", 0)),
                validates_epk_on_curve=bool(jwe_config.get("validates_epk_on_curve", True)),
                zip_enabled=bool(jwe_config.get("zip_enabled", False)),
                max_decompressed_bytes=int(jwe_config.get("max_decompressed_bytes", 250000)),
            )
            if not ok_j:
                jwe_clean = False
                violations.append(
                    JWECSPBaseURIEnvoyViolation(
                        violation_type="JWE_RFC8725BIS_ECDHES_P2C_OR_ZIP_VIOLATION",
                        severity="CRITICAL",
                        location="jwe_config",
                        detail=msg_j,
                        suggested_patch="Prohibir RSA1_5, validar epk en curva para ECDH-ES, acotar p2c <= 310000 y limitar descompresión JWE a <= 250 KB.",
                    )
                )

        if csp_document_context is not None:
            ok_c, msg_c = cls.verify_csp_base_uri_and_dangling_markup_policy(
                base_uri=str(csp_document_context.get("base_uri", "'none'")),
                object_src=str(csp_document_context.get("object_src", "'none'")),
                form_action=str(csp_document_context.get("form_action", "'self'")),
                blocks_dangling_markup_and_meta_refresh=bool(
                    csp_document_context.get("blocks_dangling_markup_and_meta_refresh", True)
                ),
            )
            if not ok_c:
                csp_clean = False
                violations.append(
                    JWECSPBaseURIEnvoyViolation(
                        violation_type="CSP_BASE_URI_OR_DANGLING_MARKUP_VIOLATION",
                        severity="HIGH",
                        location="csp_document_context",
                        detail=msg_c,
                        suggested_patch="Declarar base-uri 'none'; object-src 'none'; form-action 'self' y bloquear etiquetas <base> y <meta http-equiv='refresh'>.",
                    )
                )

        if envoy_k8s_context is not None:
            ok_m, msg_m = cls.verify_envoy_mesh_and_k8s_ssrf_policy(
                target_host=str(envoy_k8s_context.get("target_host", "api.partner.example.com")),
                target_port=int(envoy_k8s_context.get("target_port", 443)),
                envoy_admin_allow_paths_restricted=bool(
                    envoy_k8s_context.get("envoy_admin_allow_paths_restricted", True)
                ),
                automount_service_account_token=bool(
                    envoy_k8s_context.get("automount_service_account_token", False)
                ),
            )
            if not ok_m:
                mesh_clean = False
                violations.append(
                    JWECSPBaseURIEnvoyViolation(
                        violation_type="ENVOY_ADMIN_OR_K8S_CLUSTER_SSRF_CWE918",
                        severity="CRITICAL",
                        location="envoy_k8s_context",
                        detail=msg_m,
                        suggested_patch="Bloquear *.svc.cluster.local y puertos 15000/9901/10250/2379, restringir allow_paths en Envoy y fijar automountServiceAccountToken: false.",
                    )
                )

        if source_code and source_code.strip():
            low_src = source_code.lower()
            if '"rsa1_5"' in low_src or "'rsa1_5'" in low_src:
                jwe_clean = False
                violations.append(
                    JWECSPBaseURIEnvoyViolation(
                        violation_type="AST_JWE_DEPRECATED_RSA1_5_ORACLE",
                        severity="CRITICAL",
                        location="ast_jwe_decoder",
                        detail="Aceptación de algoritmo JWE 'RSA1_5' expone a ataques de Bleichenbacher (RFC 8725bis §3.2).",
                        suggested_patch="Sustituir RSA1_5 por ECDH-ES+A256KW o RSA-OAEP-256 con validación de curva.",
                    )
                )

            if ("15000/quitquitquit" in low_src or "9901/config_dump" in low_src or ".svc.cluster.local" in low_src) and (
                "verify_envoy_mesh_and_k8s_ssrf_policy" not in source_code
            ):
                mesh_clean = False
                violations.append(
                    JWECSPBaseURIEnvoyViolation(
                        violation_type="AST_ENVOY_SIDECAR_OR_K8S_INTERNAL_SSRF",
                        severity="CRITICAL",
                        location="ast_mesh_client",
                        detail="Invocación hacia puerto administrativo de Envoy (15000/9901) o servicio interno .svc.cluster.local detectada.",
                        suggested_patch="Validar destino y puerto con verify_envoy_mesh_and_k8s_ssrf_policy.",
                    )
                )

        if not jwe_clean:
            patches.append(
                {
                    "strategy": "RFC8725BIS_JWE_ECDHES_P2C_AND_ZIP_GUARD",
                    "fix": "ok, msg = JWERFC8725bisECDHESCSPBaseURIAndEnvoyMeshSSRFProver.verify_jwe_rfc8725bis_policy('ECDH-ES+A256KW', 'A256GCM', 0, True, False, 250000)",
                }
            )
        if not csp_clean:
            patches.append(
                {
                    "strategy": "STRICT_CSP_BASE_URI_NONE_AND_FORM_ACTION_SELF",
                    "fix": "ok, msg = JWERFC8725bisECDHESCSPBaseURIAndEnvoyMeshSSRFProver.verify_csp_base_uri_and_dangling_markup_policy("'none'", "'none'", "'self'", True)",
                }
            )
        if not mesh_clean:
            patches.append(
                {
                    "strategy": "ENVOY_ADMIN_ALLOW_PATHS_AND_K8S_SSRF_ISOLATION",
                    "fix": "ok, msg = JWERFC8725bisECDHESCSPBaseURIAndEnvoyMeshSSRFProver.verify_envoy_mesh_and_k8s_ssrf_policy(host, port, True, False)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return JWECSPBaseURIEnvoyReport(
            formal_jwe_csp_baseuri_envoy_safe=safe,
            jwe_rfc8725bis_ecdhes_p2c_and_zip_clean=jwe_clean,
            csp_base_uri_form_action_and_dangling_markup_clean=csp_clean,
            envoy_mesh_admin_and_k8s_ssrf_clean=mesh_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



