class SDJWTRFC9901CSPWorkerSrcAndUnixSocketDockerSSRFProver:
    """
    Nivel 91: Demostrador formal de Selective Disclosure JWT (SD-JWT / SD-JWT+KB RFC 9901),
    aislamiento CSP worker-src / Service-Worker-Allowed / Permissions-Policy y
    prevención de SSRF hacia sockets Unix locales (socketPath / http+unix:// / /var/run/docker.sock, CWE-918).
    """

    APPROVED_SD_ALGS = {"sha-256", "sha-384", "sha-512"}
    MIN_SALT_ENTROPY_BITS = 128
    SAFE_WORKER_SRC = {"'self'", "'none'"}
    REQUIRED_PERMISSIONS_DISABLED = ("camera=()", "microphone=()", "geolocation=()")
    FORBIDDEN_UDS_PATTERNS = (
        "/var/run/docker.sock",
        "/run/docker.sock",
        "/run/containerd/containerd.sock",
        "/var/run/crio/crio.sock",
        "/run/systemd/private",
        "http+unix://",
        "https+unix://",
        "unix://",
        "%2fvar%2frun%2fdocker.sock",
    )

    @classmethod
    def verify_sdjwt_rfc9901_policy(
        cls,
        sd_alg: str,
        min_salt_entropy_bits: int,
        reuses_disclosure_salts: bool,
        has_duplicate_or_shadowed_claims: bool,
        requires_kb_jwt: bool,
        verifies_kb_sd_hash: bool,
    ) -> Tuple[bool, str]:
        alg_norm = (sd_alg or "").strip().lower()
        if alg_norm not in cls.APPROVED_SD_ALGS:
            return False, f"Algoritmo _sd_alg '{sd_alg}' inseguro o no aprobado en RFC 9901 (exigir sha-256/sha-384/sha-512)."
        if int(min_salt_entropy_bits) < cls.MIN_SALT_ENTROPY_BITS:
            return False, f"Entropía de salt SD-JWT ({min_salt_entropy_bits} bits) inferior al mínimo de 128 bits (RFC 9901 Section 9.3)."
        if reuses_disclosure_salts:
            return False, "Reutilización de salts entre disclosures SD-JWT detectada; permite correlación y ataques de diccionario."
        if has_duplicate_or_shadowed_claims:
            return False, "Colisión/sombreado de claims entre el payload base y disclosures recursivos SD-JWT (Claim Shadowing)."
        if not requires_kb_jwt or not verifies_kb_sd_hash:
            return False, "Falta exigencia de Key-Binding JWT (typ=kb+jwt) o verificación criptográfica de sd_hash/nonce/aud."
        return True, "Política RFC 9901 SD-JWT y Key-Binding verificada formalmente."

    @classmethod
    def verify_csp_worker_src_and_permissions_policy(
        cls,
        worker_src: str,
        allows_root_service_worker_scope: bool,
        permissions_policy: str,
    ) -> Tuple[bool, str]:
        ws = (worker_src or "").strip().lower()
        if ws not in cls.SAFE_WORKER_SRC or "blob:" in ws or "data:" in ws or "*" in ws or "unsafe-inline" in ws:
            return False, f"Directiva CSP worker-src '{worker_src}' permite instanciar ServiceWorkers/SharedWorkers desde orígenes arbitrarios o blob:/data:."
        if allows_root_service_worker_scope:
            return False, "Cabecera Service-Worker-Allowed amplía el scope a '/' desde rutas no confiables (persistencia XSS vía ServiceWorker)."
        pp = (permissions_policy or "").strip().lower().replace(" ", "")
        for req_perm in cls.REQUIRED_PERMISSIONS_DISABLED:
            if req_perm not in pp:
                return False, f"Cabecera Permissions-Policy no bloquea explícitamente '{req_perm}' frente a delegación maliciosa."
        return True, "Aislamiento CSP worker-src, Service-Worker-Allowed y Permissions-Policy verificado."

    @classmethod
    def verify_unix_socket_and_docker_sock_ssrf_policy(
        cls,
        target_url: str,
        socket_path: str,
        allows_unix_socket_adapter: bool,
    ) -> Tuple[bool, str]:
        url_low = (target_url or "").strip().lower()
        sock_low = (socket_path or "").strip().lower()
        if allows_unix_socket_adapter:
            return False, "El cliente HTTP habilita adaptadores de Unix Domain Socket (socketPath / uds / http+unix://) para orígenes externos."
        if sock_low:
            return False, f"Parámetro socketPath/uds no vacío ('{socket_path}') permite puentear filtros IP y alcanzar daemons locales."
        for pat in cls.FORBIDDEN_UDS_PATTERNS:
            if pat in url_low or pat in sock_low:
                return False, f"Vector SSRF hacia Unix Domain Socket o daemon de contenedores detectado ('{pat}', CWE-918)."
        return True, "Transporte HTTP aislado contra SSRF vía Unix Domain Sockets y /var/run/docker.sock."

    @classmethod
    def audit_sdjwt_csp_worker_and_unix_socket_ssrf(
        cls,
        source_code: str = "",
        sdjwt_config: Optional[Dict[str, Any]] = None,
        csp_worker_context: Optional[Dict[str, Any]] = None,
        unix_socket_context: Optional[Dict[str, Any]] = None,
    ) -> SDJWTWorkerUDSReport:
        t0 = time.perf_counter_ns()
        violations: List[SDJWTWorkerUDSViolation] = []
        patches: List[Dict[str, str]] = []

        sdjwt_clean = True
        worker_clean = True
        uds_clean = True

        sd_cfg = sdjwt_config if sdjwt_config is not None else {
            "sd_alg": "sha-256",
            "min_salt_entropy_bits": 128,
            "reuses_disclosure_salts": False,
            "has_duplicate_or_shadowed_claims": False,
            "requires_kb_jwt": True,
            "verifies_kb_sd_hash": True,
        }
        ok_sd, msg_sd = cls.verify_sdjwt_rfc9901_policy(
            sd_alg=str(sd_cfg.get("sd_alg", "sha-256")),
            min_salt_entropy_bits=int(sd_cfg.get("min_salt_entropy_bits", 128)),
            reuses_disclosure_salts=bool(sd_cfg.get("reuses_disclosure_salts", False)),
            has_duplicate_or_shadowed_claims=bool(sd_cfg.get("has_duplicate_or_shadowed_claims", False)),
            requires_kb_jwt=bool(sd_cfg.get("requires_kb_jwt", True)),
            verifies_kb_sd_hash=bool(sd_cfg.get("verifies_kb_sd_hash", True)),
        )
        if not ok_sd:
            sdjwt_clean = False
            violations.append(
                SDJWTWorkerUDSViolation(
                    violation_type="SDJWT_RFC9901_SALT_KB_OR_SHADOWING_VIOLATION",
                    severity="CRITICAL",
                    location="sdjwt_config",
                    detail=msg_sd,
                    suggested_patch="Exigir _sd_alg='sha-256', salts CSPRNG >= 128 bits únicos, prohibir colisión de claims y verificar kb+jwt sd_hash.",
                )
            )

        wk_cfg = csp_worker_context if csp_worker_context is not None else {
            "worker_src": "'self'",
            "allows_root_service_worker_scope": False,
            "permissions_policy": "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
        }
        ok_wk, msg_wk = cls.verify_csp_worker_src_and_permissions_policy(
            worker_src=str(wk_cfg.get("worker_src", "'self'")),
            allows_root_service_worker_scope=bool(wk_cfg.get("allows_root_service_worker_scope", False)),
            permissions_policy=str(
                wk_cfg.get(
                    "permissions_policy",
                    "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
                )
            ),
        )
        if not ok_wk:
            worker_clean = False
            violations.append(
                SDJWTWorkerUDSViolation(
                    violation_type="CSP_WORKER_SRC_OR_PERMISSIONS_POLICY_WEAKNESS",
                    severity="HIGH",
                    location="csp_worker_context",
                    detail=msg_wk,
                    suggested_patch="Fijar worker-src 'self' o 'none', restringir Service-Worker-Allowed y declarar Permissions-Policy restrictivo.",
                )
            )

        uds_cfg = unix_socket_context if unix_socket_context is not None else {
            "target_url": "https://api.internal.example.com/v1/status",
            "socket_path": "",
            "allows_unix_socket_adapter": False,
        }
        ok_uds, msg_uds = cls.verify_unix_socket_and_docker_sock_ssrf_policy(
            target_url=str(uds_cfg.get("target_url", "https://api.internal.example.com/v1/status")),
            socket_path=str(uds_cfg.get("socket_path", "")),
            allows_unix_socket_adapter=bool(uds_cfg.get("allows_unix_socket_adapter", False)),
        )
        if not ok_uds:
            uds_clean = False
            violations.append(
                SDJWTWorkerUDSViolation(
                    violation_type="UNIX_DOMAIN_SOCKET_OR_DOCKER_SOCK_SSRF",
                    severity="CRITICAL",
                    location="unix_socket_context",
                    detail=msg_uds,
                    suggested_patch="Deshabilitar adaptadores Unix socket (socketPath='', allows_unix_socket_adapter=False) y bloquear /var/run/docker.sock.",
                )
            )

        if source_code:
            low_src = source_code.lower()
            if ("_sd_alg" in low_src and ("sha-1" in low_src or "md5" in low_src)) and (
                "verify_sdjwt_rfc9901_policy" not in source_code
            ):
                sdjwt_clean = False
                violations.append(
                    SDJWTWorkerUDSViolation(
                        violation_type="AST_SDJWT_WEAK_HASH_ALG",
                        severity="CRITICAL",
                        location="ast_sdjwt_verifier",
                        detail="Uso de algoritmo hash débil (SHA-1/MD5) en _sd_alg detectado en el AST.",
                        suggested_patch="Invocar verify_sdjwt_rfc9901_policy con _sd_alg='sha-256'.",
                    )
                )

            if ("/var/run/docker.sock" in low_src or "http+unix://" in low_src or "socketpath" in low_src) and (
                "verify_unix_socket_and_docker_sock_ssrf_policy" not in source_code
            ):
                uds_clean = False
                violations.append(
                    SDJWTWorkerUDSViolation(
                        violation_type="AST_UNIX_SOCKET_DOCKER_SSRF",
                        severity="CRITICAL",
                        location="ast_http_transport",
                        detail="Referencia directa a /var/run/docker.sock, http+unix:// o socketPath detectada en el AST.",
                        suggested_patch="Validar transporte HTTP con verify_unix_socket_and_docker_sock_ssrf_policy.",
                    )
                )

        if not sdjwt_clean:
            patches.append(
                {
                    "strategy": "RFC9901_SDJWT_CSPRNG_SALT_AND_KB_HASH_ENFORCEMENT",
                    "fix": "ok, msg = SDJWTRFC9901CSPWorkerSrcAndUnixSocketDockerSSRFProver.verify_sdjwt_rfc9901_policy('sha-256', 128, False, False, True, True)",
                }
            )
        if not worker_clean:
            patches.append(
                {
                    "strategy": "STRICT_CSP_WORKER_SRC_AND_PERMISSIONS_POLICY",
                    "fix": "ok, msg = SDJWTRFC9901CSPWorkerSrcAndUnixSocketDockerSSRFProver.verify_csp_worker_src_and_permissions_policy("'self'", False, 'camera=(), microphone=(), geolocation=()')",
                }
            )
        if not uds_clean:
            patches.append(
                {
                    "strategy": "UNIX_DOMAIN_SOCKET_AND_DOCKER_SOCK_SSRF_SHIELD",
                    "fix": "ok, msg = SDJWTRFC9901CSPWorkerSrcAndUnixSocketDockerSSRFProver.verify_unix_socket_and_docker_sock_ssrf_policy(target_url, '', False)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return SDJWTWorkerUDSReport(
            formal_sdjwt_worker_uds_safe=safe,
            sdjwt_rfc9901_salt_kb_and_claim_collision_clean=sdjwt_clean,
            csp_worker_src_serviceworker_and_permissions_policy_clean=worker_clean,
            unix_domain_socket_and_docker_sock_ssrf_clean=uds_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



