class COSERFC9052FetchMetadataAndHTTPConnectTunnelSSRFProver:
    """
    Nivel 92: Demostrador formal de CBOR Object Signing and Encryption (COSE RFC 9052 / CBOR RFC 8949:
    algoritmo en bucket protegido, prohibición de claves duplicadas en mapas CBOR y cota de longitud indefinida),
    aislamiento Cross-Site mediante Fetch Metadata Request Headers (W3C Sec-Fetch-Site / Sec-Fetch-Mode / Sec-Fetch-Dest + Vary)
    y prevención de SSRF por túneles HTTP CONNECT / Proxy-Authorization y Zone-IDs IPv6 (fe80::%25eth0, RFC 6874 / CWE-918).
    """

    APPROVED_COSE_ALGS = {"es256", "es384", "es512", "eddsa", "aes-gcm-256", "chacha20-poly1305"}
    ALLOWED_SEC_FETCH_SITE = {"same-origin", "same-site", "none"}
    REQUIRED_VARY_HEADERS = ("sec-fetch-site", "sec-fetch-mode", "sec-fetch-dest")
    FORBIDDEN_ZONE_OR_TUNNEL_PATTERNS = (
        "%25",
        "fe80:",
        "ff02:",
        "proxy-authorization",
        "x-forwarded-host",
    )

    @classmethod
    def verify_cose_rfc9052_and_cbor_rfc8949_policy(
        cls,
        cose_alg: str,
        alg_in_protected_header: bool,
        rejects_cbor_duplicate_map_keys: bool,
        rejects_cbor_indefinite_length_chunks: bool,
        verifies_crit_headers: bool,
    ) -> Tuple[bool, str]:
        alg_norm = (cose_alg or "").strip().lower()
        if alg_norm not in cls.APPROVED_COSE_ALGS:
            return False, f"Algoritmo COSE '{cose_alg}' no aprobado o inseguro en RFC 9052/9053."
        if not alg_in_protected_header:
            return False, "Parámetro COSE 'alg' ubicado en el bucket unprotected header (permite ataque de downgrade/algorithm confusion, RFC 9052 Section 3.1)."
        if not rejects_cbor_duplicate_map_keys:
            return False, "El decodificador CBOR acepta claves duplicadas en mapas (RFC 8949 Section 5.6), habilitando sombreado de claims/parámetros."
        if not rejects_cbor_indefinite_length_chunks:
            return False, "El decodificador CBOR permite strings/arrays de longitud indefinida sin cota (riesgo de agotamiento de memoria DoS)."
        if not verifies_crit_headers:
            return False, "Falta verificación estricta del parámetro protegido 'crit' (Critical Headers) en estructura COSE."
        return True, "Política criptográfica COSE RFC 9052 y decodificación determinista CBOR RFC 8949 verificada."

    @classmethod
    def verify_fetch_metadata_isolation_policy(
        cls,
        sec_fetch_site: str,
        sec_fetch_mode: str,
        sec_fetch_dest: str,
        is_state_changing_endpoint: bool,
        vary_header: str,
    ) -> Tuple[bool, str]:
        site = (sec_fetch_site or "").strip().lower()
        mode = (sec_fetch_mode or "").strip().lower()
        dest = (sec_fetch_dest or "").strip().lower()
        vary_low = (vary_header or "").strip().lower()

        if site not in cls.ALLOWED_SEC_FETCH_SITE:
            if is_state_changing_endpoint or mode == "no-cors" or dest in {"iframe", "embed", "object", "script"}:
                return False, f"Petición cross-site ('Sec-Fetch-Site: {sec_fetch_site}', mode='{sec_fetch_mode}', dest='{sec_fetch_dest}') hacia endpoint sensible sin bloqueo Resource Isolation."
        for req_v in cls.REQUIRED_VARY_HEADERS:
            if req_v not in vary_low:
                return False, f"Cabecera HTTP 'Vary' omite '{req_v}', permitiendo envenenamiento de caché (Cache Poisoning) de respuestas protegidas por Fetch Metadata."
        return True, "Política W3C Fetch Metadata (Sec-Fetch-Site/Mode/Dest + Vary) verificada formalmente."

    @classmethod
    def verify_http_connect_tunnel_and_ipv6_zone_ssrf_policy(
        cls,
        http_method: str,
        target_uri: str,
        allows_http_connect_tunnel: bool,
        allows_ipv6_zone_id: bool,
    ) -> Tuple[bool, str]:
        meth = (http_method or "GET").strip().upper()
        uri_low = (target_uri or "").strip().lower()
        if meth in {"CONNECT", "TRACE", "TRACK"} or allows_http_connect_tunnel:
            return False, f"Método o túnel HTTP '{meth}' habilitado (permite usar el servidor como proxy TCP arbitrario, CWE-918)."
        if allows_ipv6_zone_id or "%" in uri_low:
            for pat in cls.FORBIDDEN_ZONE_OR_TUNNEL_PATTERNS:
                if pat in uri_low:
                    return False, f"Vector SSRF vía IPv6 Zone-ID / Link-Local o cabecera de túnel detectado en URI ('{pat}', RFC 6874 / CWE-918)."
            if allows_ipv6_zone_id:
                return False, "El parser de red acepta identificadores de zona IPv6 (%eth0 / %25eth0, RFC 6874), exponiendo interfaces link-local fe80::/10."
        for pat in cls.FORBIDDEN_ZONE_OR_TUNNEL_PATTERNS:
            if pat in uri_low:
                return False, f"Patrón prohibido de direccionamiento link-local o túnel SSRF detectado ('{pat}')."
        return True, "Cliente HTTP blindado contra túneles HTTP CONNECT y evasión SSRF por IPv6 Zone-ID (fe80::%25)."

    @classmethod
    def audit_cose_fetch_metadata_and_connect_tunnel_ssrf(
        cls,
        source_code: str = "",
        cose_config: Optional[Dict[str, Any]] = None,
        fetch_metadata_context: Optional[Dict[str, Any]] = None,
        connect_tunnel_context: Optional[Dict[str, Any]] = None,
    ) -> COSEFetchMetaConnectReport:
        t0 = time.perf_counter_ns()
        violations: List[COSEFetchMetaConnectViolation] = []
        patches: List[Dict[str, str]] = []

        cose_clean = True
        fetch_clean = True
        tunnel_clean = True

        c_cfg = cose_config if cose_config is not None else {
            "cose_alg": "ES256",
            "alg_in_protected_header": True,
            "rejects_cbor_duplicate_map_keys": True,
            "rejects_cbor_indefinite_length_chunks": True,
            "verifies_crit_headers": True,
        }
        ok_cose, msg_cose = cls.verify_cose_rfc9052_and_cbor_rfc8949_policy(
            cose_alg=str(c_cfg.get("cose_alg", "ES256")),
            alg_in_protected_header=bool(c_cfg.get("alg_in_protected_header", True)),
            rejects_cbor_duplicate_map_keys=bool(c_cfg.get("rejects_cbor_duplicate_map_keys", True)),
            rejects_cbor_indefinite_length_chunks=bool(c_cfg.get("rejects_cbor_indefinite_length_chunks", True)),
            verifies_crit_headers=bool(c_cfg.get("verifies_crit_headers", True)),
        )
        if not ok_cose:
            cose_clean = False
            violations.append(
                COSEFetchMetaConnectViolation(
                    violation_type="COSE_RFC9052_UNPROTECTED_ALG_OR_CBOR_DUPLICATE_KEY",
                    severity="CRITICAL",
                    location="cose_config",
                    detail=msg_cose,
                    suggested_patch="Forzar alg en protected header COSE, rechazar claves duplicadas en mapas CBOR (RFC 8949) y prohibir longitudes indefinidas.",
                )
            )

        fm_cfg = fetch_metadata_context if fetch_metadata_context is not None else {
            "sec_fetch_site": "same-origin",
            "sec_fetch_mode": "cors",
            "sec_fetch_dest": "empty",
            "is_state_changing_endpoint": True,
            "vary_header": "Sec-Fetch-Site, Sec-Fetch-Mode, Sec-Fetch-Dest",
        }
        ok_fm, msg_fm = cls.verify_fetch_metadata_isolation_policy(
            sec_fetch_site=str(fm_cfg.get("sec_fetch_site", "same-origin")),
            sec_fetch_mode=str(fm_cfg.get("sec_fetch_mode", "cors")),
            sec_fetch_dest=str(fm_cfg.get("sec_fetch_dest", "empty")),
            is_state_changing_endpoint=bool(fm_cfg.get("is_state_changing_endpoint", True)),
            vary_header=str(fm_cfg.get("vary_header", "Sec-Fetch-Site, Sec-Fetch-Mode, Sec-Fetch-Dest")),
        )
        if not ok_fm:
            fetch_clean = False
            violations.append(
                COSEFetchMetaConnectViolation(
                    violation_type="FETCH_METADATA_CROSS_SITE_OR_VARY_WEAKNESS",
                    severity="HIGH",
                    location="fetch_metadata_context",
                    detail=msg_fm,
                    suggested_patch="Bloquear peticiones Sec-Fetch-Site: cross-site en endpoints mutantes y declarar Vary: Sec-Fetch-Site, Sec-Fetch-Mode, Sec-Fetch-Dest.",
                )
            )

        tun_cfg = connect_tunnel_context if connect_tunnel_context is not None else {
            "http_method": "GET",
            "target_uri": "https://api.internal.example.com/v1/health",
            "allows_http_connect_tunnel": False,
            "allows_ipv6_zone_id": False,
        }
        ok_tun, msg_tun = cls.verify_http_connect_tunnel_and_ipv6_zone_ssrf_policy(
            http_method=str(tun_cfg.get("http_method", "GET")),
            target_uri=str(tun_cfg.get("target_uri", "https://api.internal.example.com/v1/health")),
            allows_http_connect_tunnel=bool(tun_cfg.get("allows_http_connect_tunnel", False)),
            allows_ipv6_zone_id=bool(tun_cfg.get("allows_ipv6_zone_id", False)),
        )
        if not ok_tun:
            tunnel_clean = False
            violations.append(
                COSEFetchMetaConnectViolation(
                    violation_type="HTTP_CONNECT_TUNNEL_OR_IPV6_ZONE_SSRF",
                    severity="CRITICAL",
                    location="connect_tunnel_context",
                    detail=msg_tun,
                    suggested_patch="Prohibir método HTTP CONNECT/TRACE y rechazar identificadores de zona IPv6 (%25eth0 / fe80::) en URLs.",
                )
            )

        if source_code:
            low_src = source_code.lower()
            if ("unprotected_header" in low_src and "'alg'" in low_src) and (
                "verify_cose_rfc9052_and_cbor_rfc8949_policy" not in source_code
            ):
                cose_clean = False
                violations.append(
                    COSEFetchMetaConnectViolation(
                        violation_type="AST_COSE_UNPROTECTED_ALG_HEADER",
                        severity="CRITICAL",
                        location="ast_cose_verifier",
                        detail="Extracción de algoritmo 'alg' desde unprotected_header en estructura COSE detectada en el AST.",
                        suggested_patch="Extraer 'alg' exclusivamente del header protegido autenticado con verify_cose_rfc9052_and_cbor_rfc8949_policy.",
                    )
                )

            if ("fe80::" in low_src or "%25eth0" in low_src or 'method="connect"' in low_src) and (
                "verify_http_connect_tunnel_and_ipv6_zone_ssrf_policy" not in source_code
            ):
                tunnel_clean = False
                violations.append(
                    COSEFetchMetaConnectViolation(
                        violation_type="AST_IPV6_ZONE_OR_HTTP_CONNECT_SSRF",
                        severity="CRITICAL",
                        location="ast_http_client",
                        detail="Uso de dirección link-local con Zone-ID (fe80:: / %25eth0) o método HTTP CONNECT detectado en el AST.",
                        suggested_patch="Validar método y URI con verify_http_connect_tunnel_and_ipv6_zone_ssrf_policy.",
                    )
                )

        if not cose_clean:
            patches.append(
                {
                    "strategy": "RFC9052_COSE_PROTECTED_ALG_AND_RFC8949_CBOR_STRICT_MAP",
                    "fix": "ok, msg = COSERFC9052FetchMetadataAndHTTPConnectTunnelSSRFProver.verify_cose_rfc9052_and_cbor_rfc8949_policy('ES256', True, True, True, True)",
                }
            )
        if not fetch_clean:
            patches.append(
                {
                    "strategy": "W3C_FETCH_METADATA_RESOURCE_ISOLATION_POLICY",
                    "fix": "ok, msg = COSERFC9052FetchMetadataAndHTTPConnectTunnelSSRFProver.verify_fetch_metadata_isolation_policy('same-origin', 'cors', 'empty', True, 'Sec-Fetch-Site, Sec-Fetch-Mode, Sec-Fetch-Dest')",
                }
            )
        if not tunnel_clean:
            patches.append(
                {
                    "strategy": "HTTP_CONNECT_TUNNEL_AND_IPV6_ZONE_ID_SSRF_SHIELD",
                    "fix": "ok, msg = COSERFC9052FetchMetadataAndHTTPConnectTunnelSSRFProver.verify_http_connect_tunnel_and_ipv6_zone_ssrf_policy('GET', target_uri, False, False)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return COSEFetchMetaConnectReport(
            formal_cose_fetchmeta_connect_safe=safe,
            cose_rfc9052_protected_alg_and_cbor_det_clean=cose_clean,
            fetch_metadata_sec_fetch_and_vary_isolation_clean=fetch_clean,
            http_connect_tunnel_and_ipv6_zone_ssrf_clean=tunnel_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



@dataclass
class RFC9421ClearSiteConsulViolation:
    violation_type: str
    severity: str
    location: str
    detail: str
    suggested_patch: str

    def to_dict(self) -> Dict[str, Any]:
        return {
            "violation_type": self.violation_type,
            "severity": self.severity,
            "location": self.location,
            "detail": self.detail,
            "suggested_patch": self.suggested_patch,
        }


@dataclass
class RFC9421ClearSiteConsulReport:
    formal_rfc9421_clearsite_consul_safe: bool
    http_message_sig_rfc9421_components_and_replay_clean: bool
    clear_site_data_and_speculation_rules_isolation_clean: bool
    etcd_consul_mdns_discovery_ssrf_clean: bool
    violations: List[RFC9421ClearSiteConsulViolation]
    remediation_patches: List[Dict[str, str]]
    analysis_duration_ms: float

    def to_dict(self) -> Dict[str, Any]:
        return {
            "formal_rfc9421_clearsite_consul_safe": self.formal_rfc9421_clearsite_consul_safe,
            "http_message_sig_rfc9421_components_and_replay_clean": self.http_message_sig_rfc9421_components_and_replay_clean,
            "clear_site_data_and_speculation_rules_isolation_clean": self.clear_site_data_and_speculation_rules_isolation_clean,
            "etcd_consul_mdns_discovery_ssrf_clean": self.etcd_consul_mdns_discovery_ssrf_clean,
            "violations": [v.to_dict() for v in self.violations],
            "remediation_patches": self.remediation_patches,
            "analysis_duration_ms": self.analysis_duration_ms,
        }


class HTTPMessageSigRFC9421ClearSiteDataAndConsulEtcdSSRFProver:
    """
    Nivel 93: Demostrador formal de HTTP Message Signatures (RFC 9421: componentes cubiertos obligatorios
    @method, @authority, @target-uri, content-digest, ventana anti-replay expires - created <= 300s y alg explícito),
    purga criptográfica de sesión mediante Clear-Site-Data ("cache", "cookies", "storage") + Speculation-Rules
    same-origin y prevención de SSRF hacia planos de descubrimiento interno Consul (8500), etcd (2379) y mDNS (.local / 5353, CWE-918).
    """

    REQUIRED_RFC9421_COMPONENTS = ("@method", "@authority", "@target-uri", "content-digest")
    APPROVED_RFC9421_ALGS = {
        "ed25519",
        "ecdsa-p256-sha256",
        "ecdsa-p384-sha384",
        "rsa-pss-sha512",
    }
    MAX_SIGNATURE_TTL_SECONDS = 300
    REQUIRED_CLEAR_SITE_DIRECTIVES = ('"cookies"', '"storage"')
    FORBIDDEN_DISCOVERY_PORTS = {2379, 2380, 5353, 8500, 8501}
    FORBIDDEN_DISCOVERY_PATTERNS = (
        ":2379",
        ":8500",
        "/v3/kv/",
        "/v1/kv/",
        "/v1/agent/",
        ".local",
        "224.0.0.251",
    )

    @classmethod
    def verify_http_message_sig_rfc9421_policy(
        cls,
        covered_components: List[str],
        sig_alg: str,
        signature_ttl_seconds: int,
        has_unique_nonce: bool,
        verifies_content_digest_sha256: bool,
    ) -> Tuple[bool, str]:
        alg_norm = (sig_alg or "").strip().lower()
        if alg_norm not in cls.APPROVED_RFC9421_ALGS:
            return False, f"Algoritmo RFC 9421 '{sig_alg}' inseguro o ambiguo (prohibido hmac-sha256 compartido o rsa-v1_5 en bordes zero-trust)."
        comp_set = {str(c).strip().lower() for c in (covered_components or [])}
        for req_c in cls.REQUIRED_RFC9421_COMPONENTS:
            if req_c not in comp_set:
                return False, f"Signature-Input RFC 9421 omite el componente derivado obligatorio '{req_c}' (vulnerable a Request Routing / Method Tampering)."
        if int(signature_ttl_seconds) <= 0 or int(signature_ttl_seconds) > cls.MAX_SIGNATURE_TTL_SECONDS:
            return False, f"Ventana de validez RFC 9421 (expires - created = {signature_ttl_seconds}s) excede el máximo de {cls.MAX_SIGNATURE_TTL_SECONDS}s."
        if not has_unique_nonce or not verifies_content_digest_sha256:
            return False, "Falta parámetro 'nonce' único o verificación estricta del header Content-Digest (RFC 9530) en la firma HTTP."
        return True, "Firma de mensajes HTTP RFC 9421 y Content-Digest verificados formalmente."

    @classmethod
    def verify_clear_site_data_and_speculation_rules_policy(
        cls,
        clear_site_data_header: str,
        allows_cross_site_prerender_with_credentials: bool,
        checks_sec_purpose_prefetch: bool,
    ) -> Tuple[bool, str]:
        csd = (clear_site_data_header or "").strip().lower()
        for req_d in cls.REQUIRED_CLEAR_SITE_DIRECTIVES:
            if req_d not in csd and '"*"' not in csd:
                return False, f"Endpoint de logout/revocación omite {req_d} en cabecera Clear-Site-Data, dejando tokens/estado residual en el navegador."
        if allows_cross_site_prerender_with_credentials:
            return False, "Política Speculation-Rules permite prerender/prefetch cross-site con credenciales habilitadas."
        if not checks_sec_purpose_prefetch:
            return False, "Endpoints con efectos secundarios no filtran peticiones especulativas con cabecera 'Sec-Purpose: prefetch;prerender'."
        return True, "Aislamiento Clear-Site-Data y Speculation-Rules verificado."

    @classmethod
    def verify_etcd_consul_mdns_ssrf_policy(
        cls,
        target_host: str,
        target_port: int,
        target_path: str,
    ) -> Tuple[bool, str]:
        host_low = (target_host or "").strip().lower()
        path_low = (target_path or "").strip().lower()
        port_num = int(target_port)
        if port_num in cls.FORBIDDEN_DISCOVERY_PORTS:
            return False, f"Puerto de plano de control/descubrimiento interno ({port_num}: etcd/Consul/mDNS) bloqueado contra SSRF (CWE-918)."
        combined = f"{host_low}:{port_num}{path_low}"
        for pat in cls.FORBIDDEN_DISCOVERY_PATTERNS:
            if pat in combined or host_low.endswith(".local") or host_low.endswith(".consul"):
                return False, f"Acceso SSRF hacia servicio interno de descubrimiento o KV store detectado ('{pat}', CWE-918)."
        return True, "Transporte aislado contra SSRF hacia etcd (2379), Consul (8500) y mDNS (.local)."

    @classmethod
    def audit_rfc9421_clear_site_data_and_etcd_consul_ssrf(
        cls,
        source_code: str = "",
        rfc9421_config: Optional[Dict[str, Any]] = None,
        clear_site_context: Optional[Dict[str, Any]] = None,
        discovery_ssrf_context: Optional[Dict[str, Any]] = None,
    ) -> RFC9421ClearSiteConsulReport:
        t0 = time.perf_counter_ns()
        violations: List[RFC9421ClearSiteConsulViolation] = []
        patches: List[Dict[str, str]] = []

        sig_clean = True
        csd_clean = True
        disc_clean = True

        s_cfg = rfc9421_config if rfc9421_config is not None else {
            "covered_components": ["@method", "@authority", "@target-uri", "content-digest"],
            "sig_alg": "ed25519",
            "signature_ttl_seconds": 120,
            "has_unique_nonce": True,
            "verifies_content_digest_sha256": True,
        }
        ok_sig, msg_sig = cls.verify_http_message_sig_rfc9421_policy(
            covered_components=list(
                s_cfg.get(
                    "covered_components",
                    ["@method", "@authority", "@target-uri", "content-digest"],
                )
            ),
            sig_alg=str(s_cfg.get("sig_alg", "ed25519")),
            signature_ttl_seconds=int(s_cfg.get("signature_ttl_seconds", 120)),
            has_unique_nonce=bool(s_cfg.get("has_unique_nonce", True)),
            verifies_content_digest_sha256=bool(s_cfg.get("verifies_content_digest_sha256", True)),
        )
        if not ok_sig:
            sig_clean = False
            violations.append(
                RFC9421ClearSiteConsulViolation(
                    violation_type="RFC9421_HTTP_MESSAGE_SIGNATURE_WEAKNESS",
                    severity="CRITICAL",
                    location="rfc9421_config",
                    detail=msg_sig,
                    suggested_patch="Cubrir (@method @authority @target-uri content-digest) con ed25519/ecdsa-p256-sha256, nonce único y TTL <= 300s.",
                )
            )

        c_cfg = clear_site_context if clear_site_context is not None else {
            "clear_site_data_header": '"cache", "cookies", "storage"',
            "allows_cross_site_prerender_with_credentials": False,
            "checks_sec_purpose_prefetch": True,
        }
        ok_csd, msg_csd = cls.verify_clear_site_data_and_speculation_rules_policy(
            clear_site_data_header=str(
                c_cfg.get("clear_site_data_header", '"cache", "cookies", "storage"')
            ),
            allows_cross_site_prerender_with_credentials=bool(
                c_cfg.get("allows_cross_site_prerender_with_credentials", False)
            ),
            checks_sec_purpose_prefetch=bool(c_cfg.get("checks_sec_purpose_prefetch", True)),
        )
        if not ok_csd:
            csd_clean = False
            violations.append(
                RFC9421ClearSiteConsulViolation(
                    violation_type="CLEAR_SITE_DATA_OR_SPECULATION_RULES_LEAK",
                    severity="HIGH",
                    location="clear_site_context",
                    detail=msg_csd,
                    suggested_patch='Emitir Clear-Site-Data: "cache", "cookies", "storage" en logout y bloquear Sec-Purpose: prefetch en rutas mutantes.',
                )
            )

        d_cfg = discovery_ssrf_context if discovery_ssrf_context is not None else {
            "target_host": "api.partner.example.com",
            "target_port": 443,
            "target_path": "/v1/orders",
        }
        ok_disc, msg_disc = cls.verify_etcd_consul_mdns_ssrf_policy(
            target_host=str(d_cfg.get("target_host", "api.partner.example.com")),
            target_port=int(d_cfg.get("target_port", 443)),
            target_path=str(d_cfg.get("target_path", "/v1/orders")),
        )
        if not ok_disc:
            disc_clean = False
            violations.append(
                RFC9421ClearSiteConsulViolation(
                    violation_type="ETCD_CONSUL_OR_MDNS_DISCOVERY_SSRF",
                    severity="CRITICAL",
                    location="discovery_ssrf_context",
                    detail=msg_disc,
                    suggested_patch="Bloquear puertos internos 2379/8500/5353, rutas /v3/kv o /v1/kv y dominios .local/.consul.",
                )
            )

        if source_code:
            low_src = source_code.lower()
            if ("signature-input" in low_src and "hmac-sha256" in low_src) and (
                "verify_http_message_sig_rfc9421_policy" not in source_code
            ):
                sig_clean = False
                violations.append(
                    RFC9421ClearSiteConsulViolation(
                        violation_type="AST_RFC9421_WEAK_SHARED_HMAC_OR_MISSING_COMPONENTS",
                        severity="CRITICAL",
                        location="ast_http_sig_verifier",
                        detail="Uso de hmac-sha256 compartido o firma RFC 9421 sin validación de componentes detectado en el AST.",
                        suggested_patch="Invocar verify_http_message_sig_rfc9421_policy exigiendo ed25519/ecdsa-p256-sha256 y componentes completos.",
                    )
                )

            if (":2379/v3/kv" in low_src or ":8500/v1/kv" in low_src or ".consul" in low_src) and (
                "verify_etcd_consul_mdns_ssrf_policy" not in source_code
            ):
                disc_clean = False
                violations.append(
                    RFC9421ClearSiteConsulViolation(
                        violation_type="AST_ETCD_CONSUL_KV_SSRF",
                        severity="CRITICAL",
                        location="ast_http_client",
                        detail="Petición HTTP directa hacia API de etcd (:2379/v3/kv) o Consul (:8500/v1/kv) detectada en el AST.",
                        suggested_patch="Validar host, puerto y ruta con verify_etcd_consul_mdns_ssrf_policy.",
                    )
                )

        if not sig_clean:
            patches.append(
                {
                    "strategy": "RFC9421_HTTP_MESSAGE_SIGNATURE_STRICT_GUARD",
                    "fix": "ok, msg = HTTPMessageSigRFC9421ClearSiteDataAndConsulEtcdSSRFProver.verify_http_message_sig_rfc9421_policy(['@method', '@authority', '@target-uri', 'content-digest'], 'ed25519', 120, True, True)",
                }
            )
        if not csd_clean:
            patches.append(
                {
                    "strategy": "W3C_CLEAR_SITE_DATA_AND_SPECULATION_GUARD",
                    "fix": "ok, msg = HTTPMessageSigRFC9421ClearSiteDataAndConsulEtcdSSRFProver.verify_clear_site_data_and_speculation_rules_policy('cookies, storage', False, True)",
                }
            )
        if not disc_clean:
            patches.append(
                {
                    "strategy": "ETCD_CONSUL_MDNS_DISCOVERY_SSRF_SHIELD",
                    "fix": "ok, msg = HTTPMessageSigRFC9421ClearSiteDataAndConsulEtcdSSRFProver.verify_etcd_consul_mdns_ssrf_policy(host, port, path)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return RFC9421ClearSiteConsulReport(
            formal_rfc9421_clearsite_consul_safe=safe,
            http_message_sig_rfc9421_components_and_replay_clean=sig_clean,
            clear_site_data_and_speculation_rules_isolation_clean=csd_clean,
            etcd_consul_mdns_discovery_ssrf_clean=disc_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



