class UUIDv7RFC9562CSPSandboxIframeAndAltSvcSSRFProver:
    """
    Nivel 94: Demostrador formal de seguridad de identificadores UUIDv7/UUIDv4 según RFC 9562 Section 6
    (prohibición de usar UUIDv1/UUIDv7 con timestamp de 48 bits como tokens secretos de capacidades/reset sin MAC,
    exigencia de >= 62 bits de entropía CSPRNG en rand_a/rand_b), aislamiento de iframes CSP sandbox
    (prohibición de combinar allow-scripts + allow-same-origin y exigencia de X-Content-Type-Options: nosniff)
    y prevención de SSRF mediante cabeceras HTTP Alt-Svc (RFC 7838) y tramas HTTP/2-HTTP/3 ORIGIN (RFC 8336, CWE-918).
    """

    FORBIDDEN_CAPABILITY_UUID_VERSIONS = {1, 6, 7}
    MIN_CSPRNG_RANDOM_BITS = 62

    @classmethod
    def verify_uuidv7_rfc9562_security_policy(
        cls,
        uuid_version: int,
        used_as_unguessable_secret_token: bool,
        csprng_random_bits: int,
        masks_timestamp_on_public_api: bool,
    ) -> Tuple[bool, str]:
        ver = int(uuid_version)
        if used_as_unguessable_secret_token and ver in cls.FORBIDDEN_CAPABILITY_UUID_VERSIONS:
            return False, f"UUIDv{ver} incluye un timestamp predecible (48/60 bits) y NO debe usarse como capability token o enlace secreto sin firma HMAC (RFC 9562 Section 6.1)."
        if int(csprng_random_bits) < cls.MIN_CSPRNG_RANDOM_BITS:
            return False, f"Bits aleatorios CSPRNG ({csprng_random_bits}) inferiores al mínimo de {cls.MIN_CSPRNG_RANDOM_BITS} bits para evitar colisiones y adivinación de secuencias."
        if ver == 7 and not masks_timestamp_on_public_api:
            return False, "Exposición directa de UUIDv7 sin ofuscación/autorización en API pública filtra el instante exacto de creación (48-bit Unix ms) y volumen de negocio (RFC 9562 Section 6.2)."
        return True, "Política de entropía y privacidad de identificadores RFC 9562 verificada formalmente."

    @classmethod
    def verify_csp_sandbox_iframe_and_nosniff_policy(
        cls,
        sandbox_flags: str,
        x_content_type_options: str,
        allows_top_navigation_without_user_activation: bool,
    ) -> Tuple[bool, str]:
        sb_low = (sandbox_flags or "").strip().lower()
        if "allow-scripts" in sb_low and "allow-same-origin" in sb_low:
            return False, "Combinación letal 'allow-scripts allow-same-origin' en sandbox de iframe: el documento embebido puede eliminar su propio atributo sandbox del DOM padre."
        if allows_top_navigation_without_user_activation or (
            "allow-top-navigation" in sb_low and "allow-top-navigation-by-user-activation" not in sb_low
        ):
            return False, "Directiva 'allow-top-navigation' sin activación explícita del usuario permite secuestro de pestaña principal (Phishing / Tab-Redirection)."
        xcto = (x_content_type_options or "").strip().lower()
        if xcto != "nosniff":
            return False, f"Cabecera X-Content-Type-Options '{x_content_type_options}' ausente o distinta de 'nosniff' (permite ejecución XSS por MIME-sniffing)."
        return True, "Aislamiento de iframe CSP sandbox y X-Content-Type-Options: nosniff verificado."

    @classmethod
    def verify_alt_svc_rfc7838_and_origin_frame_ssrf_policy(
        cls,
        honors_untrusted_alt_svc_header: bool,
        alt_svc_target_host: str,
        alt_svc_target_port: int,
        accepts_http2_origin_frame_coalescing: bool,
    ) -> Tuple[bool, str]:
        if honors_untrusted_alt_svc_header:
            return False, "El cliente HTTP sigue cabeceras 'Alt-Svc' (RFC 7838) de orígenes no confiables, permitiendo redirigir conexiones subsiguientes hacia puertos internos (CWE-918)."
        host_low = (alt_svc_target_host or "").strip().lower()
        port_num = int(alt_svc_target_port)
        if host_low in {"127.0.0.1", "localhost", "::1", "0.0.0.0", "169.254.169.254"} or port_num in {22, 2379, 5432, 6379, 8500, 9200, 11211}:
            return False, f"Destino Alt-Svc apunta a host/puerto interno restringido ('{alt_svc_target_host}:{port_num}', CWE-918)."
        if accepts_http2_origin_frame_coalescing:
            return False, "El cliente HTTP/2-HTTP/3 permite coalescencia de conexiones mediante tramas ORIGIN (RFC 8336) sin re-verificar resolución DNS e IP privada."
        return True, "Transporte HTTP blindado contra SSRF por Alt-Svc (RFC 7838) y coalescencia de tramas ORIGIN (RFC 8336)."

    @classmethod
    def audit_uuidv7_csp_sandbox_and_altsvc_ssrf(
        cls,
        source_code: str = "",
        uuid_config: Optional[Dict[str, Any]] = None,
        csp_sandbox_context: Optional[Dict[str, Any]] = None,
        altsvc_ssrf_context: Optional[Dict[str, Any]] = None,
    ) -> UUIDv7SandboxAltSvcReport:
        t0 = time.perf_counter_ns()
        violations: List[UUIDv7SandboxAltSvcViolation] = []
        patches: List[Dict[str, str]] = []

        uuid_clean = True
        sandbox_clean = True
        altsvc_clean = True

        u_cfg = uuid_config if uuid_config is not None else {
            "uuid_version": 7,
            "used_as_unguessable_secret_token": False,
            "csprng_random_bits": 74,
            "masks_timestamp_on_public_api": True,
        }
        ok_u, msg_u = cls.verify_uuidv7_rfc9562_security_policy(
            uuid_version=int(u_cfg.get("uuid_version", 7)),
            used_as_unguessable_secret_token=bool(u_cfg.get("used_as_unguessable_secret_token", False)),
            csprng_random_bits=int(u_cfg.get("csprng_random_bits", 74)),
            masks_timestamp_on_public_api=bool(u_cfg.get("masks_timestamp_on_public_api", True)),
        )
        if not ok_u:
            uuid_clean = False
            violations.append(
                UUIDv7SandboxAltSvcViolation(
                    violation_type="UUIDV7_RFC9562_SECRET_TOKEN_OR_TIMESTAMP_LEAK",
                    severity="HIGH",
                    location="uuid_config",
                    detail=msg_u,
                    suggested_patch="Usar secrets.token_urlsafe(32) o UUIDv4 CSPRNG (122 bits) para tokens secretos y enmascarar timestamps UUIDv7 en APIs públicas.",
                )
            )

        sb_cfg = csp_sandbox_context if csp_sandbox_context is not None else {
            "sandbox_flags": "allow-scripts allow-forms",
            "x_content_type_options": "nosniff",
            "allows_top_navigation_without_user_activation": False,
        }
        ok_sb, msg_sb = cls.verify_csp_sandbox_iframe_and_nosniff_policy(
            sandbox_flags=str(sb_cfg.get("sandbox_flags", "allow-scripts allow-forms")),
            x_content_type_options=str(sb_cfg.get("x_content_type_options", "nosniff")),
            allows_top_navigation_without_user_activation=bool(
                sb_cfg.get("allows_top_navigation_without_user_activation", False)
            ),
        )
        if not ok_sb:
            sandbox_clean = False
            violations.append(
                UUIDv7SandboxAltSvcViolation(
                    violation_type="CSP_SANDBOX_ALLOW_SCRIPTS_SAME_ORIGIN_ESCAPE",
                    severity="CRITICAL",
                    location="csp_sandbox_context",
                    detail=msg_sb,
                    suggested_patch="Remover 'allow-same-origin' cuando 'allow-scripts' está activo y emitir X-Content-Type-Options: nosniff.",
                )
            )

        as_cfg = altsvc_ssrf_context if altsvc_ssrf_context is not None else {
            "honors_untrusted_alt_svc_header": False,
            "alt_svc_target_host": "cdn.example.com",
            "alt_svc_target_port": 443,
            "accepts_http2_origin_frame_coalescing": False,
        }
        ok_as, msg_as = cls.verify_alt_svc_rfc7838_and_origin_frame_ssrf_policy(
            honors_untrusted_alt_svc_header=bool(as_cfg.get("honors_untrusted_alt_svc_header", False)),
            alt_svc_target_host=str(as_cfg.get("alt_svc_target_host", "cdn.example.com")),
            alt_svc_target_port=int(as_cfg.get("alt_svc_target_port", 443)),
            accepts_http2_origin_frame_coalescing=bool(as_cfg.get("accepts_http2_origin_frame_coalescing", False)),
        )
        if not ok_as:
            altsvc_clean = False
            violations.append(
                UUIDv7SandboxAltSvcViolation(
                    violation_type="ALT_SVC_RFC7838_OR_ORIGIN_FRAME_SSRF",
                    severity="CRITICAL",
                    location="altsvc_ssrf_context",
                    detail=msg_as,
                    suggested_patch="Ignorar cabeceras Alt-Svc en clientes HTTP de backend y deshabilitar coalescencia ciega de tramas ORIGIN.",
                )
            )

        if source_code:
            low_src = source_code.lower()
            if ("allow-scripts" in low_src and "allow-same-origin" in low_src) and (
                "verify_csp_sandbox_iframe_and_nosniff_policy" not in source_code
            ):
                sandbox_clean = False
                violations.append(
                    UUIDv7SandboxAltSvcViolation(
                        violation_type="AST_IFRAME_SANDBOX_ESCAPE_COMBINATION",
                        severity="CRITICAL",
                        location="ast_iframe_template",
                        detail="Combinación 'allow-scripts' + 'allow-same-origin' detectada en definición de iframe/CSP en el AST.",
                        suggested_patch="Validar flags de sandbox con verify_csp_sandbox_iframe_and_nosniff_policy.",
                    )
                )

            if ("uuid1(" in low_src and ("reset_token" in low_src or "api_key" in low_src or "secret" in low_src)) and (
                "verify_uuidv7_rfc9562_security_policy" not in source_code
            ):
                uuid_clean = False
                violations.append(
                    UUIDv7SandboxAltSvcViolation(
                        violation_type="AST_PREDICTABLE_UUID_SECRET_TOKEN",
                        severity="HIGH",
                        location="ast_token_generator",
                        detail="Uso de UUID basado en timestamp/MAC como token secreto detectado en el AST.",
                        suggested_patch="Sustituir por secrets.token_urlsafe(32) y auditar con verify_uuidv7_rfc9562_security_policy.",
                    )
                )

        if not uuid_clean:
            patches.append(
                {
                    "strategy": "RFC9562_UUIDV7_CSPRNG_AND_CAPABILITY_GUARD",
                    "fix": "ok, msg = UUIDv7RFC9562CSPSandboxIframeAndAltSvcSSRFProver.verify_uuidv7_rfc9562_security_policy(7, False, 74, True)",
                }
            )
        if not sandbox_clean:
            patches.append(
                {
                    "strategy": "CSP_IFRAME_SANDBOX_ISOLATION_AND_NOSNIFF",
                    "fix": "ok, msg = UUIDv7RFC9562CSPSandboxIframeAndAltSvcSSRFProver.verify_csp_sandbox_iframe_and_nosniff_policy('allow-scripts', 'nosniff', False)",
                }
            )
        if not altsvc_clean:
            patches.append(
                {
                    "strategy": "RFC7838_ALT_SVC_AND_ORIGIN_FRAME_SSRF_SHIELD",
                    "fix": "ok, msg = UUIDv7RFC9562CSPSandboxIframeAndAltSvcSSRFProver.verify_alt_svc_rfc7838_and_origin_frame_ssrf_policy(False, 'cdn.example.com', 443, False)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return UUIDv7SandboxAltSvcReport(
            formal_uuidv7_sandbox_altsvc_safe=safe,
            uuidv7_rfc9562_csprng_and_idor_unguesability_clean=uuid_clean,
            csp_sandbox_iframe_and_nosniff_isolation_clean=sandbox_clean,
            alt_svc_rfc7838_and_h3_origin_frame_ssrf_clean=altsvc_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



