class DPoPRFC9449CSPFencedFrameAndH2CgRPCReflectionSSRFProver:
    """
    Nivel 95: Demostrador formal de OAuth 2.0 Demonstrating Proof-of-Possession (DPoP RFC 9449:
    typ='dpop+jwt', clave privada nunca en header jwk, verificación de ath SHA-256 del access token,
    normalización exacta htm/htu sin query/fragment y DPoP-Nonce con caché anti-replay jti),
    aislamiento CSP fenced-frame-src ('self'/'none') + Supports-Loading-Mode: fenced-frame
    y prevención de contrabando/SSRF vía Upgrade: h2c (HTTP/2 Cleartext, CWE-444) y gRPC ServerReflection en producción.
    """

    APPROVED_DPOP_ALGS = {"es256", "es384", "es512", "eddsa", "ps256"}
    SAFE_FENCED_FRAME_SRC = {"'none'", "'self'", "https:"}

    @classmethod
    def verify_dpop_rfc9449_proof_policy(
        cls,
        dpop_typ: str,
        dpop_alg: str,
        jwk_contains_private_key_material: bool,
        verifies_ath_access_token_hash: bool,
        enforces_dpop_nonce_and_jti_replay_cache: bool,
        strips_query_and_fragment_in_htu: bool,
    ) -> Tuple[bool, str]:
        if (dpop_typ or "").strip().lower() != "dpop+jwt":
            return False, f"Header typ '{dpop_typ}' inválido para prueba DPoP (RFC 9449 Section 4.2 exige 'dpop+jwt')."
        alg_norm = (dpop_alg or "").strip().lower()
        if alg_norm not in cls.APPROVED_DPOP_ALGS:
            return False, f"Algoritmo DPoP '{dpop_alg}' no aprobado o simétrico (RFC 9449 exige firma asimétrica como ES256/EdDSA)."
        if jwk_contains_private_key_material:
            return False, "El header 'jwk' del DPoP proof expone parámetros de clave privada ('d', 'p', 'q'), comprometiendo la prueba de posesión."
        if not verifies_ath_access_token_hash:
            return False, "Falta verificación del claim 'ath' (base64url SHA-256 del Access Token) en el Resource Server (RFC 9449 Section 4.2)."
        if not enforces_dpop_nonce_and_jti_replay_cache:
            return False, "Falta desafío DPoP-Nonce del servidor o caché de unicidad 'jti' contra pre-generación y replay de pruebas DPoP."
        if not strips_query_and_fragment_in_htu:
            return False, "Comparación de 'htu' sin normalizar ni descartar query/fragment (RFC 9449 Section 4.3)."
        return True, "Política OAuth 2.0 DPoP RFC 9449 (dpop+jwt, ath, jkt, DPoP-Nonce y jti) verificada formalmente."

    @classmethod
    def verify_csp_fenced_frame_and_loading_mode_policy(
        cls,
        fenced_frame_src: str,
        supports_loading_mode_header: str,
        allows_unpartitioned_storage_in_fenced_frame: bool,
    ) -> Tuple[bool, str]:
        ffs = (fenced_frame_src or "").strip().lower()
        if ffs not in cls.SAFE_FENCED_FRAME_SRC or "*" in ffs or "data:" in ffs or "blob:" in ffs:
            return False, f"Directiva CSP fenced-frame-src '{fenced_frame_src}' permite cargar marcos aislados desde orígenes no confiables o esquemas data:/blob:."
        slm = (supports_loading_mode_header or "").strip().lower()
        if ffs != "'none'" and slm != "fenced-frame":
            return False, f"Cabecera Supports-Loading-Mode '{supports_loading_mode_header}' ausente o distinta de 'fenced-frame' al servir documentos embebidos."
        if allows_unpartitioned_storage_in_fenced_frame:
            return False, "El contexto FencedFrame permite acceso a almacenamiento no particionado o comunicación postMessage de canal lateral."
        return True, "Aislamiento CSP fenced-frame-src y Supports-Loading-Mode verificado."

    @classmethod
    def verify_h2c_upgrade_and_grpc_reflection_ssrf_policy(
        cls,
        forwards_h2c_upgrade_headers: bool,
        request_headers_contain_h2c_or_http2_settings: bool,
        grpc_server_reflection_enabled_in_prod: bool,
    ) -> Tuple[bool, str]:
        if forwards_h2c_upgrade_headers or request_headers_contain_h2c_or_http2_settings:
            return False, "Proxy o cliente reenvía 'Upgrade: h2c' / 'HTTP2-Settings', permitiendo establecer un túnel HTTP/2 Cleartext directo hacia el backend y evadir controles de ruta (CWE-444 / CWE-918)."
        if grpc_server_reflection_enabled_in_prod:
            return False, "Servicio gRPC ServerReflection (v1 / v1alpha) habilitado en producción sin autenticación mTLS, exponiendo todos los esquemas Protobuf e invocación interna."
        return True, "Bloqueo de túneles Upgrade: h2c y deshabilitación de gRPC ServerReflection en producción verificados."

    @classmethod
    def audit_dpop_fenced_frame_and_h2c_grpc_ssrf(
        cls,
        source_code: str = "",
        dpop_config: Optional[Dict[str, Any]] = None,
        fenced_frame_context: Optional[Dict[str, Any]] = None,
        h2c_grpc_context: Optional[Dict[str, Any]] = None,
    ) -> DPoPFencedFrameH2CReport:
        t0 = time.perf_counter_ns()
        violations: List[DPoPFencedFrameH2CViolation] = []
        patches: List[Dict[str, str]] = []

        dpop_clean = True
        ff_clean = True
        h2c_clean = True

        d_cfg = dpop_config if dpop_config is not None else {
            "dpop_typ": "dpop+jwt",
            "dpop_alg": "ES256",
            "jwk_contains_private_key_material": False,
            "verifies_ath_access_token_hash": True,
            "enforces_dpop_nonce_and_jti_replay_cache": True,
            "strips_query_and_fragment_in_htu": True,
        }
        ok_d, msg_d = cls.verify_dpop_rfc9449_proof_policy(
            dpop_typ=str(d_cfg.get("dpop_typ", "dpop+jwt")),
            dpop_alg=str(d_cfg.get("dpop_alg", "ES256")),
            jwk_contains_private_key_material=bool(d_cfg.get("jwk_contains_private_key_material", False)),
            verifies_ath_access_token_hash=bool(d_cfg.get("verifies_ath_access_token_hash", True)),
            enforces_dpop_nonce_and_jti_replay_cache=bool(
                d_cfg.get("enforces_dpop_nonce_and_jti_replay_cache", True)
            ),
            strips_query_and_fragment_in_htu=bool(d_cfg.get("strips_query_and_fragment_in_htu", True)),
        )
        if not ok_d:
            dpop_clean = False
            violations.append(
                DPoPFencedFrameH2CViolation(
                    violation_type="DPOP_RFC9449_ATH_OR_NONCE_VIOLATION",
                    severity="CRITICAL",
                    location="dpop_config",
                    detail=msg_d,
                    suggested_patch="Exigir typ='dpop+jwt', ES256/EdDSA, verificar claim 'ath', DPoP-Nonce y caché anti-replay de 'jti'.",
                )
            )

        ff_cfg = fenced_frame_context if fenced_frame_context is not None else {
            "fenced_frame_src": "'self'",
            "supports_loading_mode_header": "fenced-frame",
            "allows_unpartitioned_storage_in_fenced_frame": False,
        }
        ok_ff, msg_ff = cls.verify_csp_fenced_frame_and_loading_mode_policy(
            fenced_frame_src=str(ff_cfg.get("fenced_frame_src", "'self'")),
            supports_loading_mode_header=str(ff_cfg.get("supports_loading_mode_header", "fenced-frame")),
            allows_unpartitioned_storage_in_fenced_frame=bool(
                ff_cfg.get("allows_unpartitioned_storage_in_fenced_frame", False)
            ),
        )
        if not ok_ff:
            ff_clean = False
            violations.append(
                DPoPFencedFrameH2CViolation(
                    violation_type="CSP_FENCED_FRAME_SRC_OR_LOADING_MODE_WEAKNESS",
                    severity="HIGH",
                    location="fenced_frame_context",
                    detail=msg_ff,
                    suggested_patch="Configurar fenced-frame-src 'self' o 'none', emitir Supports-Loading-Mode: fenced-frame y particionar storage.",
                )
            )

        h_cfg = h2c_grpc_context if h2c_grpc_context is not None else {
            "forwards_h2c_upgrade_headers": False,
            "request_headers_contain_h2c_or_http2_settings": False,
            "grpc_server_reflection_enabled_in_prod": False,
        }
        ok_h, msg_h = cls.verify_h2c_upgrade_and_grpc_reflection_ssrf_policy(
            forwards_h2c_upgrade_headers=bool(h_cfg.get("forwards_h2c_upgrade_headers", False)),
            request_headers_contain_h2c_or_http2_settings=bool(
                h_cfg.get("request_headers_contain_h2c_or_http2_settings", False)
            ),
            grpc_server_reflection_enabled_in_prod=bool(
                h_cfg.get("grpc_server_reflection_enabled_in_prod", False)
            ),
        )
        if not ok_h:
            h2c_clean = False
            violations.append(
                DPoPFencedFrameH2CViolation(
                    violation_type="H2C_UPGRADE_SMUGGLING_OR_GRPC_REFLECTION_EXPOSURE",
                    severity="CRITICAL",
                    location="h2c_grpc_context",
                    detail=msg_h,
                    suggested_patch="Descartar cabeceras Upgrade: h2c y HTTP2-Settings en proxies y deshabilitar gRPC ServerReflection en producción.",
                )
            )

        if source_code:
            low_src = source_code.lower()
            if ("upgrade" in low_src and "h2c" in low_src) and (
                "verify_h2c_upgrade_and_grpc_reflection_ssrf_policy" not in source_code
            ):
                h2c_clean = False
                violations.append(
                    DPoPFencedFrameH2CViolation(
                        violation_type="AST_H2C_CLEARTEXT_UPGRADE_SMUGGLING",
                        severity="CRITICAL",
                        location="ast_http_proxy",
                        detail="Uso o reenvío de cabecera 'Upgrade: h2c' detectado en el AST sin filtrado de contrabando HTTP/2.",
                        suggested_patch="Invocar verify_h2c_upgrade_and_grpc_reflection_ssrf_policy y eliminar Upgrade: h2c.",
                    )
                )

            if ("serverreflection" in low_src or "enable_server_reflection" in low_src) and (
                "verify_h2c_upgrade_and_grpc_reflection_ssrf_policy" not in source_code
            ):
                h2c_clean = False
                violations.append(
                    DPoPFencedFrameH2CViolation(
                        violation_type="AST_GRPC_SERVER_REFLECTION_ENABLED",
                        severity="HIGH",
                        location="ast_grpc_server",
                        detail="Habilitación directa de gRPC ServerReflection detectada en el AST.",
                        suggested_patch="Deshabilitar enable_server_reflection en entornos de producción.",
                    )
                )

        if not dpop_clean:
            patches.append(
                {
                    "strategy": "RFC9449_DPOP_ATH_AND_NONCE_GUARD",
                    "fix": "ok, msg = DPoPRFC9449CSPFencedFrameAndH2CgRPCReflectionSSRFProver.verify_dpop_rfc9449_proof_policy('dpop+jwt', 'ES256', False, True, True, True)",
                }
            )
        if not ff_clean:
            patches.append(
                {
                    "strategy": "CSP_FENCED_FRAME_SRC_AND_LOADING_MODE_ISOLATION",
                    "fix": "ok, msg = DPoPRFC9449CSPFencedFrameAndH2CgRPCReflectionSSRFProver.verify_csp_fenced_frame_and_loading_mode_policy("'self'", 'fenced-frame', False)",
                }
            )
        if not h2c_clean:
            patches.append(
                {
                    "strategy": "H2C_UPGRADE_SMUGGLING_AND_GRPC_REFLECTION_SHIELD",
                    "fix": "ok, msg = DPoPRFC9449CSPFencedFrameAndH2CgRPCReflectionSSRFProver.verify_h2c_upgrade_and_grpc_reflection_ssrf_policy(False, False, False)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return DPoPFencedFrameH2CReport(
            formal_dpop_fencedframe_h2c_safe=safe,
            dpop_rfc9449_ath_nonce_and_jkt_binding_clean=dpop_clean,
            csp_fenced_frame_src_and_loading_mode_isolation_clean=ff_clean,
            h2c_upgrade_smuggling_and_grpc_reflection_ssrf_clean=h2c_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



