class OPRFRFC9497TrustedTypesDOMAndFastCGIRedisSSRFProver:
    """
    Nivel 96: Demostrador formal de Oblivious Pseudorandom Functions (OPRF / VOPRF / POPRF RFC 9497 y
    Privacy Pass RFC 9578: validación de grupo de orden primo ristretto255/P-256, rechazo del elemento identidad,
    verificación de prueba DLEQ Schnorr y no reutilización del escalar de cegado r),
    aislamiento DOM XSS mediante CSP require-trusted-types-for 'script' + trusted-types sin política default permisiva,
    y prevención de SSRF / Protocol Smuggling hacia FastCGI (puerto 9000 / fcgi://) y Redis RESP (puerto 6379 / gopher://, CWE-918).
    """

    APPROVED_OPRF_SUITES = {
        "oprf(ristretto255, sha-512)",
        "oprf(decaf448, shake256)",
        "oprf(p-256, sha-256)",
        "oprf(p-384, sha-384)",
        "oprf(p-521, sha-512)",
    }
    FORBIDDEN_SMUGGLING_SCHEMES_AND_PORTS = (
        "fcgi://",
        "fastcgi://",
        "gopher://",
        "redis://",
        "dict://",
        ":9000",
        ":6379",
        "php_value",
        "auto_prepend_file",
        "config set",
        "slaveof",
        "replicaof",
    )

    @classmethod
    def verify_oprf_rfc9497_and_privacy_pass_policy(
        cls,
        cipher_suite: str,
        rejects_identity_element_point: bool,
        verifies_voprf_dleq_proof: bool,
        reuses_blinding_scalar: bool,
    ) -> Tuple[bool, str]:
        suite_norm = (cipher_suite or "").strip().lower()
        if suite_norm not in cls.APPROVED_OPRF_SUITES:
            return False, f"Suite OPRF '{cipher_suite}' no aprobada en RFC 9497 (exigir grupos de orden primo ristretto255/decaf448/P-256)."
        if not rejects_identity_element_point:
            return False, "Falta validación DeserializeElement != Identity en OPRF (permite ataques de elemento identidad y revelación trivial, RFC 9497 Section 5.1)."
        if not verifies_voprf_dleq_proof:
            return False, "Falta verificación de la prueba de equivalencia de logaritmo discreto (DLEQ) en modo VOPRF/POPRF (RFC 9497 / RFC 9578)."
        if reuses_blinding_scalar:
            return False, "Reutilización del escalar de cegado 'r' detectada en el cliente OPRF; rompe la ceguera criptográfica (Unlinkability)."
        return True, "Política criptográfica OPRF/VOPRF RFC 9497 y Privacy Pass RFC 9578 verificada formalmente."

    @classmethod
    def verify_csp_trusted_types_and_dom_sink_policy(
        cls,
        require_trusted_types_for: str,
        trusted_types_policies: List[str],
        allows_passthrough_default_policy: bool,
        allows_duplicates_in_trusted_types: bool,
    ) -> Tuple[bool, str]:
        rtt = (require_trusted_types_for or "").strip().lower()
        if rtt != "'script'":
            return False, f"Directiva CSP require-trusted-types-for '{require_trusted_types_for}' no fuerza "'script'" para bloquear sumideros DOM XSS."
        pol_list = [str(p).strip().lower() for p in (trusted_types_policies or []) if str(p).strip()]
        if not pol_list or "*" in pol_list:
            return False, "Directiva CSP trusted-types vacía o con comodín '*', permitiendo crear políticas arbitrarias desde scripts inyectados."
        if allows_passthrough_default_policy:
            return False, "Política Trusted Types 'default' actúa como passthrough sin sanitización, anulando la protección contra innerHTML/eval."
        if allows_duplicates_in_trusted_types or "'allow-duplicates'" in pol_list:
            return False, "Directiva trusted-types incluye 'allow-duplicates', permitiendo sobrescribir o colisionar nombres de políticas de sanitización."
        return True, "Aislamiento W3C Trusted Types (require-trusted-types-for 'script' + políticas estrictas) verificado."

    @classmethod
    def verify_fastcgi_and_redis_resp_smuggling_ssrf_policy(
        cls,
        target_endpoint: str,
        target_port: int,
        contains_crlf_or_binary_frames: bool,
    ) -> Tuple[bool, str]:
        ep_low = (target_endpoint or "").strip().lower()
        port_num = int(target_port)
        if port_num in {6379, 9000, 11211}:
            return False, f"Puerto interno de daemon sin autenticación HTTP ({port_num}: FastCGI/Redis/Memcached) bloqueado contra Protocol Smuggling SSRF (CWE-918)."
        if contains_crlf_or_binary_frames:
            return False, "Payload o URI contiene secuencias CRLF o tramas binarias destinadas a inyectar comandos RESP/FastCGI (PHP-FPM / Redis RCE)."
        combined = f"{ep_low}:{port_num}"
        for pat in cls.FORBIDDEN_SMUGGLING_SCHEMES_AND_PORTS:
            if pat in combined:
                return False, f"Vector SSRF de Protocol Smuggling hacia FastCGI o Redis detectado ('{pat}', CWE-918)."
        return True, "Transporte blindado contra Protocol Smuggling SSRF hacia FastCGI (9000) y Redis RESP (6379)."

    @classmethod
    def audit_oprf_trusted_types_and_fastcgi_redis_ssrf(
        cls,
        source_code: str = "",
        oprf_config: Optional[Dict[str, Any]] = None,
        trusted_types_context: Optional[Dict[str, Any]] = None,
        smuggling_ssrf_context: Optional[Dict[str, Any]] = None,
    ) -> OPRFTrustedTypesFastCGIReport:
        t0 = time.perf_counter_ns()
        violations: List[OPRFTrustedTypesFastCGIViolation] = []
        patches: List[Dict[str, str]] = []

        oprf_clean = True
        tt_clean = True
        smug_clean = True

        o_cfg = oprf_config if oprf_config is not None else {
            "cipher_suite": "OPRF(ristretto255, SHA-512)",
            "rejects_identity_element_point": True,
            "verifies_voprf_dleq_proof": True,
            "reuses_blinding_scalar": False,
        }
        ok_o, msg_o = cls.verify_oprf_rfc9497_and_privacy_pass_policy(
            cipher_suite=str(o_cfg.get("cipher_suite", "OPRF(ristretto255, SHA-512)")),
            rejects_identity_element_point=bool(o_cfg.get("rejects_identity_element_point", True)),
            verifies_voprf_dleq_proof=bool(o_cfg.get("verifies_voprf_dleq_proof", True)),
            reuses_blinding_scalar=bool(o_cfg.get("reuses_blinding_scalar", False)),
        )
        if not ok_o:
            oprf_clean = False
            violations.append(
                OPRFTrustedTypesFastCGIViolation(
                    violation_type="OPRF_RFC9497_IDENTITY_POINT_OR_DLEQ_VIOLATION",
                    severity="CRITICAL",
                    location="oprf_config",
                    detail=msg_o,
                    suggested_patch="Usar OPRF(ristretto255, SHA-512), rechazar el elemento identidad, verificar prueba DLEQ y generar escalar de cegado único.",
                )
            )

        tt_cfg = trusted_types_context if trusted_types_context is not None else {
            "require_trusted_types_for": "'script'",
            "trusted_types_policies": ["dompurify-policy"],
            "allows_passthrough_default_policy": False,
            "allows_duplicates_in_trusted_types": False,
        }
        ok_tt, msg_tt = cls.verify_csp_trusted_types_and_dom_sink_policy(
            require_trusted_types_for=str(tt_cfg.get("require_trusted_types_for", "'script'")),
            trusted_types_policies=list(tt_cfg.get("trusted_types_policies", ["dompurify-policy"])),
            allows_passthrough_default_policy=bool(tt_cfg.get("allows_passthrough_default_policy", False)),
            allows_duplicates_in_trusted_types=bool(tt_cfg.get("allows_duplicates_in_trusted_types", False)),
        )
        if not ok_tt:
            tt_clean = False
            violations.append(
                OPRFTrustedTypesFastCGIViolation(
                    violation_type="CSP_TRUSTED_TYPES_OR_DOM_SINK_WEAKNESS",
                    severity="HIGH",
                    location="trusted_types_context",
                    detail=msg_tt,
                    suggested_patch="Fijar require-trusted-types-for 'script' y declarar lista explícita en trusted-types sin 'allow-duplicates' ni passthrough default.",
                )
            )

        sm_cfg = smuggling_ssrf_context if smuggling_ssrf_context is not None else {
            "target_endpoint": "https://api.payments.example.com/v1/charge",
            "target_port": 443,
            "contains_crlf_or_binary_frames": False,
        }
        ok_sm, msg_sm = cls.verify_fastcgi_and_redis_resp_smuggling_ssrf_policy(
            target_endpoint=str(sm_cfg.get("target_endpoint", "https://api.payments.example.com/v1/charge")),
            target_port=int(sm_cfg.get("target_port", 443)),
            contains_crlf_or_binary_frames=bool(sm_cfg.get("contains_crlf_or_binary_frames", False)),
        )
        if not ok_sm:
            smug_clean = False
            violations.append(
                OPRFTrustedTypesFastCGIViolation(
                    violation_type="FASTCGI_OR_REDIS_RESP_PROTOCOL_SMUGGLING_SSRF",
                    severity="CRITICAL",
                    location="smuggling_ssrf_context",
                    detail=msg_sm,
                    suggested_patch="Bloquear esquemas gopher://, fcgi://, redis://, dict:// y puertos internos 9000/6379/11211.",
                )
            )

        if source_code:
            low_src = source_code.lower()
            if ("gopher://" in low_src or "fcgi://" in low_src or ":9000" in low_src or "auto_prepend_file" in low_src) and (
                "verify_fastcgi_and_redis_resp_smuggling_ssrf_policy" not in source_code
            ):
                smug_clean = False
                violations.append(
                    OPRFTrustedTypesFastCGIViolation(
                        violation_type="AST_FASTCGI_OR_GOPHER_REDIS_SMUGGLING",
                        severity="CRITICAL",
                        location="ast_network_client",
                        detail="Esquema gopher://, fcgi://, puerto :9000 o inyección PHP_VALUE auto_prepend_file detectado en el AST.",
                        suggested_patch="Validar destino y puerto con verify_fastcgi_and_redis_resp_smuggling_ssrf_policy.",
                    )
                )

            if ("createpolicy('default'" in low_src or 'createpolicy("default"' in low_src) and (
                "verify_csp_trusted_types_and_dom_sink_policy" not in source_code
            ):
                tt_clean = False
                violations.append(
                    OPRFTrustedTypesFastCGIViolation(
                        violation_type="AST_TRUSTED_TYPES_DEFAULT_PASSTHROUGH_POLICY",
                        severity="HIGH",
                        location="ast_dom_sanitizer",
                        detail="Definición de política Trusted Types 'default' detectada sin verificación formal de sanitización.",
                        suggested_patch="Auditar políticas Trusted Types con verify_csp_trusted_types_and_dom_sink_policy.",
                    )
                )

        if not oprf_clean:
            patches.append(
                {
                    "strategy": "RFC9497_OPRF_PRIME_ORDER_AND_DLEQ_GUARD",
                    "fix": "ok, msg = OPRFRFC9497TrustedTypesDOMAndFastCGIRedisSSRFProver.verify_oprf_rfc9497_and_privacy_pass_policy('OPRF(ristretto255, SHA-512)', True, True, False)",
                }
            )
        if not tt_clean:
            patches.append(
                {
                    "strategy": "W3C_TRUSTED_TYPES_STRICT_DOM_ISOLATION",
                    "fix": "ok, msg = OPRFRFC9497TrustedTypesDOMAndFastCGIRedisSSRFProver.verify_csp_trusted_types_and_dom_sink_policy("'script'", ['dompurify-policy'], False, False)",
                }
            )
        if not smug_clean:
            patches.append(
                {
                    "strategy": "FASTCGI_AND_REDIS_RESP_SMUGGLING_SSRF_SHIELD",
                    "fix": "ok, msg = OPRFRFC9497TrustedTypesDOMAndFastCGIRedisSSRFProver.verify_fastcgi_and_redis_resp_smuggling_ssrf_policy(endpoint, 443, False)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return OPRFTrustedTypesFastCGIReport(
            formal_oprf_trustedtypes_fastcgi_safe=safe,
            oprf_rfc9497_prime_order_group_and_dleq_proof_clean=oprf_clean,
            csp_trusted_types_and_dom_sink_isolation_clean=tt_clean,
            fastcgi_redis_resp_protocol_smuggling_ssrf_clean=smug_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



