class MLSRFC9420ImportMapCSPAndCiliumHubbleCNISSRFProver:
    """
    Nivel 97: Demostrador formal de Messaging Layer Security (MLS RFC 9420: suites TreeKEM aprobadas,
    monotonía estricta de epoch en Commits, verificación de firma de LeafNode y confirmación de transcript_hash),
    aislamiento CSP script-src-elem + integridad de Import Maps (<script type="importmap"> con hashes SRI en integrity map)
    y prevención de SSRF hacia agentes CNI/eBPF internos Cilium/Hubble Relay (puertos 4244/4245/9879 y /var/run/cilium/cilium.sock, CWE-918).
    """

    APPROVED_MLS_CIPHERSUITES = {
        "mls_128_dhkemx25519_aes128gcm_sha256_ed25519",
        "mls_128_dhkemp256_aes128gcm_sha256_p256",
        "mls_128_dhkemx25519_chacha20poly1305_sha256_ed25519",
        "mls_256_dhkemx448_aes256gcm_sha512_ed448",
        "mls_256_dhkemp521_aes256gcm_sha512_p521",
    }
    FORBIDDEN_CNI_PORTS = {4240, 4244, 4245, 9879, 9890}
    FORBIDDEN_CNI_PATTERNS = (
        "/var/run/cilium/cilium.sock",
        ":4244",
        ":4245",
        ":9879",
        "hubble-relay",
        "hubble-peer",
        "/v1/flows",
    )

    @classmethod
    def verify_mls_rfc9420_treekem_policy(
        cls,
        mls_ciphersuite: str,
        current_epoch: int,
        proposed_commit_epoch: int,
        verifies_leaf_node_signature: bool,
        verifies_confirmation_tag_transcript_hash: bool,
        reuses_init_key_across_groups: bool,
    ) -> Tuple[bool, str]:
        suite_norm = (mls_ciphersuite or "").strip().lower()
        if suite_norm not in cls.APPROVED_MLS_CIPHERSUITES:
            return False, f"Ciphersuite MLS '{mls_ciphersuite}' no aprobada en RFC 9420 Section 17.1."
        if int(proposed_commit_epoch) != int(current_epoch) + 1:
            return False, f"Violación de monotonía de época MLS RFC 9420: Commit epoch ({proposed_commit_epoch}) != current_epoch + 1 ({int(current_epoch) + 1})."
        if not verifies_leaf_node_signature or not verifies_confirmation_tag_transcript_hash:
            return False, "Falta verificación de firma de LeafNode en el árbol Ratchet Tree o validación de confirmation_tag sobre el transcript_hash (RFC 9420 Section 8)."
        if reuses_init_key_across_groups:
            return False, "Reutilización de KeyPackage/init_key entre múltiples grupos MLS detectada (rompe Forward Secrecy)."
        return True, "Política criptográfica MLS RFC 9420 (TreeKEM, epoch monotonicity, LeafNode signature y confirmation_tag) verificada."

    @classmethod
    def verify_csp_script_src_elem_and_importmap_policy(
        cls,
        script_src_elem: str,
        importmap_allows_external_unpinned_urls: bool,
        importmap_enforces_sri_integrity_map: bool,
    ) -> Tuple[bool, str]:
        sse = (script_src_elem or "").strip().lower()
        if not sse or "unsafe-inline" in sse or "*" in sse or "data:" in sse:
            return False, f"Directiva CSP script-src-elem '{script_src_elem}' ausente o permisiva (permite inyección de etiquetas <script> e importmaps maliciosos)."
        if importmap_allows_external_unpinned_urls:
            return False, "El bloque <script type='importmap'> mapea especificadores de módulos nativos hacia CDNs externos no fijados (Module Specifier Hijacking)."
        if not importmap_enforces_sri_integrity_map:
            return False, "El Import Map carece de mapa 'integrity' con hashes SHA-384/SHA-512 para validar módulos ES cargados dinámicamente."
        return True, "Aislamiento CSP script-src-elem e integridad de Import Maps verificados."

    @classmethod
    def verify_cilium_hubble_cni_ssrf_policy(
        cls,
        target_host: str,
        target_port: int,
        target_path: str,
    ) -> Tuple[bool, str]:
        host_low = (target_host or "").strip().lower()
        path_low = (target_path or "").strip().lower()
        port_num = int(target_port)
        if port_num in cls.FORBIDDEN_CNI_PORTS:
            return False, f"Puerto de plano de observabilidad/control CNI eBPF ({port_num}: Cilium/Hubble) bloqueado contra SSRF (CWE-918)."
        combined = f"{host_low}:{port_num}{path_low}"
        for pat in cls.FORBIDDEN_CNI_PATTERNS:
            if pat in combined:
                return False, f"Acceso SSRF hacia socket o API interna de Cilium/Hubble detectado ('{pat}', CWE-918)."
        return True, "Transporte aislado contra SSRF hacia Cilium Agent y Hubble Relay (4244/4245/9879)."

    @classmethod
    def audit_mls_importmap_csp_and_cilium_ssrf(
        cls,
        source_code: str = "",
        mls_config: Optional[Dict[str, Any]] = None,
        importmap_csp_context: Optional[Dict[str, Any]] = None,
        cilium_cni_context: Optional[Dict[str, Any]] = None,
    ) -> MLSImportMapCiliumReport:
        t0 = time.perf_counter_ns()
        violations: List[MLSImportMapCiliumViolation] = []
        patches: List[Dict[str, str]] = []

        mls_clean = True
        im_clean = True
        cni_clean = True

        m_cfg = mls_config if mls_config is not None else {
            "mls_ciphersuite": "MLS_128_DHKEMX25519_AES128GCM_SHA256_Ed25519",
            "current_epoch": 10,
            "proposed_commit_epoch": 11,
            "verifies_leaf_node_signature": True,
            "verifies_confirmation_tag_transcript_hash": True,
            "reuses_init_key_across_groups": False,
        }
        ok_m, msg_m = cls.verify_mls_rfc9420_treekem_policy(
            mls_ciphersuite=str(
                m_cfg.get("mls_ciphersuite", "MLS_128_DHKEMX25519_AES128GCM_SHA256_Ed25519")
            ),
            current_epoch=int(m_cfg.get("current_epoch", 10)),
            proposed_commit_epoch=int(m_cfg.get("proposed_commit_epoch", 11)),
            verifies_leaf_node_signature=bool(m_cfg.get("verifies_leaf_node_signature", True)),
            verifies_confirmation_tag_transcript_hash=bool(
                m_cfg.get("verifies_confirmation_tag_transcript_hash", True)
            ),
            reuses_init_key_across_groups=bool(m_cfg.get("reuses_init_key_across_groups", False)),
        )
        if not ok_m:
            mls_clean = False
            violations.append(
                MLSImportMapCiliumViolation(
                    violation_type="MLS_RFC9420_TREEKEM_EPOCH_OR_LEAF_SIG_VIOLATION",
                    severity="CRITICAL",
                    location="mls_config",
                    detail=msg_m,
                    suggested_patch="Usar suite MLS RFC 9420 aprobada, forzar proposed_epoch == current_epoch + 1 y verificar firma de LeafNode y confirmation_tag.",
                )
            )

        im_cfg = importmap_csp_context if importmap_csp_context is not None else {
            "script_src_elem": "'self' 'nonce-r4nd0m'",
            "importmap_allows_external_unpinned_urls": False,
            "importmap_enforces_sri_integrity_map": True,
        }
        ok_im, msg_im = cls.verify_csp_script_src_elem_and_importmap_policy(
            script_src_elem=str(im_cfg.get("script_src_elem", "'self' 'nonce-r4nd0m'")),
            importmap_allows_external_unpinned_urls=bool(
                im_cfg.get("importmap_allows_external_unpinned_urls", False)
            ),
            importmap_enforces_sri_integrity_map=bool(
                im_cfg.get("importmap_enforces_sri_integrity_map", True)
            ),
        )
        if not ok_im:
            im_clean = False
            violations.append(
                MLSImportMapCiliumViolation(
                    violation_type="CSP_SCRIPT_SRC_ELEM_OR_IMPORTMAP_HIJACKING",
                    severity="HIGH",
                    location="importmap_csp_context",
                    detail=msg_im,
                    suggested_patch="Restringir script-src-elem con nonce/hash estricto y declarar bloque 'integrity' SHA-384 en <script type='importmap'>.",
                )
            )

        cni_cfg = cilium_cni_context if cilium_cni_context is not None else {
            "target_host": "api.external.example.com",
            "target_port": 443,
            "target_path": "/v1/telemetry",
        }
        ok_cni, msg_cni = cls.verify_cilium_hubble_cni_ssrf_policy(
            target_host=str(cni_cfg.get("target_host", "api.external.example.com")),
            target_port=int(cni_cfg.get("target_port", 443)),
            target_path=str(cni_cfg.get("target_path", "/v1/telemetry")),
        )
        if not ok_cni:
            cni_clean = False
            violations.append(
                MLSImportMapCiliumViolation(
                    violation_type="CILIUM_HUBBLE_CNI_OR_EBPF_AGENT_SSRF",
                    severity="CRITICAL",
                    location="cilium_cni_context",
                    detail=msg_cni,
                    suggested_patch="Bloquear puertos internos Cilium/Hubble (4240/4244/4245/9879) y socket /var/run/cilium/cilium.sock.",
                )
            )

        if source_code:
            low_src = source_code.lower()
            if ("hubble-relay" in low_src or ":4245" in low_src or "cilium.sock" in low_src) and (
                "verify_cilium_hubble_cni_ssrf_policy" not in source_code
            ):
                cni_clean = False
                violations.append(
                    MLSImportMapCiliumViolation(
                        violation_type="AST_CILIUM_HUBBLE_RELAY_SSRF",
                        severity="CRITICAL",
                        location="ast_network_client",
                        detail="Conexión directa hacia Hubble Relay (:4245) o /var/run/cilium/cilium.sock detectada en el AST.",
                        suggested_patch="Validar destino de red con verify_cilium_hubble_cni_ssrf_policy.",
                    )
                )

            if ('type="importmap"' in low_src and '"integrity"' not in low_src) and (
                "verify_csp_script_src_elem_and_importmap_policy" not in source_code
            ):
                im_clean = False
                violations.append(
                    MLSImportMapCiliumViolation(
                        violation_type="AST_IMPORTMAP_MISSING_SRI_INTEGRITY",
                        severity="HIGH",
                        location="ast_html_template",
                        detail="Declaración <script type='importmap'> sin mapa 'integrity' SRI detectada en el AST.",
                        suggested_patch="Auditar el Import Map con verify_csp_script_src_elem_and_importmap_policy e incluir hashes SHA-384.",
                    )
                )

        if not mls_clean:
            patches.append(
                {
                    "strategy": "RFC9420_MLS_TREEKEM_EPOCH_AND_CONFIRMATION_GUARD",
                    "fix": "ok, msg = MLSRFC9420ImportMapCSPAndCiliumHubbleCNISSRFProver.verify_mls_rfc9420_treekem_policy('MLS_128_DHKEMX25519_AES128GCM_SHA256_Ed25519', epoch, epoch + 1, True, True, False)",
                }
            )
        if not im_clean:
            patches.append(
                {
                    "strategy": "CSP_SCRIPT_SRC_ELEM_AND_IMPORTMAP_SRI_ISOLATION",
                    "fix": "ok, msg = MLSRFC9420ImportMapCSPAndCiliumHubbleCNISSRFProver.verify_csp_script_src_elem_and_importmap_policy("'self'", False, True)",
                }
            )
        if not cni_clean:
            patches.append(
                {
                    "strategy": "CILIUM_HUBBLE_CNI_SSRF_SHIELD",
                    "fix": "ok, msg = MLSRFC9420ImportMapCSPAndCiliumHubbleCNISSRFProver.verify_cilium_hubble_cni_ssrf_policy(host, 443, path)",
                }
            )

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        safe = len(violations) == 0
        return MLSImportMapCiliumReport(
            formal_mls_importmap_cilium_safe=safe,
            mls_rfc9420_treekem_epoch_and_leaf_signature_clean=mls_clean,
            csp_script_src_elem_and_importmap_integrity_clean=im_clean,
            cilium_hubble_cni_and_ebpf_agent_ssrf_clean=cni_clean,
            violations=violations,
            remediation_patches=patches,
            analysis_duration_ms=round(dur, 3),
        )



