class BlindRSARFC9474PermissionsPolicyAndKubeletCRISSRFProver:
    """
    Nivel 101 (REG-065): Certificador Formal Tripartito de Firmas Ciegas RSA (IETF RFC 9474) y
    Protocolos Criptográficos Privacy Pass (IETF RFC 9578), Delegación de Capacidades de Hardware/Sensores
    W3C Permissions-Policy (`Permissions-Policy` / `<iframe allow=...>`) y Prevención de SSRF hacia
    Kubernetes Kubelet API (`:10250/run`, `:10250/exec`, `:10250/pods`, `:10255/pods`) y Containerd/CRI-O
    Streaming Server (`:10010/exec`).
    """

    @staticmethod
    def audit_blindrsa_permissions_policy_and_kubelet_ssrf(
        source_code: str, target_path: str = "<memory>"
    ) -> BlindRSAPermissionsKubeletSSRFReport:
        return BlindRSARFC9474PermissionsPolicyAndKubeletCRISSRFProver().verify_code(source_code, target_path)

    def verify_code(self, source_code: str, target_path: str = "<memory>") -> BlindRSAPermissionsKubeletSSRFReport:
        t0 = time.perf_counter()
        violations: List[BlindRSAPermissionsKubeletSSRFViolation] = []
        inspected_functions = 0
        blind_rsa_ok = True
        permissions_ok = True
        kubelet_ssrf_ok = True

        try:
            tree = ast.parse(source_code)
        except SyntaxError as exc:
            dt = (time.perf_counter() - t0) * 1000.0
            return BlindRSAPermissionsKubeletSSRFReport(
                target_path=target_path,
                inspected_functions=0,
                blind_rsa_rfc9474_and_privacy_pass_rfc9578_clean=False,
                w3c_permissions_policy_and_iframe_allow_clean=False,
                kubelet_10250_10255_and_cri_streaming_ssrf_clean=False,
                formal_blindrsa_permissions_kubelet_safe=False,
                violations=[
                    BlindRSAPermissionsKubeletSSRFViolation(
                        line=exc.lineno or 1,
                        function_name="<module>",
                        category="SYNTAX_ERROR",
                        severity="CRITICAL",
                        description=f"Error de sintaxis impide verificacion formal Nivel 101: {exc}",
                        counterexample={"syntax_error": str(exc)},
                        remediation="Corregir la sintaxis Python antes de ejecutar el demostrador Nivel 101.",
                    )
                ],
                mathematical_certificate="UNPROVEN_SYNTAX_ERROR",
                analysis_duration_ms=round(dt, 4),
            )

        func_nodes = [
            n for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]
        if not func_nodes:
            func_nodes = [tree]

        for func in func_nodes:
            fname = getattr(func, "name", "<module>")
            if isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
                inspected_functions += 1
            func_src = ast.unparse(func) if hasattr(ast, "unparse") else source_code
            func_lower = func_src.lower()
            lineno = getattr(func, "lineno", 1)

            # 1. IETF RFC 9474 (Blind RSA Signatures) & RFC 9578 (Privacy Pass Protocols)
            is_blind_rsa_context = any(
                tok in func_lower
                for tok in (
                    "blind_rsa", "rsabssa", "rfc9474", "rfc9578", "privacy_pass",
                    "privacypass", "blind_sign", "unblind_signature", "token_redemption",
                )
            )
            if is_blind_rsa_context:
                missing_coprime_or_random_blinding = (
                    any(m in func_lower for m in ("r = 1", "blinding_factor = 1", "deterministic_blinding=true", "skip_gcd_check=true"))
                    or ("gcd(" not in func_lower and "secrets." not in func_lower and "os.urandom" not in func_lower and "csprng" not in func_lower)
                )
                missing_unblind_verification = any(
                    m in func_lower
                    for m in ("skip_unblind_verify=true", "verify_after_unblind=false", "skip_signature_check")
                )
                non_constant_time_redemption = (
                    ("token_nonce" in func_lower or "challenge_digest" in func_lower or "authenticator" in func_lower)
                    and "compare_digest" not in func_lower
                    and "==" in func_src
                )
                if missing_coprime_or_random_blinding or missing_unblind_verification or non_constant_time_redemption:
                    blind_rsa_ok = False
                    violations.append(
                        BlindRSAPermissionsKubeletSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="BLIND_RSA_RFC9474_OR_PRIVACY_PASS_RFC9578_VULNERABILITY",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', implementacion de Firmas Ciegas RSA (RFC 9474) o Privacy Pass (RFC 9578) "
                                "omite factor de cegado aleatorio coprimo gcd(r, N) == 1 desde CSPRNG, desactiva la verificacion "
                                "de firma tras descegar (s = z * r^-1 mod N) o compara el autenticador/nonce sin tiempo constante."
                            ),
                            counterexample={
                                "rfc": "IETF RFC 9474 (RSABSSA) / RFC 9578 (Privacy Pass)",
                                "missing_coprime_csprng_blinding": missing_coprime_or_random_blinding,
                                "missing_unblind_verification": missing_unblind_verification,
                                "non_constant_time_redemption": non_constant_time_redemption,
                            },
                            remediation=(
                                "Generar r uniforme en [2, N-1] con CSPRNG verificando math.gcd(r, N) == 1 (RFC 9474 Seccion 4.1), "
                                "verificar la firma resultante tras calcular s = z * pow(r, -1, N) mod N y validar redenciones Privacy Pass "
                                "con hmac.compare_digest y cache anti-replay de token_nonce."
                            ),
                        )
                    )

            # 2. W3C Permissions-Policy Header & <iframe allow="..."> Wildcard Delegation
            is_permissions_policy_context = any(
                tok in func_lower
                for tok in (
                    "permissions-policy", "feature-policy", "<iframe", "iframe_allow",
                    "publickey-credentials-get", "browsing-topics",
                )
            )
            if is_permissions_policy_context:
                has_wildcard_permissions = any(
                    bad in func_lower
                    for bad in (
                        "geolocation=*", "camera=*", "microphone=*", "usb=*", "serial=*",
                        "hid=*", "payment=*", "publickey-credentials-get=*", "bluetooth=*",
                        'allow="camera *', 'allow="microphone *', 'allow="geolocation *',
                        'allow="usb *', 'allow="payment *', "allow='camera *", "allow='usb *",
                    )
                )
                deprecated_feature_policy = "feature-policy" in func_lower and "permissions-policy" not in func_lower
                if has_wildcard_permissions or deprecated_feature_policy:
                    permissions_ok = False
                    violations.append(
                        BlindRSAPermissionsKubeletSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="W3C_PERMISSIONS_POLICY_WILDCARD_DELEGATION",
                            severity="HIGH",
                            description=(
                                f"En '{fname}', configuracion insegura de W3C Permissions-Policy o atributo '<iframe allow=...>' "
                                "delega capacidades criticas de hardware/autenticacion (camera, microphone, geolocation, usb, serial, "
                                "hid, payment, publickey-credentials-get) al comodin '*' o utiliza la cabecera obsoleta Feature-Policy."
                            ),
                            counterexample={
                                "header": "Permissions-Policy / <iframe allow>",
                                "wildcard_delegation": has_wildcard_permissions,
                                "deprecated_feature_policy_only": deprecated_feature_policy,
                            },
                            remediation=(
                                "Restringir capacidades sensibles a 'camera=(), microphone=(), usb=(), serial=(), hid=(), geolocation=(self)' "
                                "en la cabecera Permissions-Policy y especificar origenes explicitos en atributos '<iframe allow=...>'."
                            ),
                        )
                    )

            # 3. Kubernetes Kubelet (:10250, :10255) & Containerd/CRI-O Streaming (:10010) SSRF
            has_kubelet_cri_marker = any(
                tok in func_lower
                for tok in (
                    ":10250", ":10255", ":10010", "/runningpods", "/containerlogs/",
                    "kubelet", "containerd.services.containers",
                )
            )
            if has_kubelet_cri_marker:
                has_strict_guard = any(
                    g in func_lower
                    for g in (
                        "block_kubelet_cri_ports", "disallow_kubelet_ssrf",
                        "assert_not_kubelet_endpoint", "anonymous_auth = false",
                    )
                )
                is_vulnerable_kubelet = not has_strict_guard and (
                    any(
                        sink in func_lower
                        for sink in (
                            "requests.", "httpx.", "urllib.request", "aiohttp.",
                            "urlopen", "fetch(", "websocket",
                        )
                    )
                    or any(
                        raw in func_lower
                        for raw in (
                            ":10250/pods", ":10250/run", ":10250/exec", ":10250/containerlogs",
                            ":10255/pods", ":10255/spec", ":10010/exec", "/runningpods",
                        )
                    )
                )
                if is_vulnerable_kubelet:
                    kubelet_ssrf_ok = False
                    violations.append(
                        BlindRSAPermissionsKubeletSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="KUBELET_10250_10255_OR_CRI_10010_SSRF",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', flujo SSRF hacia la API local del nodo Kubernetes Kubelet (:10250/run, /exec, /pods, "
                                ":10255/pods read-only) o el servidor de streaming CRI-O/Containerd (:10010/exec), permitiendo "
                                "exfiltracion de tokens ServiceAccount de todos los pods y ejecucion remota de comandos en contenedores."
                            ),
                            counterexample={
                                "target_endpoints": [
                                    "https://127.0.0.1:10250/run/<ns>/<pod>/<container>",
                                    "http://127.0.0.1:10255/pods",
                                    "http://127.0.0.1:10010/exec/<token>",
                                ],
                                "cwe": "CWE-918 (Server-Side Request Forgery to Kubernetes Node Control Plane)",
                            },
                            remediation=(
                                "Bloquear los puertos 10250 (Kubelet API), 10255 (Kubelet Read-Only) y 10010 (CRI Streaming) "
                                "en el filtro de egress anti-SSRF, deshabilitar '--anonymous-auth=false' y '--read-only-port=0' en Kubelet."
                            ),
                        )
                    )

        overall_safe = blind_rsa_ok and permissions_ok and kubelet_ssrf_ok and len(violations) == 0
        dt = (time.perf_counter() - t0) * 1000.0
        cert = (
            "∀ P ∈ AST_Program: Safe_Nivel101(P) ⟺ "
            "BlindRSA_RFC9474_CoprimeCSPRNG_UnblindVerify_And_PrivacyPass_RFC9578(P) ∧ "
            "W3C_PermissionsPolicy_DenyWildcardHardwareDelegation(P) ∧ "
            "NoUnauthenticatedEgress(P, {Kubelet:10250, KubeletRO:10255, CRIStream:10010}) "
            f"[Verified={overall_safe}, Functions={inspected_functions}, Violations={len(violations)}]"
        )
        return BlindRSAPermissionsKubeletSSRFReport(
            target_path=target_path,
            inspected_functions=inspected_functions,
            blind_rsa_rfc9474_and_privacy_pass_rfc9578_clean=blind_rsa_ok,
            w3c_permissions_policy_and_iframe_allow_clean=permissions_ok,
            kubelet_10250_10255_and_cri_streaming_ssrf_clean=kubelet_ssrf_ok,
            formal_blindrsa_permissions_kubelet_safe=overall_safe,
            violations=violations,
            mathematical_certificate=cert,
            analysis_duration_ms=round(dt, 4),
        )


