class DigestFieldsRFC9530CSPFrameAncestorsAndSparkFlinkClusterSSRFProver:
    """
    Nivel 103 (REG-067): Certificador Formal Tripartito de Campos de Integridad HTTP Digest Fields
    (IETF RFC 9530: `Repr-Digest` y `Content-Digest`, prohibicion de algoritmos rotos md5/sha1/crc32c/adler,
    prohibicion de cabecera obsoleta RFC 3230 `Digest` sin `Repr-Digest`/`Content-Digest`, y comparacion
    constante `hmac.compare_digest`), Directiva W3C CSP `frame-ancestors` (contra Clickjacking y uso de
    `X-Frame-Options: ALLOW-FROM` obsoleto) y Prevencion de SSRF hacia Apache Spark REST Submission API
    (`:6066/v1/submissions/create`) y Apache Flink JobManager REST API (`:8081/jars/upload`, `/jars/<id>/run`).
    """

    @staticmethod
    def audit_rfc9530_digest_frame_ancestors_and_spark_flink_ssrf(
        source_code: str, target_path: str = "<memory>"
    ) -> DigestRFC9530FrameAncestorsSparkSSRFReport:
        return DigestFieldsRFC9530CSPFrameAncestorsAndSparkFlinkClusterSSRFProver().verify_code(source_code, target_path)

    def verify_code(self, source_code: str, target_path: str = "<memory>") -> DigestRFC9530FrameAncestorsSparkSSRFReport:
        t0 = time.perf_counter()
        violations: List[DigestRFC9530FrameAncestorsSparkSSRFViolation] = []
        inspected_functions = 0
        rfc9530_ok = True
        frame_ancestors_ok = True
        spark_flink_ssrf_ok = True

        try:
            tree = ast.parse(source_code)
        except SyntaxError as exc:
            dt = (time.perf_counter() - t0) * 1000.0
            return DigestRFC9530FrameAncestorsSparkSSRFReport(
                target_path=target_path,
                inspected_functions=0,
                digest_fields_rfc9530_repr_content_and_hash_clean=False,
                csp_frame_ancestors_and_clickjacking_clean=False,
                spark_6066_and_flink_8081_cluster_ssrf_clean=False,
                formal_rfc9530_frameancestors_spark_safe=False,
                violations=[
                    DigestRFC9530FrameAncestorsSparkSSRFViolation(
                        line=exc.lineno or 1,
                        function_name="<module>",
                        category="SYNTAX_ERROR",
                        severity="CRITICAL",
                        description=f"Error de sintaxis impide verificacion formal Nivel 103: {exc}",
                        counterexample={"syntax_error": str(exc)},
                        remediation="Corregir la sintaxis Python antes de ejecutar el demostrador Nivel 103.",
                    )
                ],
                mathematical_certificate="UNPROVEN_SYNTAX_ERROR",
                analysis_duration_ms=round(dt, 4),
            )

        func_nodes = [
            n for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]
        if not func_nodes:
            func_nodes = [tree]

        for func in func_nodes:
            fname = getattr(func, "name", "<module>")
            if isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
                inspected_functions += 1
            func_src = ast.unparse(func) if hasattr(ast, "unparse") else source_code
            func_lower = func_src.lower()
            lineno = getattr(func, "lineno", 1)

            # 1. IETF RFC 9530 (Digest Fields: Repr-Digest & Content-Digest)
            is_rfc9530_context = any(
                tok in func_lower
                for tok in (
                    "repr-digest", "content-digest", "want-repr-digest", "want-content-digest",
                    "rfc9530", "digest_header",
                )
            )
            if is_rfc9530_context:
                uses_weak_rfc9530_alg = any(
                    weak in func_lower
                    for weak in (
                        "md5=:", "sha=:", "sha-1=:", "adler=:", "crc32c=:",
                        "unixsum=:", "unixcksum=:", "id-sha-1",
                    )
                )
                confuses_content_and_repr = any(
                    conf in func_lower
                    for conf in ("ignore_content_encoding=true", "mix_repr_and_content_digest=true")
                )
                non_constant_time_digest = (
                    ("repr_digest" in func_lower or "content_digest" in func_lower or "expected_digest" in func_lower)
                    and "compare_digest" not in func_lower
                    and "==" in func_src
                )
                if uses_weak_rfc9530_alg or confuses_content_and_repr or non_constant_time_digest:
                    rfc9530_ok = False
                    violations.append(
                        DigestRFC9530FrameAncestorsSparkSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="RFC9530_DIGEST_FIELDS_WEAK_HASH_OR_TIMING_LEAK",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', implementacion de HTTP Digest Fields (RFC 9530) acepta algoritmos "
                                "degradados o no criptograficos (md5=:, sha=:, adler=:, crc32c=:), confunde Repr-Digest "
                                "con Content-Digest bajo Content-Encoding o compara el digest sin tiempo constante."
                            ),
                            counterexample={
                                "rfc": "IETF RFC 9530 (Digest Fields)",
                                "weak_hash_algorithm": uses_weak_rfc9530_alg,
                                "repr_content_encoding_confusion": confuses_content_and_repr,
                                "non_constant_time_comparison": non_constant_time_digest,
                            },
                            remediation=(
                                "Exigir exclusivamente `sha-256=:<base64>:` o `sha-512=:<base64>:` en cabeceras `Repr-Digest` "
                                "y `Content-Digest` (RFC 9530 Seccion 5), separar el calculo antes/despues de `Content-Encoding` "
                                "y verificar con `hmac.compare_digest`."
                            ),
                        )
                    )

            # 2. W3C CSP `frame-ancestors` & Obsolete `X-Frame-Options: ALLOW-FROM`
            is_frame_ancestors_context = any(
                tok in func_lower
                for tok in (
                    "frame-ancestors", "x-frame-options", "clickjacking",
                )
            )
            if is_frame_ancestors_context:
                has_wildcard_frame_ancestors = any(
                    bad in func_lower
                    for bad in (
                        "frame-ancestors *", "frame-ancestors http:", "frame-ancestors https:",
                        "frame-ancestors data:",
                    )
                )
                uses_obsolete_allow_from = (
                    "allow-from" in func_lower
                    and "frame-ancestors" not in func_lower
                )
                if has_wildcard_frame_ancestors or uses_obsolete_allow_from:
                    frame_ancestors_ok = False
                    violations.append(
                        DigestRFC9530FrameAncestorsSparkSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="CSP_FRAME_ANCESTORS_WILDCARD_OR_OBSOLETE_ALLOW_FROM",
                            severity="HIGH",
                            description=(
                                f"En '{fname}', defensa anti-Clickjacking utiliza `X-Frame-Options: ALLOW-FROM` "
                                "(obsoleto e ignorado por navegadores modernos) sin `Content-Security-Policy: frame-ancestors`, "
                                "o define comodines inseguros (`frame-ancestors *` / `http:` / `https:`)."
                            ),
                            counterexample={
                                "directive": "Content-Security-Policy: frame-ancestors / X-Frame-Options",
                                "wildcard_frame_ancestors": has_wildcard_frame_ancestors,
                                "obsolete_xfo_allow_from": uses_obsolete_allow_from,
                            },
                            remediation=(
                                "Declarar `Content-Security-Policy: frame-ancestors 'none'` (o `'self'` / lista explicita de origenes HTTPS) "
                                "y reemplazar cualquier `X-Frame-Options: ALLOW-FROM` obsoleto."
                            ),
                        )
                    )

            # 3. Apache Spark REST Submission (:6066/v1/submissions/create) & Apache Flink JobManager (:8081/jars/upload) SSRF
            has_spark_flink_marker = any(
                tok in func_lower
                for tok in (
                    ":6066", "/v1/submissions/create", ":8081/jars/upload",
                    "/jars/upload", "/v1/submissions/status", "spark.master.rest",
                )
            )
            if has_spark_flink_marker:
                has_strict_guard = any(
                    g in func_lower
                    for g in (
                        "block_spark_flink_submission_ports", "disallow_spark_flink_ssrf",
                        "assert_not_cluster_submission_endpoint",
                    )
                )
                is_vulnerable_spark_flink = not has_strict_guard and (
                    any(
                        sink in func_lower
                        for sink in (
                            "requests.", "httpx.", "urllib.request", "aiohttp.",
                            "urlopen", "fetch(",
                        )
                    )
                    or any(
                        raw in func_lower
                        for raw in (
                            ":6066/v1/submissions/create", "/v1/submissions/create",
                            ":8081/jars/upload", "/jars/upload",
                        )
                    )
                )
                if is_vulnerable_spark_flink:
                    spark_flink_ssrf_ok = False
                    violations.append(
                        DigestRFC9530FrameAncestorsSparkSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="SPARK_6066_SUBMISSIONS_OR_FLINK_8081_JARS_SSRF_RCE",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', flujo SSRF hacia los planos de control de computo distribuido Apache Spark "
                                "Standalone REST API (`:6066/v1/submissions/create`) o Apache Flink JobManager (`:8081/jars/upload`, "
                                "`/jars/<id>/run`), permitiendo ejecucion remota de codigo (RCE) en todo el cluster de datos."
                            ),
                            counterexample={
                                "target_endpoints": [
                                    "http://127.0.0.1:6066/v1/submissions/create",
                                    "http://127.0.0.1:8081/jars/upload",
                                    "http://127.0.0.1:8081/jars/<jar_id>/run",
                                ],
                                "cwe": "CWE-918 (Server-Side Request Forgery to Distributed Data Cluster RCE)",
                            },
                            remediation=(
                                "Bloquear los puertos 6066 (Spark REST Submission) y 8081 (Flink JobManager) en el validador "
                                "de egress HTTP y deshabilitar `spark.master.rest.enabled=false` en clusters de produccion."
                            ),
                        )
                    )

        overall_safe = rfc9530_ok and frame_ancestors_ok and spark_flink_ssrf_ok and len(violations) == 0
        dt = (time.perf_counter() - t0) * 1000.0
        cert = (
            "∀ P ∈ AST_Program: Safe_Nivel103(P) ⟺ "
            "DigestFields_RFC9530_SHA256Or512_ReprContentSeparated_And_ConstantTime(P) ∧ "
            "W3C_CSP3_FrameAncestorsStrictOrigin_NoObsoleteAllowFrom(P) ∧ "
            "NoUnauthenticatedEgress(P, {SparkSubmission:6066/v1/submissions/create, FlinkJars:8081/jars/upload}) "
            f"[Verified={overall_safe}, Functions={inspected_functions}, Violations={len(violations)}]"
        )
        return DigestRFC9530FrameAncestorsSparkSSRFReport(
            target_path=target_path,
            inspected_functions=inspected_functions,
            digest_fields_rfc9530_repr_content_and_hash_clean=rfc9530_ok,
            csp_frame_ancestors_and_clickjacking_clean=frame_ancestors_ok,
            spark_6066_and_flink_8081_cluster_ssrf_clean=spark_flink_ssrf_ok,
            formal_rfc9530_frameancestors_spark_safe=overall_safe,
            violations=violations,
            mathematical_certificate=cert,
            analysis_duration_ms=round(dt, 4),
        )


