class TLS13EPSKRFC9258CSPScriptSrcAttrAndAirflowPrefectSSRFProver:
    """
    Nivel 105 (REG-069): Certificador Formal Tripartito de Importacion de Claves Pre-Compartidas Externas
    en TLS 1.3 (IETF RFC 9258: derivacion `derived psk` con `Epskid` ligado a protocolo/KDF/identidad contra
    ataques Selfie y confusion inter-protocolo, separacion `ext binder` vs `res binder` y MAC constante),
    Directivas Granulares W3C CSP3 `script-src-attr` y `script-src-elem` (bloqueo de `'unsafe-inline'` en
    manejadores de eventos HTML y `'unsafe-hashes'` sin hash `sha256-` anclado) y Prevencion de SSRF hacia
    Apache Airflow REST API (`:8080/api/v1/dags/<id>/dagRuns`, `/api/experimental/dags`) y Prefect Server
    (`:4200/api/deployments/<id>/create_flow_run`).
    """

    @staticmethod
    def audit_rfc9258_epsk_csp_script_attr_and_airflow_ssrf(
        source_code: str, target_path: str = "<memory>"
    ) -> TLS13EPSKCSPScriptAttrAirflowSSRFReport:
        return TLS13EPSKRFC9258CSPScriptSrcAttrAndAirflowPrefectSSRFProver().verify_code(source_code, target_path)

    def verify_code(self, source_code: str, target_path: str = "<memory>") -> TLS13EPSKCSPScriptAttrAirflowSSRFReport:
        t0 = time.perf_counter()
        violations: List[TLS13EPSKCSPScriptAttrAirflowSSRFViolation] = []
        inspected_functions = 0
        rfc9258_ok = True
        script_attr_ok = True
        airflow_ssrf_ok = True

        try:
            tree = ast.parse(source_code)
        except SyntaxError as exc:
            dt = (time.perf_counter() - t0) * 1000.0
            return TLS13EPSKCSPScriptAttrAirflowSSRFReport(
                target_path=target_path,
                inspected_functions=0,
                tls13_epsk_rfc9258_context_binding_and_binder_mac_clean=False,
                csp_script_src_attr_and_elem_clean=False,
                airflow_8080_dagruns_and_prefect_4200_ssrf_clean=False,
                formal_rfc9258_scriptattr_airflow_safe=False,
                violations=[
                    TLS13EPSKCSPScriptAttrAirflowSSRFViolation(
                        line=exc.lineno or 1,
                        function_name="<module>",
                        category="SYNTAX_ERROR",
                        severity="CRITICAL",
                        description=f"Error de sintaxis impide verificacion formal Nivel 105: {exc}",
                        counterexample={"syntax_error": str(exc)},
                        remediation="Corregir la sintaxis Python antes de ejecutar el demostrador Nivel 105.",
                    )
                ],
                mathematical_certificate="UNPROVEN_SYNTAX_ERROR",
                analysis_duration_ms=round(dt, 4),
            )

        func_nodes = [
            n for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]
        if not func_nodes:
            func_nodes = [tree]

        for func in func_nodes:
            fname = getattr(func, "name", "<module>")
            if isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
                inspected_functions += 1
            func_src = ast.unparse(func) if hasattr(ast, "unparse") else source_code
            func_lower = func_src.lower()
            lineno = getattr(func, "lineno", 1)

            # 1. IETF RFC 9258 (Importing External PSKs for TLS 1.3)
            is_rfc9258_context = any(
                tok in func_lower
                for tok in (
                    "rfc9258", "external_psk", "import_psk", "epsk", "epskid",
                    "psk_binder", "ext binder", "res binder", "derived psk",
                )
            )
            if is_rfc9258_context:
                raw_epsk_without_import_schedule = (
                    any(m in func_lower for m in ("use_raw_epsk=true", "skip_psk_import=true", "res binder"))
                    and "derived psk" not in func_lower
                )
                missing_context_binding = (
                    ("epsk" in func_lower or "external_psk" in func_lower)
                    and "derived psk" not in func_lower
                    and "hkdf" not in func_lower
                )
                non_constant_time_binder = (
                    ("psk_binder" in func_lower or "expected_binder" in func_lower)
                    and "compare_digest" not in func_lower
                    and "==" in func_src
                )
                if raw_epsk_without_import_schedule or missing_context_binding or non_constant_time_binder:
                    rfc9258_ok = False
                    violations.append(
                        TLS13EPSKCSPScriptAttrAirflowSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="TLS13_EPSK_RFC9258_MISSING_IMPORT_SCHEDULE_OR_SELFIE_ATTACK",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', implementacion de External PSK en TLS 1.3 (RFC 9258) reutiliza la clave "
                                "externa cruda sin derivar `ipsk = HKDF-Expand-Label(epskx, 'derived psk', Hash(Epskid), L)`, "
                                "mezcla etiquetas `res binder` con `ext binder` (ataque Selfie / confusion inter-protocolo) "
                                "o compara el `psk_binder` sin tiempo constante."
                            ),
                            counterexample={
                                "rfc": "IETF RFC 9258 (Importing External PSKs for TLS 1.3)",
                                "raw_epsk_without_import": raw_epsk_without_import_schedule,
                                "missing_epskid_context_binding": missing_context_binding,
                                "non_constant_time_binder_mac": non_constant_time_binder,
                            },
                            remediation=(
                                "Derivar siempre `ipsk` mediante el Key Schedule de RFC 9258 Seccion 5.1 ligando `Epskid` "
                                "(external_identity + target_protocol + target_kdf), emplear la etiqueta `'ext binder'` "
                                "y verificar `psk_binder` con `hmac.compare_digest`."
                            ),
                        )
                    )

            # 2. W3C CSP3 `script-src-attr` & `script-src-elem` Directives
            is_script_attr_context = any(
                tok in func_lower
                for tok in (
                    "script-src-attr", "script-src-elem", "unsafe-hashes",
                )
            )
            if is_script_attr_context:
                allows_unsafe_inline_attr = any(
                    bad in func_lower
                    for bad in (
                        "script-src-attr 'unsafe-inline'", "script-src-elem 'unsafe-inline'",
                        "script-src-elem *", "script-src-elem http:",
                    )
                )
                unsafe_hashes_without_digest = (
                    "'unsafe-hashes'" in func_lower
                    and not any(h in func_lower for h in ("'sha256-", "'sha384-", "'sha512-"))
                )
                if allows_unsafe_inline_attr or unsafe_hashes_without_digest:
                    script_attr_ok = False
                    violations.append(
                        TLS13EPSKCSPScriptAttrAirflowSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="CSP_SCRIPT_SRC_ATTR_UNSAFE_INLINE_OR_UNPINNED_HASHES",
                            severity="HIGH",
                            description=(
                                f"En '{fname}', directiva granular W3C CSP3 `script-src-attr` o `script-src-elem` habilita "
                                "`'unsafe-inline'` (permitiendo ejecucion XSS en atributos `onload=`/`onerror=`/`onclick=`) "
                                "o declara `'unsafe-hashes'` sin fijar un digest `'sha256-...'` / `'sha384-...'` especifico."
                            ),
                            counterexample={
                                "directive": "Content-Security-Policy: script-src-attr / script-src-elem",
                                "unsafe_inline_in_attr_or_elem": allows_unsafe_inline_attr,
                                "unpinned_unsafe_hashes": unsafe_hashes_without_digest,
                            },
                            remediation=(
                                "Establecer `script-src-attr 'none'` para bloquear todo manejador de eventos inline en HTML "
                                "y exigir nonces o hashes `'sha256-...'` explicitos en `script-src-elem`."
                            ),
                        )
                    )

            # 3. Apache Airflow REST API (:8080/api/v1/dags/<id>/dagRuns) & Prefect Server (:4200/api/deployments) SSRF
            has_airflow_prefect_marker = any(
                tok in func_lower
                for tok in (
                    "/api/v1/dags/", "/dagruns", "/api/experimental/dags/",
                    ":4200/api/deployments", "/create_flow_run",
                )
            )
            if has_airflow_prefect_marker:
                has_strict_guard = any(
                    g in func_lower
                    for g in (
                        "block_airflow_prefect_ports", "disallow_workflow_api_ssrf",
                        "assert_not_dagrun_endpoint",
                    )
                )
                is_vulnerable_airflow = not has_strict_guard and (
                    any(
                        sink in func_lower
                        for sink in (
                            "requests.", "httpx.", "urllib.request", "aiohttp.",
                            "urlopen", "fetch(",
                        )
                    )
                    or any(
                        raw in func_lower
                        for raw in (
                            "/api/v1/dags/", "/dagruns", "/api/experimental/dags/",
                            ":4200/api/deployments", "/create_flow_run",
                        )
                    )
                )
                if is_vulnerable_airflow:
                    airflow_ssrf_ok = False
                    violations.append(
                        TLS13EPSKCSPScriptAttrAirflowSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="AIRFLOW_8080_DAGRUNS_OR_PREFECT_4200_FLOWRUN_SSRF_RCE",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', flujo SSRF hacia los planos de orquestacion de workflows Apache Airflow "
                                "(`:8080/api/v1/dags/<id>/dagRuns`, `/api/experimental/dags/`, CVE-2020-11978) o Prefect Server "
                                "(`:4200/api/deployments/<id>/create_flow_run`), permitiendo disparo no autorizado de DAGs con "
                                "payloads `conf` arbitrarios y RCE en workers."
                            ),
                            counterexample={
                                "target_endpoints": [
                                    "http://127.0.0.1:8080/api/v1/dags/example_bash_operator/dagRuns",
                                    "http://127.0.0.1:8080/api/experimental/dags/example_bash_operator/dag_runs",
                                    "http://127.0.0.1:4200/api/deployments/<id>/create_flow_run",
                                ],
                                "cwe": "CWE-918 (Server-Side Request Forgery to Workflow Orchestrator RCE)",
                            },
                            remediation=(
                                "Bloquear las rutas `/api/v1/dags/*/dagRuns`, `/api/experimental/dags/*` y el puerto 4200 (Prefect) "
                                "en el filtro de egress HTTP, y exigir `auth_backend = airflow.api.auth.backend.basic_auth` / OAuth2."
                            ),
                        )
                    )

        overall_safe = rfc9258_ok and script_attr_ok and airflow_ssrf_ok and len(violations) == 0
        dt = (time.perf_counter() - t0) * 1000.0
        cert = (
            "∀ P ∈ AST_Program: Safe_Nivel105(P) ⟺ "
            "TLS13_EPSK_RFC9258_DerivedPSK_ExtBinder_And_ConstantTimeMAC(P) ∧ "
            "W3C_CSP3_ScriptSrcAttrNone_And_PinnedScriptSrcElem(P) ∧ "
            "NoUnauthenticatedEgress(P, {AirflowDAGRuns:8080/api/v1/dags/*/dagRuns, PrefectFlowRun:4200/api/deployments}) "
            f"[Verified={overall_safe}, Functions={inspected_functions}, Violations={len(violations)}]"
        )
        return TLS13EPSKCSPScriptAttrAirflowSSRFReport(
            target_path=target_path,
            inspected_functions=inspected_functions,
            tls13_epsk_rfc9258_context_binding_and_binder_mac_clean=rfc9258_ok,
            csp_script_src_attr_and_elem_clean=script_attr_ok,
            airflow_8080_dagruns_and_prefect_4200_ssrf_clean=airflow_ssrf_ok,
            formal_rfc9258_scriptattr_airflow_safe=overall_safe,
            violations=violations,
            mathematical_certificate=cert,
            analysis_duration_ms=round(dt, 4),
        )


