class Ristretto255RFC9496CSPObjectSrcAndKafkaConnectSSRFProver:
    """
    Nivel 107 (REG-071): Certificador Formal Tripartito de Grupos de Orden Primo Ristretto255 y Decaf448
    (IETF RFC 9496: rechazo obligatorio de codificaciones no canonicas `s >= p` o `IS_NEGATIVE(s) == 1` en
    DECODE, prohibicion de comparacion directa de tuplas proyectivas `(X, Y, Z, T)` y comparacion constante
    sobre `ENCODE` / equivalencia proyectiva), Directiva W3C CSP `object-src 'none'` (bloqueo de ejecucion
    de plugins/<object>/<embed> desde CDNs en `default-src`) y Prevencion de SSRF hacia Apache Kafka Connect
    REST API (`:8083/connectors`, CVE-2023-25194 JNDI RCE) y ZooKeeper AdminServer (`:8080/commands`).
    """

    @staticmethod
    def audit_rfc9496_ristretto255_csp_object_src_and_kafka_connect_ssrf(
        source_code: str, target_path: str = "<memory>"
    ) -> Ristretto255CSPObjectSrcKafkaSSRFReport:
        return Ristretto255RFC9496CSPObjectSrcAndKafkaConnectSSRFProver().verify_code(source_code, target_path)

    def verify_code(self, source_code: str, target_path: str = "<memory>") -> Ristretto255CSPObjectSrcKafkaSSRFReport:
        t0 = time.perf_counter()
        violations: List[Ristretto255CSPObjectSrcKafkaSSRFViolation] = []
        inspected_functions = 0
        rfc9496_ok = True
        object_src_ok = True
        kafka_ssrf_ok = True

        try:
            tree = ast.parse(source_code)
        except SyntaxError as exc:
            dt = (time.perf_counter() - t0) * 1000.0
            return Ristretto255CSPObjectSrcKafkaSSRFReport(
                target_path=target_path,
                inspected_functions=0,
                ristretto255_decaf448_rfc9496_canonical_decode_and_equals_clean=False,
                csp_object_src_none_and_plugin_isolation_clean=False,
                kafka_connect_8083_jndi_and_zk_admin_ssrf_clean=False,
                formal_rfc9496_objectsrc_kafkaconnect_safe=False,
                violations=[
                    Ristretto255CSPObjectSrcKafkaSSRFViolation(
                        line=exc.lineno or 1,
                        function_name="<module>",
                        category="SYNTAX_ERROR",
                        severity="CRITICAL",
                        description=f"Error de sintaxis impide verificacion formal Nivel 107: {exc}",
                        counterexample={"syntax_error": str(exc)},
                        remediation="Corregir la sintaxis Python antes de ejecutar el demostrador Nivel 107.",
                    )
                ],
                mathematical_certificate="UNPROVEN_SYNTAX_ERROR",
                analysis_duration_ms=round(dt, 4),
            )

        func_nodes = [
            n for n in ast.walk(tree)
            if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))
        ]
        if not func_nodes:
            func_nodes = [tree]

        for func in func_nodes:
            fname = getattr(func, "name", "<module>")
            if isinstance(func, (ast.FunctionDef, ast.AsyncFunctionDef)):
                inspected_functions += 1
            func_src = ast.unparse(func) if hasattr(ast, "unparse") else source_code
            func_lower = func_src.lower()
            lineno = getattr(func, "lineno", 1)

            # 1. IETF RFC 9496 (Ristretto255 & Decaf448 Prime-Order Groups)
            is_rfc9496_context = any(
                tok in func_lower
                for tok in (
                    "ristretto255", "decaf448", "rfc9496", "ristretto_decode",
                    "ristretto_equals", "decaf_decode",
                )
            )
            if is_rfc9496_context:
                accepts_non_canonical = any(
                    bad in func_lower
                    for bad in (
                        "allow_non_canonical=true", "skip_is_negative_check=true",
                        "reduce_mod_p_on_decode=true",
                    )
                )
                raw_projective_tuple_compare = (
                    ("point_p" in func_lower or "ristretto" in func_lower)
                    and "compare_digest" not in func_lower
                    and "projective_equals" not in func_lower
                    and "==" in func_src
                )
                if accepts_non_canonical or raw_projective_tuple_compare:
                    rfc9496_ok = False
                    violations.append(
                        Ristretto255CSPObjectSrcKafkaSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="RISTRETTO255_DECAF448_RFC9496_NON_CANONICAL_OR_TUPLE_EQUALITY",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', implementacion de Ristretto255/Decaf448 (RFC 9496) acepta bytes "
                                "no canonicos (`s >= p` o `IS_NEGATIVE(s) == 1`) durante `DECODE` o compara coordenadas "
                                "proyectivas `(X, Y, Z, T)` directamente con `==` en vez de evaluar equivalencia "
                                "proyectiva en tiempo constante (`hmac.compare_digest` sobre `ENCODE`)."
                            ),
                            counterexample={
                                "rfc": "IETF RFC 9496 (Ristretto255 and Decaf448)",
                                "accepts_non_canonical_encoding": accepts_non_canonical,
                                "raw_projective_or_non_constant_compare": raw_projective_tuple_compare,
                            },
                            remediation=(
                                "Rechazar en `DECODE` todo string donde `s >= p`, `IS_NEGATIVE(s) == 1`, `IS_NEGATIVE(y) == 1` "
                                "o `y == 0` (RFC 9496 Seccion 4.3.1), y comparar elementos mediante `hmac.compare_digest(encode(P), encode(Q))`."
                            ),
                        )
                    )

            # 2. W3C CSP `object-src 'none'` & `<object>` / `<embed>` Plugin Isolation
            is_object_src_context = any(
                tok in func_lower
                for tok in (
                    "object-src", "<object", "<embed",
                )
            )
            if is_object_src_context:
                permissive_object_src = any(
                    bad in func_lower
                    for bad in (
                        "object-src *", "object-src data:", "object-src http:",
                        "object-src https:", "object-src 'unsafe-inline'",
                    )
                )
                if permissive_object_src:
                    object_src_ok = False
                    violations.append(
                        Ristretto255CSPObjectSrcKafkaSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="CSP_OBJECT_SRC_PERMISSIVE_PLUGIN_OR_DATA_XSS",
                            severity="HIGH",
                            description=(
                                f"En '{fname}', directiva W3C CSP `object-src` permite comodines (`*`, `http:`, `https:`) "
                                "o esquemas `data:`, habilitando inyeccion de `<object data=...>` / `<embed src=...>` "
                                "para ejecutar scripts en el origen activo."
                            ),
                            counterexample={
                                "directive": "Content-Security-Policy: object-src",
                                "permissive_object_src": permissive_object_src,
                            },
                            remediation=(
                                "Declarar estrictamente `object-src 'none'` en toda politica Content-Security-Policy "
                                "para desactivar la carga de `<object>`, `<embed>` y `<applet>`."
                            ),
                        )
                    )

            # 3. Apache Kafka Connect REST API (:8083/connectors, CVE-2023-25194) & ZooKeeper AdminServer (:8080/commands) SSRF
            has_kafka_connect_marker = any(
                tok in func_lower
                for tok in (
                    ":8083/connectors", ":8083/connector-plugins",
                    "jndiloginmodule", "sasl.jaas.config", ":8080/commands/envi",
                )
            )
            if has_kafka_connect_marker:
                has_strict_guard = any(
                    g in func_lower
                    for g in (
                        "block_kafka_connect_8083", "disallow_kafka_connect_ssrf",
                        "assert_not_kafka_connect_endpoint",
                    )
                )
                is_vulnerable_kafka = not has_strict_guard and (
                    any(
                        sink in func_lower
                        for sink in (
                            "requests.", "httpx.", "urllib.request", "aiohttp.",
                            "urlopen", "fetch(",
                        )
                    )
                    or any(
                        raw in func_lower
                        for raw in (
                            ":8083/connectors", ":8083/connector-plugins",
                            "jndiloginmodule", ":8080/commands/envi",
                        )
                    )
                )
                if is_vulnerable_kafka:
                    kafka_ssrf_ok = False
                    violations.append(
                        Ristretto255CSPObjectSrcKafkaSSRFViolation(
                            line=lineno,
                            function_name=fname,
                            category="KAFKA_CONNECT_8083_JNDI_OR_ZOOKEEPER_ADMIN_SSRF_RCE",
                            severity="CRITICAL",
                            description=(
                                f"En '{fname}', flujo SSRF hacia Apache Kafka Connect REST API (`:8083/connectors`, "
                                "`:8083/connector-plugins`, CVE-2023-25194 inyeccion JNDI en `sasl.jaas.config`) "
                                "o ZooKeeper AdminServer (`:8080/commands/envi`), permitiendo instanciar conectores maliciosos y RCE."
                            ),
                            counterexample={
                                "target_endpoints": [
                                    "http://127.0.0.1:8083/connectors",
                                    "http://127.0.0.1:8083/connector-plugins",
                                    "http://127.0.0.1:8080/commands/envi",
                                ],
                                "cve": "CVE-2023-25194 (Apache Kafka Connect sasl.jaas.config JndiLoginModule RCE via SSRF)",
                            },
                            remediation=(
                                "Bloquear el puerto 8083 (Kafka Connect REST) y `/commands/*` (ZooKeeper AdminServer) en el "
                                "validador de egress HTTP, y deshabilitar `JndiLoginModule` mediante `-Dorg.apache.kafka.disallowed.login.modules`."
                            ),
                        )
                    )

        overall_safe = rfc9496_ok and object_src_ok and kafka_ssrf_ok and len(violations) == 0
        dt = (time.perf_counter() - t0) * 1000.0
        cert = (
            "∀ P ∈ AST_Program: Safe_Nivel107(P) ⟺ "
            "Ristretto255_Decaf448_RFC9496_CanonicalDecode_And_ConstantTimeEquals(P) ∧ "
            "W3C_CSP3_ObjectSrcNone(P) ∧ "
            "NoUnauthenticatedEgress(P, {KafkaConnect:8083/connectors, ZooKeeperAdmin:8080/commands}) "
            f"[Verified={overall_safe}, Functions={inspected_functions}, Violations={len(violations)}]"
        )
        return Ristretto255CSPObjectSrcKafkaSSRFReport(
            target_path=target_path,
            inspected_functions=inspected_functions,
            ristretto255_decaf448_rfc9496_canonical_decode_and_equals_clean=rfc9496_ok,
            csp_object_src_none_and_plugin_isolation_clean=object_src_ok,
            kafka_connect_8083_jndi_and_zk_admin_ssrf_clean=kafka_ssrf_ok,
            formal_rfc9496_objectsrc_kafkaconnect_safe=overall_safe,
            violations=violations,
            mathematical_certificate=cert,
            analysis_duration_ms=round(dt, 4),
        )


