# ==============================================================================
# NIVEL 109 (v11.2.0 - NODE-04): IETF RFC 9578 PRIVACY PASS TOKEN ISSUANCE &
# REDEMPTION, W3C CSP3 CONNECT-SRC EXFILTRATION ISOLATION & MLFLOW/GRADIO SSRF
# ==============================================================================

@dataclass
class PrivacyPassConnectSrcMLflowSSRFViolation:
    category: str
    function_name: str
    line_number: int
    description: str
    remediation: str
    cwe_or_rfc: str


@dataclass
class PrivacyPassConnectSrcMLflowSSRFReport:
    target_path: str
    inspected_functions: int
    privacy_pass_rfc9578_token_nonce_and_challenge_digest_clean: bool
    csp_connect_src_and_beacon_websocket_isolation_clean: bool
    mlflow_tracking_and_gradio_queue_proxy_ssrf_clean: bool
    formal_privacypass_connectsrc_mlflow_safe: bool
    violations: List[PrivacyPassConnectSrcMLflowSSRFViolation]
    mathematical_certificate: str
    analysis_duration_ms: float


class PrivacyPassRFC9578CSPConnectSrcAndMLflowGradioSSRFProver:
    """
    Demostrador Formal Nivel 109 (NODE-04 Shard: Red-Team Security, IFDS Taint,
    Criptografía de Tiempo Constante, CSP y Anti-SSRF):
    1. IETF RFC 9578 Privacy Pass Token Issuance & Redemption Protocol:
       - Detecta verificación de tokens Privacy Pass (type 0x0001 VOPRF / 0x0002 Blind RSA)
         que omiten el cálculo criptográfico de challenge_digest = SHA256(TokenChallenge),
         carecen de registro atómico anti-replay de token.nonce (double-spend cache) o
         comparan el autenticador/MAC con operadores no constantes (== / !=).
    2. W3C CSP3 connect-src & Exfiltration Sink Isolation:
       - Detecta cabeceras Content-Security-Policy con connect-src permisivo
         (connect-src *, connect-src ws:, connect-src wss: *, connect-src data:,
         connect-src http:) o invocaciones a navigator.sendBeacon / new WebSocket /
         new EventSource con URLs dinámicas no validadas.
    3. Anti-SSRF en MLflow Tracking Server (GHSA-65h7-c7c4-mghx / CVE-2024-2928) y
       Gradio Queue/File Proxy (CVE-2024-4325):
       - Detecta solicitudes HTTP o registro de modelos/artefactos hacia endpoints de
         MLflow (:5000/api/2.0/mlflow, /ajax-api/2.0/mlflow, artifact_location,
         model-versions/create) o Gradio (/queue/join, /file=, proxy_url) sin lista
         blanca de orígenes ni bloqueo de IPs privadas/loopback/link-local.
    """

    def verify_code(self, source_code: str, target_path: str = "<memory>") -> PrivacyPassConnectSrcMLflowSSRFReport:
        t0 = time.perf_counter()
        violations: List[PrivacyPassConnectSrcMLflowSSRFViolation] = []
        try:
            tree = ast.parse(source_code)
        except SyntaxError:
            elapsed = round((time.perf_counter() - t0) * 1000.0, 4)
            return PrivacyPassConnectSrcMLflowSSRFReport(
                target_path=target_path,
                inspected_functions=0,
                privacy_pass_rfc9578_token_nonce_and_challenge_digest_clean=False,
                csp_connect_src_and_beacon_websocket_isolation_clean=False,
                mlflow_tracking_and_gradio_queue_proxy_ssrf_clean=False,
                formal_privacypass_connectsrc_mlflow_safe=False,
                violations=[],
                mathematical_certificate="SYNTAX_ERROR",
                analysis_duration_ms=elapsed,
            )

        functions = [n for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))]
        privacypass_ok = True
        connectsrc_ok = True
        mlflow_ok = True

        for fn in functions:
            fn_src = ast.get_source_segment(source_code, fn) or ""
            fn_lower = fn_src.lower()

            # 1. Check IETF RFC 9578 Privacy Pass Token Issuance & Redemption
            touches_privacypass = any(
                kw in fn_lower
                for kw in (
                    "privacy_pass", "privacypass", "rfc9578", "token_challenge",
                    "challenge_digest", "blind_rsa_token", "voprf_token", "redeem_token"
                )
            )
            if touches_privacypass:
                has_challenge_digest = (
                    "sha256" in fn_lower and ("challenge_digest" in fn_lower or "token_challenge" in fn_lower)
                )
                has_nonce_replay_guard = any(
                    g in fn_lower
                    for g in (
                        "spent_nonces", "nonce_cache", "seen_nonces", "redeemed_nonces",
                        "check_and_mark_nonce", "nonce in "
                    )
                )
                has_ct_verify = (
                    "compare_digest" in fn_lower
                    or "verify_blind_rsa" in fn_lower
                    or "constant_time" in fn_lower
                )
                has_leaky_eq = (
                    ("authenticator ==" in fn_lower or "token_mac ==" in fn_lower or "tag ==" in fn_lower)
                    and "compare_digest" not in fn_lower
                )
                if not has_challenge_digest or not has_nonce_replay_guard or not has_ct_verify or has_leaky_eq:
                    privacypass_ok = False
                    violations.append(
                        PrivacyPassConnectSrcMLflowSSRFViolation(
                            category="PRIVACY_PASS_RFC9578_NONCE_REPLAY_OR_CHALLENGE_DIGEST_WEAKNESS",
                            function_name=fn.name,
                            line_number=fn.lineno,
                            description=(
                                f"Función '{fn.name}' implementa emisión/redención de tokens Privacy Pass (RFC 9578) "
                                "sin validar challenge_digest = SHA256(TokenChallenge), sin caché anti-replay de "
                                "token.nonce o comparando el autenticador con '=='."
                            ),
                            remediation=(
                                "Computar challenge_digest = hashlib.sha256(token_challenge).digest(), registrar "
                                "atómicamente el nonce en spent_nonces para impedir double-spending y verificar "
                                "el autenticador con hmac.compare_digest."
                            ),
                            cwe_or_rfc="IETF RFC 9578 / RFC 9576 / CWE-294 / CWE-208",
                        )
                    )

            # 2. Check W3C CSP3 connect-src & Exfiltration Sink Isolation
            touches_connect_src = any(
                kw in fn_lower
                for kw in ("connect-src", "sendbeacon", "new websocket", "new eventsource")
            )
            if touches_connect_src:
                unsafe_connect_policy = any(
                    pat in fn_lower
                    for pat in (
                        "connect-src *",
                        "connect-src 'unsafe-",
                        "connect-src data:",
                        "connect-src http:",
                        "connect-src ws:",
                        "connect-src wss: *",
                    )
                )
                unvalidated_exfil_sink = (
                    ("sendbeacon(" in fn_lower or "new websocket(" in fn_lower or "new eventsource(" in fn_lower)
                    and "allowed_connect_origins" not in fn_lower
                    and "connect-src 'self'" not in fn_lower
                )
                if unsafe_connect_policy or unvalidated_exfil_sink:
                    connectsrc_ok = False
                    violations.append(
                        PrivacyPassConnectSrcMLflowSSRFViolation(
                            category="CSP_CONNECT_SRC_WILDCARD_OR_UNVALIDATED_BEACON_WEBSOCKET_EXFIL",
                            function_name=fn.name,
                            line_number=fn.lineno,
                            description=(
                                f"Función '{fn.name}' define una directiva CSP connect-src permisiva (wildcard '*', "
                                "ws:/http:/data:) o invoca sendBeacon/WebSocket/EventSource hacia orígenes no verificados."
                            ),
                            remediation=(
                                "Restringir Content-Security-Policy a \"connect-src 'self' https://api-confiable.internal;\" "
                                "y validar todo destino de sendBeacon/WebSocket contra allowed_connect_origins."
                            ),
                            cwe_or_rfc="W3C CSP3 connect-src / CWE-359 / CWE-942",
                        )
                    )

            # 3. Check MLflow Tracking Server & Gradio Queue/File Proxy SSRF
            touches_mlflow_or_gradio = any(
                kw in fn_lower
                for kw in (
                    ":5000/api/2.0/mlflow", "/ajax-api/2.0/mlflow", "artifact_location",
                    "registered-models", "model-versions/create", "/queue/join",
                    "gradio", "/file=http", "proxy_url"
                )
            )
            if touches_mlflow_or_gradio:
                has_egress_guard = (
                    ("allowed_ml_hosts" in fn_lower or "allowed_artifact_hosts" in fn_lower or "validate_egress" in fn_lower)
                    and ("is_private" in fn_lower or "is_loopback" in fn_lower)
                )
                if not has_egress_guard:
                    mlflow_ok = False
                    violations.append(
                        PrivacyPassConnectSrcMLflowSSRFViolation(
                            category="MLFLOW_ARTIFACT_REGISTRY_OR_GRADIO_QUEUE_PROXY_SSRF",
                            function_name=fn.name,
                            line_number=fn.lineno,
                            description=(
                                f"Función '{fn.name}' interactúa con endpoints de MLflow (:5000/api/2.0/mlflow, "
                                "artifact_location) o Gradio (/queue/join, /file=, proxy_url) permitiendo SSRF "
                                "(GHSA-65h7-c7c4-mghx / CVE-2024-2928 / CVE-2024-4325) sin validación de host ni bloqueo de IPs privadas."
                            ),
                            remediation=(
                                "Validar la URL contra una lista blanca estricta (allowed_ml_hosts / allowed_artifact_hosts), "
                                "exigir esquema https:// y bloquear rangos RFC1918, loopback y link-local antes de invocar MLflow o Gradio."
                            ),
                            cwe_or_rfc="GHSA-65h7-c7c4-mghx / CVE-2024-2928 / CVE-2024-4325 / CWE-918",
                        )
                    )

        overall_safe = privacypass_ok and connectsrc_ok and mlflow_ok
        elapsed = round((time.perf_counter() - t0) * 1000.0, 4)
        cert = (
            f"∀ P ∈ AST_Program: Safe_Nivel109(P) ⟺ "
            f"RFC9578_PrivacyPass_SHA256ChallengeDigest_NonceAntiReplay_And_ConstantTimeAuth(P) ∧ "
            f"W3C_CSP3_ConnectSrcStrictOriginAndBeaconGuard(P) ∧ "
            f"NoUnauthenticatedEgress(P, {{MLflow:5000/api/2.0/mlflow, Gradio:/queue/join|/file=}}) "
            f"[Verified={overall_safe}, Functions={len(functions)}, Violations={len(violations)}]"
        )
        return PrivacyPassConnectSrcMLflowSSRFReport(
            target_path=target_path,
            inspected_functions=len(functions),
            privacy_pass_rfc9578_token_nonce_and_challenge_digest_clean=privacypass_ok,
            csp_connect_src_and_beacon_websocket_isolation_clean=connectsrc_ok,
            mlflow_tracking_and_gradio_queue_proxy_ssrf_clean=mlflow_ok,
            formal_privacypass_connectsrc_mlflow_safe=overall_safe,
            violations=violations,
            mathematical_certificate=cert,
            analysis_duration_ms=elapsed,
        )

    def verify_directory(self, root_dir: str) -> Dict[str, Any]:
        t0 = time.perf_counter()
        total_files = 0
        total_functions = 0
        all_violations: List[Dict[str, Any]] = []
        for dirpath, dirnames, filenames in os.walk(root_dir):
            dirnames[:] = [d for d in sorted(dirnames) if d not in ("__pycache__", ".git", ".venv", "tests")]
            for fname in sorted(filenames):
                if not fname.endswith(".py") or fname == "z3_prover.py":
                    continue
                fpath = os.path.join(dirpath, fname)
                try:
                    with open(fpath, "r", encoding="utf-8") as fh:
                        src = fh.read()
                except OSError:
                    continue
                rep = self.verify_code(src, fpath)
                total_files += 1
                total_functions += rep.inspected_functions
                for v in rep.violations:
                    all_violations.append(asdict(v))
        return {
            "root_dir": root_dir,
            "inspected_files": total_files,
            "inspected_functions": total_functions,
            "formal_privacypass_connectsrc_mlflow_safe": len(all_violations) == 0,
            "violations": all_violations,
            "analysis_duration_ms": round((time.perf_counter() - t0) * 1000.0, 4),
        }


