            oblivious_http_rfc9458_relay_gateway_separation_and_hpke_clean=ohttp_ok,
            csp_img_src_and_media_src_dangling_markup_isolation_clean=imgsrc_ok,
            jupyter_server_proxy_and_bentoml_runner_ssrf_clean=jupyter_ok,
