# NIVEL 78: EXPLORADOR CONCÓLICO DE NEGACIÓN SIMBÓLICA DE RAMAS (DART / CUTE /
# SAGE) Y CERTIFICADOR CYCLONEDX v1.6 CRYPTOGRAPHIC BILL OF MATERIALS (CBOM /
# POST-QUANTUM READINESS NIST CNSA 2.0) PCC (NODE-06 v8.5.0)
# ============================================================================

@dataclass
class ConcolicBranchAndCycloneDXCBOMReport:
    release_version: str
    proven_concolic_feasible_and_cbom_quantum_safe: bool
    extracted_branches_count: int
    synthesized_negation_witnesses: List[Dict[str, Any]]
    infeasible_or_dead_branches: List[str]
    quantum_vulnerable_primitives: List[str]
    cyclonedx_v1_6_cbom_document: Dict[str, Any]
    concolic_cbom_pcc_seal_sha256: str
    analysis_duration_ms: float


class ConcolicBranchExplorerAndCycloneDXCBOMProver:
    """
    Nivel 78 (NODE-06 v8.5.0):
    1. Explorador Concólico de Negación Simbólica de Predicados de Rama (DART - Godefroid,
       Klarlund & Sen / CUTE - Sen, Marinov & Agha / SAGE - Godefroid, Levin & Molnar):
       Analiza el AST de funciones críticas, extrae cada restricción de rama condicional c_i
       (ast.If / ast.Compare), construye la restricción simbólica negada ~c_i invirtiendo el
       operador relacional (< <-> >=, <= <-> >, == <-> !=) y sintetiza testigos de frontera
       (k - 1, k, k + 1) que fuerzan la transición concólica entre la rama verdadera y falsa.
       Detecta ramas muertas o contradicciones algebraicas triviales (ej. x < 5 and x > 10).
    2. Certificador CycloneDX v1.6 Cryptographic Bill of Materials (CBOM) y Post-Quantum
       Readiness (OWASP CycloneDX 1.6 / IBM Research CBOM / NIST FIPS 203 ML-KEM & FIPS 204 ML-DSA):
       Audita todos los activos criptográficos del release, rechaza primitivas vulnerables al
       algoritmo de Shor o colisiones clásicas (MD5, SHA-1, DES, 3DES, RSA-1024, RSA-2048, ECDSA
       clásico sin hibridación PQC) y emite un documento canónico CycloneDX 1.6 con componentes
       de tipo 'crypto-asset' sellado con HMAC-SHA256 sobre el linaje CAS del enjambre.
    """

    CONCOLIC_CBOM_SALT = "ALEPH_SOVEREIGN_CONCOLIC_SAGE_CYCLONEDX_CBOM_V8_5_PCC_2026"

    NEGATION_MAP = {
        "Lt": ("Ge", ">="),
        "LtE": ("Gt", ">"),
        "Gt": ("LtE", "<="),
        "GtE": ("Lt", "<"),
        "Eq": ("NotEq", "!="),
        "NotEq": ("Eq", "=="),
    }

    QUANTUM_SAFE_PRIMITIVES = {
        "SHA-256", "SHA-384", "SHA-512", "SHA3-256", "SHA3-512",
        "HMAC-SHA256", "HMAC-SHA512", "AES-256-GCM", "CHACHA20-POLY1305",
        "ML-KEM-768", "ML-KEM-1024", "ML-DSA-65", "ML-DSA-87", "SLH-DSA-SHA2-256S"
    }

    @classmethod
    def explore_concolic_branches_and_attest_cyclonedx_cbom(
        cls,
        source_code: str,
        cryptographic_assets: List[Dict[str, Any]],
        parent_bundle_sha256: str = "",
        release_version: str = "8.5.0"
    ) -> ConcolicBranchAndCycloneDXCBOMReport:
        import ast, json, hmac
        t0 = time.perf_counter_ns()

        tree = ast.parse(source_code)
        witnesses: List[Dict[str, Any]] = []
        infeasible: List[str] = []
        branch_count = 0

        for node in ast.walk(tree):
            if isinstance(node, ast.If):
                branch_count += 1
                test = node.test
                if isinstance(test, ast.Compare) and len(test.ops) == 1 and len(test.comparators) == 1:
                    op_name = type(test.ops[0]).__name__
                    var_name = test.left.id if isinstance(test.left, ast.Name) else ast.unparse(test.left)
                    comp = test.comparators[0]
                    if isinstance(comp, ast.Constant) and isinstance(comp.value, (int, float)):
                        k = comp.value
                        neg_op, neg_sym = cls.NEGATION_MAP.get(op_name, ("Negated", "not"))
                        if op_name in ("Lt", "GtE"):
                            true_w, false_w = (k - 1, k) if op_name == "Lt" else (k, k - 1)
                        elif op_name in ("LtE", "Gt"):
                            true_w, false_w = (k, k + 1) if op_name == "LtE" else (k + 1, k)
                        else:
                            true_w, false_w = (k, k + 1) if op_name == "Eq" else (k + 1, k)
                        witnesses.append({
                            "line": getattr(node, "lineno", 0),
                            "variable": var_name,
                            "original_predicate": ast.unparse(test),
                            "negated_predicate": f"{var_name} {neg_sym} {k}",
                            "true_branch_witness": true_w,
                            "false_branch_witness": false_w,
                            "negation_operator": neg_op
                        })
                elif isinstance(test, ast.BoolOp) and isinstance(test.op, ast.And):
                    # Check contradictory interval e.g. x < a and x > b with a <= b
                    lower_bound = None
                    upper_bound = None
                    for val in test.values:
                        if isinstance(val, ast.Compare) and len(val.ops) == 1 and isinstance(val.comparators[0], ast.Constant):
                            cval = val.comparators[0].value
                            if isinstance(cval, (int, float)):
                                oname = type(val.ops[0]).__name__
                                if oname in ("Gt", "GtE"):
                                    lower_bound = cval if lower_bound is None else max(lower_bound, cval)
                                elif oname in ("Lt", "LtE"):
                                    upper_bound = cval if upper_bound is None else min(upper_bound, cval)
                    if lower_bound is not None and upper_bound is not None and lower_bound >= upper_bound:
                        infeasible.append(f"line_{getattr(node, 'lineno', 0)}:{ast.unparse(test)}")
                elif isinstance(test, ast.Constant) and test.value is False:
                    infeasible.append(f"line_{getattr(node, 'lineno', 0)}:constant_false")

        vulnerable_crypto: List[str] = []
        cbom_components: List[Dict[str, Any]] = []
        for idx, asset in enumerate(cryptographic_assets):
            alg = str(asset.get("algorithm", "")).upper().strip()
            primitive = str(asset.get("primitive", "hash")).lower()
            q_level = int(asset.get("nist_quantum_security_level", 0))
            is_safe = (alg in cls.QUANTUM_SAFE_PRIMITIVES) and (q_level >= 1)
            if not is_safe:
                vulnerable_crypto.append(alg or f"unknown_asset_{idx}")
            cbom_components.append({
                "type": "crypto-asset",
                "bom-ref": f"crypto-asset-{idx+1}-{alg.lower()}",
                "name": alg,
                "cryptoProperties": {
                    "assetType": "algorithm",
                    "algorithmProperties": {
                        "primitive": primitive,
                        "executionEnvironment": "software-plain-ram",
                        "ImplementationPlatform": "x86_64"
                    },
                    "nistQuantumSecurityLevel": q_level
                }
            })

        parent_sha = parent_bundle_sha256 or "5a96c24c303c1901e897306b8d2b106dc58cd0af3d1708de7f9b7dfdcb896445"
        proven_clean = (len(infeasible) == 0 and len(vulnerable_crypto) == 0)

        cbom_doc = {
            "bomFormat": "CycloneDX",
            "specVersion": "1.6",
            "version": 1,
            "metadata": {
                "component": {
                    "type": "application",
                    "name": "el-aleph-sovereign-kernel",
                    "version": release_version,
                    "parent_cas_sha256": parent_sha
                }
            },
            "components": cbom_components
        }

        payload = f"{json.dumps(witnesses, sort_keys=True)}|{json.dumps(cbom_doc, sort_keys=True)}|{proven_clean}".encode("utf-8")
        seal = hmac.new(cls.CONCOLIC_CBOM_SALT.encode("utf-8"), payload, hashlib.sha256).hexdigest()

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        return ConcolicBranchAndCycloneDXCBOMReport(
            release_version=release_version,
            proven_concolic_feasible_and_cbom_quantum_safe=proven_clean,
            extracted_branches_count=branch_count,
            synthesized_negation_witnesses=witnesses,
            infeasible_or_dead_branches=infeasible,
            quantum_vulnerable_primitives=vulnerable_crypto,
            cyclonedx_v1_6_cbom_document=cbom_doc,
            concolic_cbom_pcc_seal_sha256=seal,
            analysis_duration_ms=round(dur, 3)
        )


