# ============================================================================
# NIVEL 81: PROBADOR DE PUNTO FIJO POR CONEXIÓN DE GALOIS CON OPERADORES DE
# WIDENING / NARROWING (COUSOT & COUSOT 1977) + ATESTACIÓN REMOTA IETF RATS
# (RFC 9334) Y ENTITY ATTESTATION TOKEN (EAT RFC 9711) PCC (NODE-06 v8.8.0)
# ============================================================================

@dataclass
class GaloisWideningNarrowingAndRATSEATReport:
    release_version: str
    proven_galois_fixpoint_bounded_and_rats_affirming: bool
    analyzed_loops_count: int
    loop_fixpoint_intervals: List[Dict[str, Any]]
    unbounded_divergent_variables: List[str]
    ietf_rats_eat_claims: Dict[str, Any]
    ear_appraisal_status: str
    galois_rats_pcc_seal_sha256: str
    analysis_duration_ms: float


class GaloisWideningNarrowingAndIETFRATSEATProver:
    """
    Nivel 81 (NODE-06 v8.8.0):
    1. Interpretación Abstracta sobre el Retículo de Intervalos con Operadores de Widening (∇)
       y Narrowing (Δ) de Cousot & Cousot ('Abstract Interpretation: A Unified Lattice Model for
       Static Analysis of Programs by Construction or Approximation of Fixpoints', POPL 1977):
       Para cada bucle o transición iterativa declarada (variable, init_val, step_delta,
       guard_op, guard_bound), calcula:
         - Iteración inicial I_0 = [init_val, init_val]
         - Paso abstracto I_1 = join(I_0, step(I_0))
         - Widening I_nabla = I_0 ∇ I_1:
             low  = -inf si low(I_1) < low(I_0) sino low(I_0)
             high = +inf si high(I_1) > high(I_0) sino high(I_0)
         - Narrowing I_delta = I_nabla Δ (I_nabla ∩ Guard(guard_op, guard_bound)):
             Refina +inf -> guard_bound si guard_op in ('<', '<=') y step_delta > 0, o
             refina -inf -> guard_bound si guard_op in ('>', '>=') y step_delta < 0.
       Certifica convergencia acotada si todas las cotas post-narrowing son finitas.
    2. Atestación Remota IETF RATS (RFC 9334 - Remote ATtestation procedureS Architecture) y
       Entity Attestation Token (EAT - RFC 9711 / Attestation Results EAR):
       Construye el conjunto canónico de claims EAT (ueid, swname, swversion, manifests,
       measurements SHA-256) y emite el dictamen del Verifier ('ear.status': 'affirming' si
       el punto fijo converge sin divergencias, o 'contraindicated' en caso contrario).
    """

    GALOIS_RATS_SALT = "ALEPH_SOVEREIGN_COUSOT_WIDENING_NARROWING_IETF_RATS_EAT_V8_8_PCC_2026"

    @classmethod
    def prove_galois_widening_narrowing_and_attest_rats_eat(
        cls,
        loop_transitions: List[Dict[str, Any]],
        measurement_digests_sha256: Dict[str, str],
        parent_bundle_sha256: str = "",
        release_version: str = "8.8.0"
    ) -> GaloisWideningNarrowingAndRATSEATReport:
        import json, hmac
        t0 = time.perf_counter_ns()

        intervals_report: List[Dict[str, Any]] = []
        divergent_vars: List[str] = []

        for spec in loop_transitions:
            var_name = str(spec.get("variable", "i"))
            init_v = int(spec.get("init_val", 0))
            step_d = int(spec.get("step_delta", 1))
            guard_op = str(spec.get("guard_op", "<")).strip()
            guard_b = spec.get("guard_bound", None)

            i0_low, i0_high = init_v, init_v
            i1_low = min(i0_low, init_v + step_d)
            i1_high = max(i0_high, init_v + step_d)

            # Operador de Widening (∇) de Cousot & Cousot
            w_low = "-inf" if i1_low < i0_low else i0_low
            w_high = "+inf" if i1_high > i0_high else i0_high

            # Operador de Narrowing (Δ) intersectado con el invariante de guarda
            n_low = w_low
            n_high = w_high
            if guard_b is not None:
                gb = int(guard_b)
                if w_high == "+inf" and guard_op in ("<", "<=") and step_d > 0:
                    n_high = gb if guard_op == "<=" else (gb - 1 + step_d)
                if w_low == "-inf" and guard_op in (">", ">=") and step_d < 0:
                    n_low = gb if guard_op == ">=" else (gb + 1 + step_d)

            is_bounded = (n_low != "-inf" and n_high != "+inf")
            if not is_bounded:
                divergent_vars.append(var_name)

            intervals_report.append({
                "variable": var_name,
                "i0_interval": [i0_low, i0_high],
                "i1_interval": [i1_low, i1_high],
                "widened_interval_nabla": [w_low, w_high],
                "narrowed_fixpoint_delta": [n_low, n_high],
                "converged_finite_bound": is_bounded
            })

        parent_sha = parent_bundle_sha256 or "4cc7be6db030aca5262c05f4486f435647eba851875f53d680f20ad846c3a59b"
        proven_bounded = (len(divergent_vars) == 0)
        ear_status = "affirming" if proven_bounded else "contraindicated"

        eat_claims = {
            "profile": "urn:ietf:rfc:9711:eat-cwt-json",
            "rats_architecture": "RFC-9334",
            "ueid": f"urn:el-aleph:node06:ueid:{parent_sha[:16]}",
            "swname": "el-aleph-sovereign-kernel",
            "swversion": release_version,
            "parent_cas_sha256": parent_sha,
            "measurements": measurement_digests_sha256,
            "ear.status": ear_status,
            "ear.trustworthiness-vector": {
                "executables": 2 if proven_bounded else 99,
                "configuration": 2 if proven_bounded else 99
            }
        }

        payload = f"{json.dumps(intervals_report, sort_keys=True)}|{json.dumps(eat_claims, sort_keys=True)}|{proven_bounded}".encode("utf-8")
        seal = hmac.new(cls.GALOIS_RATS_SALT.encode("utf-8"), payload, hashlib.sha256).hexdigest()

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        return GaloisWideningNarrowingAndRATSEATReport(
            release_version=release_version,
            proven_galois_fixpoint_bounded_and_rats_affirming=proven_bounded,
            analyzed_loops_count=len(loop_transitions),
            loop_fixpoint_intervals=intervals_report,
            unbounded_divergent_variables=divergent_vars,
            ietf_rats_eat_claims=eat_claims,
            ear_appraisal_status=ear_status,
            galois_rats_pcc_seal_sha256=seal,
            analysis_duration_ms=round(dur, 3)
        )


# ============================================================================
# NIVEL 82: PROBADOR DEL DOMINIO ABSTRACTO OCTAGONAL Y CLAUSURA FUERTE DE
# MATRIZ DE DIFERENCIAS ACOTADAS (DBM MINÉ 2006 / FLOYD-WARSHALL) + MANIFIESTO
# DE INTEGRIDAD IETF CoRIM Y CoSWID (RFC 9393) PCC (NODE-06 v8.9.0)
# ============================================================================

@dataclass
class OctagonDBMClosureAndCoRIMCoSWIDReport:
    release_version: str
    proven_octagon_dbm_consistent_and_corim_endorsed: bool
    variables_count: int
    has_negative_cycle_contradiction: bool
    violated_safety_assertions: List[str]
    dbm_shortest_path_bounds: Dict[str, float]
    ietf_corim_manifest: Dict[str, Any]
    rfc9393_coswid_tag: Dict[str, Any]
    octagon_corim_pcc_seal_sha256: str
    analysis_duration_ms: float


class OctagonDBMClosureAndIETFCoRIMCoSWIDProver:
    """
    Nivel 82 (NODE-06 v8.9.0):
    1. Dominio Abstracto Relacional Octagonal y Clausura de Matriz de Diferencias Acotadas
       (DBM - Antoine Miné, 'The Octagon Abstract Domain', Higher-Order and Symbolic Computation,
       2006 / Algoritmo de Clausura Transitiva de Floyd-Warshall):
       Modela restricciones relacionales de la forma x_i - x_j <= c (incluyendo cotas octogonales
       codificadas sobre un grafo de potencial dirigido). Ejecuta el algoritmo cúbico O(V^3) de
       Floyd-Warshall:
         m[i][j] = min(m[i][j], m[i][k] + m[k][j])
       - Si existe algún vértice v con m[v][v] < 0, detecta un ciclo negativo (sistema relacional
         insatisfacible / estado contradictorio).
       - Para cada aserción de seguridad relacional requerida (target_u - target_v <= max_allowed),
         comprueba si la cota cerrada m[u][v] <= max_allowed se cumple estrictamente.
    2. Manifiesto Conciso de Integridad de Referencia IETF CoRIM (draft-ietf-rats-corim) y
       Etiqueta Concisa de Identificación de Software CoSWID (RFC 9393):
       Construye el manifiesto CoRIM con 'reference-triples' y 'endorsed-triples' vinculado a la
       etiqueta CoSWID RFC 9393 del release y lo sella con HMAC-SHA256 sobre el linaje CAS.
    """

    OCTAGON_CORIM_SALT = "ALEPH_SOVEREIGN_MINE_OCTAGON_DBM_IETF_CORIM_COSWID_V8_9_PCC_2026"

    @classmethod
    def prove_octagon_dbm_and_attest_corim_coswid(
        cls,
        relational_constraints: List[Dict[str, Any]],
        safety_assertions: List[Dict[str, Any]],
        artifact_digests_sha256: Dict[str, str],
        parent_bundle_sha256: str = "",
        release_version: str = "8.9.0"
    ) -> OctagonDBMClosureAndCoRIMCoSWIDReport:
        import json, hmac, math
        t0 = time.perf_counter_ns()

        vars_set = {"ZERO"}
        for c in relational_constraints:
            vars_set.add(str(c.get("u", "ZERO")))
            vars_set.add(str(c.get("v", "ZERO")))
        for a in safety_assertions:
            vars_set.add(str(a.get("u", "ZERO")))
            vars_set.add(str(a.get("v", "ZERO")))

        nodes = sorted(list(vars_set))
        INF = 1e15
        dist: Dict[str, Dict[str, float]] = {
            u: {v: (0.0 if u == v else INF) for v in nodes}
            for u in nodes
        }

        # Restricción x_u - x_v <= c se codifica como arista dirigida v -> u con peso c
        # de modo que x_u <= x_v + c, y (x_u - x_w) <= (x_u - x_v) + (x_v - x_w)
        # Usamos indexación directa dbm[u][v] = cota superior de (u - v) <= c:
        # Transitividad: (u - v) = (u - k) + (k - v) <= dbm[u][k] + dbm[k][v]
        for c in relational_constraints:
            u = str(c.get("u", "ZERO"))
            v = str(c.get("v", "ZERO"))
            bound = float(c.get("max_diff", 0.0))
            if bound < dist[u][v]:
                dist[u][v] = bound

        # Clausura de Floyd-Warshall sobre DBM: dist[u][v] = min_k (dist[u][k] + dist[k][v])
        for k in nodes:
            for i in nodes:
                if dist[i][k] >= INF / 2:
                    continue
                for j in nodes:
                    if dist[k][j] >= INF / 2:
                        continue
                    cand = dist[i][k] + dist[k][j]
                    if cand < dist[i][j]:
                        dist[i][j] = cand

        has_neg_cycle = any(dist[v][v] < -1e-9 for v in nodes)

        violated: List[str] = []
        for a in safety_assertions:
            u = str(a.get("u", "ZERO"))
            v = str(a.get("v", "ZERO"))
            req_bound = float(a.get("max_allowed_diff", 0.0))
            derived = dist[u][v]
            if derived > req_bound + 1e-9:
                violated.append(f"{u} - {v} <= {req_bound} (derived: {'+inf' if derived >= INF/2 else derived})")

        bounds_out: Dict[str, float] = {}
        for u in nodes:
            for v in nodes:
                if u != v and dist[u][v] < INF / 2:
                    bounds_out[f"{u}-{v}"] = round(dist[u][v], 4)

        parent_sha = parent_bundle_sha256 or "4bc9c1bfc9de20a2e1736d677e77730eec693a4a357846aa23db18213c19d281"
        proven_ok = (not has_neg_cycle) and (len(violated) == 0)

        coswid_tag = {
            "rfc": "RFC-9393",
            "tag-id": f"urn:el-aleph:coswid:v{release_version}",
            "tag-version": 1,
            "software-name": "el-aleph-sovereign-kernel",
            "software-version": release_version,
            "version-scheme": "semver",
            "entity": {
                "entity-name": "El Aleph Sovereign Swarm NODE-06",
                "role": ["tag-creator", "software-creator", "maintainer"]
            },
            "payload": {
                "files": [
                    {"fs-name": k, "hash": {"alg": "sha-256", "value": v}}
                    for k, v in sorted(artifact_digests_sha256.items())
                ]
            }
        }

        corim_manifest = {
            "profile": "urn:ietf:params:rats:corim",
            "corim-id": f"urn:el-aleph:corim:v{release_version}:{parent_sha[:12]}",
            "parent-cas-sha256": parent_sha,
            "comid-tags": [
                {
                    "tag-identity": {"id": f"comid-el-aleph-{release_version}"},
                    "triples": {
                        "reference-triples": [
                            {
                                "environment": {"class": {"vendor": "El-Aleph", "model": "Apex-Kernel"}},
                                "measurements": artifact_digests_sha256
                            }
                        ],
                        "endorsed-triples": [
                            {
                                "condition": "octagon_dbm_relational_closure",
                                "endorsed": proven_ok
                            }
                        ]
                    }
                }
            ]
        }

        payload = f"{json.dumps(bounds_out, sort_keys=True)}|{json.dumps(corim_manifest, sort_keys=True)}|{proven_ok}".encode("utf-8")
        seal = hmac.new(cls.OCTAGON_CORIM_SALT.encode("utf-8"), payload, hashlib.sha256).hexdigest()

        dur = (time.perf_counter_ns() - t0) / 1_000_000.0
        return OctagonDBMClosureAndCoRIMCoSWIDReport(
            release_version=release_version,
            proven_octagon_dbm_consistent_and_corim_endorsed=proven_ok,
            variables_count=len(nodes),
            has_negative_cycle_contradiction=has_neg_cycle,
            violated_safety_assertions=violated,
            dbm_shortest_path_bounds=bounds_out,
            ietf_corim_manifest=corim_manifest,
            rfc9393_coswid_tag=coswid_tag,
            octagon_corim_pcc_seal_sha256=seal,
            analysis_duration_ms=round(dur, 3)
        )


