        coh_perp: Set[Tuple[str, str]] = set()
        for a in tokens:
            for b in tokens:
                if a == b or (a, b) not in coh:
                    coh_perp.add((a, b))
        coh_perp_perp: Set[Tuple[str, str]] = set()
        for a in tokens:
            for b in tokens:
                if a == b or (a, b) not in coh_perp:
                    coh_perp_perp.add((a, b))
        involution_ok = coh_perp_perp == coh and reflexive and symmetric
        if not involution_ok:
            violations.append('GIRARD_INVOLUTION_VIOLATION: Falla la involucion lineal X^perp^perp == X.')
        valid_cliques: List[Set[str]] = []
        for c in candidate_cliques or []:
            c_set = {str(x) for x in c}
            if not c_set.issubset(set(tokens)):
                violations.append(f'GIRARD_OUT_OF_WEB_CLIQUE: Elementos fuera de |X|: {sorted(c_set)}')
                continue
            if not all(((x, y) in coh for x in c_set for y in c_set)):
                violations.append(f'GIRARD_INVALID_CLIQUE: El subconjunto {sorted(c_set)} contiene tokens incoherentes.')
            else:
                valid_cliques.append(c_set)
        stable_intersection = len(valid_cliques) > 0
        for i in range(len(valid_cliques)):
            for j in range(i + 1, len(valid_cliques)):
                inter = valid_cliques[i].intersection(valid_cliques[j])
                if not all(((x, y) in coh for x in inter for y in inter)):
                    stable_intersection = False
        if not stable_intersection:
            violations.append('GIRARD_UNSTABLE_TRACE: Falla preservacion de intersecciones acotadas en cliques.')
        anticliques_count = sum((1 for a in tokens for b in tokens if a < b and (a, b) in coh_perp)) + len(tokens)
        display_ok = True
        dates_ok = True
        seen_display = False
        seen_date = False
        if not rfc9651_headers or not isinstance(rfc9651_headers, dict):
            violations.append('RFC9651_EMPTY_HEADERS: Se requiere al menos un campo HTTP estructurado RFC 9651.')
            display_ok = False
            dates_ok = False
        else:
            for k, v in rfc9651_headers.items():
                key = str(k).strip()
                val = str(v).strip()
                if not re.match('^[a-z*][a-z0-9_\\-.*]*$', key):
                    violations.append(f"RFC9651_INVALID_KEY: Clave invalida '{key}' segun RFC 9651 Sec 3.2.")
