# --- Merged from node06_v16_7: GameSemanticsAJMAbramskyAndRFC9581CBORTimeTagProver ---
class GameSemanticsAJMAbramskyAndRFC9581CBORTimeTagProver:

    @staticmethod
    def prove_ajm_game_semantics_and_verify_rfc9581_cbor(arena_moves: List[Dict[str, Any]], play_trace: List[Dict[str, Any]], rfc9581_cbor_tags: List[Dict[str, Any]], release_version: str='15.1.0') -> GameSemanticsAJMAndRFC9581Report:
        import json
        t0 = time.perf_counter()
        violations: List[str] = []
        moves_map: Dict[str, Dict[str, Any]] = {}
        for m in arena_moves or []:
            mid = str(m.get('id', '')).strip()
            role = str(m.get('polarity', '')).strip().upper()
            kind = str(m.get('kind', '')).strip().upper()
            enabler = m.get('enabler')
            if mid and role in ('O', 'P') and (kind in ('Q', 'A')):
                moves_map[mid] = {'id': mid, 'polarity': role, 'kind': kind, 'enabler': str(enabler) if enabler else None}
            else:
                violations.append(f'AJM_INVALID_ARENA_MOVE: Movimiento mal formado {m}')
        if not moves_map:
            violations.append('AJM_EMPTY_ARENA: La arena (M, lambda, vdash) no puede ser vacia.')
        op_alt_ok = True
        just_ok = True
        bracket_ok = True
        innocence_ok = True
        open_questions: List[str] = []
        seen_positions: List[str] = []
        history_free_map: Dict[str, str] = {}
        if not play_trace:
            violations.append('AJM_EMPTY_PLAY_TRACE: La jugada s in L_A no puede ser vacia.')
            op_alt_ok = False
            just_ok = False
            bracket_ok = False
            innocence_ok = False
        else:
            prev_pol = None
            for idx, step in enumerate(play_trace):
                mid = str(step.get('move_id', '')).strip()
                just_idx = step.get('justifier_index')
                if mid not in moves_map:
                    violations.append(f"AJM_UNKNOWN_MOVE_IN_PLAY: '{mid}' fuera de la arena.")
                    just_ok = False
                    continue
                m_info = moves_map[mid]
                pol = m_info['polarity']
                kind = m_info['kind']
                enabler = m_info['enabler']
                if idx == 0 and pol != 'O':
                    op_alt_ok = False
                    violations.append('AJM_INITIAL_NOT_OPPONENT: Toda jugada debe iniciar con movimiento de Opponent (O).')
                if prev_pol is not None and pol == prev_pol:
                    op_alt_ok = False
                    violations.append(f"AJM_ALTERNATION_VIOLATION: Paso {idx} repite polaridad '{pol}'.")
                prev_pol = pol
                if enabler is None:
                    if just_idx is not None:
                        just_ok = False
                        violations.append(f"AJM_INITIAL_MOVE_HAS_JUSTIFIER: Movimiento inicial '{mid}' no admite puntero.")
                elif not isinstance(just_idx, int) or just_idx < 0 or just_idx >= len(seen_positions):
                    just_ok = False
                    violations.append(f'AJM_BAD_JUSTIFIER_INDEX: Indice {just_idx} invalido en paso {idx}.')
                elif seen_positions[just_idx] != enabler:
                    just_ok = False
                    violations.append(f"AJM_JUSTIFIER_MISMATCH: '{mid}' requiere habilitador '{enabler}', obtuvo '{seen_positions[just_idx]}'.")
                if kind == 'Q':
                    open_questions.append(mid)
                elif kind == 'A':
                    if not open_questions:
                        bracket_ok = False
                        violations.append(f"AJM_UNBRACKETED_ANSWER: Respuesta '{mid}' sin pregunta abierta.")
                    else:
                        top_q = open_questions[-1]
                        if enabler != top_q:
                            bracket_ok = False
                            violations.append(f"AJM_WELL_BRACKETING_VIOLATION: Respuesta '{mid}' justifica '{enabler}' pero la pregunta pendiente mas reciente es '{top_q}'.")
                        else:
                            open_questions.pop()
                if pol == 'P' and idx >= 1:
                    prev_o_move = seen_positions[-1]
                    if prev_o_move in history_free_map and history_free_map[prev_o_move] != mid:
                        innocence_ok = False
                        violations.append(f"AJM_HISTORY_FREE_INNOCENCE_VIOLATION: P respondio '{mid}' tras '{prev_o_move}', contradiciendo respuesta previa '{history_free_map[prev_o_move]}'.")
                    history_free_map[prev_o_move] = mid
                seen_positions.append(mid)
        ext_time_ok = True
        dur_per_ok = True
        if not rfc9581_cbor_tags:
            violations.append('RFC9581_EMPTY_TAGS: Debe verificarse al menos una estructura CBOR RFC 9581.')
            ext_time_ok = False
            dur_per_ok = False
        else:
            seen_1001 = False
            seen_1002_1003 = False
            for t in rfc9581_cbor_tags:
                tag_num = t.get('tag')
                val = t.get('value', {})
                if tag_num == 1001:
                    seen_1001 = True
                    base_sec = val.get(1) if 1 in val else val.get('1')
                    nsec = val.get(-1, val.get('-1', 0))
                    tz = val.get('tz', 'UTC')
                    if not isinstance(base_sec, int):
                        ext_time_ok = False
                        violations.append('RFC9581_TAG1001_MISSING_BASE_TIME: Clave 1 (epoch seconds int) obligatoria en Tag 1001.')
                    if not isinstance(nsec, int) or nsec < 0 or nsec > 999999999:
                        ext_time_ok = False
                        violations.append(f'RFC9581_TAG1001_BAD_NANOSECONDS: Nanosegundos {nsec} fuera de [0, 999999999].')
                    if not isinstance(tz, str) or not tz.strip():
                        ext_time_ok = False
                        violations.append('RFC9581_TAG1001_INVALID_TZ: Zona horaria vacia en Tag 1001.')
                elif tag_num in (1002, 1003):
                    seen_1002_1003 = True
                    secs = val.get('seconds')
                    if not isinstance(secs, int) or secs <= 0:
                        dur_per_ok = False
                        violations.append(f'RFC9581_TAG{tag_num}_INVALID_DURATION: Duracion/periodo requiere segundos > 0.')
                else:
                    ext_time_ok = False
                    violations.append(f'RFC9581_UNSUPPORTED_TAG: Tag CBOR {tag_num} fuera de RFC 9581 (1001/1002/1003).')
            if not seen_1001:
                ext_time_ok = False
                violations.append('RFC9581_MISSING_TAG1001: Se requiere al menos un Extended Time Tag 1001.')
            if not seen_1002_1003:
                dur_per_ok = False
                violations.append('RFC9581_MISSING_DURATION_OR_PERIOD: Se requiere al menos un Tag 1002 o 1003.')
        proven = len(violations) == 0 and op_alt_ok and just_ok and bracket_ok and innocence_ok and ext_time_ok and dur_per_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'moves': sorted(moves_map.keys()), 'trace_len': len(play_trace or []), 'tags_count': len(rfc9581_cbor_tags or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return GameSemanticsAJMAndRFC9581Report(release_version=release_version, proven_ajm_game_and_rfc9581_valid=proven, arena_moves_count=len(moves_map), op_alternation_verified=op_alt_ok, justification_pointers_valid=just_ok, well_bracketed_verified=bracket_ok, history_free_innocence_verified=innocence_ok, rfc9581_tags_checked=len(rfc9581_cbor_tags or []), rfc9581_extended_time_valid=ext_time_ok, rfc9581_duration_period_valid=dur_per_ok, ajm_or_rfc9581_violations=violations, ajm_rfc9581_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


