# --- Merged from node06_v16_7: GeometryOfInteractionTracedMonoidalAndRFC9562UUIDv8Prover ---
class GeometryOfInteractionTracedMonoidalAndRFC9562UUIDv8Prover:

    @staticmethod
    def prove_goi_traced_monoidal_and_verify_rfc9562_uuidv8(u11_matrix: List[List[float]], u12_matrix: List[List[float]], u21_matrix: List[List[float]], u22_matrix: List[List[float]], sigma_matrix: List[List[float]], rfc9562_uuidv8_list: List[str], release_version: str='15.2.0') -> GeometryOfInteractionAndRFC9562UUIDv8Report:
        import json
        t0 = time.perf_counter()
        violations: List[str] = []

        def mat_mul(A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
            if not A or not B or (not A[0]) or (not B[0]) or (len(A[0]) != len(B)):
                return []
            r, k_dim, c = (len(A), len(B), len(B[0]))
            return [[sum((float(A[i][p]) * float(B[p][j]) for p in range(k_dim))) for j in range(c)] for i in range(r)]

        def mat_add(A: List[List[float]], B: List[List[float]]) -> List[List[float]]:
            if not A or not B or len(A) != len(B) or (len(A[0]) != len(B[0])):
                return []
            return [[float(A[i][j]) + float(B[i][j]) for j in range(len(A[0]))] for i in range(len(A))]

        def mat_zero(M: List[List[float]], tol: float=1e-09) -> bool:
            return bool(M) and all((abs(float(v)) <= tol for row in M for v in row))
        ext_dim = len(u11_matrix or [])
        fb_dim = len(u22_matrix or [])
        if ext_dim == 0 or fb_dim == 0:
            violations.append('GOI_EMPTY_DIMENSIONS: Dimensiones externas e internas deben ser > 0.')
        F = mat_mul(u22_matrix, sigma_matrix)
        nilpotent_ok = False
        nilpotent_k = -1
        if not F or len(F) != fb_dim or len(F[0]) != fb_dim:
            violations.append('GOI_DIMENSION_MISMATCH: u22 * sigma no es cuadrada sobre puertos de feedback.')
        else:
            curr = [row[:] for row in F]
            for step in range(1, fb_dim + 2):
                if mat_zero(curr):
                    nilpotent_ok = True
                    nilpotent_k = step
                    break
                curr = mat_mul(curr, F)
            if not nilpotent_ok:
                violations.append('GOI_NON_NILPOTENT_FEEDBACK: (U_22 * sigma)^k != 0; ciclo infinito detectado en la formula de ejecucion.')
        norm_bounded = False
        if nilpotent_ok and ext_dim > 0:
            ident = [[1.0 if i == j else 0.0 for j in range(fb_dim)] for i in range(fb_dim)]
            neumann_sum = [row[:] for row in ident]
            f_pow = [row[:] for row in F]
            for _ in range(1, nilpotent_k):
                neumann_sum = mat_add(neumann_sum, f_pow)
                f_pow = mat_mul(f_pow, F)
            term = mat_mul(u12_matrix, mat_mul(sigma_matrix, mat_mul(neumann_sum, u21_matrix)))
            ex_mat = mat_add(u11_matrix, term)
            if ex_mat:
                max_entry = max((abs(v) for row in ex_mat for v in row))
                norm_bounded = max_entry <= 1.0 + 1e-06
                if not norm_bounded:
                    violations.append(f'GOI_UNBOUNDED_EXECUTION_NORM: Norma maxima {max_entry:.4f} excede contraccion lineal 1.0.')
            else:
                violations.append('GOI_EXECUTION_FORMULA_MISMATCH: Dimensiones incompatibles en U_11 + U_12*sigma*(I-U_22*sigma)^-1*U_21.')
        sig_sq = mat_mul(sigma_matrix, sigma_matrix)
        ident_fb = [[1.0 if i == j else 0.0 for j in range(fb_dim)] for i in range(fb_dim)]
        yanking_ok = bool(sig_sq) and all((abs(sig_sq[i][j] - ident_fb[i][j]) <= 1e-06 for i in range(fb_dim) for j in range(fb_dim)))
        if not yanking_ok:
            violations.append('GOI_YANKING_INVOLUTION_VIOLATION: El operador de enlace sigma debe ser involutivo (sigma^2 == I).')
        vanishing_ok = ext_dim > 0 and fb_dim > 0 and yanking_ok
        uuid_ok = True
        if not rfc9562_uuidv8_list:
            uuid_ok = False
            violations.append('RFC9562_EMPTY_UUIDV8_LIST: Se requiere al menos un UUIDv8 determinista (RFC 9562 Sec 5.8).')
        else:
            seen_uuids = set()
            for u in rfc9562_uuidv8_list:
                us = str(u).strip().lower()
                m = re.match('^([0-9a-f]{8})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{12})$', us)
                if not m:
                    uuid_ok = False
                    violations.append(f"RFC9562_MALFORMED_UUID: Formato invalido '{u}'.")
                    continue
                g1, g2, g3, g4, g5 = m.groups()
                if g3[0] != '8':
                    uuid_ok = False
                    violations.append(f"RFC9562_NOT_VERSION_8: Nibble de version '{g3[0]}' != '8' en '{u}' (RFC 9562 Sec 5.8).")
                if g4[0] not in ('8', '9', 'a', 'b'):
                    uuid_ok = False
                    violations.append(f"RFC9562_BAD_VARIANT_BITS: Nibble de variante '{g4[0]}' fuera de 0b10xx en '{u}' (RFC 9562 Sec 4.1).")
                custom_payload = g1 + g2 + g3[1:] + g4[1:] + g5
                if all((ch == '0' for ch in custom_payload)):
                    uuid_ok = False
                    violations.append(f"RFC9562_ZERO_CUSTOM_PAYLOAD: Payload custom_a/b/c nulo en '{u}'.")
                if us in seen_uuids:
                    uuid_ok = False
                    violations.append(f"RFC9562_DUPLICATE_UUIDV8: Colision detectada en '{u}'.")
                seen_uuids.add(us)
        proven = len(violations) == 0 and nilpotent_ok and yanking_ok and vanishing_ok and norm_bounded and uuid_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'ext_dim': ext_dim, 'fb_dim': fb_dim, 'nilpotent_k': nilpotent_k, 'uuids_count': len(rfc9562_uuidv8_list or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return GeometryOfInteractionAndRFC9562UUIDv8Report(release_version=release_version, proven_goi_execution_and_rfc9562_uuidv8_valid=proven, external_ports_count=ext_dim, feedback_ports_count=fb_dim, feedback_nilpotency_step=nilpotent_k, nilpotency_verified=nilpotent_ok, yanking_axiom_verified=yanking_ok, vanishing_superposing_verified=vanishing_ok, execution_matrix_norm_bounded=norm_bounded, rfc9562_uuidv8_checked_count=len(rfc9562_uuidv8_list or []), rfc9562_uuidv8_bits_valid=uuid_ok, goi_or_rfc9562_violations=violations, goi_rfc9562_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


