# --- Merged from node06_v16_7: HeytingIntuitionisticKripkeSemanticsAndRFC9608NoRevAvailProver ---
class HeytingIntuitionisticKripkeSemanticsAndRFC9608NoRevAvailProver:

    @staticmethod
    def prove_heyting_kripke_semantics_and_verify_rfc9608_x509(kripke_worlds: List[str], accessibility_leq: List[List[str]], proposition_valuations: Dict[str, List[str]], rfc9608_certificates: List[Dict[str, Any]], max_short_lived_seconds: int=604800, release_version: str='15.5.0') -> HeytingKripkeAndRFC9608Report:
        import json
        t0 = time.perf_counter()
        violations: List[str] = []
        worlds = list(dict.fromkeys((str(w) for w in kripke_worlds or [] if str(w).strip())))
        if not worlds:
            violations.append('HEYTING_EMPTY_KRIPKE_FRAME: El conjunto de mundos W no puede ser vacio.')
        leq: Set[Tuple[str, str]] = set()
        for pair in accessibility_leq or []:
            if isinstance(pair, (list, tuple)) and len(pair) == 2:
                leq.add((str(pair[0]), str(pair[1])))
        refl_ok = all(((w, w) in leq for w in worlds)) if worlds else False
        trans_ok = all(((w1, w3) in leq for w1, w2a in leq for w2b, w3 in leq if w2a == w2b))
        if not refl_ok:
            violations.append('HEYTING_NON_REFLEXIVE_FRAME: La relacion de Kripke <= debe ser reflexiva sobre W.')
        if not trans_ok:
            violations.append('HEYTING_NON_TRANSITIVE_FRAME: La relacion de Kripke <= debe ser transitiva sobre W.')
        persistence_ok = bool(proposition_valuations) and refl_ok and trans_ok
        if not proposition_valuations:
            violations.append('HEYTING_EMPTY_VALUATIONS: Debe suministrarse al menos una valuacion proposicional V(p).')
        else:
            for prop, v_worlds in proposition_valuations.items():
                v_set = {str(w) for w in v_worlds}
                if not v_set.issubset(set(worlds)):
                    persistence_ok = False
                    violations.append(f"HEYTING_OUT_OF_FRAME_WORLD: Proposicion '{prop}' referencia mundos fuera de W.")
                    continue
                for w in v_set:
                    for w_prime in worlds:
                        if (w, w_prime) in leq and w_prime not in v_set:
                            persistence_ok = False
                            violations.append(f"HEYTING_KRIPKE_PERSISTENCE_VIOLATION: '{prop}' es verdadera en '{w}' pero falsa en '{w_prime}' con {w} <= {w_prime}.")
        upsets: List[Any] = []
        n_w = len(worlds)
        if n_w <= 10 and refl_ok and trans_ok:
            for mask in range(1 << n_w):
                cand = frozenset((worlds[i] for i in range(n_w) if mask & 1 << i))
                if all((w2 in cand for w1 in cand for w2 in worlds if (w1, w2) in leq)):
                    upsets.append(cand)
        residuation_ok = len(upsets) > 0
        if residuation_ok:

            def h_imp(A_u: Any, B_u: Any) -> Any:
                return frozenset((w for w in worlds if all((w_p not in A_u or w_p in B_u for w_p in worlds if (w, w_p) in leq))))
            for A_u in upsets:
                for B_u in upsets:
                    imp_ab = h_imp(A_u, B_u)
                    if imp_ab not in upsets:
                        residuation_ok = False
                        violations.append('HEYTING_IMPLICATION_NOT_UPSET: A => B no es cerrado hacia arriba.')
                        break
                    for X_u in upsets:
                        lhs = (X_u & A_u).issubset(B_u)
                        rhs = X_u.issubset(imp_ab)
                        if lhs != rhs:
                            residuation_ok = False
                            violations.append('HEYTING_RESIDUATION_LAW_VIOLATION: Falla X & A <= B iff X <= (A => B).')
                            break
        norev_ok = True
        short_lived_ok = True
        if not rfc9608_certificates:
            norev_ok = False
            short_lived_ok = False
            violations.append('RFC9608_EMPTY_CERTS: Se requiere al menos un certificado X.509 con noRevAvail (RFC 9608).')
        else:
            for idx, cert in enumerate(rfc9608_certificates):
                oid = str(cert.get('extension_oid', '')).strip()
                is_ca = bool(cert.get('is_ca', False))
                crit = bool(cert.get('critical', False))
                has_crl = bool(cert.get('has_crl_dp', False))
                has_ocsp = bool(cert.get('has_aia_ocsp', False))
                nb = cert.get('not_before', 0)
                na = cert.get('not_after', 0)
                if oid != '2.5.29.56':
                    norev_ok = False
                    violations.append(f"RFC9608_INVALID_OID: OID '{oid}' != '2.5.29.56' (id-ce-noRevAvail) en cert {idx}.")
                if is_ca:
                    norev_ok = False
                    violations.append(f'RFC9608_FORBIDDEN_IN_CA_CERT: Cert {idx} es CA; RFC 9608 Sec 3 prohibe noRevAvail en certificados CA.')
                if crit:
                    norev_ok = False
                    violations.append(f'RFC9608_MUST_BE_NON_CRITICAL: Cert {idx} marca noRevAvail como critical=True (RFC 9608 Sec 3).')
                if has_crl or has_ocsp:
                    norev_ok = False
                    violations.append(f'RFC9608_CONFLICTING_REVOCATION_INFO: Cert {idx} combina noRevAvail con CRL/OCSP (RFC 9608 Sec 3).')
                if not isinstance(nb, int) or not isinstance(na, int) or na <= nb or (na - nb > max_short_lived_seconds):
                    short_lived_ok = False
                    violations.append(f'RFC9608_LIFETIME_EXCEEDED: Vigencia {na - nb}s excede limite short-lived {max_short_lived_seconds}s en cert {idx}.')
        proven = len(violations) == 0 and persistence_ok and residuation_ok and norev_ok and short_lived_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'worlds': len(worlds), 'upsets': len(upsets), 'certs': len(rfc9608_certificates or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return HeytingKripkeAndRFC9608Report(release_version=release_version, proven_heyting_kripke_and_rfc9608_valid=proven, kripke_worlds_count=len(worlds), upsets_heyting_size=len(upsets), kripke_persistence_verified=persistence_ok, heyting_residuation_verified=residuation_ok, rfc9608_certs_checked=len(rfc9608_certificates or []), rfc9608_norevavail_constraints_valid=norev_ok, rfc9608_short_lived_validity_ok=short_lived_ok, heyting_or_rfc9608_violations=violations, heyting_rfc9608_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


