# --- Merged from node06_v16_7: LawvereQuantaleEnrichedMetricAndRFC9629KemriCMSProver ---
class LawvereQuantaleEnrichedMetricAndRFC9629KemriCMSProver:

    @staticmethod
    def prove_lawvere_quantale_metric_and_verify_rfc9629_cms(objects: List[str], distance_matrix: List[List[float]], rfc9629_kemri_list: List[Dict[str, Any]], release_version: str='15.6.0') -> LawvereQuantaleAndRFC9629Report:
        import json
        t0 = time.perf_counter()
        violations: List[str] = []
        objs = [str(o).strip() for o in objects or [] if str(o).strip()]
        n = len(objs)
        zero_ok = True
        tri_ok = True
        yoneda_ok = True
        if n == 0 or not distance_matrix or len(distance_matrix) != n or any((len(row) != n for row in distance_matrix)):
            violations.append('LAWVERE_INVALID_MATRIX: Matriz de distancia d: X x X -> [0, inf] mal formada.')
            zero_ok = False
            tri_ok = False
            yoneda_ok = False
        else:
            d = [[float(v) for v in row] for row in distance_matrix]
            for i in range(n):
                if abs(d[i][i]) > 1e-09:
                    zero_ok = False
                    violations.append(f'LAWVERE_NON_ZERO_IDENTITY: d({objs[i]}, {objs[i]})={d[i][i]} != 0.')
                for j in range(n):
                    if d[i][j] < -1e-09:
                        zero_ok = False
                        violations.append(f'LAWVERE_NEGATIVE_COST: d({objs[i]}, {objs[j]})={d[i][j]} < 0.')
            for i in range(n):
                for j in range(n):
                    for k in range(n):
                        if d[i][j] + d[j][k] + 1e-09 < d[i][k]:
                            tri_ok = False
                            violations.append(f'LAWVERE_TRIANGLE_VIOLATION: d({objs[i]},{objs[j]})+d({objs[j]},{objs[k]})={d[i][j] + d[j][k]:.4f} < d({objs[i]},{objs[k]})={d[i][k]:.4f}.')
            if zero_ok and tri_ok:
                for i in range(n):
                    for j in range(n):
                        sup_val = max((max(0.0, d[z_idx][j] - d[z_idx][i]) for z_idx in range(n)))
                        if abs(sup_val - d[i][j]) > 1e-06:
                            yoneda_ok = False
                            violations.append(f'LAWVERE_YONEDA_ISOMETRY_VIOLATION: sup_z(d(z,{objs[j]}) - d(z,{objs[i]}))={sup_val:.4f} != d({objs[i]},{objs[j]})={d[i][j]:.4f}.')
            else:
                yoneda_ok = False
        ori_ver_ok = True
        kek_kdf_ok = True
        allowed_kdfs = {'HKDF-SHA256', 'HKDF-SHA384', 'HKDF-SHA512', 'KMAC128', 'KMAC256'}
        if not rfc9629_kemri_list:
            ori_ver_ok = False
            kek_kdf_ok = False
            violations.append('RFC9629_EMPTY_KEMRI: Se requiere al menos un KEMRecipientInfo CMS (RFC 9629).')
        else:
            for idx, item in enumerate(rfc9629_kemri_list):
                ver = item.get('cms_version', -1)
                ori_oid = str(item.get('ori_oid', '')).strip()
                kek_len = item.get('kek_length', 0)
                kdf_alg = str(item.get('kdf_alg', '')).strip()
                kemct_hex = str(item.get('kemct_hex', '')).strip()
                enckey_hex = str(item.get('encrypted_key_hex', '')).strip()
                if ver != 0:
                    ori_ver_ok = False
                    violations.append(f'RFC9629_INVALID_VERSION: KEMRecipientInfo version={ver} != 0 (RFC 9629 Sec 3).')
                if ori_oid != '1.2.840.113549.1.9.16.13.3':
                    ori_ver_ok = False
                    violations.append(f"RFC9629_INVALID_ORI_OID: oriType='{ori_oid}' != '1.2.840.113549.1.9.16.13.3' (id-ori-kem).")
                if kek_len not in (16, 24, 32):
                    kek_kdf_ok = False
                    violations.append(f'RFC9629_INVALID_KEK_LENGTH: kekLength={kek_len} fuera de {(16, 24, 32)} bytes AES-KW.')
                if kdf_alg not in allowed_kdfs:
                    kek_kdf_ok = False
                    violations.append(f"RFC9629_UNSUPPORTED_KDF: KDF '{kdf_alg}' invalido en receptor {idx}.")
                if len(kemct_hex) < 16 or len(enckey_hex) < 32:
                    kek_kdf_ok = False
                    violations.append(f'RFC9629_TRUNCATED_CIPHERTEXT: kemct o encryptedKey truncado en receptor {idx}.')
        proven = len(violations) == 0 and zero_ok and tri_ok and yoneda_ok and ori_ver_ok and kek_kdf_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'objects': n, 'kemri_count': len(rfc9629_kemri_list or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return LawvereQuantaleAndRFC9629Report(release_version=release_version, proven_lawvere_quantale_and_rfc9629_valid=proven, objects_count=n, zero_self_distance_verified=zero_ok, triangle_inequality_verified=tri_ok, yoneda_isometry_verified=yoneda_ok, rfc9629_kemri_checked=len(rfc9629_kemri_list or []), rfc9629_ori_oid_and_version_valid=ori_ver_ok, rfc9629_kek_and_kdf_valid=kek_kdf_ok, lawvere_or_rfc9629_violations=violations, lawvere_rfc9629_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


