# --- Merged from node06_v16_7: KleisliMoggiComputationalMonadAndRFC9545JSContactProver ---
class KleisliMoggiComputationalMonadAndRFC9545JSContactProver:

    @staticmethod
    def prove_kleisli_monad_laws_and_verify_rfc9545_jscontact(domain_A: List[str], unit_eta: Dict[str, List[str]], arrow_f: Dict[str, List[str]], arrow_g: Dict[str, List[str]], arrow_h: Dict[str, List[str]], rfc9553_jscontact_cards: List[Dict[str, Any]], release_version: str='15.7.0') -> KleisliMonadAndRFC9545Report:
        import json
        t0 = time.perf_counter()
        violations: List[str] = []
        dom = [str(x).strip() for x in domain_A or [] if str(x).strip()]
        if not dom:
            violations.append('KLEISLI_EMPTY_DOMAIN: El dominio A de la categoria de Kleisli C_T no puede ser vacio.')

        def k_bind(m_vals: List[str], k_map: Dict[str, List[str]]) -> List[str]:
            out: List[str] = []
            for v in m_vals:
                for res in k_map.get(str(v), []):
                    s_res = str(res)
                    if s_res not in out:
                        out.append(s_res)
            return sorted(out)
        left_id_ok = bool(dom)
        right_id_ok = bool(dom)
        assoc_ok = bool(dom)
        for a in dom:
            eta_a = sorted((str(x) for x in (unit_eta or {}).get(a, [])))
            f_a = sorted((str(x) for x in (arrow_f or {}).get(a, [])))
            lhs_left = k_bind(eta_a, arrow_f or {})
            if lhs_left != f_a or eta_a != [a]:
                left_id_ok = False
                violations.append(f'KLEISLI_LEFT_IDENTITY_VIOLATION: (eta >=> f)({a})={lhs_left} != f({a})={f_a} (eta={eta_a}).')
            lhs_right = k_bind(f_a, unit_eta or {})
            if lhs_right != f_a:
                right_id_ok = False
                violations.append(f'KLEISLI_RIGHT_IDENTITY_VIOLATION: (f >=> eta)({a})={lhs_right} != f({a})={f_a}.')
            fg_a = k_bind(f_a, arrow_g or {})
            lhs_assoc = k_bind(fg_a, arrow_h or {})
            gh_map = {k: k_bind([str(x) for x in v], arrow_h or {}) for k, v in (arrow_g or {}).items()}
            rhs_assoc = k_bind(f_a, gh_map)
            if lhs_assoc != rhs_assoc or not f_a:
                assoc_ok = False
                violations.append(f'KLEISLI_ASSOCIATIVITY_VIOLATION: ((f >=> g) >=> h)({a})={lhs_assoc} != (f >=> (g >=> h))({a})={rhs_assoc}.')
        schema_ok = True
        id_keys_ok = True
        id_re = re.compile('^[A-Za-z0-9\\-_]{1,64}$')
        if not rfc9553_jscontact_cards:
            schema_ok = False
            id_keys_ok = False
            violations.append('RFC9553_EMPTY_CARDS: Se requiere al menos un objeto Card JSContact (RFC 9553).')
        else:
            for idx, card in enumerate(rfc9553_jscontact_cards):
                at_type = str(card.get('@type', '')).strip()
                ver = str(card.get('version', '')).strip()
                uid = str(card.get('uid', '')).strip()
                emails = card.get('emails', {})
                if at_type != 'Card':
                    schema_ok = False
                    violations.append(f"RFC9553_INVALID_TYPE: @type='{at_type}' != 'Card' en card {idx} (RFC 9553 Sec 2).")
                if ver != '1.0':
                    schema_ok = False
                    violations.append(f"RFC9553_INVALID_VERSION: version='{ver}' != '1.0' en card {idx} (RFC 9553 Sec 2.1.4).")
                if not uid:
                    schema_ok = False
                    violations.append(f"RFC9553_MISSING_UID: Propiedad obligatoria 'uid' vacia en card {idx} (RFC 9553 Sec 2.1.5).")
                if not isinstance(emails, dict) or not emails:
                    schema_ok = False
                    violations.append(f"RFC9553_EMPTY_EMAILS: Mapa 'emails' vacio o invalido en card {idx}.")
                else:
                    for ek, ev in emails.items():
                        if not id_re.match(str(ek)):
                            id_keys_ok = False
                            violations.append(f"RFC9553_INVALID_ID_KEY: Clave Id '{ek}' viola [A-Za-z0-9-_]{{1,64}} (RFC 9553 Sec 1.4.1).")
                        addr = str((ev or {}).get('address', '')).strip()
                        if '@' not in addr or addr.startswith('@') or addr.endswith('@'):
                            schema_ok = False
                            violations.append(f"RFC9553_INVALID_EMAIL_ADDRESS: Direccion '{addr}' invalida en clave '{ek}'.")
        proven = len(violations) == 0 and left_id_ok and right_id_ok and assoc_ok and schema_ok and id_keys_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'domain_size': len(dom), 'cards_count': len(rfc9553_jscontact_cards or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return KleisliMonadAndRFC9545Report(release_version=release_version, proven_kleisli_monad_and_rfc9553_jscontact_valid=proven, domain_elements_count=len(dom), left_identity_verified=left_id_ok, right_identity_verified=right_id_ok, associativity_verified=assoc_ok, rfc9553_cards_checked=len(rfc9553_jscontact_cards or []), rfc9553_card_schema_valid=schema_ok, rfc9553_id_keys_valid=id_keys_ok, kleisli_or_rfc9553_violations=violations, kleisli_rfc9553_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


