# --- Merged from node06_v16_7: ComonadUustaluVeneCoKleisliAndRFC9530ReprDigestProver ---
class ComonadUustaluVeneCoKleisliAndRFC9530ReprDigestProver:

    @staticmethod
    def prove_comonad_cokleisli_and_verify_rfc9530_repr_digest(positions: List[str], initial_values: Dict[str, int], neighborhood_map: Dict[str, List[str]], counit_focus_map: Dict[str, str], cokleisli_f_weights: Dict[str, int], cokleisli_g_weights: Dict[str, int], cokleisli_h_weights: Dict[str, int], representation_payload: str, rfc9530_repr_digest_header: str, rfc9530_want_repr_digest_header: str, release_version: str='15.8.0') -> ComonadCoKleisliAndRFC9530Report:
        import json, base64
        t0 = time.perf_counter()
        violations: List[str] = []
        pos_list = [str(p).strip() for p in positions or [] if str(p).strip()]
        if not pos_list:
            violations.append('COMONAD_EMPTY_POSITIONS: El espacio de posiciones W(A) no puede ser vacio.')
        left_coid_ok = bool(pos_list)
        right_coid_ok = bool(pos_list)
        coassoc_ok = bool(pos_list)
        for p in pos_list:
            focus_p = str((counit_focus_map or {}).get(p, ''))
            nb_p = [str(x) for x in (neighborhood_map or {}).get(p, [])]
            if focus_p != p:
                left_coid_ok = False
                right_coid_ok = False
                violations.append(f"COMONAD_COUNIT_FOCUS_MISMATCH: extract('{p}') apunta a '{focus_p}' != '{p}'.")
            if p not in nb_p:
                right_coid_ok = False
                violations.append(f"COMONAD_REFLEXIVE_NEIGHBORHOOD_MISSING: '{p}' no pertenece a su vecindad {nb_p}.")

        def extend_arrow(val_map: Dict[str, int], weights: Dict[str, int]) -> Dict[str, int]:
            out: Dict[str, int] = {}
            for p in pos_list:
                foc = str((counit_focus_map or {}).get(p, p))
                w_p = int((weights or {}).get(p, 1))
                acc = w_p * int(val_map.get(foc, 0))
                for q in (neighborhood_map or {}).get(p, []):
                    qs = str(q)
                    if qs != p:
                        acc += int(val_map.get(qs, 0))
                out[p] = acc
            return out
        if pos_list and left_coid_ok and right_coid_ok:
            v0 = {p: int((initial_values or {}).get(p, 0)) for p in pos_list}
            ext_f = extend_arrow(v0, cokleisli_f_weights or {})
            for p in pos_list:
                foc = str((counit_focus_map or {}).get(p, p))
                if ext_f.get(foc) != ext_f.get(p):
                    left_coid_ok = False
                    violations.append(f'COMONAD_LEFT_COIDENTITY_VIOLATION: extract(extend(f))({p}) != f({p}).')
            ext_eps = {p: v0.get(str((counit_focus_map or {}).get(p, p)), 0) for p in pos_list}
            if ext_eps != v0:
                right_coid_ok = False
                violations.append('COMONAD_RIGHT_COIDENTITY_VIOLATION: extend(extract)(w) != w.')
            v_f = extend_arrow(v0, cokleisli_f_weights or {})
            v_fg = extend_arrow(v_f, cokleisli_g_weights or {})
            lhs_coassoc = extend_arrow(v_fg, cokleisli_h_weights or {})
            rhs_coassoc = extend_arrow(extend_arrow(v_f, cokleisli_g_weights or {}), cokleisli_h_weights or {})
            if lhs_coassoc != rhs_coassoc or not cokleisli_f_weights:
                coassoc_ok = False
                violations.append('COMONAD_COASSOCIATIVITY_VIOLATION: Falla co-asociatividad en C_W.')
        else:
            coassoc_ok = False
        repr_ok = True
        want_ok = True
        expected_b64 = base64.b64encode(hashlib.sha256((representation_payload or '').encode('utf-8')).digest()).decode('ascii')
        m_repr = re.match('^sha-256=:([A-Za-z0-9+/=]+):$', (rfc9530_repr_digest_header or '').strip())
        if not m_repr:
            repr_ok = False
            violations.append(f"RFC9530_MALFORMED_REPR_DIGEST: Encabezado Repr-Digest '{rfc9530_repr_digest_header}' invalido (RFC 9530 Sec 2).")
        elif m_repr.group(1) != expected_b64:
            repr_ok = False
            violations.append('RFC9530_REPR_DIGEST_MISMATCH: Hash SHA-256 en Repr-Digest no coincide con representation_payload.')
        want_parts = [pt.strip() for pt in (rfc9530_want_repr_digest_header or '').split(',') if pt.strip()]
        if not want_parts:
            want_ok = False
            violations.append('RFC9530_EMPTY_WANT_REPR_DIGEST: Encabezado Want-Repr-Digest vacio (RFC 9530 Sec 4).')
        else:
            for wp in want_parts:
                mw = re.match('^([a-z0-9\\-]+)=([0-9]+)$', wp)
                if not mw:
                    want_ok = False
                    violations.append(f"RFC9530_INVALID_WANT_ITEM: Item '{wp}' invalido en Want-Repr-Digest.")
                else:
                    alg_w, prio_s = mw.groups()
                    prio = int(prio_s)
                    if alg_w not in ('sha-256', 'sha-512', 'sha-384') or prio < 0 or prio > 10:
                        want_ok = False
                        violations.append(f"RFC9530_BAD_ALGORITHM_OR_PRIORITY: '{alg_w}={prio}' fuera de rango [0..10] o algoritmo deprecado (RFC 9530 Sec 4).")
        proven = len(violations) == 0 and left_coid_ok and right_coid_ok and coassoc_ok and repr_ok and want_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'positions': len(pos_list), 'expected_b64': expected_b64, 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return ComonadCoKleisliAndRFC9530Report(release_version=release_version, proven_comonad_cokleisli_and_rfc9530_valid=proven, context_positions_count=len(pos_list), left_coidentity_verified=left_coid_ok, right_coidentity_verified=right_coid_ok, coassociativity_verified=coassoc_ok, rfc9530_headers_checked=2, rfc9530_repr_digest_verified=repr_ok, rfc9530_want_repr_digest_valid=want_ok, comonad_or_rfc9530_violations=violations, comonad_rfc9530_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


