# --- Merged from node06_v16_7: BialgebraicTuriPlotkinDistributiveLawAndRFC9596CWTHeaderProver ---
class BialgebraicTuriPlotkinDistributiveLawAndRFC9596CWTHeaderProver:

    @staticmethod
    def prove_turi_plotkin_bialgebra_and_verify_rfc9596_cwt(carrier_terms: List[str], algebra_op_table: Dict[str, Dict[str, str]], coalgebra_out_map: Dict[str, int], coalgebra_next_map: Dict[str, str], distributive_law_lambda: Dict[str, Dict[str, Any]], rfc9596_cose_cwt_headers: List[Dict[str, Any]], release_version: str='15.9.0') -> BialgebraicTuriPlotkinAndRFC9596Report:
        import json
        t0 = time.perf_counter()
        violations: List[str] = []
        terms = [str(t).strip() for t in carrier_terms or [] if str(t).strip()]
        if not terms:
            violations.append('BIALGEBRA_EMPTY_CARRIER: El conjunto portador X de la (Sigma, B)-bialgebra no puede ser vacio.')
        pentagon_ok = bool(terms)
        congruence_ok = bool(terms)
        final_hom_ok = bool(terms)
        traces: Dict[str, Tuple[int, ...]] = {}
        for x in terms:
            curr = x
            tr: List[int] = []
            for _ in range(4):
                if curr not in (coalgebra_out_map or {}) or curr not in (coalgebra_next_map or {}):
                    pentagon_ok = False
                    violations.append(f"BIALGEBRA_INCOMPLETE_COALGEBRA: Estado '{curr}' sin transicion coalgebraica.")
                    break
                tr.append(int(coalgebra_out_map[curr]))
                curr = str(coalgebra_next_map[curr])
            traces[x] = tuple(tr)
        for x in terms:
            for y in terms:
                z = str((algebra_op_table or {}).get(x, {}).get(y, ''))
                if z not in terms:
                    pentagon_ok = False
                    violations.append(f"BIALGEBRA_UNCLOSED_ALGEBRA_OP: op('{x}', '{y}')='{z}' fuera de X.")
                    continue
                key_xy = f'{x},{y}'
                spec = (distributive_law_lambda or {}).get(key_xy)
                if not isinstance(spec, dict):
                    pentagon_ok = False
                    violations.append(f"BIALGEBRA_MISSING_LAMBDA_RULE: Falta regla distributiva lambda para '{key_xy}'.")
                    continue
                exp_out = int(spec.get('out', -999999))
                exp_next = str(spec.get('next', ''))
                act_out = int((coalgebra_out_map or {}).get(z, -888888))
                act_next = str((coalgebra_next_map or {}).get(z, ''))
                if exp_out != act_out or exp_next != act_next:
                    pentagon_ok = False
                    violations.append(f'BIALGEBRA_PENTAGON_COMMUTATION_VIOLATION: En op({x},{y})={z}, coalgebra=({act_out},{act_next}) != lambda=({exp_out},{exp_next}).')
        if pentagon_ok:
            for x1 in terms:
                for x2 in terms:
                    if traces.get(x1) == traces.get(x2):
                        for y1 in terms:
                            for y2 in terms:
                                if traces.get(y1) == traces.get(y2):
                                    z1 = algebra_op_table[x1][y1]
                                    z2 = algebra_op_table[x2][y2]
                                    if traces.get(z1) != traces.get(z2):
                                        congruence_ok = False
                                        violations.append(f'BIALGEBRA_CONGRUENCE_VIOLATION: {x1}~{x2} y {y1}~{y2}, pero op({x1},{y1})={z1} !~ op({x2},{y2})={z2}.')
        else:
            congruence_ok = False
            final_hom_ok = False
        label15_ok = True
        temporal_cnf_ok = True
        if not rfc9596_cose_cwt_headers:
            label15_ok = False
            temporal_cnf_ok = False
            violations.append('RFC9596_EMPTY_HEADERS: Se requiere al menos un sobre COSE con CWT Claims Header (RFC 9596).')
        else:
            for idx, env in enumerate(rfc9596_cose_cwt_headers):
                in_protected = bool(env.get('in_protected_header', False))
                hdr_label = env.get('cose_header_label')
                claims = env.get('cwt_claims', {})
                if not in_protected or hdr_label != 15:
                    label15_ok = False
                    violations.append(f'RFC9596_INVALID_HEADER_LABEL: Sobre {idx} debe usar label=15 en protected header (RFC 9596 Sec 3).')
                if not isinstance(claims, dict):
                    temporal_cnf_ok = False
                    violations.append(f'RFC9596_NON_MAP_CLAIMS: cwt_claims no es mapa CBOR en sobre {idx}.')
                    continue
                iss = str(claims.get('1', claims.get(1, ''))).strip()
                exp = claims.get('4', claims.get(4))
                nbf = claims.get('5', claims.get(5))
                iat = claims.get('6', claims.get(6))
                cti = str(claims.get('7', claims.get(7, ''))).strip()
                cnf = str(claims.get('8', claims.get(8, ''))).strip()
                if not iss or not cti or len(cnf) < 16:
                    temporal_cnf_ok = False
                    violations.append(f'RFC9596_MISSING_MANDATORY_CLAIMS: iss(1), cti(7) o cnf(8) ausente/corto en sobre {idx}.')
                if not (isinstance(nbf, int) and isinstance(iat, int) and isinstance(exp, int) and (nbf <= iat < exp)):
                    temporal_cnf_ok = False
