# --- Merged from node06_v16_7: PresheafToposSubobjectClassifierAndRFC9278JWKThumbprintURIProver ---
class PresheafToposSubobjectClassifierAndRFC9278JWKThumbprintURIProver:

    @staticmethod
    def prove_presheaf_topos_omega_and_verify_rfc9278_jwk_uri(objects: List[str], morphisms: List[Dict[str, str]], composition_table: Dict[str, str], presheaf_F_elements: Dict[str, List[str]], presheaf_F_restriction: Dict[str, Dict[str, str]], subfunctor_U_elements: Dict[str, List[str]], rfc9278_jwk_entries: List[Dict[str, Any]], release_version: str='16.0.0') -> PresheafToposAndRFC9278Report:
        import json, base64
        t0 = time.perf_counter()
        violations: List[str] = []
        objs = [str(o).strip() for o in objects or [] if str(o).strip()]
        if not objs:
            violations.append('TOPOS_EMPTY_CATEGORY: La categoria base C del topos de prehaces no puede ser vacia.')
        morph_map: Dict[str, Tuple[str, str]] = {}
        id_by_obj: Dict[str, str] = {}
        for m in morphisms or []:
            mid = str(m.get('id', '')).strip()
            src = str(m.get('src', '')).strip()
            dst = str(m.get('dst', '')).strip()
            if mid and src in objs and (dst in objs):
                morph_map[mid] = (src, dst)
                if m.get('is_id') or mid == f'id_{src}':
                    id_by_obj[src] = mid
        sieves_ok = bool(objs) and len(id_by_obj) == len(objs)
        pullback_ok = sieves_ok
        naturality_ok = sieves_ok
        if not sieves_ok:
            violations.append('TOPOS_MISSING_IDENTITY_MORPHISMS: Cada objeto C requiere morfismo identidad id_C.')
        else:
            chi_U: Dict[str, Dict[str, Set[str]]] = {c: {} for c in objs}
            for c in objs:
                f_elems = [str(x) for x in (presheaf_F_elements or {}).get(c, [])]
                u_elems = set((str(x) for x in (subfunctor_U_elements or {}).get(c, [])))
                if not u_elems.issubset(set(f_elems)):
                    pullback_ok = False
                    violations.append(f'TOPOS_SUBFUNCTOR_NOT_SUBSET: U({c}) no es subconjunto de F({c}).')
                for x in f_elems:
                    sieve_x: Set[str] = set()
                    for f_id, (d_src, c_dst) in morph_map.items():
                        if c_dst == c:
                            restricted_x = str((presheaf_F_restriction or {}).get(f_id, {}).get(x, ''))
                            if restricted_x in set((str(v) for v in (subfunctor_U_elements or {}).get(d_src, []))):
                                sieve_x.add(f_id)
                    chi_U[c][x] = sieve_x
                    for f_id in list(sieve_x):
                        d_src, _ = morph_map[f_id]
                        for g_id, (e_src, d_dst) in morph_map.items():
                            if d_dst == d_src:
                                fg_id = str((composition_table or {}).get(f'{f_id},{g_id}', ''))
                                if fg_id not in sieve_x:
                                    sieves_ok = False
                                    violations.append(f"TOPOS_NOT_A_SIEVE: chi_U({c})({x}) contiene '{f_id}' pero no '{f_id} o {g_id}'='{fg_id}'.")
                    id_c = id_by_obj[c]
                    if (x in u_elems) != (id_c in sieve_x):
                        pullback_ok = False
                        violations.append(f"TOPOS_PULLBACK_AXIOM_VIOLATION: En {c}, x='{x}' in U iff id_{c} in chi_U falla.")
            for h_id, (c_prime, c_dst) in morph_map.items():
                for x in (presheaf_F_elements or {}).get(c_dst, []):
                    xs = str(x)
                    fh_x = str((presheaf_F_restriction or {}).get(h_id, {}).get(xs, ''))
                    if fh_x not in chi_U.get(c_prime, {}):
                        naturality_ok = False
                        violations.append(f"TOPOS_BROKEN_RESTRICTION: F({h_id})({xs})='{fh_x}' fuera de F({c_prime}).")
                    else:
                        rhs_sieve = chi_U[c_prime][fh_x]
                        lhs_sieve = {g_id for g_id, (_, g_dst) in morph_map.items() if g_dst == c_prime and str((composition_table or {}).get(f'{h_id},{g_id}', '')) in chi_U[c_dst].get(xs, set())}
                        if lhs_sieve != rhs_sieve:
                            naturality_ok = False
                            violations.append(f'TOPOS_NATURALITY_VIOLATION: h*(chi_U({c_dst})({xs})) != chi_U({c_prime})(F({h_id})({xs})).')
        urn_ok = True
        thumb_ok = True
        if not rfc9278_jwk_entries:
            urn_ok = False
            thumb_ok = False
            violations.append('RFC9278_EMPTY_ENTRIES: Se requiere al menos una entrada JWK Thumbprint URI (RFC 9278).')
        else:
            for idx, item in enumerate(rfc9278_jwk_entries):
                jwk = item.get('jwk', {})
                uri = str(item.get('thumbprint_uri', '')).strip()
                m_urn = re.match('^urn:ietf:params:oauth:jwk-thumbprint:sha-256:([A-Za-z0-9_\\-]{43})$', uri)
                if not m_urn:
                    urn_ok = False
                    violations.append(f"RFC9278_MALFORMED_URN: URI '{uri}' no cumple RFC 9278 Sec 3.")
                    continue
                kty = str(jwk.get('kty', '')).strip()
                if kty == 'OKP':
                    req_keys = ('crv', 'kty', 'x')
                elif kty == 'EC':
                    req_keys = ('crv', 'kty', 'x', 'y')
                elif kty == 'RSA':
                    req_keys = ('e', 'kty', 'n')
                else:
                    thumb_ok = False
                    violations.append(f"RFC9278_UNSUPPORTED_KTY: kty='{kty}' invalido en entrada {idx}.")
                    continue
                canon_dict = {k: str(jwk.get(k, '')) for k in req_keys}
                canon_json = json.dumps(canon_dict, separators=(',', ':'), sort_keys=True)
                exp_b64u = base64.urlsafe_b64encode(hashlib.sha256(canon_json.encode('utf-8')).digest()).decode('ascii').rstrip('=')
                if m_urn.group(1) != exp_b64u:
                    thumb_ok = False
                    violations.append(f"RFC9278_THUMBPRINT_MISMATCH: Hash en URI '{m_urn.group(1)}' != esperado '{exp_b64u}'.")
        proven = len(violations) == 0 and sieves_ok and pullback_ok and naturality_ok and urn_ok and thumb_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'objects': len(objs), 'uris': len(rfc9278_jwk_entries or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return PresheafToposAndRFC9278Report(release_version=release_version, proven_presheaf_topos_and_rfc9278_valid=proven, category_objects_count=len(objs), sieves_omega_valid=sieves_ok, subfunctor_pullback_verified=pullback_ok, characteristic_naturality_verified=naturality_ok, rfc9278_uris_checked=len(rfc9278_jwk_entries or []), rfc9278_urn_syntax_valid=urn_ok, rfc9278_thumbprint_hash_verified=thumb_ok, topos_or_rfc9278_violations=violations, topos_rfc9278_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


