# --- Merged from node06_v16_7: BeckChevalleyDescentBenaBouRoubaudAndRFC9682COSECounterSigV2Prover ---
class BeckChevalleyDescentBenaBouRoubaudAndRFC9682COSECounterSigV2Prover:

    @classmethod
    def prove_beck_chevalley_descent_and_verify_rfc9682_cose(cls, set_P: List[str], set_X: List[str], set_Y: List[str], set_Z: List[str], map_u_P_to_X: Dict[str, str], map_v_P_to_Y: Dict[str, str], map_f_X_to_Z: Dict[str, str], map_g_Y_to_Z: Dict[str, str], rfc9682_cose_countersigs: List[Dict[str, Any]], release_version: str='16.2.0') -> BeckChevalleyDescentAndRFC9682Report:
        t0 = time.perf_counter()
        violations: List[str] = []
        P = list(dict.fromkeys(set_P or []))
        X = list(dict.fromkeys(set_X or []))
        Y = list(dict.fromkeys(set_Y or []))
        Z = list(dict.fromkeys(set_Z or []))
        u = dict(map_u_P_to_X or {})
        v = dict(map_v_P_to_Y or {})
        f = dict(map_f_X_to_Z or {})
        g = dict(map_g_Y_to_Z or {})
        pb_ok = True
        bc_ok = True
        frob_ok = True
        if not P or not X or (not Y) or (not Z):
            pb_ok = False
            violations.append('PULLBACK_EMPTY_CARRIER: Los conjuntos P, X, Y, Z deben ser no vacíos.')
        expected_pairs = {(x, y) for x in X for y in Y if f.get(x) is not None and f.get(x) == g.get(y)}
        actual_pairs = set()
        for p in P:
            xp = u.get(p)
            yp = v.get(p)
            if xp not in X or yp not in Y:
                pb_ok = False
                violations.append(f"PULLBACK_INVALID_PROJECTION: p='{p}' proyecta fuera de X o Y.")
                continue
            if f.get(xp) != g.get(yp):
                pb_ok = False
                violations.append(f"PULLBACK_NON_COMMUTATIVE: f(u('{p}'))='{f.get(xp)}' != g(v('{p}'))='{g.get(yp)}'.")
            pair = (xp, yp)
            if pair in actual_pairs:
                pb_ok = False
                violations.append(f'PULLBACK_NOT_MONIC: Par duplicado {pair} en P.')
            actual_pairs.add(pair)
        if actual_pairs != expected_pairs:
            pb_ok = False
            violations.append(f'PULLBACK_UNIVERSALITY_VIOLATED: P proyecta {sorted(actual_pairs)} != producto fibrado {sorted(expected_pairs)}.')
        for y0 in Y:
            S_Y = {y0}
            v_star_S = {p for p in P if v.get(p) in S_Y}
            lhs_bc = {u.get(p) for p in v_star_S if u.get(p) in X}
            exists_g_S = {g.get(y) for y in S_Y if g.get(y) in Z}
            rhs_bc = {x for x in X if f.get(x) in exists_g_S}
            if lhs_bc != rhs_bc:
                bc_ok = False
                violations.append(f'BECK_CHEVALLEY_VIOLATION: exists_u(v*({S_Y}))={sorted(lhs_bc)} != f*(exists_g({S_Y}))={sorted(rhs_bc)}.')
        for x0 in X:
            for z0 in Z:
                A = {x0}
                B = {z0}
                f_star_B = {x for x in X if f.get(x) in B}
                lhs_frob = {f.get(x) for x in A & f_star_B if f.get(x) in Z}
                exists_f_A = {f.get(x) for x in A if f.get(x) in Z}
                rhs_frob = exists_f_A & B
                if lhs_frob != rhs_frob:
                    frob_ok = False
                    violations.append(f'FROBENIUS_RECIPROCITY_VIOLATION: exists_f(A & f*(B))={sorted(lhs_frob)} != exists_f(A) & B={sorted(rhs_frob)}.')
        cose_ctx_ok = True
        cose_dig_ok = True
        allowed_algs = {'ES256', 'ES384', 'EdDSA', 'PS256', 'ML-DSA-65'}
        if not rfc9682_cose_countersigs:
            cose_ctx_ok = False
            cose_dig_ok = False
            violations.append('RFC9682_EMPTY_COUNTERSIGS: Lista de contrafirmas COSE v2 vacía.')
        else:
            for idx, cs in enumerate(rfc9682_cose_countersigs):
                ctx = str(cs.get('context', ''))
                label = cs.get('header_label')
                alg = str(cs.get('alg', ''))
                body_prot = str(cs.get('body_protected_bstr_hex', '')).lower()
                sign_prot = str(cs.get('sign_protected_bstr_hex', '')).lower()
                ext_aad = str(cs.get('external_aad_bstr_hex', '')).lower()
                payload_sig = str(cs.get('target_signature_bstr_hex', '')).lower()
                other_fields = cs.get('other_fields_bstr_hex', [])
                expected_hash = str(cs.get('countersig_structure_sha256', '')).lower()
                if ctx not in {'CounterSignatureV2', 'CounterSignature0V2', 'CounterSignature'}:
                    cose_ctx_ok = False
                    violations.append(f"RFC9682_INVALID_CONTEXT: context '{ctx}' inválido en contrafirma {idx}.")
                if ctx == 'CounterSignatureV2' and label != 11 or (ctx == 'CounterSignature0V2' and label != 12):
                    cose_ctx_ok = False
                    violations.append(f"RFC9682_LABEL_MISMATCH: context '{ctx}' requiere label 11/12 pero recibió '{label}' en {idx}.")
                if alg not in allowed_algs:
                    cose_ctx_ok = False
                    violations.append(f"RFC9682_WEAK_OR_UNKNOWN_ALG: alg '{alg}' no permitido en contrafirma {idx}.")
