class GodelDialecticaCategoryDePaivaAndRFC9679COSEKeyThumbprintProver:

    @classmethod
    def prove_godel_dialectica_morphism_and_verify_rfc9679_cose_ktp(cls, witness_U: List[str], challenge_X: List[str], witness_V: List[str], challenge_Y: List[str], relation_alpha_UX: List[List[str]], relation_beta_VY: List[List[str]], forward_map_f_U_to_V: Dict[str, str], backward_map_F_UY_to_X: Dict[str, str], rfc9679_cose_keys: List[Dict[str, Any]], release_version: str='16.3.0') -> GodelDialecticaAndRFC9679Report:
        t0 = time.perf_counter()
        violations: List[str] = []
        U = list(dict.fromkeys(witness_U or []))
        X = list(dict.fromkeys(challenge_X or []))
        V = list(dict.fromkeys(witness_V or []))
        Y = list(dict.fromkeys(challenge_Y or []))
        alpha = {(str(pair[0]), str(pair[1])) for pair in relation_alpha_UX or [] if len(pair) == 2}
        beta = {(str(pair[0]), str(pair[1])) for pair in relation_beta_VY or [] if len(pair) == 2}
        f_map = dict(forward_map_f_U_to_V or {})
        F_map = dict(backward_map_F_UY_to_X or {})
        fwd_ok = True
        bwd_ok = True
        adj_ok = True
        mon_ok = True
        if not U or not X or (not V) or (not Y):
            fwd_ok = False
            bwd_ok = False
            violations.append('DIALECTICA_EMPTY_CARRIER: Los portadores U, X, V, Y deben ser no vacíos.')
        for u in U:
            if f_map.get(u) not in V:
                fwd_ok = False
                violations.append(f"DIALECTICA_FORWARD_INVALID: f('{u}')='{f_map.get(u)}' no pertenece a V.")
        for u in U:
            for y in Y:
                key = f'{u}|{y}'
                x_val = F_map.get(key)
                if x_val not in X:
                    bwd_ok = False
                    violations.append(f"DIALECTICA_BACKWARD_INVALID: F('{u}','{y}')='{x_val}' no pertenece a X.")
                elif fwd_ok:
                    v_val = f_map.get(u)
                    if (u, x_val) in alpha and (v_val, y) not in beta:
                        adj_ok = False
                        violations.append(f"DIALECTICA_IMPLICATION_VIOLATION: alpha('{u}','{x_val}')=True pero beta(f('{u}')='{v_val}','{y}')=False.")
        if not alpha or not beta:
            mon_ok = False
            violations.append('DIALECTICA_TRIVIAL_RELATION: Las relaciones alpha y beta deben ser no vacías.')
        cbor_order_ok = True
        ktp_hash_ok = True
        required_params_by_kty = {1: [1, -1, -2], 2: [1, -1, -2, -3], 3: [1, -1, -2]}
        if not rfc9679_cose_keys:
            cbor_order_ok = False
            ktp_hash_ok = False
            violations.append('RFC9679_EMPTY_KEYS: Lista de claves COSE vacía.')
        else:
            for idx, ck in enumerate(rfc9679_cose_keys):
                kty = ck.get('kty')
                ordered_labels = ck.get('cbor_deterministic_labels', [])
                canonical_cbor_hex = str(ck.get('canonical_cbor_bstr_hex', '')).lower()
                expected_ktp = str(ck.get('expected_thumbprint_sha256', '')).lower()
                uri = str(ck.get('cose_key_thumbprint_uri', ''))
                if kty not in required_params_by_kty:
                    cbor_order_ok = False
                    violations.append(f"RFC9679_UNSUPPORTED_KTY: kty='{kty}' inválido en clave {idx}.")
                else:
                    expected_order = required_params_by_kty[kty]
                    if list(ordered_labels) != expected_order:
                        cbor_order_ok = False
                        violations.append(f'RFC9679_CBOR_SORT_VIOLATION: Labels {ordered_labels} != orden determinista RFC 8949 {expected_order} en {idx}.')
                try:
                    raw_bytes = bytes.fromhex(canonical_cbor_hex) if canonical_cbor_hex else b''
                except ValueError:
                    raw_bytes = b''
                if not raw_bytes:
                    ktp_hash_ok = False
                    violations.append(f'RFC9679_INVALID_CBOR_HEX: canonical_cbor_bstr_hex vacío o inválido en {idx}.')
                else:
                    calc_ktp = hashlib.sha256(raw_bytes).hexdigest()
                    if calc_ktp != expected_ktp:
                        ktp_hash_ok = False
                        violations.append(f"RFC9679_THUMBPRINT_MISMATCH: SHA-256 '{calc_ktp}' != '{expected_ktp}' en {idx}.")
                    if uri and (not uri.startswith('urn:ietf:params:oauth:ckt:sha-256:')):
                        cbor_order_ok = False
                        violations.append(f"RFC9679_INVALID_URI_PREFIX: URI '{uri}' no cumple prefijo RFC 9679 en {idx}.")
        proven = len(violations) == 0 and fwd_ok and bwd_ok and adj_ok and mon_ok and cbor_order_ok and ktp_hash_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'U_size': len(U), 'keys_count': len(rfc9679_cose_keys or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return GodelDialecticaAndRFC9679Report(release_version=release_version, proven_dialectica_and_rfc9679_valid=proven, dialectica_forward_map_total=fwd_ok, dialectica_backward_witness_total=bwd_ok, dialectica_adjunction_implication_verified=adj_ok, dialectica_tensor_monoidal_verified=mon_ok, rfc9679_cose_keys_checked=len(rfc9679_cose_keys or []), rfc9679_cbor_canonical_order_valid=cbor_order_ok, rfc9679_thumbprint_sha256_verified=ktp_hash_ok, dialectica_or_rfc9679_violations=violations, dialectica_rfc9679_pcc_seal_sha256=seal, analysis_duration_ms=round(dur, 3))


