# --- Merged from node06_v16_7: KleeneHylandEffectiveToposRealizabilityAndRFC9688CMSSHA3Prover ---
class KleeneHylandEffectiveToposRealizabilityAndRFC9688CMSSHA3Prover:
    @classmethod
    def prove_kleene_hyland_realizability_and_verify_rfc9688_cms_sha3(
        cls,
        domain_I: List[str],
        predicate_phi_realizers: Dict[str, List[int]],
        predicate_psi_realizers: Dict[str, List[int]],
        implication_realizer_code_e: int,
        kleene_pca_table: Dict[str, int],
        rfc9688_cms_sha3_entries: List[Dict[str, Any]],
        release_version: str = '16.4.0',
    ) -> KleeneHylandRealizabilityAndRFC9688Report:
        t0 = time.perf_counter()
        violations: List[str] = []
        I_set = list(dict.fromkeys(domain_I or []))
        phi = {k: set(v or []) for k, v in (predicate_phi_realizers or {}).items()}
        psi = {k: set(v or []) for k, v in (predicate_psi_realizers or {}).items()}
        pca = dict(kleene_pca_table or {})
        pca_ok = True
        mp_ok = True
        conj_ok = True
        if not I_set:
            pca_ok = False
            violations.append('REALIZABILITY_EMPTY_DOMAIN: El dominio I del tripos de Hyland debe ser no vacío.')
        for i in I_set:
            phi_i = phi.get(i, set())
            psi_i = psi.get(i, set())
            if not phi_i and not psi_i:
                conj_ok = False
                violations.append(f"REALIZABILITY_EMPTY_FIBER: Fibra '{i}' sin realizadores en phi ni psi.")
            for a in sorted(phi_i):
                key = f"{implication_realizer_code_e}|{a}"
                if key not in pca:
                    pca_ok = False
                    violations.append(f"KLEENE_PCA_UNDEFINED: Aplicacion parcial {{{implication_realizer_code_e}}}({a}) indefinida en fibra '{i}'.")
                else:
                    out_realizer = pca[key]
                    if out_realizer not in psi_i:
                        mp_ok = False
                        violations.append(f"REALIZABILITY_MODUS_PONENS_VIOLATION: {{{implication_realizer_code_e}}}({a})={out_realizer} no realiza psi('{i}')={sorted(psi_i)}.")
        sha3_oid_map = {
            '2.16.840.1.101.3.4.2.8': ('SHA3-256', hashlib.sha3_256, 64),
            '2.16.840.1.101.3.4.2.9': ('SHA3-384', hashlib.sha3_384, 96),
            '2.16.840.1.101.3.4.2.10': ('SHA3-512', hashlib.sha3_512, 128),
        }
        oid_ok = True
        dig_ok = True
        if not rfc9688_cms_sha3_entries:
            oid_ok = False
            dig_ok = False
            violations.append('RFC9688_EMPTY_ENTRIES: Lista de entradas CMS SHA3 vacía.')
        else:
            for idx, ent in enumerate(rfc9688_cms_sha3_entries):
                oid = str(ent.get('digest_algorithm_oid', ''))
                alg_name = str(ent.get('alg_name', ''))
                params_present = bool(ent.get('parameters_present', False))
                content_hex = str(ent.get('encap_content_hex', '')).lower()
                expected_dig = str(ent.get('message_digest_hex', '')).lower()
                if oid not in sha3_oid_map:
                    oid_ok = False
                    violations.append(f"RFC9688_INVALID_OID: OID '{oid}' no pertenece a SHA3-256/384/512 en entrada {idx}.")
                    continue
                exp_name, hash_fn, hex_len = sha3_oid_map[oid]
                if alg_name != exp_name:
                    oid_ok = False
                    violations.append(f"RFC9688_ALG_NAME_MISMATCH: OID '{oid}' requiere '{exp_name}' pero recibió '{alg_name}' en {idx}.")
                if params_present:
                    oid_ok = False
                    violations.append(f"RFC9688_PARAMETERS_MUST_BE_ABSENT: AlgorithmIdentifier parameters debe ser ABSENT (no NULL) según RFC 9688 Sección 2 en {idx}.")
                try:
                    raw_bytes = bytes.fromhex(content_hex) if content_hex else b''
                except ValueError:
                    raw_bytes = b''
                if not raw_bytes and content_hex != '':
                    dig_ok = False
                    violations.append(f"RFC9688_INVALID_CONTENT_HEX: encap_content_hex inválido en {idx}.")
                else:
                    calc_dig = hash_fn(raw_bytes).hexdigest()
                    if len(expected_dig) != hex_len or calc_dig != expected_dig:
                        dig_ok = False
                        violations.append(f"RFC9688_DIGEST_MISMATCH: {exp_name} calculado '{calc_dig}' != '{expected_dig}' en {idx}.")
        proven = len(violations) == 0 and pca_ok and mp_ok and conj_ok and oid_ok and dig_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'domain_size': len(I_set), 'cms_entries': len(rfc9688_cms_sha3_entries or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return KleeneHylandRealizabilityAndRFC9688Report(
            release_version=release_version,
            proven_realizability_and_rfc9688_valid=proven,
            kleene_pca_application_totality_on_witnesses=pca_ok,
            realizability_modus_ponens_verified=mp_ok,
            realizability_conjunction_projection_verified=conj_ok,
            rfc9688_cms_entries_checked=len(rfc9688_cms_sha3_entries or []),
            rfc9688_sha3_oid_and_absent_params_valid=oid_ok,
            rfc9688_sha3_digest_verified=dig_ok,
            realizability_or_rfc9688_violations=violations,
            realizability_rfc9688_pcc_seal_sha256=seal,
            analysis_duration_ms=round(dur, 3),
        )


