# --- Merged from node06_v16_7: VoevodskyUnivalenceQuasiInverseAndRFC9528EDHOCTranscriptProver ---
class VoevodskyUnivalenceQuasiInverseAndRFC9528EDHOCTranscriptProver:
    @classmethod
    def prove_voevodsky_univalence_and_verify_rfc9528_edhoc_th(
        cls,
        type_A: List[str],
        type_B: List[str],
        forward_equiv_f: Dict[str, str],
        quasi_inverse_g: Dict[str, str],
        transport_p_A_to_B: Dict[str, str],
        transport_q_B_to_C: Dict[str, str],
        transport_pq_A_to_C: Dict[str, str],
        rfc9528_edhoc_sessions: List[Dict[str, Any]],
        release_version: str = '16.5.0',
    ) -> VoevodskyUnivalenceAndRFC9528Report:
        t0 = time.perf_counter()
        violations: List[str] = []
        A = list(dict.fromkeys(type_A or []))
        B = list(dict.fromkeys(type_B or []))
        f = dict(forward_equiv_f or {})
        g = dict(quasi_inverse_g or {})
        tp_p = dict(transport_p_A_to_B or {})
        tp_q = dict(transport_q_B_to_C or {})
        tp_pq = dict(transport_pq_A_to_C or {})
        retr_ok = True
        sect_ok = True
        trans_ok = True
        if not A or not B:
            retr_ok = False
            sect_ok = False
            violations.append('UNIVALENCE_EMPTY_TYPE: Los tipos A y B en el universo U deben ser no vacíos.')
        for x in A:
            fx = f.get(x)
            if fx not in B:
                retr_ok = False
                violations.append(f"UNIVALENCE_FORWARD_OUT_OF_DOMAIN: f('{x}')='{fx}' no pertenece a B.")
            else:
                gfx = g.get(fx)
                if gfx != x:
                    retr_ok = False
                    violations.append(f"UNIVALENCE_RETRACTION_VIOLATION: g(f('{x}'))='{gfx}' != '{x}'.")
        for y in B:
            gy = g.get(y)
            if gy not in A:
                sect_ok = False
                violations.append(f"UNIVALENCE_INVERSE_OUT_OF_DOMAIN: g('{y}')='{gy}' no pertenece a A.")
            else:
                fgy = f.get(gy)
                if fgy != y:
                    sect_ok = False
                    violations.append(f"UNIVALENCE_SECTION_VIOLATION: f(g('{y}'))='{fgy}' != '{y}'.")
        for x in A:
            b_val = tp_p.get(x)
            c_step = tp_q.get(b_val) if b_val is not None else None
            c_direct = tp_pq.get(x)
            if c_step is None or c_direct is None or c_step != c_direct:
                trans_ok = False
                violations.append(f"UNIVALENCE_TRANSPORT_FUNCTORIALITY_VIOLATION: transport(q, transport(p, '{x}'))='{c_step}' != transport(p.q, '{x}')='{c_direct}'.")
        suite_ok = True
        th_ok = True
        allowed_suites = {2, 3, 24, 25}
        allowed_methods = {0, 1, 2, 3}
        if not rfc9528_edhoc_sessions:
            suite_ok = False
            th_ok = False
            violations.append('RFC9528_EMPTY_SESSIONS: Lista de sesiones EDHOC vacía.')
        else:
            for idx, sess in enumerate(rfc9528_edhoc_sessions):
                method = sess.get('method')
                suite = sess.get('cipher_suite')
                msg1_hex = str(sess.get('msg1_cbor_hex', '')).lower()
                g_y_hex = str(sess.get('g_y_cbor_hex', '')).lower()
                th2_exp = str(sess.get('th2_sha256', '')).lower()
                ciphertext2_hex = str(sess.get('ciphertext2_cbor_hex', '')).lower()
                th3_exp = str(sess.get('th3_sha256', '')).lower()
                ciphertext3_hex = str(sess.get('ciphertext3_cbor_hex', '')).lower()
                th4_exp = str(sess.get('th4_sha256', '')).lower()
                if method not in allowed_methods:
                    suite_ok = False
                    violations.append(f"RFC9528_INVALID_METHOD: method='{method}' fuera de {{0..3}} en sesión {idx}.")
                if suite not in allowed_suites:
                    suite_ok = False
                    violations.append(f"RFC9528_UNAPPROVED_SUITE: cipher_suite='{suite}' no permitido (usar 2, 3, 24 o 25) en {idx}.")
                try:
                    b_m1 = bytes.fromhex(msg1_hex)
                    b_gy = bytes.fromhex(g_y_hex)
                    b_ct2 = bytes.fromhex(ciphertext2_hex)
                    b_ct3 = bytes.fromhex(ciphertext3_hex)
                    if not b_m1 or not b_gy or not b_ct2 or not b_ct3:
                        raise ValueError('empty bytes')
                    th2_calc = hashlib.sha256(b_m1 + b_gy).hexdigest()
                    th3_calc = hashlib.sha256(bytes.fromhex(th2_calc) + b_ct2).hexdigest()
                    th4_calc = hashlib.sha256(bytes.fromhex(th3_calc) + b_ct3).hexdigest()
                    if th2_calc != th2_exp or th3_calc != th3_exp or th4_calc != th4_exp:
                        th_ok = False
                        violations.append(f"RFC9528_TH_CHAIN_MISMATCH: Cadena TH_2/TH_3/TH_4 inválida en sesión {idx}.")
                except ValueError:
                    th_ok = False
                    violations.append(f"RFC9528_INVALID_HEX: Campos CBOR hex vacíos o mal formados en sesión {idx}.")
        proven = len(violations) == 0 and retr_ok and sect_ok and trans_ok and suite_ok and th_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'A_size': len(A), 'sessions': len(rfc9528_edhoc_sessions or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return VoevodskyUnivalenceAndRFC9528Report(
            release_version=release_version,
            proven_univalence_and_rfc9528_valid=proven,
            homotopy_retraction_verified=retr_ok,
            homotopy_section_verified=sect_ok,
            transport_path_functoriality_verified=trans_ok,
            rfc9528_edhoc_sessions_checked=len(rfc9528_edhoc_sessions or []),
            rfc9528_cipher_suite_and_method_valid=suite_ok,
            rfc9528_transcript_hash_chain_verified=th_ok,
            univalence_or_rfc9528_violations=violations,
            univalence_rfc9528_pcc_seal_sha256=seal,
            analysis_duration_ms=round(dur, 3),
        )


