# --- Merged from node06_v16_7: JoyalQuasiCategoryInnerHornAndRFC9458OHTTPKeyConfigProver ---
class JoyalQuasiCategoryInnerHornAndRFC9458OHTTPKeyConfigProver:
    @classmethod
    def prove_joyal_quasicategory_horn_and_verify_rfc9458_ohttp(
        cls,
        vertices_0_simplices: List[str],
        edges_1_simplices: Dict[str, List[str]],
        triangles_2_simplices: Dict[str, List[str]],
        inner_horns_lambda_2_1: List[List[str]],
        degeneracy_s0_map: Dict[str, str],
        rfc9458_ohttp_entries: List[Dict[str, Any]],
        release_version: str = '16.7.0',
    ) -> JoyalQuasiCategoryAndRFC9458Report:
        t0 = time.perf_counter()
        violations: List[str] = []
        V0 = list(dict.fromkeys(vertices_0_simplices or []))
        E1 = {k: list(v) for k, v in (edges_1_simplices or {}).items() if isinstance(v, list) and len(v) == 2}
        T2 = {k: list(v) for k, v in (triangles_2_simplices or {}).items() if isinstance(v, list) and len(v) == 3}
        s0 = dict(degeneracy_s0_map or {})
        simp_ok = True
        horn_ok = True
        deg_ok = True
        if not V0 or not E1 or not T2:
            simp_ok = False
            violations.append('QUASICAT_EMPTY_COMPLEX: El conjunto simplicial debe tener 0-símplices, 1-símplices y 2-símplices.')
        for e_id, bounds in E1.items():
            d1_e, d0_e = bounds[0], bounds[1]
            if d1_e not in V0 or d0_e not in V0:
                simp_ok = False
                violations.append(f"QUASICAT_INVALID_1_SIMPLEX: Arista '{e_id}' tiene vértices fuera de V0.")
        for t_id, faces in T2.items():
            f_d0, f_d1, f_d2 = faces[0], faces[1], faces[2]
            if f_d0 not in E1 or f_d1 not in E1 or f_d2 not in E1:
                simp_ok = False
                violations.append(f"QUASICAT_INVALID_2_SIMPLEX_FACES: Triángulo '{t_id}' referencia aristas inexistentes.")
                continue
            if E1[f_d2][0] != E1[f_d1][0]:
                simp_ok = False
                violations.append(f"SIMPLICIAL_IDENTITY_D1_D2_VIOLATION: En '{t_id}', d1(d2)='{E1[f_d2][0]}' != d1(d1)='{E1[f_d1][0]}'.")
            if E1[f_d0][0] != E1[f_d2][1]:
                simp_ok = False
                violations.append(f"SIMPLICIAL_IDENTITY_D1_D0_VIOLATION: En '{t_id}', d1(d0)='{E1[f_d0][0]}' != d0(d2)='{E1[f_d2][1]}'.")
            if E1[f_d0][1] != E1[f_d1][1]:
                simp_ok = False
                violations.append(f"SIMPLICIAL_IDENTITY_D0_D0_VIOLATION: En '{t_id}', d0(d0)='{E1[f_d0][1]}' != d0(d1)='{E1[f_d1][1]}'.")
        for horn in (inner_horns_lambda_2_1 or []):
            if len(horn) != 2:
                horn_ok = False
                violations.append(f"QUASICAT_MALFORMED_HORN: Cuerno interno {horn} debe tener [f_ab, g_bc].")
                continue
            f_ab, g_bc = horn[0], horn[1]
            if f_ab not in E1 or g_bc not in E1 or E1[f_ab][1] != E1[g_bc][0]:
                horn_ok = False
                violations.append(f"QUASICAT_NON_COMPOSABLE_HORN: Aristas '{f_ab}' y '{g_bc}' no conectan en vértice intermedio.")
                continue
            filler_found = any(faces[2] == f_ab and faces[0] == g_bc for faces in T2.values())
            if not filler_found:
                horn_ok = False
                violations.append(f"QUASICAT_MISSING_INNER_HORN_FILLER: Cuerno interno Lambda^2_1 ({f_ab}, {g_bc}) carece de 2-símplice de relleno.")
        for v in V0:
            deg_e = s0.get(v)
            if deg_e not in E1 or E1[deg_e] != [v, v]:
                deg_ok = False
                violations.append(f"SIMPLICIAL_DEGENERACY_VIOLATION: s0('{v}')='{deg_e}' no satisface d0(s0(v))=d1(s0(v))=v.")
        suite_ok = True
        hdr_ok = True
        allowed_kems = {0x0010, 0x0011, 0x0012, 0x0020}
        allowed_kdfs = {0x0001, 0x0002, 0x0003}
        allowed_aeads = {0x0001, 0x0002, 0x0003}
        if not rfc9458_ohttp_entries:
            suite_ok = False
            hdr_ok = False
            violations.append('RFC9458_EMPTY_ENTRIES: Lista de configuraciones OHTTP vacía.')
        else:
            for idx, ent in enumerate(rfc9458_ohttp_entries):
                key_id = ent.get('key_id')
                kem_id = ent.get('kem_id')
                kdf_id = ent.get('kdf_id')
                aead_id = ent.get('aead_id')
                hdr_hex = str(ent.get('encapsulated_req_hdr_hex', '')).lower()
                if not isinstance(key_id, int) or not (0 <= key_id <= 255):
                    suite_ok = False
                    violations.append(f"RFC9458_INVALID_KEY_ID: key_id='{key_id}' fuera de 0..255 en {idx}.")
                if kem_id not in allowed_kems or kdf_id not in allowed_kdfs or aead_id not in allowed_aeads:
                    suite_ok = False
                    violations.append(f"RFC9458_INVALID_HPKE_SUITE: (kem={kem_id}, kdf={kdf_id}, aead={aead_id}) inválido en {idx}.")
                expected_hdr = f"{int(key_id or 0):02x}{int(kem_id or 0):04x}{int(kdf_id or 0):04x}{int(aead_id or 0):04x}"
                if hdr_hex != expected_hdr:
                    hdr_ok = False
                    violations.append(f"RFC9458_HDR_MISMATCH: Encapsulated Request Header '{hdr_hex}' != '{expected_hdr}' (7 octetos) en {idx}.")
        proven = len(violations) == 0 and simp_ok and horn_ok and deg_ok and suite_ok and hdr_ok
        seal_payload = json.dumps({'release_version': release_version, 'proven': proven, 'V0': len(V0), 'T2': len(T2), 'ohttp': len(rfc9458_ohttp_entries or []), 'violations': violations}, sort_keys=True)
        seal = hashlib.sha256(seal_payload.encode('utf-8')).hexdigest()
        dur = (time.perf_counter() - t0) * 1000.0
        return JoyalQuasiCategoryAndRFC9458Report(
            release_version=release_version,
            proven_quasicategory_and_rfc9458_valid=proven,
            simplicial_face_identities_verified=simp_ok,
            inner_horn_lambda_2_1_filler_verified=horn_ok,
            degeneracy_unit_identities_verified=deg_ok,
            rfc9458_ohttp_configs_checked=len(rfc9458_ohttp_entries or []),
            rfc9458_hpke_suite_ids_valid=suite_ok,
            rfc9458_encapsulated_request_header_verified=hdr_ok,
            quasicategory_or_rfc9458_violations=violations,
            quasicategory_rfc9458_pcc_seal_sha256=seal,
            analysis_duration_ms=round(dur, 3),
        )


