# --- Merged from node03_v16_6: PgVectorHNSWMutualRLSAndLogicalReplicationSlotBloatProver ---
class PgVectorHNSWMutualRLSAndLogicalReplicationSlotBloatProver:

    @classmethod
    def audit_pgvector_rls_and_slot_bloat(cls, vector_and_rls_sql: str='', replication_and_maintenance_sql: str='') -> PgVectorHNSWRLSAndReplicationSlotBloatReport:
        t0 = time.perf_counter_ns()
        vec_v: List[str] = []
        slot_v: List[str] = []
        hot_v: List[str] = []
        v_src = vector_and_rls_sql or ''
        r_src = replication_and_maintenance_sql or ''
        if v_src.strip():
            has_vector = bool(re.search('\\bvector\\s*\\(\\s*\\d+\\s*\\)|USING\\s+hnsw|vector_cosine_ops|vector_l2_ops|<=>|<->', v_src, re.IGNORECASE))
            if has_vector:
                if not re.search("hnsw\\.iterative_scan\\s*=\\s*'(?:relaxed_order|strict_order)'", v_src, re.IGNORECASE):
                    vec_v.append("PGVECTOR_HNSW_RLS_POST_FILTER_STARVATION: Consulta o índice `pgvector` HNSW bajo RLS multi-tenant sin `SET LOCAL hnsw.iterative_scan = 'relaxed_order'` (o `'strict_order'`). El post-filtrado RLS descarta candidatos de otros inquilinos y provoca colapso de recall (0 resultados) para tenants con menos vectores.")
                if not re.search('ENABLE\\s+ROW\\s+LEVEL\\s+SECURITY', v_src, re.IGNORECASE) or not re.search('FORCE\\s+ROW\\s+LEVEL\\s+SECURITY', v_src, re.IGNORECASE):
                    vec_v.append('UNPROTECTED_VECTOR_EMBEDDING_TABLE: Tabla de embeddings vectoriales sin `ENABLE ROW LEVEL SECURITY` y `FORCE ROW LEVEL SECURITY`.')
        if r_src.strip():
            if re.search('pg_create_logical_replication_slot|CREATE\\s+PUBLICATION|CREATE\\s+SUBSCRIPTION', r_src, re.IGNORECASE):
                if not re.search('max_slot_wal_keep_size', r_src, re.IGNORECASE):
                    slot_v.append('UNBOUNDED_REPLICATION_SLOT_WAL_RETENTION: Configuración de replicación lógica / CDC sin cota `max_slot_wal_keep_size`, exponiendo al clúster primario a agotamiento total de disco (`pg_wal` 100% full) si un consumidor se detiene.')
                if not re.search('idle_in_transaction_session_timeout', r_src, re.IGNORECASE):
                    slot_v.append('MISSING_IDLE_IN_TRANSACTION_TIMEOUT_GUARD: Ausencia de `idle_in_transaction_session_timeout` para liberar bloqueos de xmin que impiden a VACUUM limpiar tuplas muertas.')
            if re.search('ALTER\\s+TYPE\\s+[a-zA-Z0-9_.]+\\s+ADD\\s+VALUE', r_src, re.IGNORECASE) and (not re.search('IF\\s+NOT\\s+EXISTS', r_src, re.IGNORECASE)):
                hot_v.append('NON_IDEMPOTENT_ENUM_ADD_VALUE: `ALTER TYPE ... ADD VALUE` sin cláusula `IF NOT EXISTS` falla en reintentos de migración Zero-Downtime.')
            if re.search('UPDATE\\s+', r_src, re.IGNORECASE) and (not re.search('fillfactor\\s*=\\s*(?:7[0-9]|8[0-5]|90)', r_src, re.IGNORECASE)):
                hot_v.append('MISSING_HOT_UPDATE_FILLFACTOR_TUNING: Tabla de alta tasa de `UPDATE` sin `fillfactor` reducido (75-85) ni `autovacuum_vacuum_scale_factor` agresivo (<= 0.05), impidiendo actualizaciones Heap-Only Tuple (HOT).')
        patches = {'pgvector_hnsw_rls_iterative_scan_sql': "-- 1. Tabla Multi-Tenant de Embeddings con RLS Forzado (O(1) InitPlan):\nCREATE TABLE IF NOT EXISTS public.document_embeddings (\n    id uuid NOT NULL DEFAULT uuidv7(),\n    tenant_id uuid NOT NULL,\n    embedding vector(1536) NOT NULL,\n    PRIMARY KEY (tenant_id, id)\n);\nALTER TABLE public.document_embeddings ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.document_embeddings FORCE ROW LEVEL SECURITY;\nCREATE POLICY tenant_vector_isolation ON public.document_embeddings\n  AS RESTRICTIVE FOR ALL TO authenticated\n  USING (tenant_id = (SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid));\n\nCREATE INDEX CONCURRENTLY IF NOT EXISTS idx_doc_emb_hnsw\n  ON public.document_embeddings USING hnsw (embedding vector_cosine_ops)\n  WITH (m = 16, ef_construction = 64);\n\n-- 2. Consulta Vectorial con Iterative Scan para garantizar Recall 100% bajo RLS:\nSET LOCAL hnsw.iterative_scan = 'relaxed_order';\nSET LOCAL hnsw.ef_search = 80;\nSELECT id, embedding <=> $1 AS distance\n  FROM public.document_embeddings\n WHERE tenant_id = (SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid)\n ORDER BY embedding <=> $1 LIMIT 10;", 'replication_slot_and_hot_update_guard_sql': "-- Guardas de Retención WAL y Prevención de Bloat por xmin:\nALTER SYSTEM SET max_slot_wal_keep_size = '10GB';\nSET LOCAL idle_in_transaction_session_timeout = '15s';\n\n-- Evolución Idempotente de Enumeración:\nALTER TYPE public.ticket_status ADD VALUE IF NOT EXISTS 'SETTLED_VERIFIED';\n\n-- Preservación de Actualizaciones HOT (Heap-Only Tuple) en Tablas de Alto Caudal:\nALTER TABLE public.ledger_accounts SET (\n    fillfactor = 80,\n    autovacuum_vacuum_scale_factor = 0.02,\n    autovacuum_analyze_scale_factor = 0.01\n);"}
        proven_ok = len(vec_v) == 0 and len(slot_v) == 0 and (len(hot_v) == 0)
        dur = (time.perf_counter_ns() - t0) / 1000000.0
        return PgVectorHNSWRLSAndReplicationSlotBloatReport(proven_safe=proven_ok, pgvector_hnsw_rls_starvation_violations=vec_v, replication_slot_wal_bloat_violations=slot_v, unsafe_enum_and_hot_update_violations=hot_v, synthesized_remediation_patches=patches, analysis_duration_ms=round(dur, 3))


