# --- Merged from node03_v16_6: SubtransactionSLRUMultiXactAndZeroDowntimeNotNullProver ---
class SubtransactionSLRUMultiXactAndZeroDowntimeNotNullProver:

    @classmethod
    def audit_subtrans_multixact_and_set_not_null(cls, transaction_and_locking_sql: str='', ddl_not_null_migration_sql: str='') -> SubtransactionSLRUMultiXactAndZeroDowntimeNotNullReport:
        t0 = time.perf_counter_ns()
        sub_v: List[str] = []
        mx_v: List[str] = []
        nn_v: List[str] = []
        tx_src = re.sub('--[^\\n]*', '', transaction_and_locking_sql or '')
        ddl_src = re.sub('--[^\\n]*', '', ddl_not_null_migration_sql or '')
        if tx_src.strip():
            if re.search('\\bSAVEPOINT\\b', tx_src, re.IGNORECASE) or (re.search('\\bLOOP\\b|\\bFOR\\b', tx_src, re.IGNORECASE) and re.search('\\bEXCEPTION\\s+WHEN\\b', tx_src, re.IGNORECASE)):
                sub_v.append('SUBTRANSACTION_SLRU_OVERFLOW_RISK: Uso de `SAVEPOINT` o bloques `EXCEPTION WHEN` dentro de bucles. Al superar `PGPROC_MAX_CACHED_SUBXIDS` (64), dispara contención global en `SubtransSLRULock` y degrada réplicas. Reemplazar por `INSERT ... ON CONFLICT DO UPDATE / DO NOTHING` sin subtransacciones.')
            if re.search('FOR\\s+UPDATE(?!\\s+SKIP\\s+LOCKED)', tx_src, re.IGNORECASE) and (not re.search('FOR\\s+NO\\s+KEY\\s+UPDATE', tx_src, re.IGNORECASE)):
                mx_v.append('UNNECESSARY_FOR_UPDATE_KEY_LOCK_AMPLIFICATION: `SELECT ... FOR UPDATE` adquiere bloqueo exclusivo de clave que bloquea validaciones de Foreign Keys en tablas hijas. Usar `SELECT ... FOR NO KEY UPDATE` cuando no se mutan columnas PK/UNIQUE.')
            if re.search('FOR\\s+SHARE\\b', tx_src, re.IGNORECASE) and (not re.search('FOR\\s+KEY\\s+SHARE', tx_src, re.IGNORECASE)):
                mx_v.append('MULTIXACT_SLRU_EXHAUSTION_RISK: `SELECT ... FOR SHARE` concurrente genera MultiXact IDs masivos en `pg_multixact/members`. Preferir lecturas MVCC o `FOR KEY SHARE` / `FOR NO KEY UPDATE`.')
        if ddl_src.strip():
            if re.search('ALTER\\s+COLUMN\\s+[a-zA-Z0-9_]+\\s+SET\\s+NOT\\s+NULL', ddl_src, re.IGNORECASE):
                has_not_valid_chk = bool(re.search('ADD\\s+CONSTRAINT\\s+\\w+\\s+CHECK\\s*\\([^)]*IS\\s+NOT\\s+NULL\\s*\\)\\s+NOT\\s+VALID', ddl_src, re.IGNORECASE))
                has_validate_chk = bool(re.search('VALIDATE\\s+CONSTRAINT', ddl_src, re.IGNORECASE))
                if not (has_not_valid_chk and has_validate_chk):
                    nn_v.append('BLOCKING_FULL_SCAN_SET_NOT_NULL: `ALTER COLUMN ... SET NOT NULL` ejecutado sin validar previamente una restricción `CHECK (col IS NOT NULL) NOT VALID` + `VALIDATE CONSTRAINT`. Esto bloquea lecturas y escrituras con `ACCESS EXCLUSIVE` durante todo el escaneo.')
