# --- Merged from node03_v16_6: PG18ReturningOldNewNullsNotDistinctAndAIOProver ---
class PG18ReturningOldNewNullsNotDistinctAndAIOProver:

    @classmethod
    def audit_pg18_returning_nulls_and_aio(cls, mutation_and_unique_ddl_sql: str='', cluster_io_and_upgrade_config: str='') -> PG18ReturningOldNewNullsNotDistinctAndAIOReport:
        t0 = time.perf_counter_ns()
        ret_v: List[str] = []
        null_v: List[str] = []
        aio_v: List[str] = []
        m_src = re.sub('--[^\\n]*', '', mutation_and_unique_ddl_sql or '')
        c_src = re.sub('--[^\\n]*', '', cluster_io_and_upgrade_config or '')
        if m_src.strip():
            has_select_then_update = bool(re.search('SELECT\\s+[^;]+;\\s*UPDATE\\s+', m_src, re.IGNORECASE | re.DOTALL))
            has_returning_old_new = bool(re.search('RETURNING\\s+[^;]*\\bOLD\\.[a-zA-Z0-9_]+[^;]*\\bNEW\\.[a-zA-Z0-9_]+', m_src, re.IGNORECASE))
            if has_select_then_update or (re.search('\\bUPDATE\\b', m_src, re.IGNORECASE) and (not has_returning_old_new)):
                ret_v.append('TWO_ROUNDTRIP_OR_MISSING_PG18_RETURNING_OLD_NEW_DELTA: Mutación `UPDATE` sin captura atómica de delta `RETURNING OLD.col, NEW.col` (PostgreSQL 18). Ejecutar `SELECT` + `UPDATE` separados duplica los roundtrips de red y expone la auditoría de estado previo a condiciones de carrera TOCTOU.')
            if re.search('\\bUNIQUE\\s*\\(', m_src, re.IGNORECASE) and (not re.search('NULLS\\s+NOT\\s+DISTINCT', m_src, re.IGNORECASE)):
                null_v.append('NULLABLE_UNIQUE_BYPASS_WITHOUT_NULLS_NOT_DISTINCT: Restricción o índice `UNIQUE (...)` sin cláusula `NULLS NOT DISTINCT`. Cuando una columna integrante es `NULL`, PostgreSQL permite insertar infinitos duplicados para el mismo `tenant_id`.')
        if c_src.strip():
            if not re.search("io_method\\s*=\\s*'(?:io_uring|worker)'", c_src, re.IGNORECASE):
                aio_v.append("SYNCHRONOUS_IO_BOTTLENECK_IN_PG18: Configuración sin `io_method = 'io_uring'` (o `'worker'`) en PostgreSQL 18, desaprovechando la lectura asíncrona vectorizada (hasta 2-3x más throughput en lectura de buffers).")
            if re.search('pg_upgrade', c_src, re.IGNORECASE) and (not re.search('pg_checksums|data_checksums', c_src, re.IGNORECASE)):
                aio_v.append('UNVERIFIED_DATA_CHECKSUMS_BEFORE_PG18_UPGRADE: Ejecución de `pg_upgrade` hacia PostgreSQL 18 sin validar paridad de `data_checksums` (activo por defecto en PG18), lo que aborta la actualización del clúster.')
        patches = {'pg18_single_roundtrip_returning_old_new_and_unique_sql': "-- 1. Unicidad Multi-Tenant Estricta incluyendo NULLs (NULLS NOT DISTINCT):\nCREATE TABLE IF NOT EXISTS public.workspace_nodes (\n    id uuid NOT NULL DEFAULT uuidv7(),\n    tenant_id uuid NOT NULL,\n    parent_id uuid NULL,\n    slug text NOT NULL,\n    balance_cents bigint NOT NULL DEFAULT 0,\n    version_id integer NOT NULL DEFAULT 1,\n    PRIMARY KEY (tenant_id, id),\n    CONSTRAINT uq_tenant_parent_slug UNIQUE NULLS NOT DISTINCT (tenant_id, parent_id, slug)\n);\n\n-- 2. Mutación Atómica en 1 Roundtrip con Captura de Delta (PostgreSQL 18 RETURNING OLD/NEW):\nUPDATE public.workspace_nodes\n   SET balance_cents = balance_cents + $1,\n       version_id = version_id + 1\n WHERE id = $2\n   AND tenant_id = (SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid)\n   AND version_id = $3\n RETURNING id, OLD.balance_cents AS prev_balance_cents, NEW.balance_cents AS next_balance_cents, NEW.version_id;", 'pg18_async_io_and_checksum_guard_conf': "-- Configuración de E/S Asíncrona Nativa en PostgreSQL 18:\nALTER SYSTEM SET io_method = 'io_uring';\nALTER SYSTEM SET effective_io_concurrency = 256;\n-- Verificación previa a pg_upgrade hacia PostgreSQL 18:\n-- pg_checksums --enable -D $PGDATA (asegura paridad con data_checksums = on por defecto en PG18)"}
        proven_ok = len(ret_v) == 0 and len(null_v) == 0 and (len(aio_v) == 0)
        dur = (time.perf_counter_ns() - t0) / 1000000.0
        return PG18ReturningOldNewNullsNotDistinctAndAIOReport(proven_safe=proven_ok, two_roundtrip_select_before_update_violations=ret_v, nullable_unique_duplicate_bypass_violations=null_v, async_io_and_checksum_upgrade_violations=aio_v, synthesized_remediation_patches=patches, analysis_duration_ms=round(dur, 3))


