        return PG18SQLJSONTableWALCompressionAndPublicationFilterReport(proven_safe=proven_ok, untyped_jsonb_expansion_violations=js_v, unfiltered_publication_pii_exposure_violations=pub_v, uncompressed_wal_fpi_amplification_violations=wal_v, synthesized_remediation_patches=patches, analysis_duration_ms=round(dur, 3))


