# --- Merged from node03_v16_6: PG18PgStatStatementsTrackUtilityPostgrestDbPreRequestAndColumnTypeChangeProver ---
class PG18PgStatStatementsTrackUtilityPostgrestDbPreRequestAndColumnTypeChangeProver:

    def verify_postgrest_pre_request_alter_type_and_stat_statements(self, sql_source: str) -> PG18PostgrestPreRequestAlterTypeAndStatStatementsReport:
        violations: List[str] = []
        upper_sql = sql_source.upper()
        pre_request_functions_checked = 0
        pre_request_hardened = 0
        if re.search('db_pre_request|check_request|pre_request', sql_source, re.IGNORECASE):
            pre_request_functions_checked += 1
            has_safe_current_setting = bool(re.search('current_setting\\s*\\(\\s*[\\x27\\x22]request\\.(headers|jwt\\.claims|path)[\\x27\\x22]\\s*,\\s*true\\s*\\)', sql_source, re.IGNORECASE))
            has_raise_exception = bool(re.search('RAISE\\s+EXCEPTION.*USING\\s+ERRCODE', sql_source, re.IGNORECASE))
            if not has_safe_current_setting:
                violations.append("POSTGREST_PRE_REQUEST_UNSAFE_SETTING: La función db_pre_request debe leer 'current_setting('request.headers', true)' (o request.jwt.claims) con segundo parámetro 'true' (missing_ok) para evitar abortos no controlados.")
            if not has_raise_exception:
                violations.append("POSTGREST_PRE_REQUEST_MISSING_ERRCODE: La función db_pre_request debe rechazar peticiones inválidas mediante 'RAISE EXCEPTION ... USING ERRCODE = ...' para devolver códigos HTTP deterministas en PostgREST.")
            if has_safe_current_setting and has_raise_exception:
                pre_request_hardened += 1
        alter_type_matches = re.findall('ALTER\\s+TABLE\\s+(?:ONLY\\s+)?([a-zA-Z0-9_.]+)\\s+ALTER\\s+COLUMN\\s+([a-zA-Z0-9_]+)\\s+(?:SET\\s+DATA\\s+)?TYPE\\s+([a-zA-Z0-9_()\\s]+?)(?:USING|;|,|$)', sql_source, flags=re.IGNORECASE)
        unsafe_alter_column_type_detected = 0
        for tbl, col, new_type in alter_type_matches:
            clean_type = new_type.strip().upper()
            if clean_type != 'TEXT':
                unsafe_alter_column_type_detected += 1
                violations.append(f"ZERO_DOWNTIME_ALTER_COLUMN_TYPE_REWRITE: 'ALTER TABLE {tbl} ALTER COLUMN {col} TYPE {new_type.strip()}' adquiere AccessExclusiveLock y reescribe toda la tabla en vivo. Use Expand-Contract (ADD COLUMN + trigger dual-write).")
        safe_expand_type_migrations_verified = 0
        if re.search('ADD\\s+COLUMN', upper_sql) and re.search('CREATE\\s+(?:OR\\s+REPLACE\\s+)?TRIGGER\\s+[a-zA-Z0-9_]*type_sync', sql_source, re.IGNORECASE):
            safe_expand_type_migrations_verified += 1
        stat_statements_configs_checked = 0
        stat_statements_verified = 0
        if re.search('pg_stat_statements', sql_source, re.IGNORECASE):
            stat_statements_configs_checked += 1
            track_util_off = bool(re.search('pg_stat_statements\\.track_utility\\s*(?:=|TO)\\s*[\\x27\\x22]?(off|false)[\\x27\\x22]?', sql_source, re.IGNORECASE))
            max_match = re.search('pg_stat_statements\\.max\\s*(?:=|TO)\\s*[\\x27\\x22]?(\\d+)[\\x27\\x22]?', sql_source, re.IGNORECASE)
            low_max = bool(max_match and int(max_match.group(1)) < 5000)
            if track_util_off:
                violations.append("PG_STAT_STATEMENTS_TRACK_UTILITY_DISABLED: 'pg_stat_statements.track_utility' está desactivado; debe mantenerse en 'on' para auditar latencia de DDL, VACUUM, COPY y REFRESH MATERIALIZED VIEW.")
            if low_max:
                violations.append(f"PG_STAT_STATEMENTS_MAX_TOO_LOW: 'pg_stat_statements.max' ({max_match.group(1)}) es menor a 5000, causando deallocaciones frecuentes y pérdida de telemetría en esquemas multi-tenant.")
            if not track_util_off and (not low_max):
                stat_statements_verified += 1
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_postgrest_pre_request_expand_type_and_stat_statements_ddl()
        summary = f'PG18 PostgREST db_pre_request + Expand-Contract Type + pg_stat_statements Audit: valid={is_valid}, pre_request={pre_request_hardened}/{pre_request_functions_checked}, unsafe_alter_type={unsafe_alter_column_type_detected}, expand_type_sync={safe_expand_type_migrations_verified}, stat_statements={stat_statements_verified}/{stat_statements_configs_checked}.'
        return PG18PostgrestPreRequestAlterTypeAndStatStatementsReport(is_valid=is_valid, pre_request_functions_checked=pre_request_functions_checked, pre_request_hardened=pre_request_hardened, unsafe_alter_column_type_detected=unsafe_alter_column_type_detected, safe_expand_type_migrations_verified=safe_expand_type_migrations_verified, stat_statements_configs_checked=stat_statements_configs_checked, stat_statements_verified=stat_statements_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_postgrest_pre_request_expand_type_and_stat_statements_ddl(target_table: str='public.tenant_invoices') -> str:
        return f"-- 1. Compuerta Perimetral PostgREST pgrst.db_pre_request endurecida\nCREATE OR REPLACE FUNCTION public.check_request()\nRETURNS void LANGUAGE plpgsql SECURITY INVOKER AS $$\nDECLARE\n    v_headers jsonb;\n    v_tenant_header text;\nBEGIN\n    v_headers := coalesce(current_setting('request.headers', true), '{{}}')::jsonb;\n    v_tenant_header := v_headers->>'x-tenant-id';\n    IF v_tenant_header IS NOT NULL AND v_tenant_header = 'revoked-tenant' THEN\n        RAISE EXCEPTION 'Tenant access suspended' USING ERRCODE = '42501';\n    END IF;\nEND;\n$$;\nALTER ROLE authenticator SET pgrst.db_pre_request = 'public.check_request';\n\n-- 2. Migración Expand-Contract para cambio de tipo sin AccessExclusiveLock rewrite\nALTER TABLE {target_table} ADD COLUMN IF NOT EXISTS amount_cents_v2 bigint;\nCREATE OR REPLACE FUNCTION public.fn_type_sync_amount_cents()\nRETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n    IF NEW.amount_cents_v2 IS NULL AND NEW.amount_legacy_text IS NOT NULL THEN\n        NEW.amount_cents_v2 := NEW.amount_legacy_text::bigint;\n    END IF;\n    RETURN NEW;\nEND;\n$$;\nCREATE TRIGGER trg_type_sync_amount_cents\n    BEFORE INSERT OR UPDATE ON {target_table}\n    FOR EACH ROW EXECUTE FUNCTION public.fn_type_sync_amount_cents();\n\n-- 3. Gobernanza de telemetría pg_stat_statements en PostgreSQL 18\nALTER SYSTEM SET pg_stat_statements.track_utility = 'on';\nALTER SYSTEM SET pg_stat_statements.max = 10000;"


