# --- Merged from node03_v16_6: PG18RealtimeBroadcastAuthorizationGinFastUpdateAndZeroDowntimeTableSplitProver ---
class PG18RealtimeBroadcastAuthorizationGinFastUpdateAndZeroDowntimeTableSplitProver:

    def verify_realtime_broadcast_gin_fastupdate_and_table_split(self, sql_source: str) -> PG18RealtimeBroadcastRlsGinFastUpdateAndTableSplitReport:
        violations: List[str] = []
        upper_sql = sql_source.upper()
        realtime_policies_checked = 0
        realtime_private_rls_verified = 0
        if re.search('realtime\\.messages|channel\\s*\\(', sql_source, re.IGNORECASE):
            realtime_policies_checked += 1
            has_private_false = bool(re.search('private\\s*:\\s*false', sql_source, re.IGNORECASE))
            has_realtime_messages_policy = bool(re.search('ON\\s+realtime\\.messages', sql_source, re.IGNORECASE))
            has_topic_check = bool(re.search('realtime\\.topic\\s*\\(\\s*\\)', sql_source, re.IGNORECASE))
            has_authenticated_role = bool(re.search('ON\\s+realtime\\.messages[\\s\\S]*?TO\\s+authenticated', sql_source, re.IGNORECASE))
            if has_private_false:
                violations.append("REALTIME_CHANNEL_PUBLIC_EXPOSURE: Se detectó 'private: false' en configuración de canal Realtime; los canales multi-tenant de Broadcast/Presence deben exigir 'private: true'.")
            if not has_realtime_messages_policy or not has_topic_check or (not has_authenticated_role):
                violations.append("REALTIME_MESSAGES_MISSING_TOPIC_RLS: Las políticas sobre 'realtime.messages' deben dirigirse 'TO authenticated' y validar 'realtime.topic()' frente al tenant del usuario autenticado.")
            if not has_private_false and has_realtime_messages_policy and has_topic_check and has_authenticated_role:
                realtime_private_rls_verified += 1
        gin_matches = re.findall('CREATE\\s+INDEX(?:\\s+CONCURRENTLY)?\\s+(?:IF\\s+NOT\\s+EXISTS\\s+)?([a-zA-Z0-9_]+)\\s+ON\\s+[a-zA-Z0-9_.]+\\s+USING\\s+GIN\\s*\\([^;]+;', sql_source, flags=re.IGNORECASE)
        gin_indexes_checked = len(gin_matches)
        gin_fastupdate_tuned = 0
        for idx_name in gin_matches:
            idx_stmt_match = re.search(f'CREATE\\s+INDEX(?:\\s+CONCURRENTLY)?\\s+(?:IF\\s+NOT\\s+EXISTS\\s+)?{re.escape(idx_name)}\\s+ON\\s+[^;]+;', sql_source, flags=re.IGNORECASE)
            stmt_str = idx_stmt_match.group(0) if idx_stmt_match else ''
            if re.search('WITH\\s*\\([^)]*(?:fastupdate\\s*=\\s*off|gin_pending_list_limit\\s*=\\s*\\d+)', stmt_str, re.IGNORECASE):
                gin_fastupdate_tuned += 1
            else:
                violations.append(f"GIN_INDEX_UNTUNED_PENDING_LIST: El índice GIN '{idx_name}' no especifica 'WITH (fastupdate = off)' ni 'gin_pending_list_limit', exponiendo escrituras concurrentes a pausas síncronas de vaciado de lista pendiente.")
        unsafe_table_split_drops_detected = 0
        if re.search('CREATE\\s+TABLE', upper_sql) and re.search('ALTER\\s+TABLE\\s+[a-zA-Z0-9_.]+\\s+DROP\\s+COLUMN', upper_sql):
            unsafe_table_split_drops_detected += 1
            violations.append("ZERO_DOWNTIME_TABLE_SPLIT_PREMATURE_DROP: Se detectó 'DROP COLUMN' en el mismo script de creación de tabla secundaria. Durante una partición vertical (Table Split) debe mantenerse la columna original sincronizada mediante trigger dual-write hasta completar el despliegue gradual.")
        safe_table_split_sync_verified = 0
        if re.search('CREATE\\s+(?:OR\\s+REPLACE\\s+)?TRIGGER\\s+[a-zA-Z0-9_]*split_sync', sql_source, re.IGNORECASE):
            safe_table_split_sync_verified += 1
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_realtime_broadcast_gin_fastupdate_and_table_split_ddl()
        summary = f'PG18 Realtime Broadcast RLS + GIN fastupdate + Table Split Audit: valid={is_valid}, realtime_rls={realtime_private_rls_verified}/{realtime_policies_checked}, gin_tuned={gin_fastupdate_tuned}/{gin_indexes_checked}, unsafe_split_drops={unsafe_table_split_drops_detected}, safe_split_sync={safe_table_split_sync_verified}.'
        return PG18RealtimeBroadcastRlsGinFastUpdateAndTableSplitReport(is_valid=is_valid, realtime_policies_checked=realtime_policies_checked, realtime_private_rls_verified=realtime_private_rls_verified, gin_indexes_checked=gin_indexes_checked, gin_fastupdate_tuned=gin_fastupdate_tuned, unsafe_table_split_drops_detected=unsafe_table_split_drops_detected, safe_table_split_sync_verified=safe_table_split_sync_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_realtime_broadcast_gin_fastupdate_and_table_split_ddl(primary_table: str='public.tenant_orders', Archive_table: str='public.tenant_order_payloads') -> str:
        return f"-- 1. Autorización RLS Zero-Trust en Canales Privados de Supabase Realtime (realtime.messages)\nCREATE POLICY realtime_tenant_broadcast_select ON realtime.messages\n    FOR SELECT TO authenticated\n    USING (\n        realtime.messages.extension IN ('broadcast', 'presence')\n        AND realtime.topic() = 'tenant:' || (SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id'))\n    );\n\nCREATE POLICY realtime_tenant_broadcast_insert ON realtime.messages\n    FOR INSERT TO authenticated\n    WITH CHECK (\n        realtime.messages.extension IN ('broadcast', 'presence')\n        AND realtime.topic() = 'tenant:' || (SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id'))\n    );\n\n-- 2. Índice GIN con fastupdate = off / gin_pending_list_limit acotado contra picos P99\nCREATE INDEX CONCURRENTLY IF NOT EXISTS idx_tenant_order_payloads_gin\n    ON {Archive_table} USING gin (raw_payload jsonb_path_ops)\n    WITH (fastupdate = off);\n\n-- 3. Partición Vertical (Table Split) Zero-Downtime con Trigger Dual-Write (sin DROP COLUMN prematuro)\nCREATE TABLE IF NOT EXISTS {Archive_table} (\n    tenant_id uuid NOT NULL,\n    order_id uuid NOT NULL,\n    raw_payload jsonb NOT NULL DEFAULT '{{}}'::jsonb,\n    PRIMARY KEY (tenant_id, order_id)\n);\nCREATE OR REPLACE FUNCTION public.fn_table_split_sync_order_payload() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n    IF NEW.raw_payload IS NOT NULL THEN\n        INSERT INTO {Archive_table} (tenant_id, order_id, raw_payload)\n        VALUES (NEW.tenant_id, NEW.order_id, NEW.raw_payload)\n        ON CONFLICT (tenant_id, order_id) DO UPDATE SET raw_payload = EXCLUDED.raw_payload;\n    END IF;\n    RETURN NEW;\nEND;\n$$;\nCREATE TRIGGER trg_table_split_sync_order_payload\n    AFTER INSERT OR UPDATE ON {primary_table}\n    FOR EACH ROW EXECUTE FUNCTION public.fn_table_split_sync_order_payload();"


