# --- Merged from node03_v16_6: PG18LogicalReplicationFailoverSlotsPgpartmanRetentionAndRlsCheckOptionViewProver ---
class PG18LogicalReplicationFailoverSlotsPgpartmanRetentionAndRlsCheckOptionViewProver:

    def verify_failover_slots_pg_partman_and_view_check_option(self, sql_source: str) -> PG18FailoverSlotsPgPartmanAndViewCheckOptionReport:
        violations: List[str] = []
        replication_slots_checked = 0
        failover_slots_verified = 0
        if re.search('pg_create_logical_replication_slot|CREATE_REPLICATION_SLOT|sync_replication_slots', sql_source, re.IGNORECASE):
            replication_slots_checked += 1
            has_failover_true = bool(re.search('pg_create_logical_replication_slot\\s*\\([^)]*,\\s*[^)]*,\\s*(?:false|true)\\s*,\\s*(?:true|false)\\s*,\\s*true\\s*\\)|failover\\s*(?:=>|:=|=)\\s*true', sql_source, re.IGNORECASE))
            has_sync_standby_slots = bool(re.search("synchronized_standby_slots\\s*(?:=|TO)\\s*'[a-zA-Z0-9_,]+'", sql_source, re.IGNORECASE))
            if not has_failover_true:
                violations.append("LOGICAL_SLOT_FAILOVER_DISABLED: 'pg_create_logical_replication_slot' no habilita 'failover => true', dejando huérfanos a los consumidores CDC/Realtime tras una conmutación por error (HA failover).")
            if not has_sync_standby_slots:
                violations.append("MISSING_SYNCHRONIZED_STANDBY_SLOTS: Falta configurar 'synchronized_standby_slots' para garantizar que los slots lógicos no adelanten a las réplicas físicas de respaldo antes del failover.")
            if has_failover_true and has_sync_standby_slots:
                failover_slots_verified += 1
        partman_configs_checked = 0
        partman_premake_verified = 0
        if re.search('partman\\.create_parent', sql_source, re.IGNORECASE):
            partman_configs_checked += 1
            premake_match = re.search('p_premake\\s*(?:=>|:=|=)\\s*(\\d+)', sql_source, re.IGNORECASE)
            premake_val = int(premake_match.group(1)) if premake_match else 0
            has_maintenance = bool(re.search('partman\\.run_maintenance(?:_proc)?\\s*\\(', sql_source, re.IGNORECASE))
            if premake_val < 4:
                violations.append(f"PG_PARTMAN_LOW_PREMAKE: 'partman.create_parent' define p_premake={premake_val} (< 4), arriesgando inserciones en la partición DEFAULT que bloquean futuros ATTACH PARTITION.")
            if not has_maintenance:
                violations.append("PG_PARTMAN_MISSING_MAINTENANCE_SCHEDULE: Falta programar 'CALL partman.run_maintenance_proc()' para pre-crear particiones futuras y desapegar particiones vencidas sin downtime.")
            if premake_val >= 4 and has_maintenance:
                partman_premake_verified += 1
        view_matches = re.findall('CREATE\\s+(?:OR\\s+REPLACE\\s+)?VIEW\\s+([a-zA-Z0-9_.]+)[\\s\\S]*?;', sql_source, flags=re.IGNORECASE)
        views_checked = len(view_matches)
        views_cascaded_check_verified = 0
        for v_name in view_matches:
            v_stmt_match = re.search(f'CREATE\\s+(?:OR\\s+REPLACE\\s+)?VIEW\\s+{re.escape(v_name)}[\\s\\S]*?;', sql_source, flags=re.IGNORECASE)
            v_stmt = v_stmt_match.group(0) if v_stmt_match else ''
            has_sec_invoker = bool(re.search('security_invoker\\s*=\\s*(?:true|on|1)', v_stmt, re.IGNORECASE))
            has_cascaded_check = bool(re.search('WITH\\s+CASCADED\\s+CHECK\\s+OPTION', v_stmt, re.IGNORECASE))
            if not has_sec_invoker:
                violations.append(f"VIEW_MISSING_SECURITY_INVOKER: La vista '{v_name}' no declara 'WITH (security_invoker = true)', ejecutando consultas con los permisos del propietario de la vista en lugar del rol invocador.")
            if not has_cascaded_check:
                violations.append(f"VIEW_MISSING_CASCADED_CHECK_OPTION: La vista '{v_name}' omite 'WITH CASCADED CHECK OPTION', permitiendo que INSERT/UPDATE a través de la vista produzcan filas fuera del predicado visible.")
            if has_sec_invoker and has_cascaded_check:
                views_cascaded_check_verified += 1
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_failover_slots_partman_and_cascaded_view_ddl()
        summary = f'PG18 Failover Slots + pg_partman + View CASCADED CHECK Audit: valid={is_valid}, failover_slots={failover_slots_verified}/{replication_slots_checked}, partman={partman_premake_verified}/{partman_configs_checked}, views={views_cascaded_check_verified}/{views_checked}.'
        return PG18FailoverSlotsPgPartmanAndViewCheckOptionReport(is_valid=is_valid, replication_slots_checked=replication_slots_checked, failover_slots_verified=failover_slots_verified, partman_configs_checked=partman_configs_checked, partman_premake_verified=partman_premake_verified, views_checked=views_checked, views_cascaded_check_verified=views_cascaded_check_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_failover_slots_partman_and_cascaded_view_ddl(target_table: str='public.tenant_audit_events', view_name: str='public.v_active_tenant_audit_events') -> str:
        return f"-- 1. Continuidad CDC en Alta Disponibilidad con Failover Logical Replication Slots (PG18)\nALTER SYSTEM SET synchronized_standby_slots = 'standby_node_1,standby_node_2';\nALTER SYSTEM SET sync_replication_slots = 'on';\nSELECT pg_create_logical_replication_slot(\n    slot_name => 'aleph_tenant_cdc_slot',\n    plugin => 'pgoutput',\n    temporary => false,\n    twophase => true,\n    failover => true\n);\n\n-- 2. Pre-creación y mantenimiento automático de particiones Zero-Downtime con pg_partman\nSELECT partman.create_parent(\n    p_parent_table => '{target_table}',\n    p_control => 'created_at',\n    p_interval => '1 day',\n    p_premake => 7\n);\nSELECT cron.schedule_in_database(\n    'aleph-partman-maintenance-hourly',\n    '15 * * * *',\n    $$CALL partman.run_maintenance_proc()$$,\n    'postgres',\n    'partman_maintainer_role'\n);\n\n-- 3. Vista actualizable Zero-Trust con security_invoker = true y WITH CASCADED CHECK OPTION\nCREATE OR REPLACE VIEW {view_name}\nWITH (security_invoker = true, security_barrier = true) AS\n    SELECT id, tenant_id, event_type, payload, created_at\n    FROM {target_table}\n    WHERE tenant_id = (SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid)\nWITH CASCADED CHECK OPTION;"


