# --- Merged from node03_v16_6: PG18SupavisorPreparedStatementDeallocateHotUpdateFillfactorAndExclusionGistProver ---
class PG18SupavisorPreparedStatementDeallocateHotUpdateFillfactorAndExclusionGistProver:

    def verify_supavisor_hot_fillfactor_and_exclusion_gist(self, sql_source: str) -> PG18SupavisorHotFillfactorAndExclusionGistReport:
        violations: List[str] = []
        upper_sql = sql_source.upper()
        supavisor_configs_checked = 0
        supavisor_safe_verified = 0
        if re.search('PREPARE\\s+[a-zA-Z0-9_]+\\s+AS|6543|supavisor|DEALLOCATE\\s+ALL', sql_source, re.IGNORECASE):
            supavisor_configs_checked += 1
            has_raw_prepare = bool(re.search('\\bPREPARE\\s+[a-zA-Z0-9_]+\\s+AS\\b', sql_source, re.IGNORECASE))
            has_deallocate = bool(re.search('\\bDEALLOCATE\\s+(?:ALL|[a-zA-Z0-9_]+)\\b', sql_source, re.IGNORECASE))
            has_session_set_without_local = bool(re.search('\\bSET\\s+(?!LOCAL\\b|SESSION\\s+CHARACTERISTICS\\b|TIME\\s+ZONE\\b|search_path\\b)[a-zA-Z0-9_.]+\\s*=', sql_source, re.IGNORECASE))
            if has_raw_prepare and (not has_deallocate):
                violations.append("SUPAVISOR_NAMED_PREPARE_LEAK: Se detectó 'PREPARE ... AS' sin 'DEALLOCATE ALL' en modo transacción (Supavisor puerto 6543), causando errores 'prepared statement already exists' entre clientes.")
            if has_session_set_without_local:
                violations.append("SUPAVISOR_SESSION_STATE_BLEED: Se detectó 'SET param = ...' sin 'LOCAL' sobre pool transaccional; use siempre 'SET LOCAL' dentro de 'BEGIN ... COMMIT' para no contaminar conexiones recicladas.")
            if (not has_raw_prepare or has_deallocate) and (not has_session_set_without_local):
                supavisor_safe_verified += 1
        hot_update_tables_checked = 0
        hot_fillfactor_verified = 0
        table_defs = re.findall('CREATE\\s+TABLE(?:\\s+IF\\s+NOT\\s+EXISTS)?\\s+([a-zA-Z0-9_.]+)\\s*\\([\\s\\S]*?\\)\\s*(?:WITH\\s*\\([^)]+\\))?;', sql_source, flags=re.IGNORECASE)
        for tbl_name in table_defs:
            tbl_match = re.search(f'CREATE\\s+TABLE(?:\\s+IF\\s+NOT\\s+EXISTS)?\\s+{re.escape(tbl_name)}\\s*\\([\\s\\S]*?\\)\\s*(?:WITH\\s*\\([^)]+\\))?;', sql_source, flags=re.IGNORECASE)
            tbl_stmt = tbl_match.group(0) if tbl_match else ''
            if re.search('\\b(retry_count|status|heartbeat_at|updated_at|balance_cents)\\b', tbl_stmt, re.IGNORECASE):
                hot_update_tables_checked += 1
                ff_match = re.search('fillfactor\\s*=\\s*(\\d+)', tbl_stmt, re.IGNORECASE)
                ff_val = int(ff_match.group(1)) if ff_match else 100
                if 70 <= ff_val <= 90:
                    hot_fillfactor_verified += 1
                else:
                    violations.append(f"HOT_UPDATE_MISSING_FILLFACTOR: La tabla de alta mutación '{tbl_name}' tiene fillfactor={ff_val} (debe estar entre 70 y 90, ej. WITH (fillfactor = 80)) para habilitar actualizaciones Heap-Only Tuple (HOT) en la misma página.")
        exclusion_matches = re.findall('EXCLUDE\\s+USING\\s+gist\\s*\\(([^;]+)\\)', sql_source, flags=re.IGNORECASE)
        exclusion_constraints_checked = len(exclusion_matches)
        tenant_scoped_gist_verified = 0
        has_btree_gist_ext = bool(re.search('CREATE\\s+EXTENSION(?:\\s+IF\\s+NOT\\s+EXISTS)?\\s+btree_gist', sql_source, re.IGNORECASE))
        for excl_body in exclusion_matches:
            has_tenant_eq = bool(re.search('tenant_id\\s+WITH\\s*=', excl_body, re.IGNORECASE))
            if not has_btree_gist_ext:
                violations.append("EXCLUSION_GIST_MISSING_BTREE_GIST_EXT: 'EXCLUDE USING gist' requiere 'CREATE EXTENSION IF NOT EXISTS btree_gist;' para combinar operadores de igualdad escalar (uuid/int8) con intersección de rangos (&&).")
            if not has_tenant_eq:
                violations.append("EXCLUSION_GIST_MISSING_TENANT_SCOPE: La restricción 'EXCLUDE USING gist' omite 'tenant_id WITH =', provocando bloqueos y colisiones de reservas entre distintos tenants.")
            if has_btree_gist_ext and has_tenant_eq:
                tenant_scoped_gist_verified += 1
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_supavisor_hot_fillfactor_and_exclusion_gist_ddl()
        summary = f'PG18 Supavisor + HOT Fillfactor + Exclusion GiST Audit: valid={is_valid}, supavisor={supavisor_safe_verified}/{supavisor_configs_checked}, hot_fillfactor={hot_fillfactor_verified}/{hot_update_tables_checked}, exclusion_gist={tenant_scoped_gist_verified}/{exclusion_constraints_checked}.'
        return PG18SupavisorHotFillfactorAndExclusionGistReport(is_valid=is_valid, supavisor_configs_checked=supavisor_configs_checked, supavisor_safe_verified=supavisor_safe_verified, hot_update_tables_checked=hot_update_tables_checked, hot_fillfactor_verified=hot_fillfactor_verified, exclusion_constraints_checked=exclusion_constraints_checked, tenant_scoped_gist_verified=tenant_scoped_gist_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_supavisor_hot_fillfactor_and_exclusion_gist_ddl(target_table: str='public.tenant_resource_bookings') -> str:
        return f"-- 1. Extensión btree_gist para operadores combinados de igualdad escalar + rango GiST\nCREATE EXTENSION IF NOT EXISTS btree_gist;\n\n-- 2. Tabla de alta frecuencia de actualización con fillfactor = 80 (HOT Updates) y EXCLUDE USING gist por tenant\nCREATE TABLE IF NOT EXISTS {target_table} (\n    booking_id uuid NOT NULL DEFAULT gen_random_uuid(),\n    tenant_id uuid NOT NULL,\n    resource_id uuid NOT NULL,\n    status text NOT NULL DEFAULT 'CONFIRMED',\n    retry_count integer NOT NULL DEFAULT 0,\n    updated_at timestamptz NOT NULL DEFAULT now(),\n    booking_slot tstzrange NOT NULL,\n    PRIMARY KEY (tenant_id, booking_id),\n    CONSTRAINT excl_tenant_resource_slot_no_overlap\n        EXCLUDE USING gist (tenant_id WITH =, resource_id WITH =, booking_slot WITH &&)\n) WITH (fillfactor = 80);\n\n-- 3. Transacción compatible con Supavisor (Puerto 6543 Modo Transacción) usando SET LOCAL y DEALLOCATE ALL\nBEGIN;\nSET LOCAL statement_timeout = '3000ms';\nDEALLOCATE ALL;\nCOMMIT;"


