# --- Merged from node03_v16_6: PG18PgAuditRoleLoggingSupabaseVaultTdeKeyRotationAndZeroDowntimeTableRenameProver ---
class PG18PgAuditRoleLoggingSupabaseVaultTdeKeyRotationAndZeroDowntimeTableRenameProver:

    def verify_pgaudit_vault_rotation_and_table_rename(self, sql_source: str) -> PG18PgAuditVaultRotationAndTableRenameReport:
        violations: List[str] = []
        pgaudit_configs_checked = 0
        pgaudit_hardened_verified = 0
        if re.search('pgaudit\\.', sql_source, re.IGNORECASE):
            pgaudit_configs_checked += 1
            has_ddl_role = bool(re.search("pgaudit\\.log\\s*(?:=|TO)\\s*'[^']*ddl[^']*role[^']*'", sql_source, re.IGNORECASE))
            has_unsafe_param_on = bool(re.search("pgaudit\\.log_parameter\\s*(?:=|TO)\\s*'(?:on|true|1)'", sql_source, re.IGNORECASE))
            if not has_ddl_role:
                violations.append("PGAUDIT_MISSING_DDL_ROLE_LOGGING: 'pgaudit.log' debe incluir al menos 'ddl, role' para garantizar trazabilidad forense de cambios de esquema y privilegios.")
            if has_unsafe_param_on:
                violations.append("PGAUDIT_LOG_PARAMETER_PII_LEAK: 'pgaudit.log_parameter = on' global vuelca parámetros bind (incluyendo tokens, contraseñas y PII) en texto plano a los logs del motor. Manténgalo en 'off'.")
            if has_ddl_role and (not has_unsafe_param_on):
                pgaudit_hardened_verified += 1
        vault_operations_checked = 0
        vault_rotation_verified = 0
        if re.search('vault\\.(?:secrets|decrypted_secrets|create_secret|update_secret)', sql_source, re.IGNORECASE):
            vault_operations_checked += 1
            has_raw_vault_insert = bool(re.search('INSERT\\s+INTO\\s+vault\\.secrets', sql_source, re.IGNORECASE))
            has_revoke_decrypted = bool(re.search('REVOKE\\s+ALL\\s+ON\\s+(?:TABLE\\s+)?vault\\.decrypted_secrets\\s+FROM\\s+[^;]*authenticated', sql_source, re.IGNORECASE))
            if has_raw_vault_insert:
                violations.append("VAULT_RAW_INSERT_BYPASS: Prohibido ejecutar 'INSERT INTO vault.secrets' directamente; use 'vault.create_secret()' y 'vault.update_secret()' para garantizar cifrado AEAD pgsodium.")
            if not has_revoke_decrypted:
                violations.append("VAULT_DECRYPTED_SECRETS_EXPOSED: Falta 'REVOKE ALL ON TABLE vault.decrypted_secrets FROM public, anon, authenticated' para impedir lectura de secretos desde clientes PostgREST.")
            if not has_raw_vault_insert and has_revoke_decrypted:
                vault_rotation_verified += 1
        rename_table_matches = re.findall('ALTER\\s+TABLE\\s+(?:IF\\s+EXISTS\\s+)?([a-zA-Z0-9_.]+)\\s+RENAME\\s+TO\\s+([a-zA-Z0-9_]+)', sql_source, flags=re.IGNORECASE)
        unsafe_table_renames_detected = 0
        atomic_view_table_renames_verified = 0
        for old_tbl, new_tbl in rename_table_matches:
            old_short = old_tbl.split('.')[-1]
            has_compat_view = bool(re.search(f'CREATE\\s+(?:OR\\s+REPLACE\\s+)?VIEW\\s+(?:[a-zA-Z0-9_]+\\.)?{re.escape(old_short)}\\b[\\s\\S]*?FROM\\s+(?:[a-zA-Z0-9_]+\\.)?{re.escape(new_tbl)}\\b', sql_source, re.IGNORECASE))
            if has_compat_view:
                atomic_view_table_renames_verified += 1
            else:
                unsafe_table_renames_detected += 1
                violations.append(f"ZERO_DOWNTIME_TABLE_RENAME_MISSING_VIEW: 'ALTER TABLE {old_tbl} RENAME TO {new_tbl}' sin crear atómica e inmediatamente la vista de compatibilidad 'CREATE VIEW {old_tbl} WITH (security_invoker = true) AS SELECT * FROM {new_tbl}' rompe los endpoints PostgREST y servicios en ejecución.")
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_pgaudit_vault_rotation_and_table_rename_ddl()
        summary = f'PG18 pgaudit + Vault Rotation + Zero-Downtime Table Rename Audit: valid={is_valid}, pgaudit={pgaudit_hardened_verified}/{pgaudit_configs_checked}, vault={vault_rotation_verified}/{vault_operations_checked}, table_renames_safe={atomic_view_table_renames_verified}, unsafe_table_renames={unsafe_table_renames_detected}.'
        return PG18PgAuditVaultRotationAndTableRenameReport(is_valid=is_valid, pgaudit_configs_checked=pgaudit_configs_checked, pgaudit_hardened_verified=pgaudit_hardened_verified, vault_operations_checked=vault_operations_checked, vault_rotation_verified=vault_rotation_verified, unsafe_table_renames_detected=unsafe_table_renames_detected, atomic_view_table_renames_verified=atomic_view_table_renames_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_pgaudit_vault_rotation_and_table_rename_ddl(old_table: str='public.tenant_subscriptions_legacy', new_table: str='tenant_subscriptions_v2') -> str:
        return f"-- 1. Gobernanza pgaudit con registro de DDL/Role y redacción de parámetros sensibles\nALTER SYSTEM SET pgaudit.log = 'ddl, role';\nALTER SYSTEM SET pgaudit.log_parameter = 'off';\n\n-- 2. Confinamiento y rotación criptográfica sin downtime en Supabase Vault\nREVOKE ALL ON TABLE vault.decrypted_secrets FROM public, anon, authenticated;\nSELECT vault.create_secret('sk_live_initial_rotated_token', 'stripe_tenant_webhook_key', 'Tenant webhook signing secret');\n\n-- 3. Renombrado de tabla Zero-Downtime con Vista de Compatibilidad Atómica\nBEGIN;\nSET LOCAL lock_timeout = '2000ms';\nALTER TABLE {old_table} RENAME TO {new_table};\nCREATE OR REPLACE VIEW {old_table} WITH (security_invoker = true) AS\n    SELECT * FROM public.{new_table};\nCOMMIT;"


