# --- Merged from node03_v16_6: PG18PgmqVisibilityTimeoutDlqSupabaseSsoDomainVerificationAndZeroDowntimePrimaryKeySwapProver ---
class PG18PgmqVisibilityTimeoutDlqSupabaseSsoDomainVerificationAndZeroDowntimePrimaryKeySwapProver:

    def verify_pgmq_vt_mfa_aal2_and_pk_using_index(self, sql_source: str) -> PG18PgmqVtDlqMfaAmrAndPrimaryKeySwapReport:
        violations: List[str] = []
        pgmq_consumers_checked = 0
        pgmq_vt_and_dlq_verified = 0
        if re.search('pgmq\\.(?:read|send|archive|delete)', sql_source, re.IGNORECASE):
            pgmq_consumers_checked += 1
            has_zero_vt = bool(re.search('pgmq\\.read\\s*\\([^)]*(?:vt\\s*(?:=>|:=|=)\\s*0\\b|,\\s*0\\s*,)', sql_source, re.IGNORECASE))
            has_dlq_archive = bool(re.search('pgmq\\.archive\\s*\\(', sql_source, re.IGNORECASE) and re.search('\\bread_ct\\b', sql_source, re.IGNORECASE))
            if has_zero_vt:
                violations.append("PGMQ_ZERO_VISIBILITY_TIMEOUT_RACE: 'pgmq.read' con vt=0 hace que el mensaje siga visible para otros workers en paralelo, provocando ejecución duplicada. Use vt >= 30.")
            if not has_dlq_archive:
                violations.append("PGMQ_MISSING_POISON_PILL_DLQ_ARCHIVE: El consumidor pgmq no evalúa 'read_ct' ni invoca 'pgmq.archive()' para aislar mensajes fallidos recurrentes (poison pills).")
            if not has_zero_vt and has_dlq_archive:
                pgmq_vt_and_dlq_verified += 1
        mfa_aal2_policies_checked = 0
        mfa_aal2_verified = 0
        if re.search("mfa|aal2|auth\\.jwt\\(\\)\\s*->>\\s*'aal'|split_part[\\s\\S]*?email", sql_source, re.IGNORECASE):
            mfa_aal2_policies_checked += 1
            has_restrictive_aal2 = bool(re.search("AS\\s+RESTRICTIVE[\\s\\S]*?auth\\.jwt\\(\\)\\s*->>\\s*'aal'\\s*\\)\\s*=\\s*'aal2'", sql_source, re.IGNORECASE))
            has_unverified_email_domain = bool(re.search("split_part\\s*\\(\\s*auth\\.jwt\\(\\)\\s*->>\\s*'email'", sql_source, re.IGNORECASE) and (not has_restrictive_aal2))
            if has_unverified_email_domain:
                violations.append("RLS_UNVERIFIED_EMAIL_DOMAIN_SPOOF: Filtrar acceso multi-tenant solo por 'split_part(auth.jwt()->>\\'email\\', \\'@\\', 2)' sin política AS RESTRICTIVE AAL2 permite escalada si un proveedor OAuth externo no verifica propiedad del dominio.")
            if not has_restrictive_aal2:
                violations.append("RLS_MISSING_RESTRICTIVE_MFA_AAL2: Falta política 'AS RESTRICTIVE ... USING ((SELECT auth.jwt()->>\\'aal\\') = \\'aal2\\')' para proteger operaciones sensibles con MFA verificado.")
            if has_restrictive_aal2 and (not has_unverified_email_domain):
                mfa_aal2_verified += 1
        direct_pk_matches = re.findall('ALTER\\s+TABLE\\s+(?:ONLY\\s+)?([a-zA-Z0-9_.]+)\\s+ADD\\s+(?:CONSTRAINT\\s+[a-zA-Z0-9_]+\\s+)?PRIMARY\\s+KEY\\s*\\(([^)]+)\\)', sql_source, flags=re.IGNORECASE)
        unsafe_pk_builds_detected = len(direct_pk_matches)
        for tbl, cols in direct_pk_matches:
            violations.append(f"ZERO_DOWNTIME_PK_DIRECT_BUILD_LOCK: 'ALTER TABLE {tbl} ADD PRIMARY KEY ({cols.strip()})' construye el índice B-Tree bajo AccessExclusiveLock bloqueando lecturas y escrituras. Construya primero el índice con 'CREATE UNIQUE INDEX CONCURRENTLY' y promuévalo con 'ADD CONSTRAINT ... PRIMARY KEY USING INDEX'.")
        concurrent_pk_using_index_verified = 0
        if re.search('CREATE\\s+UNIQUE\\s+INDEX\\s+CONCURRENTLY', sql_source, re.IGNORECASE) and re.search('PRIMARY\\s+KEY\\s+USING\\s+INDEX', sql_source, re.IGNORECASE):
            concurrent_pk_using_index_verified += 1
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_pgmq_vt_mfa_aal2_and_pk_using_index_ddl()
        summary = f'PG18 pgmq VT/DLQ + MFA AAL2 Restrictive RLS + Zero-Downtime PK Swap Audit: valid={is_valid}, pgmq={pgmq_vt_and_dlq_verified}/{pgmq_consumers_checked}, mfa_aal2={mfa_aal2_verified}/{mfa_aal2_policies_checked}, pk_using_index={concurrent_pk_using_index_verified}, unsafe_pk_builds={unsafe_pk_builds_detected}.'
        return PG18PgmqVtDlqMfaAmrAndPrimaryKeySwapReport(is_valid=is_valid, pgmq_consumers_checked=pgmq_consumers_checked, pgmq_vt_and_dlq_verified=pgmq_vt_and_dlq_verified, mfa_aal2_policies_checked=mfa_aal2_policies_checked, mfa_aal2_verified=mfa_aal2_verified, unsafe_pk_builds_detected=unsafe_pk_builds_detected, concurrent_pk_using_index_verified=concurrent_pk_using_index_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_pgmq_vt_mfa_aal2_and_pk_using_index_ddl(target_table: str='public.tenant_payout_ledgers') -> str:
        return f"-- 1. Consumidor transaccional Supabase pgmq con Visibility Timeout (vt = 60s) y archivo DLQ por read_ct\nCREATE OR REPLACE FUNCTION public.fn_consume_tenant_payout_queue()\nRETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pgmq, pg_temp AS $$\nDECLARE\n    v_msg record;\nBEGIN\n    FOR v_msg IN SELECT * FROM pgmq.read(queue_name => 'tenant_payouts', vt => 60, qty => 10) LOOP\n        IF v_msg.read_ct > 5 THEN\n            PERFORM pgmq.archive(queue_name => 'tenant_payouts', msg_id => v_msg.msg_id);\n        END IF;\n    END LOOP;\nEND;\n$$;\n\n-- 2. Política RLS AS RESTRICTIVE exigiendo MFA verificado (AAL2) con InitPlan O(1)\nCREATE POLICY rls_enforce_mfa_aal2_on_payouts ON {target_table}\n    AS RESTRICTIVE FOR ALL TO authenticated\n    USING ((SELECT auth.jwt()->>'aal') = 'aal2');\n\n-- 3. Promoción Zero-Downtime de Clave Primaria compuesta mediante CREATE UNIQUE INDEX CONCURRENTLY + USING INDEX\nCREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS idx_tenant_payout_ledgers_pk_v2\n    ON {target_table} (tenant_id, ledger_id);\nALTER TABLE {target_table}\n    ADD CONSTRAINT pk_tenant_payout_ledgers_v2 PRIMARY KEY USING INDEX idx_tenant_payout_ledgers_pk_v2;"


