# --- Merged from node03_v16_6: PG18HypoPgVirtualIndexExplainVerificationSupabaseStorageSignedUrlExpiryAndZeroDowntimeUniqueConstraintProver ---
class PG18HypoPgVirtualIndexExplainVerificationSupabaseStorageSignedUrlExpiryAndZeroDowntimeUniqueConstraintProver:

    def verify_hypopg_signed_url_and_unique_using_index(self, sql_source: str) -> PG18HypoPgSignedUrlAndUniqueUsingIndexReport:
        violations: List[str] = []
        hypopg_sessions_checked = 0
        hypopg_reset_verified = 0
        if re.search('hypopg_create_index|hypopg', sql_source, re.IGNORECASE):
            hypopg_sessions_checked += 1
            has_create = bool(re.search('hypopg_create_index\\s*\\(', sql_source, re.IGNORECASE))
            has_reset = bool(re.search('hypopg_reset\\s*\\(\\s*\\)', sql_source, re.IGNORECASE))
            if has_create and (not has_reset):
                violations.append("HYPOPG_MISSING_RESET_LEAK: Se invocó 'hypopg_create_index()' sin 'hypopg_reset()', dejando índices virtuales fantasma en la sesión del pool y distorsionando planes EXPLAIN posteriores.")
            if has_create and has_reset:
                hypopg_reset_verified += 1
        storage_buckets_checked = 0
        storage_private_and_ttl_verified = 0
        if re.search('storage\\.buckets|createSignedUrl', sql_source, re.IGNORECASE):
            storage_buckets_checked += 1
            has_public_bucket = bool(re.search('INSERT\\s+INTO\\s+storage\\.buckets[\\s\\S]*?\\btrue\\b', sql_source, re.IGNORECASE) or re.search('public\\s*(?:=>|:=|=)\\s*true', sql_source, re.IGNORECASE))
            ttl_matches = [int(x) for x in re.findall('createSignedUrl\\s*\\([^,]+,\\s*(\\d+)\\s*\\)', sql_source, re.IGNORECASE)]
            excessive_ttl = any((t > 3600 for t in ttl_matches))
            if has_public_bucket:
                violations.append("STORAGE_BUCKET_PUBLIC_EXPOSURE: El bucket en 'storage.buckets' tiene 'public = true'; los activos multi-tenant deben almacenarse en buckets privados ('public = false').")
            if excessive_ttl:
                violations.append(f"STORAGE_SIGNED_URL_EXCESSIVE_TTL: Se detectó 'createSignedUrl' con expiración > 3600s ({max(ttl_matches)}s), convirtiendo enlaces temporales en capacidades permanentes no revocables.")
            if not has_public_bucket and (not excessive_ttl):
                storage_private_and_ttl_verified += 1
        direct_unique_matches = re.findall('ALTER\\s+TABLE\\s+(?:ONLY\\s+)?([a-zA-Z0-9_.]+)\\s+ADD\\s+(?:CONSTRAINT\\s+[a-zA-Z0-9_]+\\s+)?UNIQUE\\s*\\(([^)]+)\\)', sql_source, flags=re.IGNORECASE)
        unsafe_unique_constraints_detected = len(direct_unique_matches)
        for tbl, cols in direct_unique_matches:
            violations.append(f"ZERO_DOWNTIME_UNIQUE_DIRECT_BUILD_LOCK: 'ALTER TABLE {tbl} ADD CONSTRAINT ... UNIQUE ({cols.strip()})' construye el índice B-Tree bajo AccessExclusiveLock bloqueando toda la tabla. Use 'CREATE UNIQUE INDEX CONCURRENTLY' seguido de 'ADD CONSTRAINT ... UNIQUE USING INDEX'.")
        concurrent_unique_using_index_verified = 0
        if re.search('CREATE\\s+UNIQUE\\s+INDEX\\s+CONCURRENTLY', sql_source, re.IGNORECASE) and re.search('UNIQUE\\s+USING\\s+INDEX', sql_source, re.IGNORECASE):
            concurrent_unique_using_index_verified += 1
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_hypopg_signed_url_and_unique_using_index_ddl()
        summary = f'PG18 HypoPG + Storage Signed URL TTL + Zero-Downtime UNIQUE Audit: valid={is_valid}, hypopg={hypopg_reset_verified}/{hypopg_sessions_checked}, storage_private={storage_private_and_ttl_verified}/{storage_buckets_checked}, unique_using_index={concurrent_unique_using_index_verified}, unsafe_unique={unsafe_unique_constraints_detected}.'
        return PG18HypoPgSignedUrlAndUniqueUsingIndexReport(is_valid=is_valid, hypopg_sessions_checked=hypopg_sessions_checked, hypopg_reset_verified=hypopg_reset_verified, storage_buckets_checked=storage_buckets_checked, storage_private_and_ttl_verified=storage_private_and_ttl_verified, unsafe_unique_constraints_detected=unsafe_unique_constraints_detected, concurrent_unique_using_index_verified=concurrent_unique_using_index_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_hypopg_signed_url_and_unique_using_index_ddl(target_table: str='public.tenant_kyc_documents') -> str:
        return f"-- 1. Verificación de índice virtual sin I/O con HypoPG y limpieza obligatoria hypopg_reset()\nCREATE EXTENSION IF NOT EXISTS hypopg;\nSELECT * FROM hypopg_create_index('CREATE INDEX ON {target_table} (tenant_id, external_ref)');\nSELECT hypopg_reset();\n\n-- 2. Bucket privado en Supabase Storage (public = false) y comentario de gobernanza Signed URL <= 900s\nINSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nVALUES ('tenant-kyc-vault', 'tenant-kyc-vault', false, 10485760, ARRAY['application/pdf'])\nON CONFLICT (id) DO UPDATE SET public = false;\n-- Client policy: supabase.storage.from('tenant-kyc-vault').createSignedUrl(path, 900)\n\n-- 3. Promoción Zero-Downtime de restricción UNIQUE mediante CREATE UNIQUE INDEX CONCURRENTLY + USING INDEX\nCREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS idx_tenant_kyc_external_ref_uniq\n    ON {target_table} (tenant_id, external_ref);\nALTER TABLE {target_table}\n    ADD CONSTRAINT uq_tenant_kyc_external_ref UNIQUE USING INDEX idx_tenant_kyc_external_ref_uniq;"


