# --- Merged from node03_v16_6: PG18PgRepackOnlineTableCompactionSupabaseEdgeFunctionJwtVerificationAndZeroDowntimeDefaultBackfillProver ---
class PG18PgRepackOnlineTableCompactionSupabaseEdgeFunctionJwtVerificationAndZeroDowntimeDefaultBackfillProver:

    def verify_pg_repack_edge_jwt_and_volatile_default(self, sql_source: str) -> PG18PgRepackEdgeJwtAndVolatileDefaultReport:
        violations: List[str] = []
        compaction_ops_checked = 0
        online_compaction_verified = 0
        if re.search('\\bVACUUM\\b|\\bCLUSTER\\b|\\bREINDEX\\b|pg_repack', sql_source, re.IGNORECASE):
            compaction_ops_checked += 1
            has_vacuum_full = bool(re.search('\\bVACUUM\\s*\\(?[^;)]*\\bFULL\\b', sql_source, re.IGNORECASE))
            has_cluster = bool(re.search('\\bCLUSTER\\s+[a-zA-Z0-9_.]+', sql_source, re.IGNORECASE))
            has_blocking_reindex = bool(re.search('\\bREINDEX\\s+(?:TABLE|INDEX|SCHEMA|DATABASE)\\s+(?!CONCURRENTLY\\b)[a-zA-Z0-9_.]+', sql_source, re.IGNORECASE))
            if has_vacuum_full:
                violations.append("ONLINE_COMPACTION_VACUUM_FULL_LOCK: 'VACUUM FULL' adquiere AccessExclusiveLock y reescribe toda la tabla bloqueando producción. Use 'pg_repack' o 'VACUUM (ANALYZE)' + 'REINDEX CONCURRENTLY'.")
            if has_cluster:
                violations.append("ONLINE_COMPACTION_CLUSTER_LOCK: 'CLUSTER' bloquea lecturas y escrituras con AccessExclusiveLock. Use 'pg_repack --order-by' para reordenar físicamente en línea.")
            if has_blocking_reindex:
                violations.append("ONLINE_COMPACTION_BLOCKING_REINDEX: 'REINDEX' sin 'CONCURRENTLY' bloquea escrituras en la tabla. Use siempre 'REINDEX TABLE/INDEX CONCURRENTLY'.")
            if not has_vacuum_full and (not has_cluster) and (not has_blocking_reindex):
                online_compaction_verified += 1
        edge_function_configs_checked = 0
        edge_jwt_or_hmac_verified = 0
        if re.search('verify_jwt|functions\\.|stripe-signature|svix-signature|x-webhook-signature', sql_source, re.IGNORECASE):
            edge_function_configs_checked += 1
            has_verify_jwt_false = bool(re.search('verify_jwt\\s*(?:=|:)\\s*false', sql_source, re.IGNORECASE))
            has_hmac_guard = bool(re.search('stripe-signature|svix-signature|x-webhook-signature|crypto\\.subtle\\.verify|constructEventAsync', sql_source, re.IGNORECASE))
            if has_verify_jwt_false and (not has_hmac_guard):
                violations.append("EDGE_FUNCTION_UNAUTHENTICATED_JWT_DISABLED: Se detectó 'verify_jwt = false' sin verificación criptográfica de firma HMAC (stripe-signature / svix-signature / crypto.subtle.verify), exponiendo la Edge Function a invocación anónima.")
            else:
                edge_jwt_or_hmac_verified += 1
        add_col_default_matches = re.findall('ALTER\\s+TABLE\\s+(?:ONLY\\s+)?([a-zA-Z0-9_.]+)\\s+ADD\\s+COLUMN(?:\\s+IF\\s+NOT\\s+EXISTS)?\\s+([a-zA-Z0-9_]+)\\s+[^;]+?\\bDEFAULT\\s+([^;]+);', sql_source, flags=re.IGNORECASE)
        volatile_default_rewrites_detected = 0
        fast_metadata_defaults_verified = 0
        for tbl, col, default_expr in add_col_default_matches:
            if re.search('\\b(clock_timestamp|random|timeofday)\\s*\\(', default_expr, re.IGNORECASE):
                volatile_default_rewrites_detected += 1
                violations.append(f"ZERO_DOWNTIME_VOLATILE_DEFAULT_REWRITE: 'ALTER TABLE {tbl} ADD COLUMN {col} ... DEFAULT {default_expr.strip()}' usa una expresión volátil que desactiva la optimización de catálogo (atthasmissing) y reescribe toda la tabla bajo AccessExclusiveLock. Use 'now()' o un valor constante no volátil.")
            else:
                fast_metadata_defaults_verified += 1
        is_valid = len(violations) == 0
        repaired_ddl = self.synthesize_pg_repack_edge_jwt_and_fast_default_ddl()
        summary = f'PG18 Online Compaction + Edge JWT/HMAC + Non-Volatile Default Audit (Level 100): valid={is_valid}, compaction={online_compaction_verified}/{compaction_ops_checked}, edge_auth={edge_jwt_or_hmac_verified}/{edge_function_configs_checked}, fast_defaults={fast_metadata_defaults_verified}, volatile_rewrites={volatile_default_rewrites_detected}.'
        return PG18PgRepackEdgeJwtAndVolatileDefaultReport(is_valid=is_valid, compaction_ops_checked=compaction_ops_checked, online_compaction_verified=online_compaction_verified, edge_function_configs_checked=edge_function_configs_checked, edge_jwt_or_hmac_verified=edge_jwt_or_hmac_verified, volatile_default_rewrites_detected=volatile_default_rewrites_detected, fast_metadata_defaults_verified=fast_metadata_defaults_verified, violations=violations, repaired_ddl_bundle=repaired_ddl, proof_obligation_summary=summary)

    @staticmethod
    def synthesize_pg_repack_edge_jwt_and_fast_default_ddl(target_table: str='public.tenant_ledger_entries') -> str:
        return f'-- 1. Compactación online sin bloqueo (REINDEX CONCURRENTLY + pg_repack)\nCREATE EXTENSION IF NOT EXISTS pg_repack;\nREINDEX TABLE CONCURRENTLY {target_table};\nVACUUM (ANALYZE) {target_table};\n\n-- 2. Gobernanza Supabase Edge Functions: verify_jwt = true por defecto y HMAC constructEventAsync en webhooks\n-- [functions.tenant-Admin-action] verify_jwt = true\n-- [functions.stripe-webhook] verify_jwt = false + stripe-signature constructEventAsync + crypto.subtle.verify\n\n-- 3. Adición instantánea de columna en catálogo (atthasmissing O(1)) con expresión DEFAULT no volátil\nALTER TABLE {target_table}\n    ADD COLUMN IF NOT EXISTS settled_at timestamptz NOT NULL DEFAULT now();'


