    def verify_parallel_index_child_rls_and_attach_partition(self, sql_source: str) -> PG18ParallelIndexChildRlsAndAttachPartitionReport:
        violations: List[str] = []
        clean_sql = re.sub('--[^\\n]*', '', sql_source)
        concurrent_indexes_checked = 0
        parallel_maintenance_tuned_verified = 0
        if re.search('CREATE\\s+(?:UNIQUE\\s+)?INDEX\\s+CONCURRENTLY', clean_sql, re.IGNORECASE):
            concurrent_indexes_checked += 1
