    @staticmethod
    def synthesize_per_table_autovacuum_composite_fk_and_batched_backfill_ddl(target_table: str='public.tenant_order_items', parent_table: str='public.tenant_orders') -> str:
        return f'-- 1. Tuning PG18 de Autovacuum por tabla para alta rotación multi-tenant\nALTER TABLE {target_table} SET (\n    autovacuum_vacuum_scale_factor = 0.01,\n    autovacuum_analyze_scale_factor = 0.005,\n    autovacuum_vacuum_cost_limit = 2000\n);\n\n-- 2. Clave foránea compuesta con tenant_id para impedir referencias cross-tenant que puentean RLS\nALTER TABLE {target_table}\n    ADD CONSTRAINT fk_tenant_order_items_composite_tenant_order\n    FOREIGN KEY (tenant_id, order_id) REFERENCES {parent_table} (tenant_id, id) NOT VALID;\nALTER TABLE {target_table}\n    VALIDATE CONSTRAINT fk_tenant_order_items_composite_tenant_order;\n\n-- 3. Backfill Zero-Downtime acotado por lotes con FOR UPDATE SKIP LOCKED\nWITH batch_rows AS (\n    SELECT id\n    FROM {target_table}\n    WHERE line_total_cents IS NULL\n    ORDER BY id\n    LIMIT 5000\n    FOR UPDATE SKIP LOCKED\n)\nUPDATE {target_table} AS t\nSET line_total_cents = t.quantity * t.unit_price_cents\nFROM batch_rows\nWHERE t.id = batch_rows.id;'


