        return f"-- 1. Reconstrucción concurrente de índice en PG18 sin bloquear lecturas ni escrituras OLTP\nREINDEX INDEX CONCURRENTLY idx_tenant_api_credentials_tenant_key_hash;\n\n-- 2. Política RLS con validación de sesión activa (session_id IS NOT NULL) y aislamiento por app_metadata\nCREATE POLICY rls_tenant_api_credentials_active_session ON {target_table}\n    AS RESTRICTIVE FOR ALL TO authenticated\n    USING (\n        tenant_id = (SELECT (auth.jwt()->'app_metadata'->>'tenant_id')::uuid)\n        AND (SELECT (auth.jwt()->>'session_id')::uuid) IS NOT NULL\n    )\n    WITH CHECK (\n        tenant_id = (SELECT (auth.jwt()->'app_metadata'->>'tenant_id')::uuid)\n        AND (SELECT (auth.jwt()->>'session_id')::uuid) IS NOT NULL\n    );\n\n-- 3. Desacoplamiento transaccional estricto entre DDL (ALTER TABLE) y backfill DML\nALTER TABLE {target_table}\n    ADD COLUMN IF NOT EXISTS key_version integer DEFAULT 1;\n-- El backfill DML se ejecuta en transacciones independientes fuera del bloqueo DDL\nWITH batch_creds AS (\n    SELECT id FROM {target_table} WHERE key_version IS NULL LIMIT 5000 FOR UPDATE SKIP LOCKED\n)\nUPDATE {target_table} AS t SET key_version = 1 FROM batch_creds WHERE t.id = batch_creds.id;"


