# --- Merged from node03_v16_6: PG18CheckpointerBgwriterIoTuningSupabaseRlsSecurityInvokerViewChainAndZeroDowntimeConstraintRenameProver ---
class PG18CheckpointerBgwriterIoTuningSupabaseRlsSecurityInvokerViewChainAndZeroDowntimeConstraintRenameProver:

    @classmethod
    def verify_pg18_checkpointer_io_security_invoker_views_and_rename_constraint(cls, sql_script: str, target_table: str='public.tenant_ledger_entries') -> PG18CheckpointerIoSecurityInvokerAndRenameConstraintReport:
        t0 = time.perf_counter()
        text = sql_script or ''
        cleaned_lines = []
        for line in text.splitlines():
            s = line.strip()
            if s.startswith('--'):
                continue
            if '--' in line:
                line = line.split('--', 1)[0]
            cleaned_lines.append(line)
        cleaned = '\n'.join(cleaned_lines)
        upper = cleaned.upper()
        violations: list[str] = []
        has_aggressive_checkpoint = bool(re.search('CHECKPOINT_COMPLETION_TARGET\\s*=\\s*[\\\'\\"]?0\\.[0-5]', upper) or re.search('CHECKPOINT_TIMEOUT\\s*=\\s*[\\\'\\"]?[1-4]\\s*MIN', upper) or re.search('PG_STAT_BGWRITER\\s*\\.[\\w]*CHECKPOINTS_TIMED', upper))
        has_safe_checkpointer = bool('CHECKPOINT_COMPLETION_TARGET' in upper and ('PG_STAT_CHECKPOINTER' in upper or 'MAX_WAL_SIZE' in upper or 'BGWRITER_LRU_MAXPAGES' in upper) and (not has_aggressive_checkpoint))
        if has_aggressive_checkpoint or not has_safe_checkpointer:
            violations.append('INV-302-1 (PG18 Checkpointer & Bgwriter I/O Tuning Violation): PostgreSQL 18 requires `checkpoint_completion_target >= 0.8`, adequate `checkpoint_timeout` / `max_wal_size`, and telemetry queries against `pg_stat_checkpointer` (replacing legacy checkpoint columns removed from `pg_stat_bgwriter`).')
        has_unprotected_view = False
        for m in re.finditer('CREATE\\s+(?:OR\\s+REPLACE\\s+)?VIEW\\s+([\\w\\.]+)\\s*(.*?)(?:AS\\s+SELECT)', upper, re.DOTALL):
            view_header = m.group(2) or ''
            if 'SECURITY_INVOKER' not in view_header or re.search('SECURITY_INVOKER\\s*=\\s*(?:FALSE|OFF)', view_header):
                has_unprotected_view = True
        has_security_invoker_view = bool(re.search('SECURITY_INVOKER\\s*=\\s*(?:TRUE|ON)', upper) and ('AUTH.JWT()' in upper or "CURRENT_SETTING('REQUEST.JWT.CLAIMS'" in upper or 'TENANT_ID' in upper) and (not has_unprotected_view))
        if has_unprotected_view or not has_security_invoker_view:
            violations.append('INV-302-2 (Supabase RLS View Chain Security Invoker Violation): All views in a multi-tenant dependency chain must explicitly specify `WITH (security_invoker = true)` so PostgreSQL 18 / Supabase evaluates underlying table and chained view RLS policies as the invoking tenant rather than the view owner.')
        has_drop_readd_rename = bool(re.search('DROP\\s+CONSTRAINT\\s+[\\w]+\\s*,\\s*ADD\\s+CONSTRAINT', upper))
        has_safe_rename = bool(('RENAME CONSTRAINT' in upper or ('ALTER INDEX' in upper and 'RENAME TO' in upper)) and 'LOCK_TIMEOUT' in upper and (not has_drop_readd_rename))
        if has_drop_readd_rename or not has_safe_rename:
            violations.append('INV-302-3 (Zero-Downtime Constraint/Index Rename Violation): Never rename a constraint by running `DROP CONSTRAINT ... , ADD CONSTRAINT ...` in production. Use metadata-only `ALTER TABLE ... RENAME CONSTRAINT old_name TO new_name` or `ALTER INDEX ... RENAME TO` guarded by `SET LOCAL lock_timeout`.')
        passed = len(violations) == 0
        remediated = cls.synthesize_remediated_sql(target_table)
        elapsed = round((time.perf_counter() - t0) * 1000.0, 3)
        digest = hashlib.sha256(f'LEVEL302|{passed}|{len(violations)}|{target_table}'.encode('utf-8')).hexdigest()[:16]
        return PG18CheckpointerIoSecurityInvokerAndRenameConstraintReport(target_table=target_table, passed=passed, checkpointer_io_tuning_verified=1 if has_safe_checkpointer else 0, security_invoker_view_chain_verified=1 if has_security_invoker_view else 0, zero_downtime_constraint_rename_verified=1 if has_safe_rename else 0, blocking_or_unsafe_patterns_detected=len(violations), violations=violations, remediated_sql=remediated, proof_hash=digest, analysis_duration_ms=elapsed)

    @staticmethod
    def synthesize_remediated_sql(target_table: str='public.tenant_ledger_entries') -> str:
        return f"-- 1. PostgreSQL 18 Checkpointer & Background Writer I/O Tuning + pg_stat_checkpointer\nALTER SYSTEM SET checkpoint_completion_target = '0.9';\nALTER SYSTEM SET checkpoint_timeout = '20min';\nALTER SYSTEM SET max_wal_size = '32GB';\nALTER SYSTEM SET bgwriter_lru_maxpages = 400;\nSELECT num_timed, num_requested, write_time, sync_time FROM pg_stat_checkpointer;\n\n-- 2. Cadena de vistas multi-tenant con security_invoker = true\nCREATE OR REPLACE VIEW {target_table}_v_summary\nWITH (security_invoker = true, security_barrier = true)\nAS SELECT id, tenant_id, amount_cents FROM {target_table}\nWHERE tenant_id = (SELECT (auth.jwt() ->> 'tenant_id')::uuid);\n\n-- 3. Renombrado Zero-Downtime de constraint e índice en catálogo bajo lock_timeout\nSET LOCAL lock_timeout = '1500ms';\nALTER TABLE {target_table} RENAME CONSTRAINT chk_amount_legacy TO chk_amount_non_negative;\nALTER INDEX idx_ledger_legacy RENAME TO idx_ledger_tenant_created_at;"


