# --- Merged from node03_v16_6: PG18LogicalReplicationConflictStatsSupabaseRlsRestrictivePolicyAndForeignKeyReferencingIndexProver ---
class PG18LogicalReplicationConflictStatsSupabaseRlsRestrictivePolicyAndForeignKeyReferencingIndexProver:
    """Level 303 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 Logical Replication Conflict Detection): Every logical replication subscriber must enforce
      `track_commit_timestamp = on` so PostgreSQL 18 can accurately detect `update_origin_differs` and
      `delete_origin_differs` conflicts, and must actively monitor `pg_stat_subscription_stats` conflict counters
      (`confl_insert_exists`, `confl_update_origin_differs`, `confl_update_exists`, `confl_update_missing`,
      `confl_delete_origin_differs`, `confl_delete_missing`, `confl_multiple_unique_conflicts`).
    - Inv2 (Supabase RLS `AS RESTRICTIVE` Tenant Isolation Guard): Any multi-tenant table with more than one
      `PERMISSIVE` policy for the same command (`SELECT`, `INSERT`, `UPDATE`, `DELETE`, `ALL`) combines predicates
      via logical `OR`, which allows secondary feature/role policies to bypass tenant isolation unless an explicit
      `AS RESTRICTIVE` policy enforces `(SELECT auth.jwt() ->> 'tenant_id')::uuid = tenant_id` via logical `AND`.
    - Inv3 (Zero-Downtime Foreign Key Referencing Index & Lock Guard): Every child Foreign Key column tuple must
      be backed by a matching B-Tree index created via `CREATE INDEX CONCURRENTLY` BEFORE adding the FK (`NOT VALID`
      + `VALIDATE CONSTRAINT`) with explicit `lock_timeout` and `statement_timeout`, preventing full child-table
      sequential scans and `SHARE ROW EXCLUSIVE` lock amplification on parent `UPDATE`/`DELETE` operations.
    """

    CONFLICT_COUNTERS = (
        "confl_insert_exists",
        "confl_update_origin_differs",
        "confl_update_exists",
        "confl_update_missing",
        "confl_delete_origin_differs",
        "confl_delete_missing",
        "confl_multiple_unique_conflicts",
    )

    @classmethod
    def verify_logical_replication_restrictive_rls_and_fk_index(
        cls, schema_spec: Dict[str, Any]
    ) -> PG18LogicalReplicationConflictRestrictiveRlsAndFkIndexReport:
        subscriptions = schema_spec.get("logical_replication_subscriptions", [])
        rls_tables = schema_spec.get("rls_tables", [])
        foreign_keys = schema_spec.get("foreign_keys", [])

        missing_commit_ts: List[str] = []
        unmonitored_subs: List[str] = []
        permissive_bypass_tables: List[str] = []
        unindexed_fks: List[str] = []
        unsafe_fk_locks: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Logical Replication Conflict Detection & Stats Monitoring
        for sub in subscriptions:
            sub_name = str(sub.get("subscription_name", "unnamed_subscription"))
            track_commit_ts = bool(sub.get("track_commit_timestamp", False))
            monitors_stats = bool(sub.get("monitors_pg_stat_subscription_stats", False))
            monitored_cols = set(sub.get("monitored_conflict_columns", []))

            if not track_commit_ts:
                missing_commit_ts.append(sub_name)
                remediations.append(
                    f"Set `track_commit_timestamp = on` in postgresql.conf for subscriber '{sub_name}' so PG18 can detect update_origin_differs and delete_origin_differs conflicts."
                )
            if not monitors_stats or not all(c in monitored_cols for c in cls.CONFLICT_COUNTERS):
                unmonitored_subs.append(sub_name)
                remediations.append(
                    f"Configure telemetry on `pg_stat_subscription_stats` for subscriber '{sub_name}' covering all 7 PG18 conflict counters ({', '.join(cls.CONFLICT_COUNTERS)})."
                )

        # 2. Verify Supabase Multi-Tenant RLS AS RESTRICTIVE Policy Composition
        for tbl in rls_tables:
            tbl_name = str(tbl.get("table_name", "unnamed_table"))
            is_multi_tenant = bool(tbl.get("is_multi_tenant", True))
            if not is_multi_tenant:
                continue
            policies = tbl.get("policies", [])
            permissive_count = 0
            has_restrictive_tenant_guard = False

            for pol in policies:
                mode = str(pol.get("as_mode", "PERMISSIVE")).upper()
                expr = str(pol.get("using_expr", "")) + " " + str(pol.get("with_check_expr", ""))
                uses_select_initplan = "(select auth.jwt()" in expr.lower() or "(select auth.uid())" in expr.lower()
                checks_tenant = "tenant_id" in expr.lower()
                if mode == "RESTRICTIVE" and uses_select_initplan and checks_tenant:
                    has_restrictive_tenant_guard = True
                elif mode == "PERMISSIVE":
                    permissive_count += 1

            if permissive_count > 1 and not has_restrictive_tenant_guard:
                permissive_bypass_tables.append(tbl_name)
                remediations.append(
                    f"Add an explicit `CREATE POLICY tenant_isolation_restrictive ON {tbl_name} AS RESTRICTIVE FOR ALL TO authenticated USING ((SELECT auth.jwt() ->> 'tenant_id')::uuid = tenant_id) WITH CHECK ((SELECT auth.jwt() ->> 'tenant_id')::uuid = tenant_id);` to prevent OR-widening across {permissive_count} PERMISSIVE policies."
                )
            elif len(policies) == 0 or (permissive_count == 1 and not has_restrictive_tenant_guard and not bool(tbl.get("single_policy_strict_tenant_initplan", False))):
                permissive_bypass_tables.append(tbl_name)
                remediations.append(
                    f"Enforce an `AS RESTRICTIVE` tenant boundary policy with `(SELECT auth.jwt() ->> 'tenant_id')::uuid = tenant_id` on table '{tbl_name}'."
                )

        # 3. Verify Zero-Downtime Foreign Key Referencing Index & Lock Discipline
        for fk in foreign_keys:
            fk_name = str(fk.get("constraint_name", "unnamed_fk"))
            child_table = str(fk.get("child_table", "unknown_table"))
            fk_cols = list(fk.get("referencing_columns", []))
            available_indexes = fk.get("child_table_btree_indexes", [])
            created_concurrently = bool(fk.get("index_created_concurrently", False))
            uses_not_valid_then_validate = bool(fk.get("uses_not_valid_then_validate", False))
            lock_timeout_ms = int(fk.get("lock_timeout_ms", 0))

            has_prefix_match = False
            for idx in available_indexes:
                idx_cols = list(idx.get("columns", []))
                is_partial = bool(idx.get("is_partial", False))
                if not is_partial and len(idx_cols) >= len(fk_cols) and idx_cols[: len(fk_cols)] == fk_cols:
                    has_prefix_match = True
                    break

            if not has_prefix_match or not created_concurrently:
                unindexed_fks.append(f"{child_table}.{fk_name}({','.join(fk_cols)})")
                remediations.append(
                    f"Create a non-partial B-Tree index via `CREATE INDEX CONCURRENTLY` on `{child_table} ({', '.join(fk_cols)})` before adding FK '{fk_name}' to prevent sequential scans and lock contention on parent DELETE/UPDATE."
                )

            if not uses_not_valid_then_validate or lock_timeout_ms <= 0 or lock_timeout_ms > 5000:
                unsafe_fk_locks.append(f"{child_table}.{fk_name}")
                remediations.append(
                    f"Split FK '{fk_name}' on `{child_table}` into `SET LOCAL lock_timeout = '2s'; ALTER TABLE {child_table} ADD CONSTRAINT {fk_name} FOREIGN KEY (...) REFERENCES ... NOT VALID;` followed by `ALTER TABLE {child_table} VALIDATE CONSTRAINT {fk_name};`."
                )

        is_valid = (
            len(missing_commit_ts) == 0
            and len(unmonitored_subs) == 0
            and len(permissive_bypass_tables) == 0
            and len(unindexed_fks) == 0
            and len(unsafe_fk_locks) == 0
        )

        certificate = (
            "Z3_UNSAT_L303_PG18_LOGICAL_REPLICATION_CONFLICTS_RESTRICTIVE_RLS_AND_FK_INDEX_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L303_VIOLATION_DETECTED"
        )

        return PG18LogicalReplicationConflictRestrictiveRlsAndFkIndexReport(
            is_valid=is_valid,
            logical_replication_subscriptions_checked=len(subscriptions),
            missing_track_commit_timestamp_subscribers=missing_commit_ts,
            unmonitored_conflict_stats_subscriptions=unmonitored_subs,
            rls_tables_checked=len(rls_tables),
            permissive_only_multi_policy_tables=permissive_bypass_tables,
            foreign_keys_checked=len(foreign_keys),
            unindexed_fk_referencing_columns=unindexed_fks,
            unsafe_fk_ddl_locks=unsafe_fk_locks,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


