# --- Merged from node03_v16_6: PG18TemporalWithoutOverlapsConstraintSupabaseRlsStorageBucketPathIsolationAndZeroDowntimeColumnTypeChangeProver ---
class PG18TemporalWithoutOverlapsConstraintSupabaseRlsStorageBucketPathIsolationAndZeroDowntimeColumnTypeChangeProver:
    """Level 304 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 Temporal WITHOUT OVERLAPS & PERIOD FK Integrity): Any multi-tenant temporal table modeling
      non-overlapping validity intervals (`tstzrange` / `daterange`) must enforce `PRIMARY KEY (tenant_id, entity_id, valid_period WITHOUT OVERLAPS)`
      or `UNIQUE (tenant_id, entity_id, valid_period WITHOUT OVERLAPS)` backed by `btree_gist`, and any temporal child
      Foreign Key must use `FOREIGN KEY (tenant_id, entity_id, PERIOD valid_period) REFERENCES parent_table (tenant_id, entity_id, PERIOD valid_period)`.
    - Inv2 (Supabase `storage.objects` Multi-Tenant Path Prefix RLS Isolation): Every multi-tenant bucket in
      `storage.objects` must enforce `bucket_id = '<bucket>'` AND `(storage.foldername(name))[1] = (SELECT auth.jwt() ->> 'tenant_id')`
      across both `USING` and `WITH CHECK` clauses (`SELECT`, `INSERT`, `UPDATE`, `DELETE`) with `AS RESTRICTIVE` or strict tenant guard,
      preventing cross-tenant file reads or overwrites in shared buckets.
    - Inv3 (Zero-Downtime Column Type Migration via Expand-Contract): Non-binary-coercible column type changes
      must NEVER execute direct `ALTER TABLE ... ALTER COLUMN ... TYPE ...` (which holds `ACCESS EXCLUSIVE` lock during a full
      table and index rewrite). Instead, they must execute the 4-phase Expand-Contract protocol:
      (1) `ADD COLUMN <new_col>` nullable, (2) dual-write trigger + batched backfill, (3) `CREATE INDEX CONCURRENTLY` +
      `CHECK (<new_col> IS NOT NULL) NOT VALID` + `VALIDATE CONSTRAINT`, and (4) view/column swap under `lock_timeout <= 2000ms`.
    """

    @classmethod
    def verify_temporal_without_overlaps_storage_rls_and_column_type_change(
        cls, migration_spec: Dict[str, Any]
    ) -> PG18TemporalWithoutOverlapsStorageRlsAndColumnTypeChangeReport:
        temporal_tables = migration_spec.get("temporal_tables", [])
        storage_buckets = migration_spec.get("storage_buckets", [])
        column_migrations = migration_spec.get("column_type_migrations", [])

        invalid_temporal: List[str] = []
        vulnerable_buckets: List[str] = []
        unsafe_type_changes: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Temporal WITHOUT OVERLAPS & PERIOD FK constraints
        for tbl in temporal_tables:
            tbl_name = str(tbl.get("table_name", "unnamed_temporal_table"))
            has_btree_gist = bool(tbl.get("btree_gist_enabled", False))
            uses_without_overlaps = bool(tbl.get("uses_without_overlaps_key", False))
            leading_tenant_key = bool(tbl.get("tenant_id_leading_in_gist_key", False))
            has_temporal_fk = bool(tbl.get("has_temporal_child_fk", False))
            uses_period_fk = bool(tbl.get("uses_period_in_temporal_fk", True))

            if (
                not has_btree_gist
                or not uses_without_overlaps
                or not leading_tenant_key
                or (has_temporal_fk and not uses_period_fk)
            ):
                invalid_temporal.append(tbl_name)
                remediations.append(
                    f"Enable `CREATE EXTENSION IF NOT EXISTS btree_gist;` and declare `PRIMARY KEY (tenant_id, id, valid_range WITHOUT OVERLAPS)` (plus `FOREIGN KEY (tenant_id, parent_id, PERIOD valid_range)` for child tables) on '{tbl_name}'."
                )

        # 2. Verify Supabase Storage `storage.objects` Multi-Tenant Path Prefix RLS Isolation
        for bkt in storage_buckets:
            bkt_id = str(bkt.get("bucket_id", "unnamed_bucket"))
            checks_bucket_id = bool(bkt.get("checks_bucket_id", False))
            checks_foldername_tenant = bool(bkt.get("checks_foldername_first_segment_tenant_jwt", False))
            uses_select_initplan = bool(bkt.get("uses_select_auth_jwt_initplan", False))
            enforces_with_check_on_write = bool(bkt.get("enforces_with_check_on_insert_update", False))

            if (
                not checks_bucket_id
                or not checks_foldername_tenant
                or not uses_select_initplan
                or not enforces_with_check_on_write
            ):
                vulnerable_buckets.append(bkt_id)
                remediations.append(
                    f"Enforce RLS on `storage.objects` for bucket '{bkt_id}' with `USING (bucket_id = '{bkt_id}' AND (storage.foldername(name))[1] = (SELECT auth.jwt() ->> 'tenant_id'))` and matching `WITH CHECK`."
                )

        # 3. Verify Zero-Downtime Column Type Migration (Expand-Contract vs Direct ALTER COLUMN TYPE)
        for mig in column_migrations:
            target = f"{mig.get('table_name', 'unknown_table')}.{mig.get('column_name', 'unknown_col')}"
            is_binary_coercible = bool(mig.get("is_binary_coercible", False))
            uses_direct_alter_type = bool(mig.get("uses_direct_alter_column_type", False))
            uses_expand_contract = bool(mig.get("uses_expand_contract_dual_write_backfill", False))
            lock_timeout_ms = int(mig.get("lock_timeout_ms", 0))

            if (not is_binary_coercible and uses_direct_alter_type) or (
                not is_binary_coercible and not uses_expand_contract
            ) or lock_timeout_ms <= 0 or lock_timeout_ms > 5000:
                unsafe_type_changes.append(target)
                remediations.append(
                    f"Replace `ALTER TABLE ... ALTER COLUMN {target} TYPE ...` with a 4-phase Expand-Contract migration (`ADD COLUMN`, dual-write trigger + batched backfill, `CREATE INDEX CONCURRENTLY` + `NOT VALID`/`VALIDATE CONSTRAINT`, and atomic column swap under `lock_timeout = '2s'`)."
                )

        is_valid = (
            len(invalid_temporal) == 0
            and len(vulnerable_buckets) == 0
            and len(unsafe_type_changes) == 0
        )

        certificate = (
            "Z3_UNSAT_L304_PG18_TEMPORAL_WITHOUT_OVERLAPS_STORAGE_RLS_AND_EXPAND_CONTRACT_TYPE_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L304_VIOLATION_DETECTED"
        )

        return PG18TemporalWithoutOverlapsStorageRlsAndColumnTypeChangeReport(
            is_valid=is_valid,
            temporal_tables_checked=len(temporal_tables),
            invalid_temporal_without_overlaps_tables=invalid_temporal,
            storage_buckets_checked=len(storage_buckets),
            vulnerable_storage_rls_buckets=vulnerable_buckets,
            column_type_migrations_checked=len(column_migrations),
            unsafe_alter_column_type_rewrites=unsafe_type_changes,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


