# --- Merged from node03_v16_6: PG18GeneratedColumnVirtualStoredDisciplineSupabaseRlsRealtimePublicationFilterAndZeroDowntimeTablePartitioningProver ---
class PG18GeneratedColumnVirtualStoredDisciplineSupabaseRlsRealtimePublicationFilterAndZeroDowntimeTablePartitioningProver:
    """Level 305 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 VIRTUAL/STORED Generated Column Discipline): Adding a generated column on an existing large table
      must use PostgreSQL 18 `GENERATED ALWAYS AS (...) VIRTUAL` (unless indexed in B-Tree/GIN where STORED or
      expression index `CREATE INDEX CONCURRENTLY` is required) and its expression must be strictly `IMMUTABLE`
      without volatile functions or table-rewriting `STORED` additions under `ACCESS EXCLUSIVE`.
    - Inv2 (Supabase Realtime Multi-Tenant RLS Isolation): Every multi-tenant Realtime channel / table must enforce
      `realtime.messages` RLS (`AS RESTRICTIVE` or strict tenant topic prefix `split_part(realtime.topic(), ':', 1) = (SELECT auth.jwt() ->> 'tenant_id')`)
      and any table in `supabase_realtime` publication must have `ENABLE ROW LEVEL SECURITY` + `FORCE ROW LEVEL SECURITY`
      with `(SELECT auth.jwt() ->> 'tenant_id')::uuid = tenant_id`.
    - Inv3 (Zero-Downtime `ATTACH PARTITION` Pre-Validated CHECK Discipline): Before executing
      `ALTER TABLE parent ATTACH PARTITION child FOR VALUES ...`, the migration must add a matching bound constraint
      `ALTER TABLE child ADD CONSTRAINT ... CHECK (...) NOT VALID;` and `ALTER TABLE child VALIDATE CONSTRAINT ...;`
      followed by `ATTACH PARTITION` under `lock_timeout <= 2000ms` so PostgreSQL skips the full partition scan.
    """

    @classmethod
    def verify_pg18_virtual_generated_realtime_rls_and_attach_partition(
        cls, migration_spec: Dict[str, Any]
    ) -> PG18GeneratedColumnVirtualStoredRealtimeRlsAndAttachPartitionReport:
        gen_cols = migration_spec.get("generated_columns", [])
        realtime_channels = migration_spec.get("realtime_channels", [])
        partition_attachments = migration_spec.get("partition_attachments", [])

        invalid_gen: List[str] = []
        vulnerable_rt: List[str] = []
        unsafe_parts: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Generated Columns (VIRTUAL vs STORED & IMMUTABLE expression)
        for col in gen_cols:
            col_id = f"{col.get('table_name', 'unknown_table')}.{col.get('column_name', 'unknown_col')}"
            is_immutable = bool(col.get("expression_is_immutable", False))
            mode = str(col.get("generation_mode", "STORED")).upper()
            added_to_existing_large_table = bool(col.get("added_to_existing_large_table", False))
            uses_concurrent_expr_index_if_indexed = bool(col.get("uses_concurrent_expr_index_if_indexed", True))

            if (
                not is_immutable
                or (added_to_existing_large_table and mode == "STORED")
                or not uses_concurrent_expr_index_if_indexed
            ):
                invalid_gen.append(col_id)
                remediations.append(
                    f"Use PostgreSQL 18 `GENERATED ALWAYS AS (<immutable_expr>) VIRTUAL` on `{col_id}` (and `CREATE INDEX CONCURRENTLY` on the immutable expression if indexing is needed) to avoid an `ACCESS EXCLUSIVE` full table rewrite."
                )

        # 2. Verify Supabase Realtime Multi-Tenant RLS & Topic Prefix Isolation
        for ch in realtime_channels:
            ch_name = str(ch.get("channel_or_table", "unnamed_channel"))
            rls_enabled_and_forced = bool(ch.get("rls_enabled_and_forced", False))
            checks_tenant_topic_prefix = bool(ch.get("checks_realtime_topic_tenant_prefix", False))
            uses_select_jwt_initplan = bool(ch.get("uses_select_auth_jwt_initplan", False))
            enforces_write_with_check = bool(ch.get("enforces_with_check_on_broadcast_insert", False))

            if (
                not rls_enabled_and_forced
                or not checks_tenant_topic_prefix
                or not uses_select_jwt_initplan
                or not enforces_write_with_check
            ):
                vulnerable_rt.append(ch_name)
                remediations.append(
                    f"Enforce `FORCE ROW LEVEL SECURITY` on `realtime.messages` / `{ch_name}` with `split_part(realtime.topic(), ':', 1) = (SELECT auth.jwt() ->> 'tenant_id')` in both `USING` and `WITH CHECK`."
                )

        # 3. Verify Zero-Downtime ATTACH PARTITION with Pre-Validated CHECK Constraint
        for part in partition_attachments:
            part_id = f"{part.get('parent_table', 'parent')}->{part.get('partition_table', 'child')}"
            pre_validated_check = bool(part.get("has_pre_validated_matching_check_constraint", False))
            used_not_valid_then_validate = bool(part.get("used_not_valid_then_validate_before_attach", False))
            lock_timeout_ms = int(part.get("lock_timeout_ms", 0))

            if (
                not pre_validated_check
                or not used_not_valid_then_validate
                or lock_timeout_ms <= 0
                or lock_timeout_ms > 5000
            ):
                unsafe_parts.append(part_id)
                remediations.append(
                    f"Before `ATTACH PARTITION` on `{part_id}`, execute `ALTER TABLE child ADD CONSTRAINT bound_chk CHECK (...) NOT VALID; ALTER TABLE child VALIDATE CONSTRAINT bound_chk;` and run `ATTACH PARTITION` under `SET LOCAL lock_timeout = '2s'`."
                )

        is_valid = (
            len(invalid_gen) == 0
            and len(vulnerable_rt) == 0
            and len(unsafe_parts) == 0
        )

        certificate = (
            "Z3_UNSAT_L305_PG18_VIRTUAL_GENERATED_REALTIME_RLS_AND_ATTACH_PARTITION_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L305_VIOLATION_DETECTED"
        )

        return PG18GeneratedColumnVirtualStoredRealtimeRlsAndAttachPartitionReport(
            is_valid=is_valid,
            generated_columns_checked=len(gen_cols),
            invalid_generated_columns=invalid_gen,
            realtime_channels_checked=len(realtime_channels),
            vulnerable_realtime_rls_channels=vulnerable_rt,
            partition_attachments_checked=len(partition_attachments),
            unsafe_partition_attachments=unsafe_parts,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


