# --- Merged from node03_v16_6: PG18ReturningOldNewDeltaAuditSupabaseRlsJwtCustomClaimsHookAndZeroDowntimeDetachPartitionConcurrentlyProver ---
class PG18ReturningOldNewDeltaAuditSupabaseRlsJwtCustomClaimsHookAndZeroDowntimeDetachPartitionConcurrentlyProver:
    """Level 306 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 `RETURNING OLD AS ..., NEW AS ...` Single-Roundtrip Delta Audit): Every state-mutating ledger/audit
      `UPDATE`, `DELETE`, or `MERGE` statement in PostgreSQL 18 must utilize `RETURNING OLD AS old_row, NEW AS new_row`
      to capture both pre-state and post-state atomically in a single roundtrip and verify integer-cent conservation
      (`new_row.amount_cents - old_row.amount_cents == expected_delta_cents`).
    - Inv2 (Supabase RLS `app_metadata` & Custom Access Token Hook Security): RLS policies must NEVER reference mutable
      `user_metadata` or `raw_user_meta_data` (which authenticated users can forge via `supabase.auth.updateUser()`).
      Tenant and role claims must originate from `app_metadata` (`(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid`)
      or a `custom_access_token_hook` locked down to `supabase_auth_admin` (`REVOKE ALL FROM PUBLIC, authenticated, anon`).
    - Inv3 (Zero-Downtime `DETACH PARTITION ... CONCURRENTLY`): Retiring or archiving a historical partition must
      execute `ALTER TABLE parent DETACH PARTITION child CONCURRENTLY;` (which takes `SHARE UPDATE EXCLUSIVE` instead of
      `ACCESS EXCLUSIVE`), never a blocking `DETACH PARTITION` or direct `DROP TABLE` on an attached partition.
    """

    @classmethod
    def verify_pg18_returning_old_new_app_metadata_rls_and_detach_concurrently(
        cls, audit_spec: Dict[str, Any]
    ) -> PG18ReturningOldNewAppMetadataRlsAndDetachPartitionConcurrentlyReport:
        mutations = audit_spec.get("dml_mutations", [])
        jwt_policies = audit_spec.get("jwt_claim_policies", [])
        detachments = audit_spec.get("partition_detachments", [])

        invalid_mutations: List[str] = []
        insecure_jwt: List[str] = []
        blocking_detach: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 RETURNING OLD AS ..., NEW AS ... Delta Audit
        for mut in mutations:
            mut_id = str(mut.get("statement_id", "unnamed_mutation"))
            uses_pg18_returning_old_new = bool(mut.get("uses_pg18_returning_old_and_new", False))
            verifies_zero_sum_delta = bool(mut.get("verifies_integer_cents_delta_conservation", False))

            if not uses_pg18_returning_old_new or not verifies_zero_sum_delta:
                invalid_mutations.append(mut_id)
                remediations.append(
                    f"Refactor mutation '{mut_id}' to use PostgreSQL 18 `RETURNING OLD AS old_row, NEW AS new_row` and assert `new_row.balance_cents - old_row.balance_cents == delta_cents`."
                )

        # 2. Verify Supabase JWT app_metadata vs user_metadata & Auth Hook Lockdown
        for pol in jwt_policies:
            pol_id = str(pol.get("policy_name", "unnamed_policy"))
            references_user_metadata = bool(pol.get("references_mutable_user_metadata", False))
            uses_app_metadata_initplan = bool(pol.get("uses_select_jwt_app_metadata_initplan", False))
            auth_hook_locked_to_admin = bool(pol.get("custom_access_token_hook_revoked_from_public_anon_authenticated", False))

            if references_user_metadata or not uses_app_metadata_initplan or not auth_hook_locked_to_admin:
                insecure_jwt.append(pol_id)
                remediations.append(
                    f"Eliminate `user_metadata`/`raw_user_meta_data` from policy '{pol_id}'; enforce `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id` and `REVOKE ALL ON FUNCTION public.custom_access_token_hook FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.custom_access_token_hook TO supabase_auth_admin;`."
                )

        # 3. Verify Zero-Downtime DETACH PARTITION ... CONCURRENTLY
        for det in detachments:
            det_id = f"{det.get('parent_table', 'parent')}->{det.get('partition_table', 'child')}"
            uses_concurrently = bool(det.get("uses_detach_partition_concurrently", False))
            avoids_direct_drop_while_attached = bool(det.get("avoids_direct_drop_table_while_attached", False))
            handles_finalize_if_interrupted = bool(det.get("supports_detach_finalize_recovery", False))

            if not uses_concurrently or not avoids_direct_drop_while_attached or not handles_finalize_if_interrupted:
                blocking_detach.append(det_id)
                remediations.append(
                    f"Use `ALTER TABLE {det.get('parent_table', 'parent')} DETACH PARTITION {det.get('partition_table', 'child')} CONCURRENTLY;` (with `FINALIZE` recovery support) before archiving or dropping `{det.get('partition_table', 'child')}`."
                )

        is_valid = (
            len(invalid_mutations) == 0
            and len(insecure_jwt) == 0
            and len(blocking_detach) == 0
        )

        certificate = (
            "Z3_UNSAT_L306_PG18_RETURNING_OLD_NEW_APP_METADATA_RLS_AND_DETACH_CONCURRENTLY_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L306_VIOLATION_DETECTED"
        )

        return PG18ReturningOldNewAppMetadataRlsAndDetachPartitionConcurrentlyReport(
            is_valid=is_valid,
            dml_mutations_checked=len(mutations),
            invalid_returning_old_new_mutations=invalid_mutations,
            jwt_claim_policies_checked=len(jwt_policies),
            insecure_user_metadata_rls_policies=insecure_jwt,
            partition_detachments_checked=len(detachments),
            blocking_partition_detachments=blocking_detach,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


