# --- Merged from node03_v16_6: PG18SkipScanMulticolumnBTreeIndexSupabaseRlsPostgrestEmbeddedResourceGuardAndZeroDowntimeDropColumnProver ---
class PG18SkipScanMulticolumnBTreeIndexSupabaseRlsPostgrestEmbeddedResourceGuardAndZeroDowntimeDropColumnProver:
    """Level 307 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 B-Tree Skip Scan & Multi-Tenant Key Ordering): Composite B-Tree indexes must either place
      `tenant_id` as the leading key for O(log N) tenant-scoped point/range lookups, or if designed for PostgreSQL 18
      B-Tree Skip Scan across a leading status/bucket column, bound the leading column's distinct values (`ndv <= 32`)
      with `tenant_id` in the second position.
    - Inv2 (Supabase PostgREST Embedded Resource Join RLS Guard): Every table reachable via a Foreign Key relationship
      exposed to PostgREST embedded queries (`select('*, target(*)')`) must have `ENABLE ROW LEVEL SECURITY`,
      `FORCE ROW LEVEL SECURITY`, and an initplan-cached `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id`
      policy so embedded joins cannot leak cross-tenant rows.
    - Inv3 (Zero-Downtime Column Drop Discipline): Dropping a column in production must decouple application queries
      and views in phase N-1, forbid `DROP COLUMN ... CASCADE` (which can silently drop dependent RLS policies or views),
      and execute `SET LOCAL lock_timeout = '2s'; ALTER TABLE ... DROP COLUMN ... RESTRICT;`.
    """

    @classmethod
    def verify_pg18_skip_scan_postgrest_embedded_rls_and_drop_column(
        cls, schema_spec: Dict[str, Any]
    ) -> PG18SkipScanPostgrestEmbeddedRlsAndZeroDowntimeDropColumnReport:
        indexes = schema_spec.get("btree_indexes", [])
        fk_relations = schema_spec.get("postgrest_fk_relations", [])
        col_drops = schema_spec.get("column_drops", [])

        bad_indexes: List[str] = []
        rls_gaps: List[str] = []
        unsafe_drops: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 B-Tree Skip Scan & Multi-Tenant Composite Index Ordering
        for idx in indexes:
            idx_name = str(idx.get("index_name", "unnamed_index"))
            cols = list(idx.get("columns", []))
            leading_ndv = int(idx.get("leading_column_ndv", 999999))
            created_concurrently = bool(idx.get("created_concurrently", False))

            valid_tenant_lead = len(cols) >= 1 and cols[0] == "tenant_id"
            valid_pg18_skip_scan = len(cols) >= 2 and cols[1] == "tenant_id" and 1 <= leading_ndv <= 32

            if not created_concurrently or (not valid_tenant_lead and not valid_pg18_skip_scan):
                bad_indexes.append(idx_name)
                remediations.append(
                    f"Rebuild index '{idx_name}' via `CREATE INDEX CONCURRENTLY` with `tenant_id` as the leading column (or second column behind a low-cardinality column with NDV <= 32 for PG18 B-Tree Skip Scan)."
                )

        # 2. Verify Supabase PostgREST Embedded Resource Join RLS Guard
        for rel in fk_relations:
            rel_id = f"{rel.get('source_table', 'src')}->{rel.get('target_table', 'dst')}"
            target_rls_enabled_and_forced = bool(rel.get("target_rls_enabled_and_forced", False))
            target_has_restrictive_app_metadata_policy = bool(
                rel.get("target_has_restrictive_app_metadata_tenant_policy", False)
            )
            fk_indexed_on_source = bool(rel.get("fk_indexed_on_source", False))

            if (
                not target_rls_enabled_and_forced
                or not target_has_restrictive_app_metadata_policy
                or not fk_indexed_on_source
            ):
                rls_gaps.append(rel_id)
                remediations.append(
                    f"Enforce `ENABLE ROW LEVEL SECURITY` + `FORCE ROW LEVEL SECURITY` and an `AS RESTRICTIVE` `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id` policy on embedded target table in '{rel_id}'."
                )

        # 3. Verify Zero-Downtime Column Removal (Contract Phase)
        for drop in col_drops:
            drop_id = f"{drop.get('table_name', 'tbl')}.{drop.get('column_name', 'col')}"
            decoupled_in_prior_release = bool(drop.get("decoupled_from_app_and_views_in_prior_release", False))
            uses_cascade = bool(drop.get("uses_drop_cascade", False))
            has_dependent_rls_or_views = bool(drop.get("has_active_dependent_rls_policies_or_views", False))
            lock_timeout_ms = int(drop.get("lock_timeout_ms", 0))

            if (
                not decoupled_in_prior_release
                or uses_cascade
                or has_dependent_rls_or_views
                or lock_timeout_ms <= 0
                or lock_timeout_ms > 5000
            ):
                unsafe_drops.append(drop_id)
                remediations.append(
                    f"Decouple '{drop_id}' from all queries/views in release N-1, remove dependent RLS/view references explicitly, and execute `SET LOCAL lock_timeout = '2s'; ALTER TABLE ... DROP COLUMN ... RESTRICT;` without `CASCADE`."
                )

        is_valid = (
            len(bad_indexes) == 0
            and len(rls_gaps) == 0
            and len(unsafe_drops) == 0
        )

        certificate = (
            "Z3_UNSAT_L307_PG18_SKIP_SCAN_POSTGREST_EMBEDDED_RLS_AND_DROP_COLUMN_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L307_VIOLATION_DETECTED"
        )

        return PG18SkipScanPostgrestEmbeddedRlsAndZeroDowntimeDropColumnReport(
            is_valid=is_valid,
            btree_indexes_checked=len(indexes),
            suboptimal_skip_scan_indexes=bad_indexes,
            postgrest_fk_relations_checked=len(fk_relations),
            exposed_postgrest_fk_rls_gaps=rls_gaps,
            column_drops_checked=len(col_drops),
            unsafe_column_drops=unsafe_drops,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


