# --- Merged from node03_v16_6: PG18AsyncIoMethodWorkerUringTuningSupabaseRlsVaultSecretDecryptionConfinementAndZeroDowntimeEnumEvolutionProver ---
class PG18AsyncIoMethodWorkerUringTuningSupabaseRlsVaultSecretDecryptionConfinementAndZeroDowntimeEnumEvolutionProver:
    """Level 308 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 Asynchronous I/O Subsystem Tuning): PostgreSQL 18 deployments must set `io_method` to `'worker'`
      or `'io_uring'` (never legacy blocking `'sync'`), with `effective_io_concurrency >= 16`,
      `maintenance_io_concurrency >= 16`, and `128 <= io_combine_limit_kb <= 1024`.
    - Inv2 (Supabase Vault `vault.decrypted_secrets` Multi-Tenant Confinement): Direct access to `vault.decrypted_secrets`
      must be revoked from `PUBLIC`, `anon`, and `authenticated`. Any wrapper RPC must enforce `SET search_path = ''`,
      bind `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id`, and never return raw plaintext
      secrets across tenant boundaries.
    - Inv3 (Zero-Downtime Enum / Domain Evolution): Schema migrations must never rewrite a table via
      `ALTER TABLE ... ALTER COLUMN ... TYPE new_enum` to remove or rename an enum value; instead, additions must
      use `ALTER TYPE ... ADD VALUE IF NOT EXISTS` and removals/transitions must use a non-blocking
      `ADD CONSTRAINT ... CHECK (...) NOT VALID` + `VALIDATE CONSTRAINT` under `lock_timeout <= 2000ms`.
    """

    @classmethod
    def verify_pg18_aio_vault_secret_rls_and_enum_evolution(
        cls, cluster_spec: Dict[str, Any]
    ) -> PG18AsyncIoVaultSecretRlsAndZeroDowntimeEnumEvolutionReport:
        aio_configs = cluster_spec.get("pg18_aio_configs", [])
        vault_accessors = cluster_spec.get("vault_secret_accessors", [])
        enum_migrations = cluster_spec.get("enum_migrations", [])

        bad_aio: List[str] = []
        bad_vault: List[str] = []
        bad_enum: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Asynchronous I/O Subsystem Configuration
        for cfg in aio_configs:
            node_id = str(cfg.get("instance_id", "unnamed_instance"))
            io_method = str(cfg.get("io_method", "sync")).lower()
            eff_conc = int(cfg.get("effective_io_concurrency", 1))
            maint_conc = int(cfg.get("maintenance_io_concurrency", 1))
            combine_kb = int(cfg.get("io_combine_limit_kb", 0))

            if (
                io_method not in ("worker", "io_uring")
                or eff_conc < 16
                or maint_conc < 16
                or not (128 <= combine_kb <= 1024)
            ):
                bad_aio.append(node_id)
                remediations.append(
                    f"Configure PostgreSQL 18 instance '{node_id}' with `io_method = 'io_uring'` (or `'worker'`), `effective_io_concurrency = 32`, `maintenance_io_concurrency = 32`, and `io_combine_limit = '256kB'`."
                )

        # 2. Verify Supabase Vault Multi-Tenant Secret Confinement
        for acc in vault_accessors:
            acc_id = str(acc.get("accessor_name", "unnamed_accessor"))
            revoked_direct_decrypted_view = bool(acc.get("revoked_direct_decrypted_secrets_from_public_anon_authenticated", False))
            enforces_empty_search_path = bool(acc.get("enforces_empty_search_path", False))
            enforces_app_metadata_tenant_match = bool(acc.get("enforces_app_metadata_tenant_id_match", False))

            if (
                not revoked_direct_decrypted_view
                or not enforces_empty_search_path
                or not enforces_app_metadata_tenant_match
            ):
                bad_vault.append(acc_id)
                remediations.append(
                    f"Lock down Vault accessor '{acc_id}': `REVOKE ALL ON vault.decrypted_secrets FROM PUBLIC, anon, authenticated;`, set `SET search_path = ''`, and enforce `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id`."
                )

        # 3. Verify Zero-Downtime Enum / State Domain Evolution
        for em in enum_migrations:
            em_id = str(em.get("migration_id", "unnamed_enum_migration"))
            rewrites_table_with_alter_column_type = bool(em.get("rewrites_table_with_alter_column_type", False))
            uses_add_value_if_not_exists_or_not_valid_check = bool(
                em.get("uses_add_value_if_not_exists_or_not_valid_check", False)
            )
            lock_timeout_ms = int(em.get("lock_timeout_ms", 0))

            if (
                rewrites_table_with_alter_column_type
                or not uses_add_value_if_not_exists_or_not_valid_check
                or lock_timeout_ms <= 0
                or lock_timeout_ms > 5000
            ):
                bad_enum.append(em_id)
                remediations.append(
                    f"Refactor enum migration '{em_id}' to avoid `ALTER COLUMN ... TYPE` table rewrites; use `ALTER TYPE ... ADD VALUE IF NOT EXISTS` or `ADD CONSTRAINT ... CHECK (...) NOT VALID` + `VALIDATE CONSTRAINT` under `lock_timeout = '2s'`."
                )

        is_valid = (
            len(bad_aio) == 0
            and len(bad_vault) == 0
            and len(bad_enum) == 0
        )

        certificate = (
            "Z3_UNSAT_L308_PG18_AIO_VAULT_SECRET_RLS_AND_ZERO_DOWNTIME_ENUM_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L308_VIOLATION_DETECTED"
        )

        return PG18AsyncIoVaultSecretRlsAndZeroDowntimeEnumEvolutionReport(
            is_valid=is_valid,
            aio_configs_checked=len(aio_configs),
            suboptimal_pg18_aio_configs=bad_aio,
            vault_accessors_checked=len(vault_accessors),
            vulnerable_vault_secret_accessors=bad_vault,
            enum_migrations_checked=len(enum_migrations),
            unsafe_enum_type_rewrites=bad_enum,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


