# --- Merged from node03_v16_6: PG18ParallelGinIndexBuildMaintenanceWorkMemSupabaseRlsPgvectorHnswIterativeScanAndZeroDowntimeReindexConcurrentlyProver ---
class PG18ParallelGinIndexBuildMaintenanceWorkMemSupabaseRlsPgvectorHnswIterativeScanAndZeroDowntimeReindexConcurrentlyProver:
    """Level 311 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 Parallel GIN Index Build & Pending-List Bounds): Multi-tenant JSONB/FTS GIN indexes in PostgreSQL 18
      must be built via `CREATE INDEX CONCURRENTLY ... USING gin` with `max_parallel_maintenance_workers >= 2`,
      `maintenance_work_mem_mb >= 256`, and `gin_pending_list_limit_kb <= 4096` to prevent fastupdate flush stalls.
    - Inv2 (Supabase `pgvector` HNSW Iterative Scan under Multi-Tenant RLS): Vector similarity queries on RLS-protected
      multi-tenant tables must enable `hnsw.iterative_scan IN ('relaxed_order', 'strict_order')` and enforce an
      `AS RESTRICTIVE` `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id` filter so HNSW post-filtering
      never returns incomplete top-k results for smaller tenants.
    - Inv3 (Zero-Downtime `REINDEX INDEX CONCURRENTLY` & Invalid Artifact Cleanup): Index bloat remediation must use
      `REINDEX INDEX CONCURRENTLY`, verify `pg_index.indisvalid = true`, and drop any leftover invalid `_ccnew`/`_ccold`
      indexes via `DROP INDEX CONCURRENTLY`.
    """

    @classmethod
    def verify_pg18_parallel_gin_pgvector_iterative_rls_and_reindex_concurrently(
        cls, index_spec: Dict[str, Any]
    ) -> PG18ParallelGinPgvectorHnswIterativeScanRlsAndReindexConcurrentlyReport:
        gin_indexes = index_spec.get("pg18_gin_indexes", [])
        vector_indexes = index_spec.get("pgvector_rls_indexes", [])
        reindex_ops = index_spec.get("reindex_operations", [])

        bad_gin: List[str] = []
        bad_vec: List[str] = []
        bad_reindex: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Parallel GIN Index Build & Pending-List Bounds
        for gidx in gin_indexes:
            idx_name = str(gidx.get("index_name", "unnamed_gin_index"))
            created_concurrently = bool(gidx.get("created_concurrently", False))
            parallel_workers = int(gidx.get("max_parallel_maintenance_workers", 0))
            maint_mem_mb = int(gidx.get("maintenance_work_mem_mb", 64))
            pending_limit_kb = int(gidx.get("gin_pending_list_limit_kb", 8192))

            if (
                not created_concurrently
                or parallel_workers < 2
                or maint_mem_mb < 256
                or pending_limit_kb > 4096
            ):
                bad_gin.append(idx_name)
                remediations.append(
                    f"Build GIN index '{idx_name}' in PostgreSQL 18 with `CREATE INDEX CONCURRENTLY`, `max_parallel_maintenance_workers = 4`, `maintenance_work_mem = '512MB'`, and `WITH (gin_pending_list_limit = 2048)`."
                )

        # 2. Verify Supabase pgvector HNSW Iterative Scan under Multi-Tenant RLS
        for vidx in vector_indexes:
            v_name = str(vidx.get("index_name", "unnamed_hnsw_index"))
            iterative_mode = str(vidx.get("hnsw_iterative_scan_mode", "off")).lower()
            has_restrictive_app_metadata_rls = bool(vidx.get("enforces_restrictive_app_metadata_tenant_rls", False))
            created_concurrently = bool(vidx.get("created_concurrently", False))

            if (
                iterative_mode not in ("relaxed_order", "strict_order")
                or not has_restrictive_app_metadata_rls
                or not created_concurrently
            ):
                bad_vec.append(v_name)
                remediations.append(
                    f"Configure `pgvector` HNSW index '{v_name}' with `SET LOCAL hnsw.iterative_scan = 'relaxed_order';`, build via `CREATE INDEX CONCURRENTLY`, and enforce an `AS RESTRICTIVE` `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id` RLS policy."
                )

        # 3. Verify Zero-Downtime REINDEX INDEX CONCURRENTLY & Invalid Artifact Cleanup
        for rop in reindex_ops:
            op_id = str(rop.get("target_index", "unnamed_reindex_target"))
            uses_concurrently = bool(rop.get("uses_reindex_concurrently", False))
            verifies_indisvalid = bool(rop.get("verifies_pg_index_indisvalid_true", False))
            cleans_up_ccnew_ccold = bool(rop.get("drops_invalid_ccnew_ccold_concurrently", False))

            if not uses_concurrently or not verifies_indisvalid or not cleans_up_ccnew_ccold:
                bad_reindex.append(op_id)
                remediations.append(
                    f"Execute `REINDEX INDEX CONCURRENTLY {op_id};`, verify `indisvalid = true` in `pg_index`, and clean up any residual invalid `_ccnew`/`_ccold` indexes with `DROP INDEX CONCURRENTLY`."
                )

        is_valid = (
            len(bad_gin) == 0
            and len(bad_vec) == 0
            and len(bad_reindex) == 0
        )

        certificate = (
            "Z3_UNSAT_L311_PG18_PARALLEL_GIN_PGVECTOR_ITERATIVE_RLS_AND_REINDEX_CONCURRENTLY_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L311_VIOLATION_DETECTED"
        )

        return PG18ParallelGinPgvectorHnswIterativeScanRlsAndReindexConcurrentlyReport(
            is_valid=is_valid,
            gin_indexes_checked=len(gin_indexes),
            suboptimal_pg18_gin_indexes=bad_gin,
            pgvector_rls_indexes_checked=len(vector_indexes),
            starvation_prone_pgvector_rls_indexes=bad_vec,
            reindex_operations_checked=len(reindex_ops),
            unsafe_reindex_operations=bad_reindex,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


