# --- Merged from node03_v16_6: PG18PgStatIoPerBackendWalTrackingSupabaseRlsPgCronJobTenantContextConfinementAndZeroDowntimePrimaryKeySwapProver ---
class PG18PgStatIoPerBackendWalTrackingSupabaseRlsPgCronJobTenantContextConfinementAndZeroDowntimePrimaryKeySwapProver:
    """Level 312 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 `pg_stat_io` Byte-Granular & Per-Backend WAL I/O Telemetry): PostgreSQL 18 clusters must enable
      `track_io_timing = on` and `track_wal_io_timing = on`, and monitor `pg_stat_io` byte counters
      (`read_bytes`, `write_bytes`, `extend_bytes` across `object IN ('relation', 'wal')`) plus `pg_stat_get_backend_io(pid)`.
    - Inv2 (Supabase `pg_cron` Multi-Tenant RLS Confinement): Scheduled jobs in `pg_cron` must never execute tenant
      DML under a superuser/`BYPASSRLS` role without explicitly dropping privileges via `SET LOCAL ROLE`, binding
      `request.jwt.claims` (`app_metadata.tenant_id`), enforcing `SET search_path = ''`, and revoking `cron` schema
      privileges from `PUBLIC`, `anon`, and `authenticated`.
    - Inv3 (Zero-Downtime Primary Key Swap via `PRIMARY KEY USING INDEX`): Replacing a primary key on a live table
      must pre-build a `UNIQUE INDEX CONCURRENTLY` leading with `tenant_id`, pre-validate `NOT NULL` via
      `CHECK (... IS NOT NULL) NOT VALID` + `VALIDATE CONSTRAINT`, and execute `DROP CONSTRAINT ..., ADD CONSTRAINT ... PRIMARY KEY USING INDEX ...`
      under `SET LOCAL lock_timeout = '2s'`.
    """

    @classmethod
    def verify_pg18_stat_io_pg_cron_rls_and_pk_swap(
        cls, cluster_spec: Dict[str, Any]
    ) -> PG18PgStatIoPerBackendWalPgCronRlsAndZeroDowntimePkSwapReport:
        io_nodes = cluster_spec.get("pg18_io_telemetry_nodes", [])
        cron_jobs = cluster_spec.get("pg_cron_jobs", [])
        pk_swaps = cluster_spec.get("pk_swap_migrations", [])

        bad_io: List[str] = []
        bad_cron: List[str] = []
        bad_pk: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 pg_stat_io Byte Counters & Per-Backend WAL I/O Telemetry
        for node in io_nodes:
            node_id = str(node.get("node_id", "unnamed_node"))
            track_io_timing = bool(node.get("track_io_timing_enabled", False))
            track_wal_io_timing = bool(node.get("track_wal_io_timing_enabled", False))
            monitors_byte_counters = bool(node.get("monitors_read_write_extend_bytes_and_wal_object", False))
            monitors_per_backend_io = bool(node.get("monitors_pg_stat_get_backend_io", False))

            if (
                not track_io_timing
                or not track_wal_io_timing
                or not monitors_byte_counters
                or not monitors_per_backend_io
            ):
                bad_io.append(node_id)
                remediations.append(
                    f"Enable `track_io_timing = on` and `track_wal_io_timing = on` on '{node_id}', and monitor PG18 `pg_stat_io` (`read_bytes`, `write_bytes`, `extend_bytes` for `relation` and `wal`) plus `pg_stat_get_backend_io(pid)`."
                )

        # 2. Verify Supabase pg_cron Multi-Tenant Role & JWT Context Confinement
        for job in cron_jobs:
            job_name = str(job.get("job_name", "unnamed_cron_job"))
            revoked_cron_from_public = bool(job.get("revoked_cron_schema_from_public_anon_authenticated", False))
            switches_to_non_bypassrls_role = bool(job.get("switches_local_role_to_rls_enforced_role", False))
            binds_tenant_jwt_claims = bool(job.get("binds_local_request_jwt_claims_app_metadata_tenant_id", False))
            enforces_empty_search_path = bool(job.get("enforces_empty_search_path", False))

            if (
                not revoked_cron_from_public
                or not switches_to_non_bypassrls_role
                or not binds_tenant_jwt_claims
                or not enforces_empty_search_path
            ):
                bad_cron.append(job_name)
