# --- Merged from node03_v16_6: PG18ExplainBuffersDefaultAutoExplainPlanDriftSupabaseRlsGraphqlMaxDepthIntrospectionGuardAndZeroDowntimeSequenceBigintUpgradeProver ---
class PG18ExplainBuffersDefaultAutoExplainPlanDriftSupabaseRlsGraphqlMaxDepthIntrospectionGuardAndZeroDowntimeSequenceBigintUpgradeProver:
    """Level 313 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 `EXPLAIN (ANALYZE)` Default `BUFFERS` & Auto-Explain Guard): Multi-tenant queries audited under
      PostgreSQL 18 `EXPLAIN (ANALYZE)` (which includes `BUFFERS` by default) must exhibit `temp_written_blocks == 0`,
      avoid `Seq Scan` on tables with `rows > 1000`, and keep `auto_explain.log_buffers = on`.
    - Inv2 (Supabase `pg_graphql` Depth & RLS Isolation Guard): GraphQL endpoints backed by `pg_graphql` must enforce
      `max_depth <= 5`, disable unauthenticated schema introspection in production, and require `FORCE ROW LEVEL SECURITY`
      with an `AS RESTRICTIVE` `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id` policy on all
      exposed node and edge tables.
    - Inv3 (Zero-Downtime Sequence `bigint` Upgrade & Overflow Guard): Sequences and identity columns must use 64-bit
      `bigint` (`int8`) or `uuidv7()` with utilization `< 70%`, and any upgrade from 32-bit `int4` on a populated table
      must use the Expand-Contract dual-write + `CREATE UNIQUE INDEX CONCURRENTLY` protocol instead of a blocking
      `ALTER COLUMN ... TYPE bigint` table rewrite.
    """

    @classmethod
    def verify_pg18_explain_buffers_pg_graphql_rls_and_bigint_sequence(
        cls, audit_spec: Dict[str, Any]
    ) -> PG18ExplainBuffersAutoExplainPgGraphqlRlsAndBigintSequenceReport:
        explain_plans = audit_spec.get("pg18_explain_plans", [])
        graphql_endpoints = audit_spec.get("pg_graphql_endpoints", [])
        sequences = audit_spec.get("sequence_columns", [])

        bad_plans: List[str] = []
        bad_gql: List[str] = []
        bad_seq: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 EXPLAIN (ANALYZE) Default BUFFERS & Zero Temp-Block / Seq-Scan Guard
        for plan in explain_plans:
            q_id = str(plan.get("query_id", "unnamed_query"))
            buffers_present = bool(plan.get("buffers_metrics_captured", False))
            temp_written_blocks = int(plan.get("temp_written_blocks", 0))
            uses_seq_scan_on_large_table = bool(plan.get("uses_seq_scan_on_large_tenant_table", False))

            if not buffers_present or temp_written_blocks > 0 or uses_seq_scan_on_large_table:
                bad_plans.append(q_id)
                remediations.append(
                    f"Optimize query '{q_id}' using PG18 `EXPLAIN (ANALYZE)` default `BUFFERS` telemetry: eliminate `Temp Written Blocks` ({temp_written_blocks}) via composite `(tenant_id, ...)` index and raise `work_mem`."
                )

        # 2. Verify Supabase pg_graphql Depth Ceiling, Introspection Lockdown & Multi-Tenant RLS
        for gql in graphql_endpoints:
            ep_name = str(gql.get("endpoint_name", "unnamed_graphql_endpoint"))
            max_depth = int(gql.get("max_query_depth", 99))
            introspection_disabled_for_anon = bool(gql.get("introspection_disabled_for_anon", False))
            all_edges_enforce_restrictive_rls = bool(gql.get("all_reachable_tables_enforce_restrictive_tenant_rls", False))

            if max_depth > 5 or max_depth <= 0 or not introspection_disabled_for_anon or not all_edges_enforce_restrictive_rls:
                bad_gql.append(ep_name)
                remediations.append(
                    f"Harden `pg_graphql` endpoint '{ep_name}': enforce `max_query_depth <= 5`, disable anonymous introspection, and apply `FORCE ROW LEVEL SECURITY` + `AS RESTRICTIVE` tenant policies on all reachable edge tables."
                )

        # 3. Verify Zero-Downtime Sequence Bigint Upgrade & Overflow Prevention
        for seq in sequences:
            seq_id = f"{seq.get('table_name', 'tbl')}.{seq.get('column_name', 'id')}"
            data_type = str(seq.get("data_type", "integer")).lower()
            utilization_ratio = float(seq.get("sequence_utilization_ratio", 1.0))
            uses_blocking_alter_type = bool(seq.get("uses_direct_alter_column_type_bigint", False))
            uses_expand_contract_if_migrating = bool(seq.get("uses_expand_contract_if_upgrading_int4", True))

            if (
                data_type not in ("bigint", "int8", "uuid")
                or utilization_ratio >= 0.70
                or uses_blocking_alter_type
                or not uses_expand_contract_if_migrating
            ):
                bad_seq.append(seq_id)
                remediations.append(
                    f"Upgrade `{seq_id}` to `bigint GENERATED ALWAYS AS IDENTITY` (or PG18 `uuidv7()`) using the 4-phase Expand-Contract migration (`ADD COLUMN id_bigint`, dual-write trigger + batched backfill, `CREATE UNIQUE INDEX CONCURRENTLY`, and atomic PK swap) without `ALTER COLUMN TYPE` table rewrite."
                )

        is_valid = (
            len(bad_plans) == 0
            and len(bad_gql) == 0
            and len(bad_seq) == 0
        )

        certificate = (
            "Z3_UNSAT_L313_PG18_EXPLAIN_BUFFERS_PG_GRAPHQL_RLS_AND_BIGINT_SEQUENCE_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L313_VIOLATION_DETECTED"
        )

        return PG18ExplainBuffersAutoExplainPgGraphqlRlsAndBigintSequenceReport(
            is_valid=is_valid,
            explain_plans_checked=len(explain_plans),
            regressed_pg18_explain_buffer_plans=bad_plans,
            graphql_endpoints_checked=len(graphql_endpoints),
            vulnerable_pg_graphql_endpoints=bad_gql,
            sequences_checked=len(sequences),
            overflow_or_rewriting_sequences=bad_seq,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


