# --- Merged from node03_v16_6: PG18OAuthBearerValidatorConnectionSecuritySupabaseRlsSupavisorTransactionPoolPreparedStatementAndZeroDowntimeDefaultBackfillProver ---
class PG18OAuthBearerValidatorConnectionSecuritySupabaseRlsSupavisorTransactionPoolPreparedStatementAndZeroDowntimeDefaultBackfillProver:
    """Level 314 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 Native `oauth` / `scram-sha-256` HBA & Validator Security): PostgreSQL 18 `pg_hba.conf` entries must
      enforce `hostssl`, use `oauth` (with `oauth_validator_libraries`, explicit `issuer`, and `scope`) or `scram-sha-256`,
      and forbid legacy `md5`, `password`, or `trust`.
    - Inv2 (Supabase Supavisor Transaction-Mode Pool Isolation): Connections through transaction-mode pooling (`port 6543`)
      must never execute session-level `SET` (`set_config(..., false)`) which bleeds tenant state across pooled transactions;
      all context settings must use `SET LOCAL` (`set_config(..., true)`) combined with `AS RESTRICTIVE` `app_metadata.tenant_id` RLS.
    - Inv3 (Zero-Downtime Fast-Default Column Addition): Adding a column with a `DEFAULT` on an existing table must use
      a non-volatile expression so PostgreSQL uses `pg_attribute.attmissingval` metadata-only fast defaults, or split a
      volatile default into `ADD COLUMN` (nullable) + `ALTER COLUMN SET DEFAULT` + batched backfill under `lock_timeout <= 2000ms`.
    """

    @classmethod
    def verify_pg18_oauth_supavisor_pool_rls_and_fast_default(
        cls, audit_spec: Dict[str, Any]
    ) -> PG18OAuthValidatorSupavisorPoolRlsAndFastDefaultColumnReport:
        hba_entries = audit_spec.get("pg18_hba_entries", [])
        pool_configs = audit_spec.get("supavisor_pool_configs", [])
        add_cols = audit_spec.get("add_column_migrations", [])

        bad_hba: List[str] = []
        bad_pool: List[str] = []
        bad_cols: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Native OAuth / SCRAM-SHA-256 & hostssl HBA Security
        for entry in hba_entries:
            rule_id = str(entry.get("rule_id", "unnamed_hba_rule"))
            conn_type = str(entry.get("connection_type", "host")).lower()
            auth_method = str(entry.get("auth_method", "md5")).lower()
            has_valid_oauth_issuer_scope = bool(entry.get("has_valid_oauth_validator_issuer_and_scope", True))

            if (
                conn_type != "hostssl"
                or auth_method not in ("oauth", "scram-sha-256")
                or (auth_method == "oauth" and not has_valid_oauth_issuer_scope)
            ):
                bad_hba.append(rule_id)
                remediations.append(
                    f"Harden PG18 `pg_hba.conf` rule '{rule_id}' to require `hostssl` with `oauth` (backed by `oauth_validator_libraries`, `issuer`, and `scope`) or `scram-sha-256`."
                )

        # 2. Verify Supabase Supavisor Transaction-Mode Pool Isolation (No Session-Level SET Bleed)
        for pcfg in pool_configs:
            pool_id = str(pcfg.get("pool_name", "unnamed_pool"))
            uses_session_level_set = bool(pcfg.get("uses_session_level_set_or_set_config_false", False))
            enforces_set_local_only = bool(pcfg.get("enforces_set_local_or_set_config_true", False))
            enforces_restrictive_rls = bool(pcfg.get("enforces_restrictive_app_metadata_tenant_rls", False))

            if uses_session_level_set or not enforces_set_local_only or not enforces_restrictive_rls:
                bad_pool.append(pool_id)
                remediations.append(
                    f"Eliminate session-level `SET` / `set_config(..., false)` on Supavisor transaction pool '{pool_id}'; use strictly transaction-scoped `SET LOCAL` / `set_config(..., true)` and `AS RESTRICTIVE` `app_metadata.tenant_id` RLS."
                )

        # 3. Verify Zero-Downtime Fast-Default Column Addition
        for col in add_cols:
            col_id = f"{col.get('table_name', 'tbl')}.{col.get('column_name', 'col')}"
            has_inline_volatile_default = bool(col.get("has_inline_volatile_default_on_add_column", False))
            uses_fast_default_or_split_backfill = bool(col.get("uses_non_volatile_fast_default_or_split_backfill", False))
            lock_timeout_ms = int(col.get("lock_timeout_ms", 0))

            if (
                has_inline_volatile_default
                or not uses_fast_default_or_split_backfill
                or lock_timeout_ms <= 0
                or lock_timeout_ms > 5000
            ):
                bad_cols.append(col_id)
                remediations.append(
                    f"Refactor `ADD COLUMN` on `{col_id}`: avoid inline volatile `DEFAULT` (which forces an `ACCESS EXCLUSIVE` table rewrite); use a non-volatile fast default (`attmissingval`) or split into `ADD COLUMN` nullable + `ALTER COLUMN SET DEFAULT` + batched backfill under `lock_timeout = '2s'`."
                )

        is_valid = (
            len(bad_hba) == 0
            and len(bad_pool) == 0
            and len(bad_cols) == 0
        )

        certificate = (
            "Z3_UNSAT_L314_PG18_OAUTH_SUPAVISOR_POOL_RLS_AND_FAST_DEFAULT_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L314_VIOLATION_DETECTED"
        )

        return PG18OAuthValidatorSupavisorPoolRlsAndFastDefaultColumnReport(
            is_valid=is_valid,
            hba_entries_checked=len(hba_entries),
            insecure_pg18_hba_entries=bad_hba,
            pool_configs_checked=len(pool_configs),
            session_bleed_pool_configs=bad_pool,
            add_column_defaults_checked=len(add_cols),
            rewriting_volatile_add_columns=bad_cols,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


