# --- Merged from node03_v16_6: PG18PgChecksumsDataIntegrityVerificationSupabaseRlsPostgresFdwUserMappingConfinementAndZeroDowntimeTableSplitVerticalPartitionProver ---
class PG18PgChecksumsDataIntegrityVerificationSupabaseRlsPostgresFdwUserMappingConfinementAndZeroDowntimeTableSplitVerticalPartitionProver:
    """Level 315 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 Default `data_checksums = on` & Zero Checksum Failures): PostgreSQL 18 clusters must enforce
      `data_checksums = on`, `ignore_checksum_failure = off`, and `checksum_failures == 0` in `pg_stat_database`.
    - Inv2 (Supabase Foreign Data Wrapper `FOREIGN TABLE` Multi-Tenant Confinement): Because PostgreSQL `FOREIGN TABLE`
      objects do not support native RLS, they must never reside in `public`, must forbid `USER MAPPING FOR PUBLIC`,
      must revoke direct access from `PUBLIC`/`anon`/`authenticated`, and must be exposed only via a tenant-filtered
      wrapper pushing down `tenant_id = (SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid`.
    - Inv3 (Zero-Downtime Vertical Table Split): Splitting cold payload columns out of a hot table must use a
      sidecar table with `PRIMARY KEY (tenant_id, parent_id)`, dual-write trigger + batched backfill, `NOT VALID` +
      `VALIDATE CONSTRAINT` FK, and `DROP COLUMN ... RESTRICT` under `SET LOCAL lock_timeout = '2s'`.
    """

    @classmethod
    def verify_pg18_checksums_fdw_confinement_and_vertical_split(
        cls, audit_spec: Dict[str, Any]
    ) -> PG18DataChecksumsFdwTenantConfinementAndVerticalTableSplitReport:
        clusters = audit_spec.get("pg18_checksum_clusters", [])
        foreign_tables = audit_spec.get("fdw_foreign_tables", [])
        vertical_splits = audit_spec.get("vertical_table_splits", [])

        bad_clusters: List[str] = []
        bad_fdw: List[str] = []
        bad_splits: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Default data_checksums = on & Zero Checksum Failures
        for cl in clusters:
            cl_id = str(cl.get("cluster_id", "unnamed_cluster"))
            checksums_on = bool(cl.get("data_checksums_enabled", False))
            ignore_failure = bool(cl.get("ignore_checksum_failure_enabled", True))
            failures_count = int(cl.get("checksum_failures_count", 1))

            if not checksums_on or ignore_failure or failures_count != 0:
                bad_clusters.append(cl_id)
                remediations.append(
                    f"Enforce `data_checksums = on` and `ignore_checksum_failure = off` on PG18 cluster '{cl_id}', and verify `pg_stat_database.checksum_failures == 0`."
                )

        # 2. Verify Supabase Foreign Data Wrapper (FOREIGN TABLE) Multi-Tenant Confinement
        for ft in foreign_tables:
            ft_name = str(ft.get("foreign_table_name", "unnamed_foreign_table"))
            in_private_schema = bool(ft.get("resides_in_private_schema_not_public", False))
            forbids_public_user_mapping = bool(ft.get("forbids_user_mapping_for_public", False))
            revoked_from_client_roles = bool(ft.get("revoked_from_public_anon_authenticated", False))
            pushes_down_app_metadata_tenant_id = bool(ft.get("wrapper_pushes_down_app_metadata_tenant_id", False))

            if (
                not in_private_schema
                or not forbids_public_user_mapping
                or not revoked_from_client_roles
                or not pushes_down_app_metadata_tenant_id
            ):
                bad_fdw.append(ft_name)
                remediations.append(
                    f"Move foreign table `{ft_name}` to `private_fdw` schema, drop `USER MAPPING FOR PUBLIC`, `REVOKE ALL FROM PUBLIC, anon, authenticated`, and expose only via a wrapper filtering `tenant_id = (SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid`."
                )

        # 3. Verify Zero-Downtime Vertical Table Split (Hot/Cold Decomposition)
        for sp in vertical_splits:
            sp_id = f"{sp.get('hot_table', 'hot')}->{sp.get('cold_sidecar_table', 'cold')}"
            has_composite_tenant_pk = bool(sp.get("sidecar_has_composite_tenant_id_pk", False))
            uses_dual_write_and_batched_backfill = bool(sp.get("uses_dual_write_trigger_and_batched_backfill", False))
            uses_not_valid_fk_and_drop_restrict = bool(sp.get("uses_not_valid_fk_and_drop_column_restrict", False))
            lock_timeout_ms = int(sp.get("lock_timeout_ms", 0))

            if (
                not has_composite_tenant_pk
                or not uses_dual_write_and_batched_backfill
                or not uses_not_valid_fk_and_drop_restrict
                or lock_timeout_ms <= 0
                or lock_timeout_ms > 5000
            ):
                bad_splits.append(sp_id)
                remediations.append(
                    f"Execute zero-downtime vertical split `{sp_id}` with sidecar `PRIMARY KEY (tenant_id, parent_id)`, dual-write trigger + batched backfill, `NOT VALID`/`VALIDATE CONSTRAINT` FK, and `DROP COLUMN ... RESTRICT` under `lock_timeout = '2s'`."
                )

        is_valid = (
            len(bad_clusters) == 0
            and len(bad_fdw) == 0
            and len(bad_splits) == 0
        )

        certificate = (
            "Z3_UNSAT_L315_PG18_CHECKSUMS_FDW_CONFINEMENT_AND_VERTICAL_SPLIT_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L315_VIOLATION_DETECTED"
        )

        return PG18DataChecksumsFdwTenantConfinementAndVerticalTableSplitReport(
            is_valid=is_valid,
            checksum_clusters_checked=len(clusters),
            unprotected_checksum_clusters=bad_clusters,
            foreign_tables_checked=len(foreign_tables),
            exposed_fdw_foreign_tables=bad_fdw,
            vertical_splits_checked=len(vertical_splits),
            unsafe_vertical_table_splits=bad_splits,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


