# --- Merged from node03_v16_6: PG18PgUpgradeOptimizerStatisticsCarryoverSupabaseRlsEdgeFunctionServiceRoleBypassGuardAndZeroDowntimeCheckConstraintModificationProver ---
class PG18PgUpgradeOptimizerStatisticsCarryoverSupabaseRlsEdgeFunctionServiceRoleBypassGuardAndZeroDowntimeCheckConstraintModificationProver:
    """Level 316 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 `pg_upgrade` Optimizer Statistics Carryover): Major version upgrade pipelines to PostgreSQL 18 must
      enable native optimizer statistics carryover (`pg_upgrade` / `pg_dump --statistics`) and run targeted `ANALYZE`
      on tables with multi-column `CREATE STATISTICS` before opening client traffic to prevent plan-flip outages.
    - Inv2 (Supabase Edge Function `service_role` Bypass Prevention): User-invoked Edge Functions and Server Actions
      must never instantiate a `SUPABASE_SERVICE_ROLE_KEY` client (`BYPASSRLS`); they must use `SUPABASE_ANON_KEY` and
      forward the caller's `Authorization: Bearer <jwt>` header so PostgreSQL enforces `AS RESTRICTIVE` `app_metadata.tenant_id` RLS.
    - Inv3 (Zero-Downtime `CHECK` Constraint Replacement): Modifying a `CHECK` constraint must add the new constraint
      as `NOT VALID` under `SET LOCAL lock_timeout = '2s'`, run `VALIDATE CONSTRAINT` (under `SHARE UPDATE EXCLUSIVE`),
      and only then `DROP CONSTRAINT` on the old constraint, avoiding both `ACCESS EXCLUSIVE` scans and unvalidated gaps.
    """

    @classmethod
    def verify_pg18_upgrade_stats_edge_function_rls_and_check_replace(
        cls, audit_spec: Dict[str, Any]
    ) -> PG18UpgradeStatsCarryoverEdgeFunctionRlsAndCheckConstraintReplaceReport:
        upgrades = audit_spec.get("pg18_upgrade_pipelines", [])
        edge_fns = audit_spec.get("supabase_edge_functions", [])
        check_replacements = audit_spec.get("check_constraint_replacements", [])

        bad_upgrades: List[str] = []
        bad_edge: List[str] = []
        bad_checks: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 pg_upgrade Optimizer Statistics Carryover & Extended Stats Analyze
        for upg in upgrades:
            pipe_id = str(upg.get("pipeline_id", "unnamed_upgrade_pipeline"))
            carries_over_stats = bool(upg.get("preserves_optimizer_statistics_in_pg18_upgrade", False))
            analyzes_extended_stats = bool(upg.get("analyzes_extended_statistics_before_traffic_cutover", False))

            if not carries_over_stats or not analyzes_extended_stats:
                bad_upgrades.append(pipe_id)
                remediations.append(
                    f"Enable PostgreSQL 18 optimizer statistics carryover in `pg_upgrade` pipeline '{pipe_id}' and run `ANALYZE` on tables with extended statistics before traffic cutover."
                )

        # 2. Verify Supabase Edge Functions Forward User Authorization Header Instead of service_role
        for fn in edge_fns:
            fn_name = str(fn.get("function_name", "unnamed_edge_function"))
            is_user_facing = bool(fn.get("is_user_facing_endpoint", True))
            uses_service_role_key = bool(fn.get("uses_supabase_service_role_key", False))
            forwards_user_auth_header = bool(fn.get("forwards_caller_authorization_jwt_header", False))

            if is_user_facing and (uses_service_role_key or not forwards_user_auth_header):
                bad_edge.append(fn_name)
                remediations.append(
                    f"Refactor user-facing Edge Function '{fn_name}': replace `SUPABASE_SERVICE_ROLE_KEY` with `SUPABASE_ANON_KEY` and pass `global: {{ headers: {{ Authorization: req.headers.get('Authorization')! }} }}` to enforce `AS RESTRICTIVE` tenant RLS."
                )

        # 3. Verify Zero-Downtime CHECK Constraint Replacement (Add NOT VALID -> VALIDATE -> DROP old)
        for chk in check_replacements:
            chk_id = f"{chk.get('table_name', 'tbl')}:{chk.get('old_constraint', 'old')}->{chk.get('new_constraint', 'new')}"
            adds_not_valid_first = bool(chk.get("adds_new_check_not_valid_before_dropping_old", False))
            validates_before_drop = bool(chk.get("validates_new_check_before_dropping_old", False))
            lock_timeout_ms = int(chk.get("lock_timeout_ms", 0))

            if (
                not adds_not_valid_first
                or not validates_before_drop
                or lock_timeout_ms <= 0
                or lock_timeout_ms > 5000
            ):
                bad_checks.append(chk_id)
                remediations.append(
                    f"Replace CHECK constraint `{chk_id}` safely: (1) `SET LOCAL lock_timeout = '2s'; ALTER TABLE ... ADD CONSTRAINT new_chk CHECK (...) NOT VALID;`, (2) `ALTER TABLE ... VALIDATE CONSTRAINT new_chk;`, (3) `ALTER TABLE ... DROP CONSTRAINT old_chk;`."
                )

        is_valid = (
            len(bad_upgrades) == 0
            and len(bad_edge) == 0
            and len(bad_checks) == 0
        )

        certificate = (
            "Z3_UNSAT_L316_PG18_UPGRADE_STATS_EDGE_FUNCTION_RLS_AND_CHECK_REPLACE_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L316_VIOLATION_DETECTED"
        )

        return PG18UpgradeStatsCarryoverEdgeFunctionRlsAndCheckConstraintReplaceReport(
            is_valid=is_valid,
            upgrade_pipelines_checked=len(upgrades),
            unprotected_pg18_upgrade_stats_pipelines=bad_upgrades,
            edge_functions_checked=len(edge_fns),
            bypassrls_service_role_edge_functions=bad_edge,
            check_replacements_checked=len(check_replacements),
            unsafe_check_constraint_replacements=bad_checks,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


