        bad_sso: List[str] = []
        bad_unique: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 Subtransaction SLRU Overflow Prevention (<= 64 subxids per transaction)
        for rt in routines:
            rt_name = str(rt.get("routine_name", "unnamed_routine"))
            max_subxids = int(rt.get("max_savepoints_or_exception_blocks_per_tx", 0))
            uses_on_conflict_or_merge = bool(rt.get("uses_set_based_on_conflict_or_merge", False))
            has_tx_timeout = bool(rt.get("enforces_transaction_timeout", False))

            if max_subxids > 64 or not uses_on_conflict_or_merge or not has_tx_timeout:
                bad_routines.append(rt_name)
                remediations.append(
                    f"Refactor routine '{rt_name}' to eliminate looped `SAVEPOINT`/`EXCEPTION` blocks (`max_subxids={max_subxids} > 64`); use set-based `INSERT ... ON CONFLICT` / `MERGE` and configure PG18 `transaction_timeout`."
                )

        # 2. Verify Supabase Enterprise SSO / SAML 2.0 Domain-to-Tenant Mapping & RLS
        for sso in sso_mappings:
            domain_id = str(sso.get("sso_domain", "unnamed_domain"))
            verifies_idp_provider_id = bool(sso.get("binds_verified_sso_provider_id_to_single_tenant", False))
            injects_into_app_metadata = bool(sso.get("injects_tenant_id_into_immutable_app_metadata", False))
            enforces_restrictive_rls = bool(sso.get("enforces_restrictive_app_metadata_tenant_rls", False))

            if not verifies_idp_provider_id or not injects_into_app_metadata or not enforces_restrictive_rls:
                bad_sso.append(domain_id)
                remediations.append(
                    f"Harden SSO SAML mapping for '{domain_id}': bind verified `sso_provider_id` to a single `tenant_id` in `app_metadata` via `supabase_auth_admin` hook and enforce `AS RESTRICTIVE` `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid = tenant_id`."
                )

        # 3. Verify Zero-Downtime UNIQUE Constraint Addition via UNIQUE USING INDEX
        for uq in unique_migrations:
            uq_id = f"{uq.get('table_name', 'tbl')}.{uq.get('constraint_name', 'uq')}"
            built_unique_idx_concurrently = bool(uq.get("built_unique_index_concurrently_leading_tenant_id", False))
            uses_unique_using_index = bool(uq.get("uses_add_constraint_unique_using_index", False))
