# --- Merged from node03_v16_6: PG18IdleTransactionSessionTimeoutLockQueueDefenseSupabaseRlsPgmqQueueTenantIsolationAndZeroDowntimeForeignKeyCascadeReplacementProver ---
class PG18IdleTransactionSessionTimeoutLockQueueDefenseSupabaseRlsPgmqQueueTenantIsolationAndZeroDowntimeForeignKeyCascadeReplacementProver:
    """Level 318 Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations).
    Verifies:
    - Inv1 (PG18 Transaction & Idle-in-Transaction Timeout Lock-Convoy Defense): Every database role/pool profile in
      PostgreSQL 18 must enforce `0 < transaction_timeout_ms <= 30000`, `0 < idle_in_transaction_session_timeout_ms <= 10000`,
      and `0 < lock_timeout_ms <= 5000`, and forbid external HTTP calls inside open transactions.
    - Inv2 (Supabase `pgmq` Queue Multi-Tenant Confinement): Direct `USAGE`/`EXECUTE` on schema `pgmq` must be revoked
      from `PUBLIC`, `anon`, and `authenticated`; enqueue wrappers must enforce `SET search_path = ''` and stamp
      `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid` into the message envelope.
    - Inv3 (Zero-Downtime High-Fanout Foreign Key Cascade Replacement): High-fanout child tables (`fanout > 10000`)
      must forbid `ON DELETE CASCADE` (using `ON DELETE RESTRICT` + batched `ctid` deletion) and replace existing FKs
      via `ADD CONSTRAINT new_fk ... NOT VALID` -> `VALIDATE CONSTRAINT new_fk` -> `DROP CONSTRAINT old_fk`.
    """

    @classmethod
    def verify_pg18_tx_timeout_pgmq_rls_and_fk_cascade_replacement(
        cls, audit_spec: Dict[str, Any]
    ) -> PG18TransactionTimeoutConvoyPgmqRlsAndFkCascadeReplacementReport:
        timeout_profiles = audit_spec.get("pg18_timeout_profiles", [])
        pgmq_queues = audit_spec.get("pgmq_queues", [])
        fk_migrations = audit_spec.get("fk_cascade_migrations", [])

        bad_timeouts: List[str] = []
        bad_queues: List[str] = []
        bad_fks: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 transaction_timeout, idle_in_transaction_session_timeout & lock_timeout
        for prof in timeout_profiles:
            role_id = str(prof.get("role_or_pool_name", "unnamed_role"))
            tx_timeout = int(prof.get("transaction_timeout_ms", 0))
            idle_tx_timeout = int(prof.get("idle_in_transaction_session_timeout_ms", 0))
            lck_timeout = int(prof.get("lock_timeout_ms", 0))
            forbids_http_in_tx = bool(prof.get("forbids_outbound_http_inside_open_tx", False))

            if (
                not (0 < tx_timeout <= 30000)
                or not (0 < idle_tx_timeout <= 10000)
                or not (0 < lck_timeout <= 5000)
                or not forbids_http_in_tx
            ):
                bad_timeouts.append(role_id)
                remediations.append(
                    f"Configure PG18 role '{role_id}' with `ALTER ROLE {role_id} SET transaction_timeout = '15s'; ALTER ROLE {role_id} SET idle_in_transaction_session_timeout = '5s'; ALTER ROLE {role_id} SET lock_timeout = '2s';` and move HTTP calls outside SQL transactions."
                )

        # 2. Verify Supabase pgmq Multi-Tenant Queue Confinement
        for q in pgmq_queues:
            q_name = str(q.get("queue_name", "unnamed_pgmq_queue"))
            revoked_pgmq_from_clients = bool(q.get("revoked_pgmq_schema_from_public_anon_authenticated", False))
            wrapper_stamps_app_metadata_tenant = bool(q.get("enqueue_wrapper_stamps_app_metadata_tenant_id", False))
            enforces_empty_search_path = bool(q.get("enforces_empty_search_path", False))

            if not revoked_pgmq_from_clients or not wrapper_stamps_app_metadata_tenant or not enforces_empty_search_path:
                bad_queues.append(q_name)
                remediations.append(
                    f"Confinar `pgmq` queue '{q_name}': `REVOKE ALL ON SCHEMA pgmq FROM PUBLIC, anon, authenticated; REVOKE ALL ON ALL TABLES IN SCHEMA pgmq FROM PUBLIC, anon, authenticated;` and route enqueue through a `SET search_path = ''` RPC binding `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid`."
                )

        # 3. Verify Zero-Downtime High-Fanout Foreign Key Cascade Replacement
        for fk in fk_migrations:
            fk_id = f"{fk.get('child_table', 'child')}.{fk.get('constraint_name', 'fk')}"
            uses_on_delete_cascade_on_high_fanout = bool(fk.get("uses_on_delete_cascade_on_high_fanout_table", False))
            adds_not_valid_and_validates_before_drop = bool(
                fk.get("adds_new_fk_not_valid_and_validates_before_dropping_old", False)
            )
            uses_batched_child_deletion = bool(fk.get("uses_batched_ctid_child_deletion_workflow", False))

            if (
                uses_on_delete_cascade_on_high_fanout
                or not adds_not_valid_and_validates_before_drop
                or not uses_batched_child_deletion
            ):
                bad_fks.append(fk_id)
                remediations.append(
                    f"Replace high-fanout `ON DELETE CASCADE` on `{fk_id}` with `ON DELETE RESTRICT` + batched child purge, and migrate via `ADD CONSTRAINT new_fk ... NOT VALID; VALIDATE CONSTRAINT new_fk; DROP CONSTRAINT old_fk;`."
                )

        is_valid = (
            len(bad_timeouts) == 0
            and len(bad_queues) == 0
            and len(bad_fks) == 0
        )

        certificate = (
            "Z3_UNSAT_L318_PG18_TX_TIMEOUT_PGMQ_RLS_AND_FK_CASCADE_REPLACEMENT_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_L318_VIOLATION_DETECTED"
        )

        return PG18TransactionTimeoutConvoyPgmqRlsAndFkCascadeReplacementReport(
            is_valid=is_valid,
            role_timeout_profiles_checked=len(timeout_profiles),
            convoy_vulnerable_timeout_profiles=bad_timeouts,
            pgmq_queues_checked=len(pgmq_queues),
            exposed_pgmq_multi_tenant_queues=bad_queues,
            fk_cascade_migrations_checked=len(fk_migrations),
            unsafe_high_fanout_fk_cascades=bad_fks,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


