# --- Merged from node05_v15_4: RivetUtilityPreservingRepoPPRAndTideKVChunkedPrefillProver ---
class RivetUtilityPreservingRepoPPRAndTideKVChunkedPrefillProver:

    def verify_rivet_ppr_and_tidekv_prefill(self, target_name: str='rivet_ppr_tidekv_cluster', file_count: int=120, signal_grounding_alpha: float=0.6, utility_linking_alpha: float=0.7, ppr_iterations: int=20, rrf_kappa: int=60, lex_rank: int=1, sem_rank: int=2, str_rank: int=1, explicit_code_mention: bool=True, edge_weights: Optional[Dict[str, float]]=None, retained_dep_snippets: int=10, retained_usage_snippets: int=8, retained_config_snippets: int=6, context_budget_tokens: int=8192, shaped_section_tokens: Optional[Dict[str, int]]=None, num_layers: int=32, delayed_eviction_layers: int=4, prompt_tokens: int=16384, chunk_prefill_tokens: int=1024, kv_budget_tokens: int=2048, guarded_prompt_tokens: int=256, irregular_hbm_gather_ops: int=0) -> RivetUtilityPreservingRepoPPRAndTideKVChunkedPrefillReport:
        t0 = time.perf_counter()
        violations: List[str] = []
        if edge_weights is None:
            edge_weights = {'import': 1.0, 'symbol_ref': 0.8, 'indirect_import': 0.7, 'caller': 0.5, 'config': 0.3}
        if shaped_section_tokens is None:
            shaped_section_tokens = {'target': 2400, 'dependency': 1100, 'usage': 750, 'config': 450}
        used_tfidf_fallback = file_count < 20
        lsa_latent_dim = 0 if used_tfidf_fallback else min(256, max(1, file_count - 1))
        if not 0.5 <= signal_grounding_alpha <= 0.75:
            violations.append(f'RIVET_GROUNDING_ALPHA_OUT_OF_RANGE: alpha={signal_grounding_alpha} must be in [0.50, 0.75] (< 0.85).')
        if not 0.6 <= utility_linking_alpha <= 0.8:
            violations.append(f'RIVET_LINKING_ALPHA_OUT_OF_RANGE: alpha={utility_linking_alpha} must be in [0.60, 0.80] (< 0.85).')
        if ppr_iterations < 15:
            violations.append(f'RIVET_INSUFFICIENT_PPR_ITERATIONS: iterations={ppr_iterations} < 15.')
        if rrf_kappa != 60:
            violations.append(f'RIVET_NON_CANONICAL_RRF_KAPPA: kappa={rrf_kappa} != 60 (Cormack et al.).')
        prior = 0.05 if explicit_code_mention else 0.0
        rrf_score = 1.0 / (rrf_kappa + max(1, lex_rank)) + 1.0 / (rrf_kappa + max(1, sem_rank)) + 1.0 / (rrf_kappa + max(1, str_rank)) + prior
        w_imp = float(edge_weights.get('import', 0.0))
        w_sym = float(edge_weights.get('symbol_ref', 0.0))
        w_ind = float(edge_weights.get('indirect_import', 0.0))
        w_cal = float(edge_weights.get('caller', 0.0))
        w_cfg = float(edge_weights.get('config', 0.0))
        evidence_weights_monotone = w_imp >= w_sym >= w_ind >= w_cal >= w_cfg > 0.0
        if not evidence_weights_monotone:
            violations.append('RIVET_EVIDENCE_TIER_ORDER_VIOLATION: expected import >= symbol_ref >= indirect_import >= caller >= config > 0.')
        if retained_dep_snippets > 12 or retained_usage_snippets > 10 or retained_config_snippets > 10:
            violations.append(f'RIVET_UTILITY_SNIPPET_CAP_EXCEEDED: dep={retained_dep_snippets}/12, usage={retained_usage_snippets}/10, cfg={retained_config_snippets}/10.')
        if context_budget_tokens <= 4096:
            caps = {'target': 1400, 'dependency': 420, 'usage': 240, 'config': 140}
        else:
            caps = {'target': 2500, 'dependency': 1200, 'usage': 800, 'config': 500}
        budget_shaping_within_cap = True
        total_shaped_tokens = 0
        for sec, cap in caps.items():
            val = int(shaped_section_tokens.get(sec, 0))
            total_shaped_tokens += val
            if val < 0 or val > cap:
                budget_shaping_within_cap = False
                violations.append(f"RIVET_SECTION_BUDGET_OVERFLOW: section '{sec}'={val} exceeds cap {cap}.")
        if total_shaped_tokens > context_budget_tokens:
            budget_shaping_within_cap = False
            violations.append(f'RIVET_TOTAL_CONTEXT_OVERFLOW: {total_shaped_tokens} > {context_budget_tokens}.')
        uncompressed_peak = max(1, num_layers * prompt_tokens)
        active_evict_layers = max(0, num_layers - delayed_eviction_layers)
        tidekv_peak = delayed_eviction_layers * prompt_tokens + active_evict_layers * (kv_budget_tokens + chunk_prefill_tokens)
        reduction_ratio = 1.0 - float(tidekv_peak) / float(uncompressed_peak)
        if tidekv_peak >= uncompressed_peak or reduction_ratio < 0.4:
            violations.append(f'TIDEKV_INSUFFICIENT_PEAK_REDUCTION: reduction_ratio={reduction_ratio:.4f} < 0.40.')
        if irregular_hbm_gather_ops > 0:
            violations.append(f'THINKV_IRREGULAR_HBM_GATHER_DETECTED: gather_ops={irregular_hbm_gather_ops} > 0.')
        if guarded_prompt_tokens < 64 or guarded_prompt_tokens > kv_budget_tokens:
            violations.append(f'TIDEKV_PROMPT_GUARD_VIOLATION: guarded_prompt_tokens={guarded_prompt_tokens} out of bounds [64, {kv_budget_tokens}].')
        elapsed = (time.perf_counter() - t0) * 1000.0
        return RivetUtilityPreservingRepoPPRAndTideKVChunkedPrefillReport(target_name=target_name, passed=len(violations) == 0, file_count=file_count, lsa_latent_dim=lsa_latent_dim, used_tfidf_fallback=used_tfidf_fallback, signal_grounding_alpha=round(signal_grounding_alpha, 4), utility_linking_alpha=round(utility_linking_alpha, 4), rrf_kappa=rrf_kappa, code_mention_prior=round(prior, 4), fused_anchor_score=round(rrf_score, 6), evidence_weights_monotone=evidence_weights_monotone, retained_dep_snippets=retained_dep_snippets, retained_usage_snippets=retained_usage_snippets, retained_config_snippets=retained_config_snippets, budget_shaping_within_cap=budget_shaping_within_cap, total_shaped_tokens=total_shaped_tokens, context_budget_tokens=context_budget_tokens, tidekv_peak_tokens_per_head=tidekv_peak, uncompressed_peak_tokens_per_head=uncompressed_peak, peak_hbm_reduction_ratio=round(reduction_ratio, 6), irregular_hbm_gather_ops=irregular_hbm_gather_ops, guarded_prompt_tokens=guarded_prompt_tokens, violations=violations, proof_latency_ms=elapsed)


