# --- Merged from node05_v15_4: InlineCoderBidirectionalCallGraphAndFastKVBehaviorPreservingProver ---
class InlineCoderBidirectionalCallGraphAndFastKVBehaviorPreservingProver:
    def verify_inlinecoder_and_fastkv_kl(
        self,
        target_name: str = "inlinecoder_fastkv_cluster",
        upstream_callers_inlined: int = 4,
        ast_callees: Optional[List[str]] = None,
        llm_callees: Optional[List[str]] = None,
        retrieved_utilities: Optional[List[str]] = None,
        anchor_perplexity_score: float = 1.42,
        tsp_layer_index: int = 10,
        total_layers: int = 32,
        tsp_propagation_rate: float = 0.50,
        kv_retention_rate: float = 0.20,
        max_kl_divergence_bits: float = 0.008,
        kl_threshold_bits: float = 0.025,
        separate_masked_forward_passes: int = 0,
    ) -> InlineCoderBidirectionalCallGraphAndFastKVBehaviorPreservingReport:
        t0 = time.perf_counter()
        violations: List[str] = []

        if ast_callees is None:
            ast_callees = ["dfs_paths", "normalize_ast_node", "resolve_import_edge"]
        if llm_callees is None:
            llm_callees = ["dfs_paths", "compute_ppr_scores", "format_type_contract"]
        if retrieved_utilities is None:
            retrieved_utilities = ["dfs_paths", "normalize_ast_node", "compute_ppr_scores"]

        q_ast = set(ast_callees)
        q_llm = set(llm_callees)
        q_union = q_ast | q_llm
        c_ret = set(retrieved_utilities)

        if upstream_callers_inlined < 1:
            violations.append(
                f"INLINECODER_MISSING_UPSTREAM_CALLERS: upstream_callers_inlined={upstream_callers_inlined} < 1."
            )
        if len(q_union) == 0:
            violations.append("INLINECODER_EMPTY_DOWNSTREAM_QUERY_UNION: Q_AST U Q_LLM is empty.")

        prevented_dup = len(q_union & c_ret) > 0
        if not prevented_dup:
            violations.append(
                "INLINECODER_UNGROUNDED_DOWNSTREAM_RETRIEVAL: retrieved utilities do not intersect Q_AST U Q_LLM."
            )
        if anchor_perplexity_score <= 0.0 or anchor_perplexity_score > 15.0:
            violations.append(
                f"INLINECODER_ANCHOR_PERPLEXITY_ANOMALY: perplexity={anchor_perplexity_score} out of (0, 15.0]."
            )

        tsp_kv_decoupled_valid = (
            1 <= tsp_layer_index < total_layers
            and 0.0 < kv_retention_rate <= tsp_propagation_rate <= 1.0
        )
        if not tsp_kv_decoupled_valid:
            violations.append(
                f"FASTKV_TSP_DECOUPLING_VIOLATION: tsp_layer={tsp_layer_index}/{total_layers}, "
                f"kv_rate={kv_retention_rate}, tsp_rate={tsp_propagation_rate}."
            )

        early_frac = float(tsp_layer_index) / float(max(1, total_layers))
        late_frac = 1.0 - early_frac
        effective_prefill_work = early_frac + late_frac * max(0.05, tsp_propagation_rate)
        prefill_speedup = round(1.0 / max(0.1, effective_prefill_work), 4)
        decode_speedup = round(min(2.87, 1.0 / max(0.348, kv_retention_rate * 1.75)), 4)

        if max_kl_divergence_bits < 0.0 or max_kl_divergence_bits > kl_threshold_bits:
            violations.append(
                f"BEHAVIOR_PRESERVING_KL_EXCEEDED: D_KL={max_kl_divergence_bits} > {kl_threshold_bits}."
            )
