# --- Merged from node05_v15_4: SaracoderHierarchicalContextPruningAndNovaKVGSRQProver ---
class SaracoderHierarchicalContextPruningAndNovaKVGSRQProver:
    """
    Level 228 Formal Verifier (Tool #237 - NODE-05 Shard v14.6.0):
    1. Saracoder Hierarchical Context Pruning & External-Aware Identifier Disambiguator (arXiv:2508.10068v3, Oct 2026):
       - Constructs induced program-sliced subgraphs over control-flow, dataflow, and control dependencies.
       - Expands initial candidate pool |P| = top_k * k (with k > 1), applies 4-stage Hierarchical Feature Optimization (HF_OP)
         eliminating exact textual duplicates (exact_duplicate_snippets_retained == 0), disambiguates external cross-file
         symbols D_ext via EAID (ambiguous_external_identifiers == 0), and enforces hard budget |C| = |S_ref| + |D_ext| <= L_max.
    2. NOVA-KV Attention-Preserving Transform Vector Quantization (arXiv:2608.04074, Aug 2026) & GSRQ Gain-Shape Residual Quantization (arXiv:2607.01065, Jul 2026):
       - Verifies non-orthogonal key transform satisfying the generalized Parseval relation (residual <= 1e-5) and orthogonal value transform
         under equal-volume partitions so equal-size codebooks attain the variable-rate MSE optimum.
       - Verifies Gain-Shape K-means (GSKM) residual quantization eliminating Euclidean centroid shrinkage (angular_alignment_cosine >= 0.94)
         at <= 2.0 bits per element (>= 8x KV memory compression vs FP16).
    """

    def verify_saracoder_and_novakv_gsrq(
        self,
        target_name: str = "saracoder_novakv_gsrq_cluster",
        top_k_base: int = 8,
        expansion_factor_k: int = 4,
        exact_duplicate_snippets_retained: int = 0,
        ambiguous_external_identifiers: int = 0,
        s_ref_tokens: int = 2400,
        d_ext_tokens: int = 1600,
        max_budget_tokens: int = 4096,
        is_key_transform_non_orthogonal: bool = True,
        is_value_transform_orthogonal: bool = True,
        generalized_parseval_residual: float = 1.2e-6,
        equal_volume_partitions_valid: bool = True,
        centroid_shrinkage_eliminated: bool = True,
        angular_alignment_cosine: float = 0.968,
        quant_bits_per_element: float = 1.5,
    ) -> SaracoderHierarchicalContextPruningAndNovaKVGSRQReport:
        t0 = time.perf_counter()
        violations: List[str] = []

        if top_k_base <= 0 or expansion_factor_k <= 1:
            violations.append(
                f"SARACODER_POOL_EXPANSION_INVALID: top_k_base={top_k_base}, expansion_factor_k={expansion_factor_k} (requires k > 1)."
            )
        pool_size = max(0, top_k_base) * max(0, expansion_factor_k)

        if exact_duplicate_snippets_retained > 0:
            violations.append(
                f"SARACODER_HF_OP_DUPLICATES_RETAINED: exact_duplicate_snippets_retained={exact_duplicate_snippets_retained} > 0."
            )

        if ambiguous_external_identifiers > 0:
            violations.append(
                f"SARACODER_EAID_UNRESOLVED_SYMBOLS: ambiguous_external_identifiers={ambiguous_external_identifiers} > 0."
            )

        total_tokens = max(0, s_ref_tokens) + max(0, d_ext_tokens)
        if s_ref_tokens <= 0 or d_ext_tokens <= 0 or total_tokens > max_budget_tokens:
            violations.append(
                f"SARACODER_CONTEXT_BUDGET_VIOLATION: s_ref={s_ref_tokens} + d_ext={d_ext_tokens} = {total_tokens} > max_budget={max_budget_tokens}."
            )

        density_gain = round(float(pool_size) / float(max(1, top_k_base)) * (float(d_ext_tokens) / float(max(1, total_tokens)) + 1.0), 4)

        if not is_key_transform_non_orthogonal or not is_value_transform_orthogonal:
            violations.append(
                f"NOVAKV_TRANSFORM_ DUALITY_VIOLATION: key_non_orthogonal={is_key_transform_non_orthogonal}, value_orthogonal={is_value_transform_orthogonal}."
            )

        if generalized_parseval_residual < 0.0 or generalized_parseval_residual > 1e-5:
            violations.append(
                f"NOVAKV_PARSEVAL_RESIDUAL_EXCEEDED: residual={generalized_parseval_residual} > 1e-5."
            )

        if not equal_volume_partitions_valid:
            violations.append("NOVAKV_UNEQUAL_VOLUME_PARTITIONS: equal-size codebooks fail variable-rate optimality.")

        if not centroid_shrinkage_eliminated or angular_alignment_cosine < 0.94 or angular_alignment_cosine > 1.0:
            violations.append(
                f"GSRQ_CENTROID_SHRINKAGE_OR_ALIGNMENT_DEFICIT: shrinkage_eliminated={centroid_shrinkage_eliminated}, cosine={angular_alignment_cosine}."
            )

        if quant_bits_per_element <= 0.0 or quant_bits_per_element > 2.0:
            violations.append(
                f"GSRQ_NOVAKV_BITRATE_EXCEEDED: quant_bits_per_element={quant_bits_per_element} > 2.0 bits."
            )

        kv_comp_ratio = round(16.0 / max(0.25, quant_bits_per_element), 4)
        elapsed = (time.perf_counter() - t0) * 1000.0

        return SaracoderHierarchicalContextPruningAndNovaKVGSRQReport(
            target_name=target_name,
            passed=(len(violations) == 0),
            initial_candidate_pool_size=pool_size,
            top_k_base=top_k_base,
            expansion_factor_k=expansion_factor_k,
            exact_duplicate_snippets_retained=exact_duplicate_snippets_retained,
            ambiguous_external_identifiers=ambiguous_external_identifiers,
            s_ref_tokens=s_ref_tokens,
            d_ext_tokens=d_ext_tokens,
            total_context_tokens=total_tokens,
            max_budget_tokens=max_budget_tokens,
            knowledge_density_gain_ratio=density_gain,
            is_key_transform_non_orthogonal=is_key_transform_non_orthogonal,
            is_value_transform_orthogonal=is_value_transform_orthogonal,
            generalized_parseval_residual=round(generalized_parseval_residual, 8),
            equal_volume_partitions_valid=equal_volume_partitions_valid,
            centroid_shrinkage_eliminated=centroid_shrinkage_eliminated,
            angular_alignment_cosine=round(angular_alignment_cosine, 4),
            quant_bits_per_element=round(quant_bits_per_element, 4),
            kv_compression_ratio=kv_comp_ratio,
            violations=violations,
            proof_latency_ms=elapsed,
        )


