            eta_end_to_end_speedup_vs_fa2=eta_end_to_end_speedup_vs_fa2,
            deferkv_prefill_decode_boundary_step=deferkv_prefill_decode_boundary_step,
            premature_prefill_only_evictions=premature_prefill_only_evictions,
            deferkv_retained_kv_ratio=deferkv_retained_kv_ratio,
