            violations.append(
                f"CGM_CHA_ASSUMPTION_HIERARCHY_VIOLATION: cha_enabled={cha_assumption_hierarchy_enabled}, unresolved_edges={unresolved_cha_virtual_dispatch_edges} (arXiv:2505.16901)."
            )

