            thinkv_quantization_factor_a=thinkv_quantization_factor_a,
            thinkv_eviction_factor_b=thinkv_eviction_factor_b,
            effective_kv_memory_footprint_ratio=effective_footprint_ratio,
            reemergent_thought_token_eviction_violations=reemergent_thought_token_eviction_violations,
            violations=violations,
