# --- Merged from node01_v13_2: WasmComponentModelCanonicalABIAndLinearMemorySandboxProver ---
class WasmComponentModelCanonicalABIAndLinearMemorySandboxProver:
    """
    Nivel 113 — Hito Mayor v12.0.0 Sovereign Apex (NODE-01 Shard - Tool MCP #122):
    Demostrador Formal del Modelo de Componentes WebAssembly (Wasm 2.0 / Wasmtime / Cranelift), Interfaz Binaria
    Canónica WIT (Lifting/Lowering con cabi_realloc) y Aislamiento de Capacidades WASI 0.2 (Preview 2):
    1. Confinamiento de Memoria Lineal mediante Páginas de Guarda (4 GiB + Guard Pages PROT_NONE) y CFI en call_indirect:
       Verifica que si el compilador JIT (Cranelift) elide chequeos explícitos de límites en accesos i32.load/store,
       la región virtual reservada más las páginas de guarda sea >= 2^32 bytes (4 GiB) para atrapar cualquier
       offset de 32 bits en hardware, y que toda instrucción call_indirect valide en tiempo de ejecución la
       igualdad canónica de firma de tipos (table[idx].type_id == expected_sig_id) antes de saltar.
    2. Aislamiento Shared-Nothing en Canonical ABI (Lifting / Lowering vía cabi_realloc):
       Audita que el paso de strings y listas entre componentes no comparta punteros crudos de memoria lineal,
       sino que valide alineación (ptr % align == 0) y límites (ptr + byte_len <= mem_size) al hacer lift,
       aloje un buffer disjunto mediante cabi_realloc en el componente destino al hacer lower, y ejecute
       cabi_post_* exactamente una vez tras finalizar la lectura (impidiendo Use-After-Free y Double-Free).
    3. Linealidad de Recursos WASI 0.2 (own<T> vs borrow<T>) y Cero Autoridad Ambiental:
       Verifica que ningún componente pueda abrir rutas de sistema de archivos o sockets sin un descriptor de
       capacidad pre-abierto explícitamente en su tabla de handles, y que sea imposible destruir un recurso
       own<T> mientras su contador de préstamos activos num_lends (borrow<T>) sea mayor que cero.
    """

    FOUR_GIB = 1 << 32

    @staticmethod
    def verify_wasm_component_model_and_wasi_sandbox(
        linear_memories_and_tables: List[Dict[str, Any]],
        canonical_abi_transfers: List[Dict[str, Any]],
        wasi_resource_handles: List[Dict[str, Any]],
        wasm_module_id: str = "clipperops_codere_wasm_component_v12_0"
    ) -> WasmComponentModelAndWASICapabilityReport:
        import json, hashlib
        t0 = time.perf_counter_ns()
        mem_violations: List[str] = []
        abi_violations: List[str] = []
        wasi_violations: List[str] = []
        verified_count = 0

        # 1. Verify Linear Memory Guard Pages & call_indirect Signature CFI
        for idx, lm in enumerate(linear_memories_and_tables):
            mid = str(lm.get("memory_id", f"wasm_mem_{idx}"))
            elides_explicit_bounds_checks = bool(lm.get("jit_elides_explicit_bounds_check", True))
            reserved_plus_guard_bytes = int(lm.get("virtual_reservation_plus_guard_bytes", 1 << 33))
            enforces_call_indirect_sig_check = bool(lm.get("enforces_call_indirect_canonical_type_check", True))

            if elides_explicit_bounds_checks and reserved_plus_guard_bytes < WasmComponentModelCanonicalABIAndLinearMemorySandboxProver.FOUR_GIB:
                mem_violations.append(
                    f"Escape de sandbox de memoria lineal Wasm en {mid}: el JIT elide chequeos explícitos pero la reserva virtual + guard pages ({reserved_plus_guard_bytes} B) < 4 GiB."
                )
            if not enforces_call_indirect_sig_check:
                mem_violations.append(
                    f"Violación de Control-Flow Integrity (CFI) en {mid}: call_indirect no verifica la firma canónica del funcref en la tabla."
                )
            if (not elides_explicit_bounds_checks or reserved_plus_guard_bytes >= WasmComponentModelCanonicalABIAndLinearMemorySandboxProver.FOUR_GIB) and enforces_call_indirect_sig_check:
                verified_count += 1

        # 2. Verify WIT Canonical ABI Lifting/Lowering Isolation & cabi_realloc Bounds
        for idx, ab in enumerate(canonical_abi_transfers):
            tid = str(ab.get("transfer_id", f"wit_abi_{idx}"))
            shares_raw_linear_pointer = bool(ab.get("shares_raw_pointer_without_lift_lower", False))
            ptr_addr = int(ab.get("Realloc_ptr", 1024))
            alignment = int(ab.get("required_alignment", 4))
            byte_len = int(ab.get("payload_byte_len", 256))
            target_mem_size = int(ab.get("target_linear_memory_bytes", 65536))
            cabi_post_free_count = int(ab.get("cabi_post_return_cleanup_calls", 1))

            if shares_raw_linear_pointer:
                abi_violations.append(
                    f"Violación Shared-Nothing en WIT Canonical ABI ({tid}): paso de puntero crudo entre componentes sin copia lift/lower."
                )
            if alignment <= 0 or (ptr_addr % alignment) != 0 or (ptr_addr + byte_len) > target_mem_size:
                abi_violations.append(
                    f"Buffer cabi_realloc inválido en {tid}: ptr={ptr_addr} (align={alignment}) + len={byte_len} excede memoria destino ({target_mem_size})."
                )
            if cabi_post_free_count != 1:
                abi_violations.append(
                    f"Corrupción de ciclo de vida en {tid}: llamadas a cabi_post_return = {cabi_post_free_count} (!= 1; causa fuga o double-free)."
                )
            if not shares_raw_linear_pointer and alignment > 0 and (ptr_addr % alignment) == 0 and (ptr_addr + byte_len) <= target_mem_size and cabi_post_free_count == 1:
                verified_count += 1

        # 3. Verify WASI 0.2 Capability Resource Handle Table Linearity (own<T> vs borrow<T>)
        for idx, wh in enumerate(wasi_resource_handles):
            hid = str(wh.get("handle_id", f"wasi_h_{idx}"))
            allows_ambient_authority = bool(wh.get("allows_ambient_fs_or_net_without_preopen_handle", False))
            active_borrow_lends = int(wh.get("active_borrow_lends_count", 0))
            attempts_own_resource_drop = bool(wh.get("attempts_resource_drop_while_borrowed", False))
            validates_handle_table_generation = bool(wh.get("validates_handle_index_and_generation_epoch", True))

            if allows_ambient_authority:
                wasi_violations.append(
                    f"Autoridad ambiental detectada en WASI 0.2 ({hid}): acceso a archivos/red sin descriptor de capacidad pre-abierto."
                )
            if attempts_own_resource_drop and active_borrow_lends > 0:
                wasi_violations.append(
                    f"Destrucción prematura de recurso own<T> en WASI ({hid}): resource.drop invocado con num_lends={active_borrow_lends} > 0 préstamos borrow<T> activos."
                )
            if not validates_handle_table_generation:
                wasi_violations.append(
                    f"Falsificación o reuso ABA de descriptor WASI en {hid}: la tabla de recursos no valida índice ni época generacional."
                )
            if not allows_ambient_authority and not (attempts_own_resource_drop and active_borrow_lends > 0) and validates_handle_table_generation:
                verified_count += 1

        mem_ok = len(mem_violations) == 0
        abi_ok = len(abi_violations) == 0
        wasi_ok = len(wasi_violations) == 0
        overall_ok = mem_ok and abi_ok and wasi_ok

        rust_code = "\n".join([
            "// 1. Wasmtime v12+ Component Model & WASI 0.2 Capability-Scoped Host:",
            "let mut config = wasmtime::Config::new();",
            "config.wasm_component_model(true);",
            "config.static_memory_maximum_size(1 << 32); // 4 GiB + Guard Pages",
            "let mut wasi = wasmtime_wasi::WasiCtxBuilder::new(); // Zero ambient authority by default"
        ])

        payload_str = json.dumps({
            "wasm_module_id": wasm_module_id,
            "overall_ok": overall_ok,
            "mem_ok": mem_ok,
            "abi_ok": abi_ok,
            "wasi_ok": wasi_ok,
            "verified_count": verified_count
        }, sort_keys=True)
        pcc_hash = hashlib.sha256(payload_str.encode("utf-8")).hexdigest()
        dur_ms = round((time.perf_counter_ns() - t0) / 1_000_000.0, 3)

        return WasmComponentModelAndWASICapabilityReport(
            wasm_module_id=wasm_module_id,
            proven_wasm_component_model_and_wasi_sandbox_sound=overall_ok,
            linear_memory_guard_pages_and_call_indirect_type_verified=mem_ok,
            canonical_abi_lift_lower_isolation_and_realloc_verified=abi_ok,
            wasi_capability_handle_linearity_and_no_ambient_auth_verified=wasi_ok,
            verified_wasm_components_and_handles_count=verified_count,
            linear_memory_and_cfi_violations=mem_violations,
            canonical_abi_lift_lower_violations=abi_violations,
            wasi_capability_handle_violations=wasi_violations,
            synthesized_wasmtime_wit_rust_code=rust_code,
            pcc_certificate_sha256=pcc_hash,
            analysis_duration_ms=dur_ms
        )


