# --- Merged from node01_v13_2: RISCVISAzkVMMemoryConsistencyAndPMPIsolationProver ---
class RISCVISAzkVMMemoryConsistencyAndPMPIsolationProver:
    """
    Nivel 114 (v12.1.0 - NODE-01 Shard - Tool MCP #123):
    Demostrador Formal de la Arquitectura RISC-V (RV32IM / RV64GC), Consistencia de Memoria Offline en zkVMs
    (Blum et al. FOCS 1991; Setty et al. Spice / Lasso / Jolt; Succinct SP1 & RISC Zero) y Protección de Memoria
    Física (PMP Privileged Spec):
    1. Invariante del Registro Cableado a Cero (x0 === 0) y Alineación de Contador de Programa (PC):
       Verifica que en el circuito AIR/Plonkish de decodificación RISC-V, cualquier instrucción con registro
       destino rd == 0 ignore la escritura (x0_val_after == 0) mediante la compuerta (is_rd_zero * reg_out == 0),
       impidiendo que un probador malicioso inyecte valores no nulos en x0 (lo que corrompe pseudo-instrucciones
       mv, beqz y saltos incondicionales jal x0), y verifica que el PC permanezca alineado a 4 bytes (o 2 bytes
       en extensión comprimida C).
    2. Consistencia de Memoria Offline por Permutación de Multiconjuntos (Init U Write == Read U Final) y
       Monotonía Estricta de Reloj (t_prev < clk):
       Audita que cada acceso a RAM en el ciclo clk verifique mediante range-check que (clk - t_prev - 1) >= 0
       sin wrap-around en el cuerpo finito, que una lectura (Load) reinserte (addr, val_read, clk) en el
       multiconjunto Write mientras una escritura (Store) inserte (addr, val_new, clk), y que el producto
       acumulado de permutación (Grand Product / LogUp) de (Init U Write) coincida exactamente con (Read U Final).
    3. Aislamiento de Protección de Memoria Física RISC-V (PMP Priority Ordering, Lock Bit L==1 y Prohibición W=1,R=0):
       Verifica que las entradas pmpcfg[0..15] prohíban la combinación reservada ilegal (W == 1 and R == 0),
       exijan el bit de bloqueo L == 1 cuando una regla deba restringir también al modo máquina (M-mode), y no
       sombreen inadvertidamente regiones críticas mediante entradas previas de mayor prioridad (índice menor).
    """

    @staticmethod
    def verify_riscv_zkvm_memory_and_pmp(
        riscv_instruction_steps: List[Dict[str, Any]],
        offline_memory_accesses: List[Dict[str, Any]],
        pmp_config_entries: List[Dict[str, Any]],
        riscv_trace_id: str = "codere_sp1_risc0_zkvm_v12_1"
    ) -> RISCVzkVMMemoryAndPMPIsolationReport:
        import json, hashlib
        t0 = time.perf_counter_ns()
        isa_violations: List[str] = []
        mem_violations: List[str] = []
        pmp_violations: List[str] = []
        verified_count = 0

        # 1. Verify x0 === 0 Hardwired Invariant & PC Alignment
        for idx, st in enumerate(riscv_instruction_steps):
            sid = str(st.get("step_id", f"rv_step_{idx}"))
            rd_index = int(st.get("rd_reg_index", 0))
            x0_val_after = int(st.get("x0_register_value_after", 0))
            gates_write_on_rd_nonzero = bool(st.get("circuit_gates_write_on_rd_ne_zero", True))
            pc_addr = int(st.get("pc_address", 0x1000))
            allows_compressed_c_ext = bool(st.get("allows_rvc_16bit_alignment", False))

            if x0_val_after != 0 or (rd_index == 0 and not gates_write_on_rd_nonzero):
                isa_violations.append(
                    f"Corrupción del registro x0 en circuito RISC-V ({sid}): x0_after={x0_val_after} (!=0) o falta compuerta rd!=0."
                )
            req_align = 2 if allows_compressed_c_ext else 4
            if (pc_addr % req_align) != 0:
                isa_violations.append(
                    f"Desalineación de PC en RISC-V ({sid}): PC={hex(pc_addr)} no es múltiplo de {req_align}."
                )
            if x0_val_after == 0 and (rd_index != 0 or gates_write_on_rd_nonzero) and (pc_addr % req_align) == 0:
                verified_count += 1

        # 2. Verify zkVM Offline Memory Checking (Read/Write Multiset & Timestamp Monotonicity t_prev < clk)
        for idx, ma in enumerate(offline_memory_accesses):
            mid = str(ma.get("mem_op_id", f"mem_{idx}"))
            prev_ts = int(ma.get("prev_timestamp", 5))
            curr_clk = int(ma.get("current_clk", 12))
            range_checked_delta_ts = bool(ma.get("range_checks_clk_minus_prev_ts", True))
            init_plus_write_digest = int(ma.get("init_union_write_multiset_digest", 777))
            read_plus_final_digest = int(ma.get("read_union_final_multiset_digest", 777))

            if curr_clk <= prev_ts or not range_checked_delta_ts:
                mem_violations.append(
                    f"Violación de causalidad temporal en memoria zkVM ({mid}): clk={curr_clk} <= t_prev={prev_ts} o falta range-check anti-wraparound."
                )
            if init_plus_write_digest != read_plus_final_digest:
                mem_violations.append(
                    f"Falsificación de permutación de memoria offline en {mid}: H(Init U Write)={init_plus_write_digest} != H(Read U Final)={read_plus_final_digest}."
                )
            if curr_clk > prev_ts and range_checked_delta_ts and init_plus_write_digest == read_plus_final_digest:
                verified_count += 1

        # 3. Verify RISC-V Physical Memory Protection (PMP) Priority, Lock Bit & RWX Encoding
        for idx, pmp in enumerate(pmp_config_entries):
            pid = str(pmp.get("pmp_id", f"pmp_{idx}"))
            r_bit = bool(pmp.get("read_bit_R", True))
            w_bit = bool(pmp.get("write_bit_W", False))
            x_bit = bool(pmp.get("exec_bit_X", True))
            l_lock_bit = bool(pmp.get("lock_bit_L", True))
            must_enforce_in_m_mode = bool(pmp.get("requires_machine_mode_enforcement", True))
            shadowed_by_earlier_catchall = bool(pmp.get("shadowed_by_lower_index_wide_entry", False))

            if w_bit and not r_bit:
                pmp_violations.append(
                    f"Codificación PMP ilegal reservada en {pid}: W=1 con R=0 está prohibido por la especificación privilegiada RISC-V."
                )
            if must_enforce_in_m_mode and not l_lock_bit:
                pmp_violations.append(
                    f"Bypass de PMP en M-mode ({pid}): falta el bit Lock (L=1), por lo que el modo máquina ignora esta restricción de memoria."
                )
            if shadowed_by_earlier_catchall:
                pmp_violations.append(
                    f"Sombreado de prioridad PMP en {pid}: una entrada con índice menor cubre este rango y anula esta regla."
                )
            if not (w_bit and not r_bit) and (not must_enforce_in_m_mode or l_lock_bit) and not shadowed_by_earlier_catchall:
                verified_count += 1

        isa_ok = len(isa_violations) == 0
        mem_ok = len(mem_violations) == 0
        pmp_ok = len(pmp_violations) == 0
        overall_ok = isa_ok and mem_ok and pmp_ok

        rust_code = "\n".join([
            "// 1. SP1 / RISC Zero AIR Constraint for Hardwired x0 == 0 & Memory Timestamp:",
            "builder.when(is_rd_zero).assert_zero(rd_val_next);",
            "builder.send_range_check_u24(clk_expr - prev_timestamp_expr - AB::Expr::ONE);",
            "// 2. RISC-V PMP Locked M-Mode Configuration:",
            "let pmpcfg_byte: u8 = PMP_L | PMP_NAPOT | PMP_R; // L=1 enforces rule in M-mode, W=0"
        ])

        payload_str = json.dumps({
            "riscv_trace_id": riscv_trace_id,
            "overall_ok": overall_ok,
            "isa_ok": isa_ok,
            "mem_ok": mem_ok,
            "pmp_ok": pmp_ok,
            "verified_count": verified_count
        }, sort_keys=True)
        pcc_hash = hashlib.sha256(payload_str.encode("utf-8")).hexdigest()
        dur_ms = round((time.perf_counter_ns() - t0) / 1_000_000.0, 3)

        return RISCVzkVMMemoryAndPMPIsolationReport(
            riscv_trace_id=riscv_trace_id,
            proven_riscv_zkvm_memory_and_pmp_sound=overall_ok,
            x0_hardwired_zero_and_pc_alignment_verified=isa_ok,
            offline_memory_multiset_timestamp_monotonicity_verified=mem_ok,
            pmp_priority_lock_bit_and_rwx_encoding_verified=pmp_ok,
            verified_riscv_cycles_and_pmp_entries_count=verified_count,
            isa_x0_and_alignment_violations=isa_violations,
            offline_memory_checking_violations=mem_violations,
            pmp_privilege_isolation_violations=pmp_violations,
            synthesized_sp1_risc0_rust_code=rust_code,
            pcc_certificate_sha256=pcc_hash,
            analysis_duration_ms=dur_ms
        )


