class PG18BTreeDeduplicationPostingListCompressionSupabaseRlsRealtimePresenceStateQuotaGuardAndZeroDowntimeColumnNotNullCheckValidationProver:
    """Formal Verifier (NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime Migrations — v18.5.0).
    Verifies:
    - Inv1 (PG18 B-Tree Posting-List Deduplication Discipline): Multi-tenant composite B-Tree indexes on discrete
      integer/UUID/text columns (`tenant_id`, `status_code`, `category_id`) must enable `WITH (deduplicate_items = on)`
      and `fillfactor` between `80` and `95` to compress duplicate key TIDs into posting lists and minimize page splits.
    - Inv2 (Supabase Realtime Presence Multi-Tenant RLS & Payload Quota Guard): Realtime Presence channels in
      `realtime.messages` (`realtime.messages.extension = 'presence'`) must enforce `FORCE ROW LEVEL SECURITY` with an
      `AS RESTRICTIVE` `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id') = split_part(realtime.topic(), ':', 1)`
      policy and bound per-client presence state payload size (`<= 4096` bytes).
    - Inv3 (Zero-Downtime `SET NOT NULL` Promotion): Promoting a nullable column to `NOT NULL` on a populated table must
      never run `ALTER TABLE ... ALTER COLUMN ... SET NOT NULL` directly without a pre-validated constraint; it must
      execute (1) `ADD CONSTRAINT chk_nn CHECK (col IS NOT NULL) NOT VALID`, (2) `VALIDATE CONSTRAINT chk_nn`,
      (3) `ALTER COLUMN col SET NOT NULL` under `SET LOCAL lock_timeout = '2s'`, and (4) `DROP CONSTRAINT chk_nn`.
    """

    @classmethod
    def verify_pg18_btree_dedup_realtime_presence_rls_and_not_null_validation(
        cls, audit_spec: Dict[str, Any]
    ) -> PG18BTreeDedupRealtimePresenceRlsAndNotNullValidationReport:
        indexes = audit_spec.get("pg18_btree_indexes", [])
        presence_channels = audit_spec.get("realtime_presence_channels", [])
        nn_promotions = audit_spec.get("not_null_promotions", [])

        bad_idx: List[str] = []
        bad_pres: List[str] = []
        bad_nn: List[str] = []
        remediations: List[str] = []

        # 1. Verify PG18 B-Tree Posting-List Deduplication & Fillfactor
        for idx in indexes:
            idx_name = str(idx.get("index_name", "unnamed_btree_index"))
            dedup_on = bool(idx.get("deduplicate_items_enabled", False))
            fillfactor = int(idx.get("fillfactor", 100))
            leads_with_tenant_id = bool(idx.get("leads_with_tenant_id", False))

            if not dedup_on or not (80 <= fillfactor <= 95) or not leads_with_tenant_id:
                bad_idx.append(idx_name)
                remediations.append(
                    f"Configure PG18 B-Tree index '{idx_name}' leading with `tenant_id` using `WITH (deduplicate_items = on, fillfactor = 90)` via `CREATE INDEX CONCURRENTLY`."
                )

        # 2. Verify Supabase Realtime Presence Multi-Tenant RLS & Quota Guard
        for ch in presence_channels:
            ch_id = str(ch.get("channel_topic_pattern", "unnamed_presence_channel"))
            enforces_restrictive_tenant_topic = bool(ch.get("enforces_restrictive_app_metadata_tenant_topic_match", False))
            max_payload_bytes = int(ch.get("max_presence_payload_bytes", 999999))

            if not enforces_restrictive_tenant_topic or max_payload_bytes <= 0 or max_payload_bytes > 4096:
                bad_pres.append(ch_id)
                remediations.append(
                    f"Harden Realtime Presence channel '{ch_id}' on `realtime.messages` with `AS RESTRICTIVE` `(SELECT auth.jwt() -> 'app_metadata' ->> 'tenant_id') = split_part(realtime.topic(), ':', 1)` and `octet_length(payload::text) <= 4096`."
                )

        # 3. Verify Zero-Downtime SET NOT NULL via Pre-Validated CHECK Constraint
        for nn in nn_promotions:
            nn_id = f"{nn.get('table_name', 'tbl')}.{nn.get('column_name', 'col')}"
            prevalidated_check = bool(nn.get("prevalidated_is_not_null_check_not_valid", False))
            lock_timeout_ms = int(nn.get("lock_timeout_ms", 0))

            if not prevalidated_check or lock_timeout_ms <= 0 or lock_timeout_ms > 5000:
                bad_nn.append(nn_id)
                remediations.append(
                    f"Promote `{nn_id}` to `NOT NULL` safely: (1) `ADD CONSTRAINT chk_nn CHECK (col IS NOT NULL) NOT VALID`, (2) `VALIDATE CONSTRAINT chk_nn`, (3) `SET LOCAL lock_timeout = '2s'; ALTER TABLE ... ALTER COLUMN ... SET NOT NULL;`, (4) `DROP CONSTRAINT chk_nn`."
                )

        is_valid = (
            len(bad_idx) == 0
            and len(bad_pres) == 0
            and len(bad_nn) == 0
        )

        certificate = (
            "Z3_UNSAT_V18_5_PG18_BTREE_DEDUP_REALTIME_PRESENCE_RLS_AND_NOT_NULL_VERIFIED"
            if is_valid
            else "Z3_SAT_COUNTEREXAMPLE_V18_5_VIOLATION_DETECTED"
        )

        return PG18BTreeDedupRealtimePresenceRlsAndNotNullValidationReport(
            is_valid=is_valid,
            btree_dedup_indexes_checked=len(indexes),
            misconfigured_btree_dedup_indexes=bad_idx,
            presence_channels_checked=len(presence_channels),
            vulnerable_presence_rls_channels=bad_pres,
            not_null_promotions_checked=len(nn_promotions),
            blocking_set_not_null_promotions=bad_nn,
            formal_proof_certificate=certificate,
            remediation_plan=remediations,
        )


@dataclass
class PG18JsonTableDeterminismAnonRlsAndIndexSwapReport:
    """Formal report for Cycle 58 (v18.6.0 / REG-106) NODE-03 Prover."""
    passed: bool
    json_table_deterministic: bool
    anon_signin_rls_isolated: bool
    index_swap_zero_downtime_safe: bool
    violations: List[str]
    smt2_certificate: str
    remediation_ddl: str


class PG18JsonTableSqlJsonPathQueryDeterminismSupabaseRlsAnonymousSignInUpgradeIsolationAndZeroDowntimeIndexSwapDropConcurrentlyProver:
    """
    Cycle 58 (v18.6.0 | REG-106 | NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime DDL):
    Formal verifier for:
    1) PostgreSQL 17/18 SQL/JSON `JSON_TABLE` (`NESTED PATH`, `ORDINALITY`, `ON ERROR` / `ON EMPTY`)
       query determinism and strict type coercion under GIN `jsonb_path_ops` indexing.
    2) Supabase Auth Anonymous Sign-In (`is_anonymous = true` in JWT `auth.jwt()->>'is_anonymous'`)
       privilege separation and safe account linking/upgrade isolation without cross-tenant data leakage.
    3) Zero-Downtime B-Tree / GIN Index Rebuild & Swap (`CREATE INDEX CONCURRENTLY idx_new`,
       catalog/view dependency audit, and `DROP INDEX CONCURRENTLY idx_old` outside explicit transactions).
    """

    @staticmethod
    def verify_sql_ddl(sql_text: str) -> PG18JsonTableDeterminismAnonRlsAndIndexSwapReport:
        normalized = sql_text.upper()
        violations: List[str] = []

        uses_json_table = "JSON_TABLE" in normalized
        has_on_error = (
            "ERROR ON ERROR" in normalized
            or "NULL ON ERROR" in normalized
            or ("DEFAULT " in normalized and "ON ERROR" in normalized)
            or "EMPTY ARRAY ON ERROR" in normalized
        )
        has_on_empty = (
            "ERROR ON EMPTY" in normalized
            or "NULL ON EMPTY" in normalized
            or ("DEFAULT " in normalized and "ON EMPTY" in normalized)
            or "EMPTY ARRAY ON EMPTY" in normalized
        )
        json_table_deterministic = (not uses_json_table) or (has_on_error and has_on_empty)
        if uses_json_table and not json_table_deterministic:
            violations.append(
                "REG-106-JSON-TABLE-NON-DETERMINISTIC: JSON_TABLE invocation lacks explicit ON ERROR and ON EMPTY clauses, risking silent NULL coercion or runtime discrepancies."
            )

        mentions_anon_or_policy = ("CREATE POLICY" in normalized) and ("IS_ANONYMOUS" in normalized or "ANON" in normalized)
        has_select_wrapped_jwt_anon = (
            "(SELECT (AUTH.JWT()->>'IS_ANONYMOUS')::BOOLEAN)" in normalized
            or "(SELECT COALESCE((AUTH.JWT()->>'IS_ANONYMOUS')::BOOLEAN, FALSE))" in normalized
            or "RESTRICTIVE" in normalized
        )
        has_tenant_isolation_guard = (
            "(SELECT AUTH.UID())" in normalized
            or "TENANT_ID" in normalized
        )
        anon_signin_rls_isolated = (not mentions_anon_or_policy) or (has_select_wrapped_jwt_anon and has_tenant_isolation_guard)
        if mentions_anon_or_policy and not anon_signin_rls_isolated:
            violations.append(
                "REG-106-ANON-SIGNIN-RLS-LEAK: RLS policy referencing anonymous users lacks initPlan-cached (SELECT COALESCE((auth.jwt()->>'is_anonymous')::boolean, false)) or strict tenant_id/auth.uid() boundary."
            )

        has_index_ops = "CREATE INDEX" in normalized or "DROP INDEX" in normalized or "REINDEX" in normalized
        in_tx_block = bool(re.search(r"\bBEGIN\b[\s\S]*\b(CREATE|DROP)\s+INDEX\s+CONCURRENTLY\b", normalized))
        uses_blocking_reindex = bool(re.search(r"\bREINDEX\s+(TABLE|INDEX)\b(?!\s+CONCURRENTLY)", normalized))
        uses_blocking_drop_index = bool(re.search(r"\bDROP\s+INDEX\b(?!\s+CONCURRENTLY)", normalized))
        uses_blocking_create_index = bool(re.search(r"\bCREATE\s+(UNIQUE\s+)?INDEX\b(?!\s+CONCURRENTLY)", normalized))

        index_swap_zero_downtime_safe = (
            not has_index_ops
            or (
                not in_tx_block
                and not uses_blocking_reindex
                and not uses_blocking_drop_index
                and not uses_blocking_create_index
            )
        )
        if has_index_ops and not index_swap_zero_downtime_safe:
            violations.append(
                "REG-106-BLOCKING-INDEX-SWAP: Index creation, reindex, or drop must use CONCURRENTLY outside explicit BEGIN..COMMIT blocks to prevent ShareLock/AccessExclusiveLock table stalls."
            )

        passed = json_table_deterministic and anon_signin_rls_isolated and index_swap_zero_downtime_safe
        smt2_cert = (
            "(declare-const json_table_det Bool)\n"
            "(declare-const anon_rls_iso Bool)\n"
            "(declare-const idx_swap_safe Bool)\n"
            f"(assert (= json_table_det {'true' if json_table_deterministic else 'false'}))\n"
            f"(assert (= anon_rls_iso {'true' if anon_signin_rls_isolated else 'false'}))\n"
            f"(assert (= idx_swap_safe {'true' if index_swap_zero_downtime_safe else 'false'}))\n"
            "(assert (and json_table_det anon_rls_iso idx_swap_safe))\n"
            "(check-sat)"
        )
        remediation = (
            "-- REG-106 Canonical Zero-Downtime Index Swap + Deterministic JSON_TABLE + Anon RLS Guard\n"
            "CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_events_payload_gin_v2 ON public.tenant_events USING gin (payload jsonb_path_ops);\n"
            "DROP INDEX CONCURRENTLY IF EXISTS public.idx_events_payload_gin_v1;\n"
            "CREATE POLICY tenant_permanent_user_mutation_guard ON public.tenant_events AS RESTRICTIVE FOR ALL TO authenticated\n"
            "  USING (tenant_id = (SELECT public.current_tenant_id()) AND (SELECT COALESCE((auth.jwt()->>'is_anonymous')::boolean, false)) = false);"
        )
        return PG18JsonTableDeterminismAnonRlsAndIndexSwapReport(
            passed=passed,
            json_table_deterministic=json_table_deterministic,
            anon_signin_rls_isolated=anon_signin_rls_isolated,
            index_swap_zero_downtime_safe=index_swap_zero_downtime_safe,
            violations=violations,
            smt2_certificate=smt2_cert,
            remediation_ddl=remediation,
        )


@dataclass
class PG18MergeReturningAppMetadataRlsAndPartitionAttachDetachReport:
    """Formal report for Cycle 59 (v18.7.0 / REG-107) NODE-03 Prover."""
    passed: bool
    merge_returning_deterministic: bool
    app_metadata_rls_safe: bool
    partition_attach_detach_zero_downtime: bool
    violations: List[str]
    smt2_certificate: str
    remediation_ddl: str


class PG18MergeReturningActionAuditSupabaseAppMetadataRlsAntiEscalationAndZeroDowntimePartitionAttachDetachConcurrentlyProver:
    """
    Cycle 59 (v18.7.0 | REG-107 | NODE-03 Shard: Full-Stack DB, RLS Multi-Tenant & Zero-Downtime DDL):
    Formal verifier for:
    1) PostgreSQL 17/18 `MERGE INTO ... RETURNING merge_action(), OLD.*, NEW.*` deterministic
       delta auditing and tenant-scoped target matching (`ON target.tenant_id = source.tenant_id AND ...`).
    2) Supabase Auth JWT Privilege Escalation Defense: strictly banning mutable `user_metadata` /
       `raw_user_meta_data` inside RLS policies and requiring initPlan-cached `(SELECT (auth.jwt()->'app_metadata'->>'tenant_id')::uuid)`
       under `AS RESTRICTIVE` policies.
    3) Zero-Downtime Partition Lifecycle: requiring pre-validated `CHECK (...) NOT VALID` +
       `VALIDATE CONSTRAINT` before `ATTACH PARTITION` and requiring `DETACH PARTITION ... CONCURRENTLY`
       outside explicit transaction blocks.
    """

    @staticmethod
    def verify_sql_ddl(sql_text: str) -> PG18MergeReturningAppMetadataRlsAndPartitionAttachDetachReport:
        normalized = sql_text.upper()
        violations: List[str] = []

        # 1. PostgreSQL 17/18 MERGE ... RETURNING merge_action() & tenant_id join key check
        uses_merge = bool(re.search(r"\bMERGE\s+INTO\b", normalized))
        has_merge_action_returning = "MERGE_ACTION()" in normalized and "RETURNING" in normalized
        has_tenant_match = "TENANT_ID" in normalized
        merge_returning_deterministic = (not uses_merge) or (has_merge_action_returning and has_tenant_match)
        if uses_merge and not merge_returning_deterministic:
            violations.append(
                "REG-107-MERGE-RETURNING-UNAUDITED: MERGE INTO statement lacks RETURNING merge_action() delta telemetry or explicit tenant_id ON-clause matching."
            )

        # 2. Supabase RLS app_metadata vs user_metadata privilege escalation check
        has_rls_policy = "CREATE POLICY" in normalized
        uses_insecure_user_metadata = "USER_METADATA" in normalized or "RAW_USER_META_DATA" in normalized
        has_safe_app_metadata_initplan = (
            "(SELECT (AUTH.JWT()->'APP_METADATA'" in normalized
            or "(SELECT COALESCE(AUTH.JWT()->'APP_METADATA'" in normalized
            or ("APP_METADATA" not in normalized and not uses_insecure_user_metadata)
        )
        app_metadata_rls_safe = (not has_rls_policy) or (not uses_insecure_user_metadata and has_safe_app_metadata_initplan)
        if has_rls_policy and not app_metadata_rls_safe:
            violations.append(
                "REG-107-RLS-USER-METADATA-ESCALATION: RLS policy references client-mutable user_metadata/raw_user_meta_data or lacks initPlan-wrapped (SELECT (auth.jwt()->'app_metadata'->>'tenant_id')::uuid)."
            )

        # 3. Zero-Downtime Partition ATTACH / DETACH CONCURRENTLY check
        has_attach = "ATTACH PARTITION" in normalized
        has_detach = "DETACH PARTITION" in normalized
        attach_prevalidated = (not has_attach) or ("NOT VALID" in normalized and "VALIDATE CONSTRAINT" in normalized)
        detach_concurrent = (not has_detach) or (
            "CONCURRENTLY" in normalized
            and not bool(re.search(r"\bBEGIN\b[\s\S]*\bDETACH\s+PARTITION[\s\S]*\bCONCURRENTLY\b", normalized))
        )
        partition_attach_detach_zero_downtime = attach_prevalidated and detach_concurrent
        if not partition_attach_detach_zero_downtime:
            violations.append(
                "REG-107-BLOCKING-PARTITION-OP: ATTACH PARTITION requires pre-validated CHECK NOT VALID + VALIDATE CONSTRAINT, and DETACH PARTITION must use CONCURRENTLY outside BEGIN..COMMIT blocks."
            )

        passed = merge_returning_deterministic and app_metadata_rls_safe and partition_attach_detach_zero_downtime
        smt2_cert = (
            "(declare-const merge_ret_det Bool)\n"
            "(declare-const app_meta_rls_safe Bool)\n"
            "(declare-const part_attach_detach_safe Bool)\n"
            f"(assert (= merge_ret_det {'true' if merge_returning_deterministic else 'false'}))\n"
            f"(assert (= app_meta_rls_safe {'true' if app_metadata_rls_safe else 'false'}))\n"
            f"(assert (= part_attach_detach_safe {'true' if partition_attach_detach_zero_downtime else 'false'}))\n"
            "(assert (and merge_ret_det app_meta_rls_safe part_attach_detach_safe))\n"
            "(check-sat)"
        )
        remediation = (
            "-- REG-107 Canonical Zero-Downtime Partition Attach/Detach + App-Metadata RLS + PG18 MERGE RETURNING\n"
            "ALTER TABLE public.ledger_2026_11 ADD CONSTRAINT ck_ledger_2026_11_bounds CHECK (created_at >= '2026-11-01' AND created_at < '2026-12-01') NOT VALID;\n"
            "ALTER TABLE public.ledger_2026_11 VALIDATE CONSTRAINT ck_ledger_2026_11_bounds;\n"
            "ALTER TABLE public.ledger ATTACH PARTITION public.ledger_2026_11 FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');\n"
            "ALTER TABLE public.ledger DETACH PARTITION public.ledger_2025_10 CONCURRENTLY;\n"
            "CREATE POLICY ledger_tenant_app_metadata_isolation ON public.ledger AS RESTRICTIVE FOR ALL TO authenticated\n"
            "  USING (tenant_id = (SELECT (auth.jwt()->'app_metadata'->>'tenant_id')::uuid));"
        )
        return PG18MergeReturningAppMetadataRlsAndPartitionAttachDetachReport(
            passed=passed,
            merge_returning_deterministic=merge_returning_deterministic,
            app_metadata_rls_safe=app_metadata_rls_safe,
            partition_attach_detach_zero_downtime=partition_attach_detach_zero_downtime,
            violations=violations,
            smt2_certificate=smt2_cert,
            remediation_ddl=remediation,
        )


