        dag_name = str(dag_spec.get("dag_name", "mazurkiewicz_dpor_diamond_dag"))
        raw_nodes = list(dag_spec.get("nodes", []))
        raw_edges = [
            (str(e[0]).strip(), str(e[1]).strip())
            for e in dag_spec.get("edges", [])
            if isinstance(e, (list, tuple)) and len(e) == 2
        ]
        domain_inv = dict(dag_spec.get("domain_invariants", {}))

        node_ids: List[str] = []
        file_map: Dict[str, str] = {}
        range_map: Dict[str, Tuple[int, int]] = {}
        transform_map: Dict[str, Dict[str, Any]] = {}
        all_icp_bounds: Set[int] = {-1, 0, 1, 2}
        total_phis = 0
        overwrite_count = 0
        violations: List[str] = []
        patches: List[str] = []

        for idx, nd in enumerate(raw_nodes):
            nid = str(nd.get("id", f"node_{idx}")).strip()
            node_ids.append(nid)
            file_map[nid] = str(nd.get("target_file", "default.py"))
            br = list(nd.get("byte_range", [0, 0]))
            a_b = int(br[0]) if len(br) >= 1 else 0
