class CaracalBatchAppendHotspotPieceSplittingAndBohmPlaceholderMVCCDAGProver:
    """
    Nivel 355 (v21.4.0 — REG-131): Demostrador Formal de Gestión de Contención Determinista
    Caracal (Batch-Append + Serial Piece Splitting) y Pre-Asignación de Placeholders MVCC Bohm.
    """

    FORBIDDEN_CALLS = {
        "insert_version_with_per_row_cas_contention",
        "execute_monolithic_hotspot_tx_without_piece_splitting",
        "read_bohm_placeholder_before_value_filled",
        "assign_non_monotonic_64bit_serial_id",
    }

    REQUIRED_GUARDS = [
        "preallocate_batch_append_version_slots_in_initialization_phase",
        "split_contended_hotspot_pieces_to_pinned_core_queues",
        "enforce_bohm_placeholder_barrier_and_sorted_serial_id_visibility",
    ]

    @staticmethod
    def default_safe_code() -> str:
        return (
            "def execute_caracal_bohm_deterministic_epoch(epoch_batch):\n"
            "    preallocate_batch_append_version_slots_in_initialization_phase()\n"
            "    split_contended_hotspot_pieces_to_pinned_core_queues()\n"
            "    enforce_bohm_placeholder_barrier_and_sorted_serial_id_visibility()\n"
            "    return commit_caracal_bohm_deterministic_epoch(epoch_batch)\n"
        )

    @staticmethod
    def default_caracal_bohm_spec() -> Dict[str, Any]:
        return {
            "epoch_number": 214,
            "storage_min_epoch_fence": 214,
            "batch_append_arrays": [
                {
                    "key": "codere_jackpot_pool_01",
                    "declared_write_serial_ids": [1010, 1020, 1030],
                    "appended_slot_serial_ids": [1010, 1020, 1030],
                    "cas_retries_in_execution_phase": 0,
                }
            ],
            "bohm_placeholder_reads": [
                {
                    "reader_serial_id": 1025,
                    "selected_writer_serial_id": 1020,
                    "candidate_writer_serial_ids": [1010, 1020, 1030],
                    "placeholder_filled": False,
                    "reader_blocked_until_placeholder_filled": True,
                }
            ],
            "hotspot_piece_splits": [
                {
                    "piece_id": "piece_codere_round_settlement",
                    "row_contention_degree": 32,
                    "hotspot_split_threshold": 8,
                    "piece_extracted_and_core_pinned": True,
                    "assigned_core_id": 3,
                }
            ],
        }

    @staticmethod
    def _strip_comments_and_strings(code: str) -> str:
        import io
        import tokenize

        if not code:
            return ""
        out_tokens = []
        try:
            reader = io.StringIO(code).readline
            for tok_type, tok_str, _, _, _ in tokenize.generate_tokens(reader):
                if tok_type == tokenize.COMMENT:
                    continue
                if tok_type == tokenize.STRING:
                    out_tokens.append("''")
                else:
                    out_tokens.append(tok_str)
            return " ".join(out_tokens)
        except Exception:
            return code

    @classmethod
    def _audit_ast_caracal_bohm_safety(cls, code: str) -> Tuple[bool, List[int], List[str]]:
        if not code or not code.strip():
            return True, [], []
        _ = cls._strip_comments_and_strings(code)
        try:
            tree = ast.parse(code)
        except SyntaxError as exc:
            return False, [getattr(exc, "lineno", 1) or 1], [f"SYNTAX_ERROR: {exc}"]

        unsafe_lines: List[int] = []
        violations: List[str] = []

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                guards_seen = set()
                for stmt in ast.walk(node):
                    if isinstance(stmt, ast.Call):
                        func_name = ""
                        if isinstance(stmt.func, ast.Name):
                            func_name = stmt.func.id
                        elif isinstance(stmt.func, ast.Attribute):
                            func_name = stmt.func.attr
                        if func_name in cls.REQUIRED_GUARDS:
                            guards_seen.add(func_name)
                        if func_name in cls.FORBIDDEN_CALLS:
                            missing = [g for g in cls.REQUIRED_GUARDS if g not in guards_seen]
                            if missing:
                                lineno = getattr(stmt, "lineno", 1)
                                unsafe_lines.append(lineno)
                                violations.append(
                                    f"AST_UNSAFE_CARACAL_BOHM_CALL: '{func_name}' en línea {lineno} sin guardas Caracal/Bohm previas {missing}."
                                )
        return len(unsafe_lines) == 0, unsafe_lines, violations

    @classmethod
    def _repair_ast_caracal_bohm_code(cls, code: str) -> str:
        if not code or not code.strip():
            return cls.default_safe_code()
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return cls.default_safe_code()

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                guard_calls = [
                    ast.Expr(value=ast.Call(func=ast.Name(id=g, ctx=ast.Load()), args=[], keywords=[]))
                    for g in cls.REQUIRED_GUARDS
                ]
                filtered_body = []
                for stmt in node.body:
                    replaced = False
                    if isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Call):
                        fname = ""
                        if isinstance(stmt.value.func, ast.Name):
                            fname = stmt.value.func.id
                        elif isinstance(stmt.value.func, ast.Attribute):
                            fname = stmt.value.func.attr
                        if fname in cls.FORBIDDEN_CALLS:
                            filtered_body.append(
                                ast.Expr(
                                    value=ast.Call(
                                        func=ast.Name(id="commit_caracal_bohm_deterministic_epoch", ctx=ast.Load()),
                                        args=stmt.value.args,
                                        keywords=stmt.value.keywords,
                                    )
                                )
                            )
                            replaced = True
                    if not replaced:
                        filtered_body.append(stmt)
                node.body = guard_calls + filtered_body
        ast.fix_missing_locations(tree)
        try:
            return ast.unparse(tree)
        except Exception:
            return cls.default_safe_code()

    @classmethod
    def _evaluate_caracal_bohm_invariants(
        cls, spec: Dict[str, Any]
    ) -> Tuple[bool, bool, bool, bool, List[str], Dict[str, Any]]:
        violations: List[str] = []

        epoch_num = int(spec.get("epoch_number", 0))
        min_epoch = int(spec.get("storage_min_epoch_fence", 0))
        epoch_serial_id_monotonicity_valid = epoch_num >= min_epoch
        if not epoch_serial_id_monotonicity_valid:
            violations.append(
                f"CARACAL_EPOCH_FENCE_VIOLATION: epoch_number ({epoch_num}) < storage_min_epoch_fence ({min_epoch})."
            )

        batch_arrays = list(spec.get("batch_append_arrays", []))
        batch_append_placeholder_preallocation_valid = True
        boundary_serial_ids: List[int] = []
        for arr in batch_arrays:
            key = str(arr.get("key", "unknown"))
            declared = [int(x) for x in arr.get("declared_write_serial_ids", [])]
            appended = [int(x) for x in arr.get("appended_slot_serial_ids", [])]
            cas_retries = int(arr.get("cas_retries_in_execution_phase", 0))
            for sid in declared:
                boundary_serial_ids.extend([sid - 1, sid, sid + 1])
            strictly_sorted = all(appended[i] < appended[i + 1] for i in range(len(appended) - 1))
            if appended != sorted(declared) or not strictly_sorted or cas_retries != 0:
                batch_append_placeholder_preallocation_valid = False
                violations.append(
                    f"CARACAL_BATCH_APPEND_VIOLATION: key='{key}' appended={appended} vs sorted(declared)={sorted(declared)}, cas_retries={cas_retries}."
                )
                epoch_serial_id_monotonicity_valid = epoch_serial_id_monotonicity_valid and strictly_sorted

        bohm_reads = list(spec.get("bohm_placeholder_reads", []))
        bohm_placeholder_barrier_visibility_valid = True
        for br in bohm_reads:
            r_sid = int(br.get("reader_serial_id", 0))
            sel_w = int(br.get("selected_writer_serial_id", -1))
            candidates = [int(x) for x in br.get("candidate_writer_serial_ids", [])]
            filled = bool(br.get("placeholder_filled", False))
            blocked = bool(br.get("reader_blocked_until_placeholder_filled", False))
            boundary_serial_ids.extend([r_sid - 1, r_sid, r_sid + 1])
            preceding = [c for c in candidates if c < r_sid]
            expected_writer = max(preceding) if preceding else -1
            if sel_w != expected_writer or (not filled and not blocked):
                bohm_placeholder_barrier_visibility_valid = False
                violations.append(
                    f"BOHM_PLACEHOLDER_VISIBILITY_VIOLATION: reader={r_sid} seleccionó writer={sel_w} (esperado={expected_writer}), filled={filled}, blocked={blocked}."
                )

        splits = list(spec.get("hotspot_piece_splits", []))
        hotspot_piece_serial_splitting_valid = True
        for sp in splits:
            piece_id = str(sp.get("piece_id", "unknown"))
            deg = int(sp.get("row_contention_degree", 0))
            thresh = int(sp.get("hotspot_split_threshold", 8))
            pinned = bool(sp.get("piece_extracted_and_core_pinned", False))
            core_id = int(sp.get("assigned_core_id", -1))
            if deg >= thresh and (not pinned or core_id < 0):
                hotspot_piece_serial_splitting_valid = False
                violations.append(
                    f"CARACAL_HOTSPOT_SPLIT_VIOLATION: piece='{piece_id}' con contención {deg} >= {thresh} no fue extraída y fijada a un core válido (pinned={pinned}, core_id={core_id})."
                )

        witness = {
            "epoch_number": epoch_num,
            "storage_min_epoch_fence": min_epoch,
            "boundary_serial_ids_checked": sorted(set(boundary_serial_ids)),
        }
        return (
            batch_append_placeholder_preallocation_valid,
            bohm_placeholder_barrier_visibility_valid,
            hotspot_piece_serial_splitting_valid,
            epoch_serial_id_monotonicity_valid,
            violations,
            witness,
        )

    @classmethod
    def _repair_caracal_bohm_spec(cls, spec: Dict[str, Any]) -> Dict[str, Any]:
        import copy

        repaired = copy.deepcopy(spec) if spec else cls.default_caracal_bohm_spec()
        min_epoch = max(1, int(repaired.get("storage_min_epoch_fence", 214)))
        repaired["storage_min_epoch_fence"] = min_epoch
        if int(repaired.get("epoch_number", 0)) < min_epoch:
            repaired["epoch_number"] = min_epoch

        for arr in repaired.get("batch_append_arrays", []):
            declared = sorted(set(int(x) for x in arr.get("declared_write_serial_ids", [1010, 1020, 1030])))
            if len(declared) < 2:
                declared = [1010, 1020, 1030]
            arr["declared_write_serial_ids"] = declared
            arr["appended_slot_serial_ids"] = list(declared)
            arr["cas_retries_in_execution_phase"] = 0

        for br in repaired.get("bohm_placeholder_reads", []):
            r_sid = int(br.get("reader_serial_id", 1025))
            candidates = sorted(set(int(x) for x in br.get("candidate_writer_serial_ids", [1010, 1020, 1030])))
            preceding = [c for c in candidates if c < r_sid]
            if not preceding:
                candidates = [r_sid - 5] + candidates
                preceding = [r_sid - 5]
            br["candidate_writer_serial_ids"] = sorted(set(candidates))
            br["selected_writer_serial_id"] = max(preceding)
            if not bool(br.get("placeholder_filled", False)):
                br["reader_blocked_until_placeholder_filled"] = True

        for sp in repaired.get("hotspot_piece_splits", []):
            deg = int(sp.get("row_contention_degree", 32))
            thresh = int(sp.get("hotspot_split_threshold", 8))
            if deg >= thresh:
                sp["piece_extracted_and_core_pinned"] = True
                if int(sp.get("assigned_core_id", -1)) < 0:
                    sp["assigned_core_id"] = 0

        return repaired

