    @classmethod
    def _audit_ast_guards(cls, code: str) -> Tuple[bool, List[int], List[str]]:
        if not code or not code.strip():
            return True, [], []
        _ = BambooRetiredLockEarlyReleaseCommitBarrierAndRococoDeferredPieceDAGProver._strip_comments_and_strings(code)
        unsafe_lines: List[int] = []
        violations: List[str] = []
        try:
            tree = ast.parse(code)
        except SyntaxError:
            return False, [1], ["SYNTAX_ERROR"]

        seen_guards: set = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func_name = ""
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    func_name = node.func.attr
                if func_name in cls.REQUIRED_GUARDS:
                    seen_guards.add(func_name)

        all_guards_present = all(g in seen_guards for g in cls.REQUIRED_GUARDS)

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func_name = ""
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    func_name = node.func.attr
                if func_name in cls.FORBIDDEN_CALLS and not all_guards_present:
                    lineno = getattr(node, "lineno", 1)
                    unsafe_lines.append(lineno)
                    violations.append(
                        f"Línea {lineno}: llamada peligrosa '{func_name}' sin guardias formales Janus/Taurus {cls.REQUIRED_GUARDS}."
                    )

        return len(unsafe_lines) == 0, sorted(set(unsafe_lines)), violations

    @classmethod
    def _evaluate_janus_taurus_invariants(
        cls, spec: Dict[str, Any]
    ) -> Tuple[bool, bool, bool, bool, List[str], Dict[str, Any]]:
        violations: List[str] = []
        witness: Dict[str, Any] = {
            "critical_boundary_points": ["assigned_lsn - 1", "assigned_lsn", "assigned_lsn + 1"],
            "janus_quorum_counterexamples": [],
            "janus_scc_counterexamples": [],
            "taurus_lv_update_counterexamples": [],
            "taurus_recovery_counterexamples": [],
        }

        quorum_ok = True
        for item in spec.get("janus_quorums", []):
            pid = str(item.get("tx_piece_id", "unknown_piece"))
            n_rep = int(item.get("replica_count", 5))
            fast_replies = int(item.get("fast_quorum_replies", 0))
            identical = bool(item.get("Identical_dependency_graphs", False))
            paxos_ok = bool(item.get("paxos_slow_path_quorum_met", False))
            union_built = bool(item.get("union_graph_constructed", False))
            fast_path_valid = (fast_replies >= n_rep and identical)
            if not union_built or (not fast_path_valid and not paxos_ok):
                quorum_ok = False
                violations.append(
                    f"Janus Quorum Violation en '{pid}': fast_replies={fast_replies}/{n_rep}, identical={identical}, paxos_ok={paxos_ok}, union_built={union_built}."
                )
                witness["janus_quorum_counterexamples"].append(
                    {
                        "tx_piece_id": pid,
                        "fast_quorum_replies": fast_replies,
                        "replica_count": n_rep,
                        "paxos_slow_path_quorum_met": paxos_ok,
                    }
                )

        scc_ok = True
        for item in spec.get("janus_scc_executions", []):
            sid = str(item.get("scc_id", "unknown_scc"))
            tiebreaker = bool(item.get("scc_deterministic_timestamp_tiebreaker_enforced", False))
            ready = bool(item.get("local_piece_operands_ready", False))
            aborted_cycle = bool(item.get("aborted_due_to_cycle", False))
            if not tiebreaker or not ready or aborted_cycle:
                scc_ok = False
                violations.append(
                    f"Janus SCC Execution Violation en '{sid}': tiebreaker={tiebreaker}, operands_ready={ready}, aborted_due_to_cycle={aborted_cycle}."
                )
                witness["janus_scc_counterexamples"].append(
                    {
                        "scc_id": sid,
                        "scc_deterministic_timestamp_tiebreaker_enforced": tiebreaker,
                        "local_piece_operands_ready": ready,
                        "aborted_due_to_cycle": aborted_cycle,
                    }
                )

        lv_ok = True
        for item in spec.get("taurus_lv_updates", []):
            tid = str(item.get("tx_id", "unknown_tx"))
            s_idx = int(item.get("stream_idx", 0))
            lsn = int(item.get("assigned_lsn", 0))
            obs_lv = [int(x) for x in item.get("observed_item_lv", [])]
            tx_lv = [int(x) for x in item.get("tx_lv", [])]
            after_lv = [int(x) for x in item.get("item_after_lv", [])]
            unlocked_after = bool(item.get("lock_released_after_lv_update", False))
            k_len = len(obs_lv)
            dom_obs = (len(tx_lv) == k_len and all(tx_lv[i] >= obs_lv[i] for i in range(k_len)))
            dom_after = (len(after_lv) == k_len and all(after_lv[i] >= tx_lv[i] for i in range(k_len)))
            lsn_match = (0 <= s_idx < len(tx_lv) and tx_lv[s_idx] >= lsn)
            if not dom_obs or not dom_after or not lsn_match or not unlocked_after:
                lv_ok = False
                violations.append(
                    f"Taurus LSNVector Update Violation en '{tid}': dom_obs={dom_obs}, dom_after={dom_after}, lsn_match={lsn_match}, unlocked_after={unlocked_after}."
                )
                witness["taurus_lv_update_counterexamples"].append(
                    {
                        "tx_id": tid,
                        "observed_item_lv": obs_lv,
                        "tx_lv": tx_lv,
                        "item_after_lv": after_lv,
                        "lock_released_after_lv_update": unlocked_after,
                    }
                )

        rec_ok = True
        for item in spec.get("taurus_recovery_replays", []):
            tid = str(item.get("tx_id", "unknown_recovery_tx"))
            tx_lv = [int(x) for x in item.get("tx_lv", [])]
            rep_lv = [int(x) for x in item.get("replayed_streams_lv", [])]
            barrier_respected = bool(item.get("replayed_only_after_vector_barrier", False))
            k_len = len(tx_lv)
            vec_met = (len(rep_lv) == k_len and all(rep_lv[i] >= tx_lv[i] for i in range(k_len)))
            if not vec_met or not barrier_respected:
                rec_ok = False
                violations.append(
                    f"Taurus Parallel Recovery Violation en '{tid}': vec_met={vec_met}, barrier_respected={barrier_respected}, tx_lv={tx_lv}, replayed_streams_lv={rep_lv}."
                )
                witness["taurus_recovery_counterexamples"].append(
                    {
                        "tx_id": tid,
                        "tx_lv": tx_lv,
                        "replayed_streams_lv": rep_lv,
                        "replayed_only_after_vector_barrier": barrier_respected,
                    }
                )

        return quorum_ok, scc_ok, lv_ok, rec_ok, violations, witness

    @classmethod
    def _synthesize_cegis_repair(
        cls, code: str, spec: Dict[str, Any]
    ) -> Tuple[str, Dict[str, Any]]:
        import copy
        repaired_lines = [
            "consolidate_janus_union_dependency_graph_and_tarjan_scc_order()",
            "update_taurus_elementwise_max_lsn_vector_before_lock_release()",
            "enforce_taurus_parallel_wal_recovery_vector_barrier()",
        ]
        nl = chr(10)
        if code and code.strip():
            repaired_code = nl.join(repaired_lines) + nl + code.lstrip(nl)
        else:
            repaired_code = nl.join(repaired_lines)

        repaired_spec = json.loads(json.dumps(spec))
        for item in repaired_spec.get("janus_quorums", []):
            n_rep = max(5, int(item.get("replica_count", 5)))
            item["replica_count"] = n_rep
            item["fast_quorum_replies"] = n_rep
            item["Identical_dependency_graphs"] = True
            item["paxos_slow_path_quorum_met"] = True
            item["union_graph_constructed"] = True

        for item in repaired_spec.get("janus_scc_executions", []):
            item["scc_deterministic_timestamp_tiebreaker_enforced"] = True
            item["local_piece_operands_ready"] = True
            item["aborted_due_to_cycle"] = False

        for item in repaired_spec.get("taurus_lv_updates", []):
            s_idx = int(item.get("stream_idx", 0))
            lsn = int(item.get("assigned_lsn", 500))
            obs_lv = [int(x) for x in item.get("observed_item_lv", [480, 420, 390, 410])]
            tx_lv = list(obs_lv)
            if 0 <= s_idx < len(tx_lv):
                tx_lv[s_idx] = max(tx_lv[s_idx], lsn)
            item["tx_lv"] = tx_lv
            item["item_after_lv"] = list(tx_lv)
            item["lock_released_after_lv_update"] = True

        for item in repaired_spec.get("taurus_recovery_replays", []):
            tx_lv = [int(x) for x in item.get("tx_lv", [500, 420, 390, 410])]
            rep_lv = [int(x) for x in item.get("replayed_streams_lv", list(tx_lv))]
            if len(rep_lv) != len(tx_lv):
                rep_lv = list(tx_lv)
            else:
                rep_lv = [max(rep_lv[i], tx_lv[i]) for i in range(len(tx_lv))]
            item["replayed_streams_lv"] = rep_lv
            item["replayed_only_after_vector_barrier"] = True

        return repaired_code, repaired_spec

