    @classmethod
    def _audit_ast_guards(cls, code: str) -> Tuple[bool, List[int], List[str]]:
        if not code or not code.strip():
            return True, [], []
        try:
            tree = ast.parse(code)
        except SyntaxError as exc:
            return False, [exc.lineno or 1], [f"SyntaxError en línea {exc.lineno}: {exc.msg}"]

        called_names: Set[str] = set()
        unsafe_lines: List[int] = []
        violations: List[str] = []

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func_name = None
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    func_name = node.func.attr
                if func_name:
                    called_names.add(func_name)
                    if func_name in cls.UNSAFE_CALL_NAMES:
                        lineno = getattr(node, "lineno", 1)
                        unsafe_lines.append(lineno)
                        violations.append(
                            f"Llamada peligrosa Hekaton-MVCC/Dumbo-NG '{func_name}' en línea {lineno} sin guardas formales."
                        )

        if unsafe_lines:
            has_all_guards = all(g in called_names for g in cls.REQUIRED_GUARD_MARKERS)
            if has_all_guards:
                return True, [], []
            return False, sorted(set(unsafe_lines)), violations

        return True, [], []

    @classmethod
    def _evaluate_hekaton_dumbong_invariants(
        cls, spec: Dict[str, Any]
    ) -> Tuple[bool, bool, bool, bool, List[str], Dict[str, Any]]:
        violations: List[str] = []
        smt_witness: Dict[str, Any] = {}

        dep_entries = spec.get("hekaton_version_dependencies", [])
        dep_ok = True
        if not dep_entries:
            dep_ok = False
            violations.append("hekaton_version_dependencies vacío: se requiere al menos una versión MVCC verificada.")
        for idx, item in enumerate(dep_entries):
            tx_id = str(item.get("tx_id", f"tx_{idx}"))
            begin_ts = int(item.get("begin_ts", 0))
            end_ts = int(item.get("end_ts", 0))
            dep_cnt = int(item.get("commit_dependency_counter", -1))
            parent_aborted = bool(item.get("speculative_parent_aborted", False))
            gated_release = bool(item.get("external_result_released_only_after_dep_zero", False))
            if begin_ts >= end_ts or dep_cnt != 0 or parent_aborted or not gated_release:
                dep_ok = False
                violations.append(
                    f"Violación Hekaton MVCC Dependency en {tx_id}: begin_ts={begin_ts}, end_ts={end_ts}, dep_counter={dep_cnt}, parent_aborted={parent_aborted}, gated_release={gated_release}."
                )
                smt_witness[f"hekaton_dep_counterexample_{tx_id}"] = {
                    "begin_ts": begin_ts,
                    "end_ts": end_ts,
                    "commit_dependency_counter": dep_cnt,
                    "speculative_parent_aborted": parent_aborted,
                }

        scan_entries = spec.get("hekaton_validation_scans", [])
        scan_ok = True
        if not scan_entries:
            scan_ok = False
            violations.append("hekaton_validation_scans vacío: se requiere validación de Read-Set y Scan-Set.")
        for idx, item in enumerate(scan_entries):
            tx_id = str(item.get("tx_id", f"tx_scan_{idx}"))
            read_vis = bool(item.get("read_versions_visible_at_commit_ts", False))
            scan_rep = bool(item.get("scan_set_phantom_repeatability_verified", False))
            latch_free = bool(item.get("lock_free_index_latch_free", False))
            if not read_vis or not scan_rep or not latch_free:
                scan_ok = False
                violations.append(
                    f"Violación Hekaton Read/Scan Validation en {tx_id}: read_visible={read_vis}, scan_repeatability={scan_rep}, latch_free={latch_free}."
                )
                smt_witness[f"hekaton_scan_counterexample_{tx_id}"] = {
                    "read_versions_visible_at_commit_ts": read_vis,
                    "scan_set_phantom_repeatability_verified": scan_rep,
                    "lock_free_index_latch_free": latch_free,
                }

        bcast_entries = spec.get("dumbo_ng_broadcast_streams", [])
        bcast_ok = True
        if not bcast_entries:
            bcast_ok = False
            violations.append("dumbo_ng_broadcast_streams vacío: se requiere al menos un flujo de broadcast certificado.")
        for idx, item in enumerate(bcast_entries):
            prop_id = str(item.get("proposer_id", f"val_{idx}"))
            slot_h = int(item.get("slot_height", 0))
            f_val = int(item.get("byzantine_f", 1))
            signers = int(item.get("slot_quorum_certificate_signers", 0))
            pred_cert = bool(item.get("pipelined_predecessor_slot_certified", False))
            min_q = 2 * f_val + 1
            if f_val < 1 or slot_h < 1 or signers < min_q or not pred_cert:
                bcast_ok = False
                violations.append(
                    f"Violación Dumbo-NG Broadcast Stream en {prop_id} (slot {slot_h}): signers={signers} < 2f+1={min_q} o pred_cert={pred_cert}."
                )
