    @classmethod
    def _audit_ast_guards(cls, code: str) -> Tuple[bool, List[int], List[str]]:
        if not code or not code.strip():
            return True, [], []
        try:
            tree = ast.parse(code)
        except SyntaxError as exc:
            return False, [exc.lineno or 1], [f"SyntaxError en línea {exc.lineno}: {exc.msg}"]

        called_names: Set[str] = set()
        unsafe_lines: List[int] = []
        violations: List[str] = []

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func_name = None
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    func_name = node.func.attr
                if func_name:
                    called_names.add(func_name)
                    if func_name in cls.UNSAFE_CALL_NAMES:
                        lineno = getattr(node, "lineno", 1)
                        unsafe_lines.append(lineno)
                        violations.append(
                            f"Llamada peligrosa HyPer-MVCC/HotStuff-1 '{func_name}' en línea {lineno} sin guardas formales."
                        )

        if unsafe_lines:
            has_all_guards = all(g in called_names for g in cls.REQUIRED_GUARD_MARKERS)
            if has_all_guards:
                return True, [], []
            return False, sorted(set(unsafe_lines)), violations

        return True, [], []

    @classmethod
    def _evaluate_hyper_hotstuff1_invariants(
        cls, spec: Dict[str, Any]
    ) -> Tuple[bool, bool, bool, bool, List[str], Dict[str, Any]]:
        violations: List[str] = []
        smt_witness: Dict[str, Any] = {}

        undo_entries = spec.get("hyper_undo_buffers", [])
        undo_ok = True
        if not undo_entries:
            undo_ok = False
            violations.append("hyper_undo_buffers vacío: se requiere al menos un buffer de undo versionado.")
        for idx, item in enumerate(undo_entries):
            tx_id = str(item.get("tx_id", f"tx_{idx}"))
            s_ts = int(item.get("snapshot_start_ts", 0))
            c_ts = int(item.get("commit_ts", 0))
            undo_linked = bool(item.get("in_place_update_undo_buffer_linked", False))
            vv_sync = bool(item.get("version_vector_dirty_flag_synchronized", False))
            if s_ts >= c_ts or not undo_linked or not vv_sync:
                undo_ok = False
                violations.append(
                    f"Violación HyPer Undo Buffer en {tx_id}: snapshot_start_ts={s_ts}, commit_ts={c_ts}, undo_linked={undo_linked}, vv_sync={vv_sync}."
                )
                smt_witness[f"hyper_undo_counterexample_{tx_id}"] = {
                    "snapshot_start_ts": s_ts,
                    "commit_ts": c_ts,
                    "in_place_update_undo_buffer_linked": undo_linked,
                    "version_vector_dirty_flag_synchronized": vv_sync,
                }

        prec_entries = spec.get("hyper_precision_locks", [])
        prec_ok = True
        if not prec_entries:
            prec_ok = False
            violations.append("hyper_precision_locks vacío: se requiere validación de Precision Locking PSB.")
        for idx, item in enumerate(prec_entries):
            tx_id = str(item.get("tx_id", f"tx_prec_{idx}"))
            intersects = bool(item.get("extensional_committed_writes_intersect_read_predicates", True))
            psb_ok = bool(item.get("precision_lock_psb_validated", False))
            if intersects or not psb_ok:
                prec_ok = False
                violations.append(
                    f"Violación HyPer Precision Locking en {tx_id}: extensional_intersects={intersects}, psb_validated={psb_ok}."
                )
                smt_witness[f"hyper_precision_counterexample_{tx_id}"] = {
                    "extensional_committed_writes_intersect_read_predicates": intersects,
                    "precision_lock_psb_validated": psb_ok,
                }

        spec_entries = spec.get("hotstuff1_speculative_phases", [])
        spec_ok = True
        if not spec_entries:
            spec_ok = False
            violations.append("hotstuff1_speculative_phases vacío: se requiere al menos una fase especulativa.")
        for idx, item in enumerate(spec_entries):
            view_id = item.get("view_id", idx)
            f_val = int(item.get("byzantine_f", 1))
            votes = int(item.get("speculative_phase1_vote_count", 0))
            prefix_ok = bool(item.get("prefix_speculation_dilemma_guard_satisfied", False))
            min_q = 2 * f_val + 1
            if f_val < 1 or votes < min_q or not prefix_ok:
                spec_ok = False
                violations.append(
                    f"Violación HotStuff-1 One-Phase Speculation en vista {view_id}: votes={votes} < 2f+1={min_q}, prefix_guard={prefix_ok}."
                )
                smt_witness[f"hotstuff1_spec_counterexample_{view_id}"] = {
                    "speculative_phase1_vote_count": votes,
                    "required_quorum": min_q,
                    "prefix_speculation_dilemma_guard_satisfied": prefix_ok,
                }

        slot_entries = spec.get("hotstuff1_dynamic_slots", [])
        slot_ok = True
        if not slot_entries:
            slot_ok = False
            violations.append("hotstuff1_dynamic_slots vacío: se requiere al menos un registro de slotting dinámico.")
        for idx, item in enumerate(slot_entries):
            view_id = item.get("view_id", idx)
            slots = int(item.get("executed_slots_in_view", 0))
            lat_ms = int(item.get("slot_execution_latency_ms", 0))
            budget_ms = int(item.get("view_timer_budget_ms", 0))
            lin_ok = bool(item.get("linear_communication_complexity_preserved", False))
            if slots < 1 or budget_ms <= 0 or lat_ms > budget_ms or not lin_ok:
                slot_ok = False
                violations.append(
                    f"Violación HotStuff-1 Dynamic Slotting en vista {view_id}: slots={slots}, latency={lat_ms}ms > budget={budget_ms}ms, linear={lin_ok}."
                )
                smt_witness[f"hotstuff1_slot_counterexample_{view_id}"] = {
                    "executed_slots_in_view": slots,
                    "slot_execution_latency_ms": lat_ms,
                    "view_timer_budget_ms": budget_ms,
                    "linear_communication_complexity_preserved": lin_ok,
                }

        return undo_ok, prec_ok, spec_ok, slot_ok, violations, smt_witness

