    @classmethod
    def _audit_ast_guards(cls, code: str) -> Tuple[bool, List[int], List[str]]:
        if not code or not code.strip():
            return True, [], []
        try:
            tree = ast.parse(code)
        except SyntaxError as exc:
            return False, [exc.lineno or 1], [f"SyntaxError en línea {exc.lineno}: {exc.msg}"]

        called_names: Set[str] = set()
        unsafe_lines: List[int] = []
        violations: List[str] = []

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func_name = None
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    func_name = node.func.attr
                if func_name:
                    called_names.add(func_name)
                    if func_name in cls.UNSAFE_CALL_NAMES:
                        lineno = getattr(node, "lineno", 1)
                        unsafe_lines.append(lineno)
                        violations.append(
                            f"Llamada peligrosa Scalog/Starfish '{func_name}' en línea {lineno} sin guardas formales."
                        )

        if unsafe_lines:
            has_all_guards = all(g in called_names for g in cls.REQUIRED_GUARD_MARKERS)
            if has_all_guards:
                return True, [], []
            return False, sorted(set(unsafe_lines)), violations

        return True, [], []

