    @classmethod
    def _audit_ast_guards(cls, code: str) -> Tuple[bool, List[int], List[str]]:
        if not code or not code.strip():
            return True, [], []
        try:
            tree = ast.parse(code)
        except SyntaxError as exc:
            return False, [exc.lineno or 1], [f"SyntaxError en línea {exc.lineno}: {exc.msg}"]

        called_names: Set[str] = set()
        unsafe_lines: List[int] = []
        violations: List[str] = []

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func_name = None
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    func_name = node.func.attr
                if func_name:
                    called_names.add(func_name)
                    if func_name in cls.UNSAFE_CALL_NAMES:
                        lineno = getattr(node, "lineno", 1)
                        unsafe_lines.append(lineno)
                        violations.append(
                            f"Llamada peligrosa Delos/LightDAG '{func_name}' en línea {lineno} sin guardas formales."
                        )

        if unsafe_lines:
            has_all_guards = all(g in called_names for g in cls.REQUIRED_GUARD_MARKERS)
            if has_all_guards:
                return True, [], []
            return False, sorted(set(unsafe_lines)), violations

        return True, [], []

    @classmethod
    def _evaluate_delos_lightdag_invariants(
        cls, spec: Dict[str, Any]
    ) -> Tuple[bool, bool, bool, bool, List[str], Dict[str, Any]]:
        violations: List[str] = []
        smt_witness: Dict[str, Any] = {}

        trans_entries = spec.get("delos_loglet_transitions", [])
        seal_ok = True
        if not trans_entries:
            seal_ok = False
            violations.append("delos_loglet_transitions vacío: se requiere al menos una transición de Loglet.")
        for idx, item in enumerate(trans_entries):
            t_id = str(item.get("transition_id", f"trans_{idx}"))
            max_off = int(item.get("sealed_loglet_max_offset", -1))
            next_off = int(item.get("next_loglet_start_offset", -1))
            sealed = bool(item.get("active_loglet_sealed_before_chain_switch", False))
            contig = bool(item.get("virtual_log_stripe_offset_contiguous", False))
            if max_off < 0 or next_off != max_off + 1 or not sealed or not contig:
                seal_ok = False
                violations.append(
                    f"Violación Delos Loglet Sealing en {t_id}: max_off={max_off}, next_off={next_off} (req {max_off+1}), sealed={sealed}, contig={contig}."
                )
                smt_witness[f"delos_seal_counterexample_{t_id}"] = {
                    "sealed_loglet_max_offset": max_off,
                    "next_loglet_start_offset": next_off,
                    "active_loglet_sealed_before_chain_switch": sealed,
                    "virtual_log_stripe_offset_contiguous": contig,
                }

        meta_entries = spec.get("delos_metastore_epochs", [])
        meta_ok = True
        if not meta_entries:
            meta_ok = False
            violations.append("delos_metastore_epochs vacío: se requiere versión de MetaStore Delos.")
        for idx, item in enumerate(meta_entries):
            c_id = str(item.get("chain_id", f"chain_{idx}"))
            prev_v = int(item.get("previous_metastore_version", 0))
            curr_v = int(item.get("current_metastore_version", 0))
            zd_ok = bool(item.get("zero_downtime_protocol_upgrade_verified", False))
            if prev_v < 0 or curr_v <= prev_v or not zd_ok:
                meta_ok = False
                violations.append(
                    f"Violación Delos MetaStore Epoch en {c_id}: prev_v={prev_v}, curr_v={curr_v}, zero_downtime={zd_ok}."
                )
                smt_witness[f"delos_meta_counterexample_{c_id}"] = {
                    "previous_metastore_version": prev_v,
                    "current_metastore_version": curr_v,
                    "zero_downtime_protocol_upgrade_verified": zd_ok,
                }

        cbc_entries = spec.get("lightdag_cbc_broadcasts", [])
        cbc_ok = True
        if not cbc_entries:
            cbc_ok = False
            violations.append("lightdag_cbc_broadcasts vacío: se requiere difusión CBC LightDAG.")
        for idx, item in enumerate(cbc_entries):
            v_id = str(item.get("vertex_id", f"vtx_{idx}"))
            f_val = int(item.get("byzantine_f", 1))
            total_v = int(item.get("total_validators", 0))
            steps = int(item.get("lightweight_broadcast_steps", 0))
            signers = int(item.get("equivocation_free_cbc_quorum_signers", 0))
            min_total = 3 * f_val + 1
            min_q = 2 * f_val + 1
            if f_val < 1 or total_v < min_total or steps != 2 or signers < min_q:
                cbc_ok = False
                violations.append(
                    f"Violación LightDAG Two-Step CBC en {v_id}: steps={steps} (req 2), signers={signers} < 2f+1={min_q}, total={total_v} < {min_total}."
                )
                smt_witness[f"lightdag_cbc_counterexample_{v_id}"] = {
                    "lightweight_broadcast_steps": steps,
                    "equivocation_free_cbc_quorum_signers": signers,
                    "required_quorum": min_q,
                    "total_validators": total_v,
                }

        commit_entries = spec.get("lightdag_totality_commits", [])
        commit_ok = True
        if not commit_entries:
            commit_ok = False
            violations.append("lightdag_totality_commits vacío: se requiere confirmación de totalidad LightDAG.")
        for idx, item in enumerate(commit_entries):
            a_id = str(item.get("anchor_id", f"anchor_{idx}"))
            f_val = int(item.get("byzantine_f", 1))
            total_v = int(item.get("total_validators", 0))
            pull_ok = bool(item.get("ancestor_pull_totality_recovery_enabled", False))
            quorum = int(item.get("leader_anchor_commit_quorum_validators", 0))
            min_total = 3 * f_val + 1
            min_q = 2 * f_val + 1
            if f_val < 1 or total_v < min_total or not pull_ok or quorum < min_q:
                commit_ok = False
                violations.append(
                    f"Violación LightDAG Totality Commit en {a_id}: ancestor_pull={pull_ok}, quorum={quorum} < 2f+1={min_q}, total={total_v} < {min_total}."
                )
                smt_witness[f"lightdag_commit_counterexample_{a_id}"] = {
                    "ancestor_pull_totality_recovery_enabled": pull_ok,
                    "leader_anchor_commit_quorum_validators": quorum,
                    "required_quorum": min_q,
                }

        return seal_ok, meta_ok, cbc_ok, commit_ok, violations, smt_witness

    @classmethod
    def _synthesize_cegis_repair(
        cls, code: str, spec: Dict[str, Any]
    ) -> Tuple[str, Dict[str, Any]]:
        import copy
        repaired_code = code
        if code and code.strip():
            lines = code.splitlines()
            patched_lines: List[str] = []
            guard_injected = False
            for line in lines:
                stripped = line.strip()
                if (
                    not guard_injected
                    and any(u in stripped for u in cls.UNSAFE_CALL_NAMES)
                    and not stripped.startswith("#")
                ):
                    indent = line[: len(line) - len(line.lstrip())]
                    patched_lines.append(
                        f"{indent}enforce_delos_virtuallog_loglet_sealing_and_metastore_continuity_guard()"
                    )
                    patched_lines.append(
                        f"{indent}enforce_lightdag_consistent_broadcast_and_ancestor_totality_guard()"
                    )
                    guard_injected = True
                patched_lines.append(line)
            repaired_code = "\n".join(patched_lines) + ("\n" if code.endswith("\n") else "")

        repaired_spec = json.loads(json.dumps(spec))
        for item in repaired_spec.get("delos_loglet_transitions", []):
            max_off = max(0, int(item.get("sealed_loglet_max_offset", 1000)))
            item["sealed_loglet_max_offset"] = max_off
            item["next_loglet_start_offset"] = max_off + 1
            item["active_loglet_sealed_before_chain_switch"] = True
            item["virtual_log_stripe_offset_contiguous"] = True

        for item in repaired_spec.get("delos_metastore_epochs", []):
            prev_v = max(0, int(item.get("previous_metastore_version", 1)))
            curr_v = int(item.get("current_metastore_version", prev_v + 1))
            if curr_v <= prev_v:
                curr_v = prev_v + 1
            item["previous_metastore_version"] = prev_v
            item["current_metastore_version"] = curr_v
            item["zero_downtime_protocol_upgrade_verified"] = True

        for item in repaired_spec.get("lightdag_cbc_broadcasts", []):
            f_val = max(1, int(item.get("byzantine_f", 1)))
            min_total = 3 * f_val + 1
            min_q = 2 * f_val + 1
            item["byzantine_f"] = f_val
            item["total_validators"] = max(int(item.get("total_validators", 0)), min_total)
            item["lightweight_broadcast_steps"] = 2
            item["equivocation_free_cbc_quorum_signers"] = max(
                int(item.get("equivocation_free_cbc_quorum_signers", 0)), min_q
            )

        for item in repaired_spec.get("lightdag_totality_commits", []):
            f_val = max(1, int(item.get("byzantine_f", 1)))
            min_total = 3 * f_val + 1
            min_q = 2 * f_val + 1
            item["byzantine_f"] = f_val
            item["total_validators"] = max(int(item.get("total_validators", 0)), min_total)
            item["ancestor_pull_totality_recovery_enabled"] = True
            item["leader_anchor_commit_quorum_validators"] = max(
                int(item.get("leader_anchor_commit_quorum_validators", 0)), min_q
            )

        return repaired_code, repaired_spec

    @classmethod
    def audit_and_repair_delos_virtuallog_and_lightdag(
        cls,
        code: str = "",
        delos_lightdag_spec: Optional[Dict[str, Any]] = None,
        dag_edges: Optional[List[Tuple[str, str]]] = None,
        auto_repair: bool = True,
    ) -> DelosLightDAGAuditReport:
        import copy
        spec = (
            copy.deepcopy(delos_lightdag_spec)
            if delos_lightdag_spec
            else cls.default_delos_lightdag_spec()
        )
        edges = dag_edges if dag_edges is not None else cls.DEFAULT_DAG_EDGES

        ast_ok, unsafe_lines, ast_violations = cls._audit_ast_guards(code)
        seal_ok, meta_ok, cbc_ok, commit_ok, spec_violations, smt_witness = (
            cls._evaluate_delos_lightdag_invariants(spec)
        )
        violations = ast_violations + spec_violations

        cegis_repaired = False
        repaired_code = code
        repaired_spec = spec

        if (not ast_ok or not seal_ok or not meta_ok or not cbc_ok or not commit_ok) and auto_repair:
            repaired_code, repaired_spec = cls._synthesize_cegis_repair(code, spec)
            ast_ok, unsafe_lines, ast_violations = cls._audit_ast_guards(repaired_code)
            seal_ok, meta_ok, cbc_ok, commit_ok, spec_violations, smt_witness = (
                cls._evaluate_delos_lightdag_invariants(repaired_spec)
            )
            violations = ast_violations + spec_violations
            cegis_repaired = True

        nodes_set = set(cls.DEFAULT_DAG_NODES)
