    @classmethod
    def _audit_ast_guards(cls, code: str) -> Tuple[bool, List[int], List[str]]:
        if not code or not code.strip():
            return True, [], []
        try:
            tree = ast.parse(code)
        except SyntaxError as exc:
            return False, [exc.lineno or 1], [f"SyntaxError en línea {exc.lineno}: {exc.msg}"]

        called_names: Set[str] = set()
        unsafe_lines: List[int] = []
        violations: List[str] = []

        for node in ast.walk(tree):
            if isinstance(node, ast.Call):
                func_name = None
                if isinstance(node.func, ast.Name):
                    func_name = node.func.id
                elif isinstance(node.func, ast.Attribute):
                    func_name = node.func.attr
                if func_name:
                    called_names.add(func_name)
                    if func_name in cls.UNSAFE_CALL_NAMES:
                        lineno = getattr(node, "lineno", 1)
                        unsafe_lines.append(lineno)
                        violations.append(
                            f"Llamada peligrosa Tango/Hydrangea '{func_name}' en línea {lineno} sin guardas formales."
                        )

        if unsafe_lines:
            has_all_guards = all(g in called_names for g in cls.REQUIRED_GUARD_MARKERS)
            if has_all_guards:
                return True, [], []
            return False, sorted(set(unsafe_lines)), violations

        return True, [], []

    @classmethod
    def _evaluate_tango_hydrangea_invariants(
        cls, spec: Dict[str, Any]
    ) -> Tuple[bool, bool, bool, bool, List[str], Dict[str, Any]]:
        violations: List[str] = []
        smt_witness: Dict[str, Any] = {}

        rw_entries = spec.get("tango_remote_write_txs", [])
        rw_ok = True
        if not rw_entries:
            rw_ok = False
            violations.append("tango_remote_write_txs vacío: se requiere al menos una transacción Remote-Write Tango.")
        for idx, item in enumerate(rw_entries):
            t_id = str(item.get("tx_id", f"tx_{idx}"))
            blind_ok = bool(item.get("blind_remote_stream_append_verified", False))
            ignore_ok = bool(item.get("consuming_client_ignores_unhosted_remote_writes", False))
            bp_ok = bool(item.get("redundant_stream_backpointers_valid", False))
            if not blind_ok or not ignore_ok or not bp_ok:
                rw_ok = False
                violations.append(
                    f"Violación Tango Remote-Write en {t_id}: blind_append={blind_ok}, ignore_unhosted={ignore_ok}, backpointers={bp_ok}."
                )
                smt_witness[f"tango_rw_counterexample_{t_id}"] = {
                    "blind_remote_stream_append_verified": blind_ok,
                    "consuming_client_ignores_unhosted_remote_writes": ignore_ok,
                    "redundant_stream_backpointers_valid": bp_ok,
                }

        ckpt_entries = spec.get("tango_checkpoints", [])
        ckpt_ok = True
        if not ckpt_entries:
            ckpt_ok = False
            violations.append("tango_checkpoints vacío: se requiere validación de checkpoint/forget Tango.")
        for idx, item in enumerate(ckpt_entries):
            o_id = str(item.get("object_id", f"obj_{idx}"))
            c_off = int(item.get("checkpoint_offset", 0))
            f_off = int(item.get("forget_trim_offset", 0))
            logged_ok = bool(item.get("checkpoint_logged_on_shared_log", False))
            if c_off <= 0 or f_off < 0 or f_off > c_off or not logged_ok:
                ckpt_ok = False
                violations.append(
                    f"Violación Tango Checkpoint/Forget en {o_id}: checkpoint_offset={c_off}, forget_trim_offset={f_off}, logged={logged_ok}."
                )
                smt_witness[f"tango_ckpt_counterexample_{o_id}"] = {
                    "checkpoint_offset": c_off,
                    "forget_trim_offset": f_off,
                    "checkpoint_logged_on_shared_log": logged_ok,
                }

        slot_entries = spec.get("hydrangea_mixed_fault_slots", [])
        slot_ok = True
        if not slot_entries:
            slot_ok = False
            violations.append("hydrangea_mixed_fault_slots vacío: se requiere configuración de slots Hydrangea.")
        for idx, item in enumerate(slot_entries):
            slot_id = item.get("slot_id", idx)
            f_val = int(item.get("byzantine_f", 1))
            c_val = int(item.get("crash_c", 0))
            k_val = int(item.get("tunable_k", 0))
            n_val = int(item.get("total_parties_n", 0))
            p_val = int(item.get("observed_optimistic_faults_p", 0))
            q_ok = bool(item.get("optimistic_two_round_quorum_verified", False))
            min_n = 3 * f_val + 2 * c_val + k_val + 1
            max_p = c_val + (k_val // 2)
            if (
                f_val < 1
                or c_val < 0
                or k_val < 0
                or n_val < min_n
                or p_val < 0
                or p_val > max_p
                or not q_ok
            ):
                slot_ok = False
                violations.append(
                    f"Violación Hydrangea Mixed-Fault Slot en {slot_id}: n={n_val} < {min_n}, p={p_val} > c+k//2={max_p}, quorum_ok={q_ok}."
                )
                smt_witness[f"hydrangea_slot_counterexample_{slot_id}"] = {
                    "total_parties_n": n_val,
                    "required_min_n": min_n,
                    "observed_optimistic_faults_p": p_val,
                    "max_optimistic_faults_p": max_p,
                    "optimistic_two_round_quorum_verified": q_ok,
                }

        fb_entries = spec.get("hydrangea_fallback_guarantees", [])
        fb_ok = True
        if not fb_entries:
            fb_ok = False
            violations.append("hydrangea_fallback_guarantees vacío: se requiere validación de cota inferior y fallback Hydrangea.")
        for idx, item in enumerate(fb_entries):
            cl_id = str(item.get("cluster_id", f"cluster_{idx}"))
            imp_ok = bool(item.get("two_round_impossibility_above_bound_enforced", False))
            three_ok = bool(item.get("three_round_adversarial_fallback_verified", False))
            if not imp_ok or not three_ok:
                fb_ok = False
                violations.append(
                    f"Violación Hydrangea Fallback en {cl_id}: impossibility_enforced={imp_ok}, three_round_fallback={three_ok}."
                )
                smt_witness[f"hydrangea_fallback_counterexample_{cl_id}"] = {
                    "two_round_impossibility_above_bound_enforced": imp_ok,
                    "three_round_adversarial_fallback_verified": three_ok,
                }

        return rw_ok, ckpt_ok, slot_ok, fb_ok, violations, smt_witness

