class MakoSpeculative2PCGeoReplicationAndBanyanFastRotatingLeaderTwoStepBFTProver:
    """
    Nivel 387 (v24.6.0 — 399 MCP Tools | REG-163 | Shard NODE-01):
    Demostrador Formal de Transacciones Distribuidas Especulativas con Geo-Replicación Desacoplada
    Mako (Shen, Cui, Sen, Angel, Mu USENIX OSDI 2025, Speculative 2PC con acotamiento de abortos en
    cascada por watermark y 3.66M TPC-C tx/s en 10 shards, 8.6x speedup) + Consenso BFT de Líder
    Rotativo con Crecimiento y Finalización en 2 Pasos (2 Retardos de Red) Banyan (Vonlanthen,
    Sliwinski, Albarello, Wattenhofer ETH Zürich arXiv:2312.05869, resiliencia parametrizada
    n >= 3f + 2p* - 1 con 1 <= p* <= f y penalidad cero al caer al camino estándar).
    """

    UNSAFE_PATTERNS = (
        "blocking_2pc_wait_cross_dc_paxos_before_local_commit(",
        "unbounded_speculative_2pc_cascading_abort_chain(",
        "three_step_rotating_leader_bft_without_banyan_fast_path(",
        "underprovisioned_banyan_quorum_below_3f_plus_2p_star_minus_1(",
    )

    @classmethod
    def _tarjan_scc_and_kahn_waves(
        cls, nodes: List[str], edges: List[Tuple[str, str]]
    ) -> Tuple[bool, List[List[str]], List[List[str]]]:
        adj: Dict[str, List[str]] = {n: [] for n in nodes}
        in_deg: Dict[str, int] = {n: 0 for n in nodes}
        for u, v in edges:
            if u not in adj:
                adj[u] = []
                in_deg[u] = 0
            if v not in adj:
                adj[v] = []
                in_deg[v] = 0
            adj[u].append(v)
            in_deg[v] += 1

        index = 0
        indices: Dict[str, int] = {}
        lowlink: Dict[str, int] = {}
        stack: List[str] = []
        on_stack: Set[str] = set()
        sccs: List[List[str]] = []

        def strongconnect(v: str) -> None:
            nonlocal index
            indices[v] = index
            lowlink[v] = index
            index += 1
            stack.append(v)
            on_stack.add(v)
            for w in sorted(adj.get(v, [])):
                if w not in indices:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], indices[w])
            if lowlink[v] == indices[v]:
                comp: List[str] = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    comp.append(w)
                    if w == v:
                        break
                sccs.append(sorted(comp))

        for n in sorted(adj.keys()):
            if n not in indices:
                strongconnect(n)

        has_self_loop = any(u == v for u, v in edges)
        is_dag = all(len(c) == 1 for c in sccs) and not has_self_loop

        waves: List[List[str]] = []
        rem_in = dict(in_deg)
        visited = 0
        current_wave = sorted([n for n, d in rem_in.items() if d == 0])
        while current_wave:
            waves.append(current_wave)
            visited += len(current_wave)
            next_wave: List[str] = []
            for u in current_wave:
                for v in sorted(adj.get(u, [])):
                    rem_in[v] -= 1
                    if rem_in[v] == 0:
                        next_wave.append(v)
            current_wave = sorted(next_wave)

        if visited != len(adj):
            is_dag = False

        return is_dag, waves, sccs

