class RTXRepairableDisaggregatedMemoryIndexTransactionAndSimpleITSignatureFreeSpeculativePipelinedBFTProver:
    """
    Nivel 388 (v24.7.0 — Hito 400 MCP Tools | REG-164 | Shard NODE-01):
    Demostrador Formal de Índices Transaccionales Reparables sobre Memoria Desagregada RDMA/CXL
    rTX (Haodi Lu, Xingda Wei, Rong Chen, Haibo Chen et al. arXiv:2308.02501, detección al vuelo
    de clientes caídos y reparación online de actualizaciones no atómicas en RaceHashing y Sherman
    B+Tree con 1.2x-2x speedup frente a transacciones distribuidas tradicionales) + Consenso BFT
    Práctico Libre de Firmas Post-Cuántico Simple-IT con Pipelining Especulativo (Xuechao Wang et al.
    arXiv:2606.14404, latencia teórica de 4 retardos de mensaje y 3 retardos en ruta optimista sobre
    Reliable Broadcast y Reliable Notification en variantes Mempool-Simple-IT y Dispersed-Simple-IT).
    """

    UNSAFE_PATTERNS = (
        "non_atomic_disaggregated_index_multi_rdma_write_without_rtx(",
        "heavy_distributed_2pc_lock_for_disaggregated_btree_index(",
        "quantum_vulnerable_signature_bft_without_simple_it_rbc(",
        "unpipelined_signature_free_bft_exceeding_4_message_delays(",
    )

    @classmethod
    def _tarjan_scc_and_kahn_waves(
        cls, nodes: List[str], edges: List[Tuple[str, str]]
    ) -> Tuple[bool, List[List[str]], List[List[str]]]:
        adj: Dict[str, List[str]] = {n: [] for n in nodes}
        in_deg: Dict[str, int] = {n: 0 for n in nodes}
        for u, v in edges:
            if u not in adj:
                adj[u] = []
                in_deg[u] = 0
            if v not in adj:
                adj[v] = []
                in_deg[v] = 0
            adj[u].append(v)
            in_deg[v] += 1

        index = 0
        indices: Dict[str, int] = {}
        lowlink: Dict[str, int] = {}
        stack: List[str] = []
        on_stack: Set[str] = set()
        sccs: List[List[str]] = []

        def strongconnect(v: str) -> None:
            nonlocal index
            indices[v] = index
            lowlink[v] = index
            index += 1
            stack.append(v)
            on_stack.add(v)
            for w in sorted(adj.get(v, [])):
                if w not in indices:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], indices[w])
            if lowlink[v] == indices[v]:
                comp: List[str] = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    comp.append(w)
                    if w == v:
                        break
                sccs.append(sorted(comp))

        for n in sorted(adj.keys()):
            if n not in indices:
                strongconnect(n)

        has_self_loop = any(u == v for u, v in edges)
        is_dag = all(len(c) == 1 for c in sccs) and not has_self_loop

        waves: List[List[str]] = []
        rem_in = dict(in_deg)
        visited = 0
        current_wave = sorted([n for n, d in rem_in.items() if d == 0])
        while current_wave:
            waves.append(current_wave)
            visited += len(current_wave)
            next_wave: List[str] = []
            for u in current_wave:
                for v in sorted(adj.get(u, [])):
                    rem_in[v] -= 1
                    if rem_in[v] == 0:
                        next_wave.append(v)
            current_wave = sorted(next_wave)

        if visited != len(adj):
            is_dag = False

        return is_dag, waves, sccs

