    @classmethod
    def _tarjan_scc_and_kahn_waves(
        cls, nodes: List[str], edges: List[Tuple[str, str]]
    ) -> Tuple[bool, List[List[str]], List[List[str]]]:
        adj: Dict[str, List[str]] = {n: [] for n in nodes}
        in_deg: Dict[str, int] = {n: 0 for n in nodes}
        for u, v in edges:
            adj.setdefault(u, []).append(v)
            adj.setdefault(v, [])
            in_deg.setdefault(u, 0)
            in_deg[v] = in_deg.get(v, 0) + 1

        index = 0
        indices: Dict[str, int] = {}
        lowlink: Dict[str, int] = {}
        stack: List[str] = []
        on_stack: Set[str] = set()
        sccs: List[List[str]] = []

        def strongconnect(v: str) -> None:
            nonlocal index
            indices[v] = index
            lowlink[v] = index
            index += 1
            stack.append(v)
            on_stack.add(v)
            for w in sorted(adj.get(v, [])):
                if w not in indices:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif w in on_stack:
                    lowlink[v] = min(lowlink[v], indices[w])
            if lowlink[v] == indices[v]:
                comp: List[str] = []
                while True:
                    w = stack.pop()
                    on_stack.remove(w)
                    comp.append(w)
                    if w == v:
                        break
                sccs.append(sorted(comp))

        for n in sorted(adj.keys()):
            if n not in indices:
                strongconnect(n)

        has_self_loop = any(u == v for u, v in edges)
        is_dag = all(len(c) == 1 for c in sccs) and not has_self_loop

        waves: List[List[str]] = []
        rem_in = dict(in_deg)
        visited = 0
        current_wave = sorted([n for n, d in rem_in.items() if d == 0])
        while current_wave:
            waves.append(current_wave)
            visited += len(current_wave)
            next_wave: List[str] = []
            for u in current_wave:
                for v in sorted(adj.get(u, [])):
                    rem_in[v] -= 1
                    if rem_in[v] == 0:
                        next_wave.append(v)
            current_wave = sorted(next_wave)

        if visited != len(adj):
            is_dag = False

        return is_dag, waves, sccs

