    forward_kahn_waves: List[List[str]]
    tarjan_sccs: List[List[str]]
    codere_double_entry_and_lock_order_ok: bool
    clipperops_ctl_error_recovery_ok: bool
    goar_vba7_and_draft_safety_ok: bool
