            emul_ok = bool(ws.get("omega_i_sigma_lower_bound_and_log_overhead_classic_emulation_verified", False))
            w_viol = int(ws.get("subthreshold_edge_delivery_assumption_or_interference_violation_count", 1))

            if not cum_sig or not lb_bound:
                wbn_lb_ok = False
                violations.append(
                    f"Weighted Beeping Network {pid} violates cumulative signal receiving threshold or O(I_sigma log n * (M + log n)) Local Broadcast bound."
                )
