            tid = str(ts.get("task_id", "st_0"))
            poset_lat = bool(ts.get("global_protocol_states_modeled_as_finite_posets_and_distributive_lattices", False))
            stone_link = bool(ts.get("spectral_space_pi_infinity_stone_duality_topological_link_verified", False))
            spec_map = bool(ts.get("colorless_task_solvable_iff_delta_compatible_spectral_map_exists", False))
