            if not poset_lat or not stone_link:
                poset_ok = False
                violations.append(
                    f"Stone duality task {tid} violates finite poset / distributive lattice modeling or Pi^infty(I) spectral space topological duality."
                )
                smt_witness[f"poset_{tid}"] = {
                    "global_protocol_states_modeled_as_finite_posets_and_distributive_lattices": poset_lat,
                    "spectral_space_pi_infinity_stone_duality_topological_link_verified": stone_link,
                }

            if not spec_map or t_viol != 0:
                spectral_ok = False
                violations.append(
                    f"Stone duality task {tid} violates colorless task solvability equivalence with Delta-compatible spectral map f: Pi^infty(I) -> O."
                )
                smt_witness[f"spectral_{tid}"] = {
                    "colorless_task_solvable_iff_delta_compatible_spectral_map_exists": spec_map,
                    "incompatible_spectral_map_or_broken_distributive_lattice_violations": t_viol,
                }

