        ast_ok = True
        unsafe_lines: List[int] = []
        if code:
            for idx, line in enumerate(code.splitlines(), start=1):
                stripped = line.split("#", 1)[0]
                for pat in cls.UNSAFE_AST_PATTERNS:
                    if pat in stripped:
                        ast_ok = False
                        unsafe_lines.append(idx)
