class ByzantineAgreementStrongEfficiencyLowerBoundsAndPlanarMaxFlowDualIncisionProver:
    ENGINE_VERSION = "28.6.0"
    VERIFICATION_LEVEL = 427

    @classmethod
    def build_default_clean_spec(cls) -> Dict[str, Any]:
        return {"level": 427, "invariants_ok": True, "dag_edges": [["n1", "n2"], ["n2", "n3"]], "auto_cegis_repair": False}

    @classmethod
    def build_default_flawed_spec(cls) -> Dict[str, Any]:
        return {"level": 427, "invariants_ok": False, "dag_edges": [["n1", "n2"], ["n2", "n1"]], "auto_cegis_repair": True}

    @classmethod
    def prove_and_repair(cls, spec: Optional[Dict[str, Any]] = None) -> ByzantineAgreementStrongEfficiencyLowerBoundsAndPlanarMaxFlowDualIncisionAuditReport:
        if spec is None:
            spec = cls.build_default_clean_spec()
        inv_ok = bool(spec.get("invariants_ok", True))
        edges = spec.get("dag_edges", [])
        violations: List[str] = []
        if not inv_ok:
            violations.append("INVARIANT_VIOLATION_DETECTED")
        adj: Dict[str, List[str]] = {}
        for e in edges:
            if len(e) == 2:
                adj.setdefault(str(e[0]), []).append(str(e[1]))
                adj.setdefault(str(e[1]), [])
        state = {u: 0 for u in adj}
        has_cycle = False
        def dfs(u: str) -> None:
            nonlocal has_cycle
            state[u] = 1
            for v in adj.get(u, []):
                if state.get(v, 0) == 1:
                    has_cycle = True
                elif state.get(v, 0) == 0:
                    dfs(v)
            state[u] = 2
        for u in list(adj.keys()):
            if state[u] == 0:
                dfs(u)
        if has_cycle:
            violations.append("DAG_CYCLE_DETECTED")
        is_valid = len(violations) == 0
        repaired = cls.build_default_clean_spec() if (not is_valid and bool(spec.get("auto_cegis_repair", False))) else {}
        score = 1.0 if is_valid else 0.0
        h = hashlib.sha256(json.dumps({"l": cls.VERIFICATION_LEVEL, "v": is_valid, "viol": violations}, sort_keys=True).encode()).hexdigest()
        return ByzantineAgreementStrongEfficiencyLowerBoundsAndPlanarMaxFlowDualIncisionAuditReport(
            level=cls.VERIFICATION_LEVEL,
            engine_version=cls.ENGINE_VERSION,
            is_valid=is_valid,
            pareto_reg007_dominance_score=score,
            violations=violations,
            cegis_repaired_spec=repaired,
            certificate_hash=h,
        )

    @classmethod
    def prove_and_repair_from_clean(cls, clean_spec: Dict[str, Any]) -> ByzantineAgreementStrongEfficiencyLowerBoundsAndPlanarMaxFlowDualIncisionAuditReport:
        rep = cls.prove_and_repair({**clean_spec, "auto_cegis_repair": False})
        rep.cegis_repaired_spec = clean_spec
        return rep


