@dataclass
class SmallMessageGraphSketchGossipAndAdversarialMajoritySupervisedComputingAuditReport:
    is_valid: bool
    nodes_n: int
    diameter_D: int
    hop_parameter_c: int
    weak_conductance_Phi_c: float
    message_bits: int
    polylog_message_budget_bits: int
    degree_threshold_Delta_Th: int
    weak_conductance_gossip_rounds: int
    diameter_sketch_gossip_rounds: int
