        lat_gain = round(((baseline_latency_ms - candidate_latency_ms) / max(baseline_latency_ms, 1e-6)) * 100.0, 4)
        thr_gain = round(((candidate_throughput_ops - baseline_throughput_ops) / max(baseline_throughput_ops, 1e-6)) * 100.0, 4)
