        normalized = sql_text.upper()
        violations: List[str] = []

        # 1. PG18 VIRTUAL generated columns & WITHOUT OVERLAPS check
        has_bloated_stored_generated = "GENERATED ALWAYS AS" in normalized and "STORED" in normalized and "ALLOW_STORED_GENERATED" not in normalized
        has_unprotected_temporal_range_pk = "DATERANGE" in normalized and "PRIMARY KEY" in normalized and "WITHOUT OVERLAPS" not in normalized
        pg18_virtual_generated_and_temporal_without_overlaps_sound = (
            not has_bloated_stored_generated and not has_unprotected_temporal_range_pk
        )
        if not pg18_virtual_generated_and_temporal_without_overlaps_sound:
            violations.append(
                "REG-118-PG18-STORED-GENERATED-OR-OVERLAPPING-TEMPORAL-KEY: Use GENERATED ALWAYS AS (...) VIRTUAL to prevent write/WAL amplification and include WITHOUT OVERLAPS on temporal range primary/unique keys."
            )

        # 2. Supabase View security_invoker = true check
        creates_view = "CREATE VIEW" in normalized or "CREATE OR REPLACE VIEW" in normalized
        has_security_invoker = "SECURITY_INVOKER = TRUE" in normalized or "SECURITY_INVOKER=TRUE" in normalized or "SECURITY_INVOKER = ON" in normalized
        supabase_security_invoker_view_rls_sound = (not creates_view) or has_security_invoker
        if not supabase_security_invoker_view_rls_sound:
            violations.append(
                "REG-118-VIEW-BYPASSES-RLS-WITHOUT-SECURITY-INVOKER: CREATE VIEW in public schema omits WITH (security_invoker = true), executing as view owner and bypassing underlying table RLS in PostgREST."
            )

