        if not zero_downtime_not_valid_fk_safe:
            violations.append(
                "REG-118-BLOCKING-FOREIGN-KEY-VALIDATION: ALTER TABLE ... ADD CONSTRAINT ... FOREIGN KEY executed without NOT VALID, blocking writes across both tables during full table scan."
            )

