            f"(declare-const security_invoker_ok Bool) (assert (= security_invoker_ok {'true' if supabase_security_invoker_view_rls_sound else 'false'}))\n"
            f"(declare-const fk_not_valid_ok Bool) (assert (= fk_not_valid_ok {'true' if zero_downtime_not_valid_fk_safe else 'false'}))\n"
            "(assert (and virtual_temporal_ok security_invoker_ok fk_not_valid_ok))\n"
            "(check-sat)"
