        if not pg18_uuidv7_btree_locality_sound:
            violations.append(
                "REG-119-RANDOM-UUIDV4-BTREE-PAGE-SPLIT: Primary key uses random gen_random_uuid()/uuid_generate_v4() instead of PostgreSQL 18 monotonic uuidv7(), causing severe B-Tree page fragmentation and WAL bloat."
            )

        # 2. Supabase SECURITY DEFINER search_path = '' and REVOKE EXECUTE check
