        has_empty_search_path = "SET SEARCH_PATH = ''" in normalized or "SET SEARCH_PATH=''" in normalized or "SET SEARCH_PATH TO ''" in normalized
        has_revoke_public_anon = "REVOKE EXECUTE" in normalized and "PUBLIC" in normalized
