            f"(declare-const sec_definer_confined Bool) (assert (= sec_definer_confined {'true' if supabase_security_definer_search_path_confined else 'false'}))\n"
            f"(declare-const unique_using_index_ok Bool) (assert (= unique_using_index_ok {'true' if zero_downtime_unique_using_index_safe else 'false'}))\n"
