            f"(declare-const supabase_rls_update_ok Bool) (assert (= supabase_rls_update_ok {'true' if supabase_rls_update_with_check_and_index_sound else 'false'}))\n"
            f"(declare-const bigint_identity_ok Bool) (assert (= bigint_identity_ok {'true' if zero_downtime_bigint_identity_no_serial_overflow_safe else 'false'}))\n"
