            ");\n"
            "CREATE INDEX CONCURRENTLY idx_ledger_sequences_tenant_id ON public.ledger_sequences (tenant_id);\n"
            "CREATE POLICY tenant_update_isolation ON public.ledger_sequences AS RESTRICTIVE FOR UPDATE TO authenticated\n"
