            f"(declare-const supabase_hypopg_ok Bool) (assert (= supabase_hypopg_ok {'true' if supabase_hypopg_reset_and_index_advisor_confinement_sound else 'false'}))",
            f"(declare-const replica_identity_ok Bool) (assert (= replica_identity_ok {'true' if zero_downtime_replica_identity_no_full_scan_safe else 'false'}))",
