        has_seq_decl = ("CREATE SEQUENCE" in normalized) or ("GENERATED ALWAYS AS IDENTITY" in normalized) or ("GENERATED BY DEFAULT AS IDENTITY" in normalized)
        has_bigint = ("AS BIGINT" in normalized) or ("BIGINT GENERATED" in normalized)
