        has_rollback = "ROLLBACK;" in normalized
        has_any_pgtap_call = ("POLICIES_ARE(" in normalized) or ("POLICY_ROLES_ARE(" in normalized) or ("POLICY_CMD_IS(" in normalized)
        has_commit_in_pgtap = has_any_pgtap_call and (("COMMIT;" in normalized) or not has_rollback)

