        has_safe_user_mapping = bool(re.search(r"CREATE\s+USER\s+MAPPING\s+(IF\s+NOT\s+EXISTS\s+)?FOR\s+POSTGRES\b", normalized))
        has_revoke_foreign_table = ("REVOKE ALL ON FOREIGN TABLE" in normalized) or ("REVOKE ALL ON ALL TABLES IN SCHEMA PRIVATE" in normalized)

