# --- Merged from Z4: PG18GinFastupdatePendingListGuardSupabasePgPlanFilterStatementCostLimitAndZeroDowntimeReindexConcurrentlyProver ---
class PG18GinFastupdatePendingListGuardSupabasePgPlanFilterStatementCostLimitAndZeroDowntimeReindexConcurrentlyProver:
    """
    Formal Symbolic Verifier #153 (v23.4.0 - REG-154):
    1. PostgreSQL 18 GIN Index WITH (fastupdate = off) / Bounded gin_pending_list_limit p99 Write-Latency Guard.
    2. Supabase pg_plan_filter (plan_filter.statement_cost_limit) Role Cost Guard for anon and authenticated.
    3. Zero-Downtime REINDEX INDEX/TABLE CONCURRENTLY Outside Transaction Blocks vs Blocking REINDEX Blocker.
    """

    @staticmethod
    def verify_sql_ddl(sql_text: str) -> PG18GinFastupdateSupabasePgPlanFilterAndReindexConcurrentlyReport:
        normalized = " ".join(sql_text.upper().split())
        violations: List[str] = []
        invariants: List[str] = [
            "INV-PG18-GIN-FASTUPDATE-01: GIN indexes on multi-tenant tables declare WITH (fastupdate = off) or bounded gin_pending_list_limit <= 2048 to prevent foreground pending-list flush stalls",
            "INV-SUPABASE-PLAN-FILTER-02: Roles anon and authenticated enforce plan_filter.statement_cost_limit <= 100000 via pg_plan_filter to abort runaway cartesian/SeqScan plans before execution",
            "INV-ZD-REINDEX-CONCURRENTLY-03: Index rebuilds use REINDEX INDEX/TABLE CONCURRENTLY outside transaction blocks and forbid blocking REINDEX"
        ]

        # Pillar 1: PG18 GIN fastupdate = off or bounded gin_pending_list_limit
        has_gin_index = "USING GIN" in normalized
        has_fastupdate_off = bool(re.search(r"FASTUPDATE\s*=\s*(OFF|FALSE|0)", normalized))
        pending_limit_match = re.search(r"GIN_PENDING_LIST_LIMIT\s*=\s*(\d+)", normalized)
        pending_limit_kb = int(pending_limit_match.group(1)) if pending_limit_match else 0
        has_bounded_pending_limit = 64 <= pending_limit_kb <= 2048

        has_pg18_gin_fastupdate_or_bounded_pending_list = (
            has_gin_index and (has_fastupdate_off or has_bounded_pending_limit)
        )
        has_unbounded_gin_pending_list_spike_risk = (
            has_gin_index and not has_fastupdate_off and (pending_limit_kb == 0 or pending_limit_kb > 2048)
        )

        if not has_pg18_gin_fastupdate_or_bounded_pending_list:
            violations.append(
                "VIOLATION-PG18-GIN-FASTUPDATE-01: GIN index must specify WITH (fastupdate = off) or WITH (fastupdate = on, gin_pending_list_limit = 64..2048) to eliminate p99 foreground flush stalls."
            )
        if has_unbounded_gin_pending_list_spike_risk:
            violations.append(
                "VIOLATION-PG18-GIN-SPIKE-01B: Unbounded GIN pending list (default 4MB) causes synchronous foreground cleanup stalls on multi-tenant writes."
            )

        # Pillar 2: Supabase pg_plan_filter Role Cost Guard
        anon_cost_match = re.search(
            r"ALTER\s+ROLE\s+ANON\s+SET\s+PLAN_FILTER\.STATEMENT_COST_LIMIT\s*(?:=|TO)\s*(\d+(?:\.\d+)?)",
            normalized,
        )
        auth_cost_match = re.search(
            r"ALTER\s+ROLE\s+AUTHENTICATED\s+SET\s+PLAN_FILTER\.STATEMENT_COST_LIMIT\s*(?:=|TO)\s*(\d+(?:\.\d+)?)",
            normalized,
        )
        statement_cost_limit_anon = float(anon_cost_match.group(1)) if anon_cost_match else 0.0
        statement_cost_limit_auth = float(auth_cost_match.group(1)) if auth_cost_match else 0.0

        has_supabase_pg_plan_filter_role_cost_limits = (
            (0.0 < statement_cost_limit_anon <= 50000.0)
            and (0.0 < statement_cost_limit_auth <= 100000.0)
        )
        has_unbounded_anon_or_authenticated_plan_cost = not has_supabase_pg_plan_filter_role_cost_limits

        if not has_supabase_pg_plan_filter_role_cost_limits:
            violations.append(
                "VIOLATION-SUPABASE-PLAN-FILTER-02: Missing or excessive plan_filter.statement_cost_limit on roles anon (<= 50000) and authenticated (<= 100000)."
            )

        # Pillar 3: Zero-Downtime REINDEX CONCURRENTLY vs Blocking REINDEX
        has_reindex_concurrently = bool(re.search(r"REINDEX\s+(?:INDEX|TABLE)\s+CONCURRENTLY\b", normalized))
        has_blocking_reindex = bool(re.search(r"REINDEX\s+(?:INDEX|TABLE|SCHEMA|DATABASE|SYSTEM)\s+(?!CONCURRENTLY\b)\S+", normalized))
        has_tx_block = ("BEGIN;" in normalized) or ("START TRANSACTION" in normalized)
        has_blocking_reindex_or_tx_wrapped_reindex_concurrently = (
            has_blocking_reindex or (has_reindex_concurrently and has_tx_block) or not has_reindex_concurrently
        )

        if has_blocking_reindex:
            violations.append(
                "VIOLATION-ZD-BLOCKING-REINDEX-03: Standard REINDEX locks out writes on the table; use REINDEX INDEX CONCURRENTLY or REINDEX TABLE CONCURRENTLY."
            )
        if has_reindex_concurrently and has_tx_block:
            violations.append(
                "VIOLATION-ZD-REINDEX-TX-03B: REINDEX CONCURRENTLY cannot be executed inside a transaction block (BEGIN ... COMMIT)."
            )
        if not has_reindex_concurrently:
            violations.append(
                "VIOLATION-ZD-REINDEX-MISSING-03C: Missing non-blocking REINDEX INDEX/TABLE CONCURRENTLY statement."
            )

        valid = (
            has_pg18_gin_fastupdate_or_bounded_pending_list
            and not has_unbounded_gin_pending_list_spike_risk
            and has_supabase_pg_plan_filter_role_cost_limits
            and not has_unbounded_anon_or_authenticated_plan_cost
            and not has_blocking_reindex_or_tx_wrapped_reindex_concurrently
            and len(violations) == 0
        )

        smt_proof_certificate = (
            "QED-Z3-REG-154-V23-4-0: UNSAT (No GIN pending-list foreground stall, unbounded PostgREST query cost, or blocking REINDEX write lock reachable)"
            if valid
            else "SAT-COUNTEREXAMPLE-REG-154-V23-4-0: Reachable GIN pending-list flush spike, unbounded query plan cost, or blocking/tx-wrapped REINDEX"
        )

        remediation_ddl = """-- Remediated PostgreSQL 18 GIN fastupdate=off + Supabase pg_plan_filter Cost Limits + Zero-Downtime REINDEX CONCURRENTLY (REG-154 v23.4.0)
CREATE INDEX CONCURRENTLY IF NOT EXISTS idx_tenant_events_metadata_gin
    ON public.tenant_ledger_events
    USING gin (metadata jsonb_path_ops)
    WITH (fastupdate = off);

ALTER ROLE anon SET plan_filter.statement_cost_limit = 10000;
ALTER ROLE authenticated SET plan_filter.statement_cost_limit = 50000;

REINDEX INDEX CONCURRENTLY public.idx_tenant_events_metadata_gin;"""

        return PG18GinFastupdateSupabasePgPlanFilterAndReindexConcurrentlyReport(
            valid=valid,
            has_pg18_gin_fastupdate_or_bounded_pending_list=has_pg18_gin_fastupdate_or_bounded_pending_list,
            has_unbounded_gin_pending_list_spike_risk=has_unbounded_gin_pending_list_spike_risk,
            has_supabase_pg_plan_filter_role_cost_limits=has_supabase_pg_plan_filter_role_cost_limits,
            has_unbounded_anon_or_authenticated_plan_cost=has_unbounded_anon_or_authenticated_plan_cost,
            has_blocking_reindex_or_tx_wrapped_reindex_concurrently=has_blocking_reindex_or_tx_wrapped_reindex_concurrently,
            statement_cost_limit_anon=statement_cost_limit_anon,
            checked_invariants=invariants,
            violations=violations,
            smt_proof_certificate=smt_proof_certificate,
            remediation_ddl=remediation_ddl,
        )


